  str_homestory_chat_14801005 = "Oye, ¿vas a terminar la conversación tan sin rodeos?",
  str_homestory_chat_14801006 = "Si tienes algo que decir, dímelo ahora mismo.",
  str_homestory_chat_14821001 = "¿Qué estás buscando?",
  str_homestory_chat_14821002 = "Haz visto Robyn?",
  str_homestory_chat_14821003 = "Robyn! Robyn!!",
  str_homestory_chat_14821004 = "No, no he...",
  str_homestory_chat_14821005 = "¿Tienes prisa por encontrarla? Yo te puedo ayudar con eso.",
  str_homestory_chat_14821006 = "¡Claro que soy yo! ¡Han pasado diez minutos desde que la vi!",
  str_homestory_chat_14821007 = "¡Nunca había pasado tanto tiempo sin verla!",
  str_homestory_chat_14821008 = "E-Eso es un poco exagerado...",
  str_homestory_chat_14821009 = "Ella está justo ahí...",
  str_homestory_chat_14821010 = "De todos modos, ¿por qué tengo la sensación de que siempre estás buscando a tu hermana?",
  str_homestory_chat_14821011 = "¿A qué estás llegando exactamente?",
  str_homestory_chat_14821012 = "N-No, no quise decir nada con eso...",
  str_homestory_chat_14821013 = "Creo que deberías darte prisa para buscar a tu hermana.",
  str_homestory_chat_14822001 = "¿Qué tienes en mente?",
  str_homestory_chat_14822002 = "Oh... ¿No tienes nada interesante aquí?",
  str_homestory_chat_14822003 = "\"Algo interesante\"?",
  str_homestory_chat_14822004 = "Como jarrones antiguos, y piedras con inscripciones antiguas...",
  str_homestory_chat_14822005 = "¿Tienes alguno aquí?",
  str_homestory_chat_14822006 = "¡Por supuesto!",
  str_homestory_chat_14822007 = "Te llevaré allí la próxima vez.",
  str_homestory_chat_14822008 = "Genial, no tengo idea de que también ofrezcas servicios de búsqueda del tesoro.",
  str_homestory_chat_14822009 = "No...",
  str_homestory_chat_14822010 = "Justo como pense...",
  str_homestory_chat_14822011 = "Olvídalo. No es un gran problema de todos modos.",
  str_homestory_chat_14823001 = "Pareces bastante libre.",
  str_homestory_chat_14823002 = "Estoy aburrido y no hay peleas que pelear.",
  str_homestory_chat_14823003 = "¿Quién se estaba desahogando antes de entrar?",
  str_homestory_chat_14823004 = "Ahora que estás tan acostumbrado al camino de la espada, ¿no es hora de llevar una vida sin preocupaciones también?",
  str_homestory_chat_14823005 = "Bien, bien. Estás bien.",
  str_homestory_chat_14823006 = "Hazte a un lado.",
  str_homestory_chat_14823007 = "¿Qué estás haciendo?",
  str_homestory_chat_14823008 = "Déjame cortar el árbol un par de veces, al menos hasta que esté satisfecho...",
  str_homestory_chat_14823009 = "De esa manera, puedo seguir llevando una vida sin preocupaciones.",
  str_homestory_chat_14823010 = "¡Oye, oye! ¡Deja de destruir el lugar!",
  str_homestory_chat_14824001 = "¿Cuál es el plan?",
  str_homestory_chat_14824002 = "¿Plan? no tengo uno",
  str_homestory_chat_14824003 = "¡Qué aburrida sería la vida si todo siguiera un plan!",
  str_homestory_chat_14824004 = "¿Realmente vives según el plan todos los días?",
  str_homestory_chat_14824005 = "¡Sí!",
  str_homestory_chat_14824006 = "Me da una sensación de seguridad cuando tengo mi día planeado.",
  str_homestory_chat_14824007 = "Así es como PlayerName ¿pensamiento?",
  str_homestory_chat_14824008 = "¡Pensé que eras más un tipo feliz y despreocupado!",
  str_homestory_chat_14824009 = "Nunca...",
  str_homestory_chat_14824010 = "Las cosas nunca salen según lo planeado.",
  str_homestory_chat_14824011 = "¡Eso es absolutamente correcto!",
  str_homestory_chat_14824012 = "¡Cada día es diferente, y eso es lo que hace que la vida sea interesante!",
  str_homestory_chat_14825001 = "¿Quieres ir a comprar ropa?",
  str_homestory_chat_14825002 = "¿No parece haber un lugar que venda ropa en sus jardines de nubes?",
  str_homestory_chat_14825003 = "Porque aquí no es necesario... ¿No puedes ir a Umbraton si quieres comprar ropa?",
  str_homestory_chat_14825004 = "Quiero comprarte unas, chatarrero.",
  str_homestory_chat_14825005 = "¿Ah? ¿Para mí?",
  str_homestory_chat_14825006 = "¿Por qué?",
  str_homestory_chat_14825007 = "Porque sigues usando la misma ropa, ya me cansé de verlas.",
  str_homestory_chat_14825008 = "Bueno... Tienes un punto.",
  str_homestory_chat_14825009 = "No necesito ninguno.",
  str_homestory_chat_14825010 = "Bueno, ¿quieres ir a Umbraton conmigo?",
  str_homestory_chat_14825011 = "Lo pensare.",
  str_homestory_chat_14825012 = "¿Qué hay que pensar? Si sigues yendo a todas partes con la misma ropa, incluso los Chubbs se cansarán de verte.",
  str_homestory_chat_14826001 = "¿Práctica?",
  str_homestory_chat_14826002 = "A veces necesito practicar con mis dagas. No siempre puedo luchar contra los peces y los árboles.",
  str_homestory_chat_14826003 = "Así que tú eres el que dejó esos rasguños en los árboles...",
  str_homestory_chat_14826004 = "¡Ayúdame a encontrar un buen compañero de combate!",
  str_homestory_chat_14826005 = "Aquí nadie es adecuado.",
  str_homestory_chat_14826006 = "Deberías pegarte a los árboles.",
  str_homestory_chat_14826007 = "O... ¿qué pasa con las rocas?",
  str_homestory_chat_14826008 = "Creo que me estás engañando, chatarrero.",
  str_homestory_chat_14826009 = "Es porque este es un lugar pacífico. Deberías relajarte cuando estés aquí.",
  str_homestory_chat_14826010 = "Creo que es hora de encontrar algunos objetivos para mí. ¡Esos Chubbs se ven bastante adecuados!",
  str_homestory_chat_14826011 = "Se mueven lentamente y no contraatacan. Incluso parecen muy duraderos.",
  str_homestory_chat_14826012 = "¡Por favor no!",
  str_homestory_chat_12299999 = "¿Te apetece un vaso de diésel en un día increíble como hoy?",
  str_homestory_chat_12221001 = "Gracias pero no gracias.",
  str_homestory_chat_12221002 = "¿Estás seguro de que vas a dejar pasar un diesel viejo tan apetecible?",
  str_homestory_chat_12221003 = "Viejo diesel... En serio, no te entiendo.",
  str_homestory_chat_12222001 = "¿Cómo te está gustando aquí?",
  str_homestory_chat_12222002 = "En realidad es un lugar bastante decente...",
  str_homestory_chat_12222003 = "pero el diesel aquí es un poco caro.",
  str_homestory_chat_12222004 = "Quiero decir, son enviados desde lejos, después de todo.",
  str_homestory_chat_12222005 = "¡Esos tontos de Illumina deben haber subido los precios furtivamente!",
  str_homestory_chat_12222006 = "...Hay algo que no estoy seguro si debería decirte.",
  str_homestory_chat_12222007 = "¿Por qué andas por las ramas, jefe?",
  str_homestory_chat_12222008 = "Es solo que el diésel lo envía Rediesel Wrench.",
  str_homestory_chat_12222009 = "!",
  str_homestory_chat_12222010 = "¿Estás molesto?",
  str_homestory_chat_12222011 = "Gracias por informarme sobre esto, jefe...",
  str_homestory_chat_12222012 = "¡Finalmente puedo conseguir un poco de diesel gratis!",
  str_homestory_chat_12223001 = "En fin, dejemos de lado el diésel...",
  str_homestory_chat_12223002 = "¿Qué estás mirando?",
  str_homestory_chat_12223003 = "Haz visto Rabbie, ¿jefe?",
  str_homestory_chat_12223004 = "¿Necesitas algo de ella?",
  str_homestory_chat_12223005 = "¡Hace horas que no la veo!",
  str_homestory_chat_12223006 = "¿Qué pasa si le pasa algo y yo no estoy allí para protegerla?",
  str_homestory_chat_12223007 = "¡Me arrepentiré para siempre!",
  str_homestory_chat_12223008 = "tienes que ahorrar Rabbie, ¡Jefe! ¡Sálvame!",
  str_homestory_chat_12223009 = "... Está bien, cálmate. Solo estás histérica.",
  str_homestory_chat_11299999 = "Hola mi amigo.",
  str_homestory_chat_11201001 = "Hola, Nemesis.",
  str_homestory_chat_11201002 = "¿Quieres unirte a mí para que se haga justicia hoy?",
  str_homestory_chat_11201003 = "Con Nemesis aquí, se siente mucho más seguro aquí.",
  str_homestory_chat_11201004 = "Por supuesto. Nunca dejaría que la oscuridad se enconara.",
  str_homestory_chat_11221001 = "Está tan tranquilo aquí últimamente.",
  str_homestory_chat_11221002 = "Sí, pero las patrullas siguen siendo necesarias.",
  str_homestory_chat_11221003 = "No, no hay necesidad.",
  str_homestory_chat_11221004 = "Dudo que alguno de nosotros esté en desacuerdo ya que todos somos amigos.",
  str_homestory_chat_11221005 = "Ese es un punto justo...",
  str_homestory_chat_11221006 = "pero cortarlo de raíz es algo que tengo que hacer como ejecutor.",
  str_homestory_chat_11221007 = "Es una gran idea.",
  str_homestory_chat_11221008 = "Todos somos amigos aquí, pero estamos obligados a tener algunas fricciones.",
  str_homestory_chat_11221009 = "Odiaría que alguien se metiera en una pelea.",
  str_homestory_chat_11221010 = "Gracias por afirmar el valor de mi trabajo, mi amigo.",
  str_homestory_chat_11221011 = "Déjame tomar el reinado para salvaguardar esta tranquilidad.",
  str_homestory_chat_11222001 = "¿Qué paso?",
  str_homestory_chat_11222002 = "Acabo de impedir que alguien dañe el entorno eraveiliano.",
  str_homestory_chat_11222003 = "¿Eh? ¿Qué hizo esa persona?",
  str_homestory_chat_11222004 = "Estaba tratando de arrancar flores en el jardín...",
  str_homestory_chat_11222005 = "¡y nunca podré tolerar este tipo de ruptura de reglas!",
  str_homestory_chat_11222006 = "¿Qué le hiciste?",
  str_homestory_chat_11222007 = "Usé mi Blade of Judgement para enviarlo a volar.",
  str_homestory_chat_11222008 = "¡Ay! Gracias por proteger el medio ambiente aquí, Nemesis.",
  str_homestory_chat_11222009 = "Pero todavía tengo que poner señales de advertencia para el jardín.",
  str_homestory_chat_11222010 = "¿Advertir a todos contra...?",
  str_homestory_chat_11222011 = "Para advertir a todos que recoger flores es una actividad de alto riesgo.",
  str_homestory_chat_11223001 = "Te ves muy feliz...",
  str_homestory_chat_11223002 = "¿Te pasó algo bueno hoy?",
  str_homestory_chat_11223003 = "Ayudé a un gatito perdido a encontrar el camino de regreso a casa.",
  str_homestory_chat_11223004 = "Tanto el gatito como su dueña estaban muy agradecidos.",
  str_homestory_chat_11223005 = "El sol parece estar brillando aún más intensamente hoy.",
  str_homestory_chat_11223006 = "Sin duda es un hermoso día.",
  str_homestory_chat_11223007 = "Me alegra compartir esta experiencia contigo, amigo mío.",
  str_homestory_chat_11223008 = "Debería estar haciendo cumplir la justicia y ayudando a otros en días como estos.",
  str_homestory_chat_11224001 = "¿Quieres aumentar la plantilla?",
  str_homestory_chat_11224002 = "Sí, quiero formar una patrulla para mantener la ley y el orden aquí.",
  str_homestory_chat_11224003 = "Esto no es la Federación Illumina... No necesitas estar tan ansioso.",
  str_homestory_chat_11224004 = "No puedo seguir siendo tan complaciente. Incluso con mi disposición, he comenzado a holgazanear últimamente.",
  str_homestory_chat_11224005 = "No quiero trabajar en absoluto... No puedo dejar que esto continúe.",
  str_homestory_chat_11224006 = "¿Deberíamos ponerte a cargo de recordarles a todos que trabajen duro?",
  str_homestory_chat_11224007 = "¡Qué buena idea! Me pondré manos a la obra de inmediato.",
  str_homestory_chat_11224008 = "¡Qué asombrosa eficiencia!",
  str_homestory_chat_11225001 = "¿Estás buscando los Chubbs?",
  str_homestory_chat_11225002 = "Sí. ¿Qué piensas de ellos?",
  str_homestory_chat_11225003 = "Son buenos compañeros.",
  str_homestory_chat_11225004 = "Sólo compañeros, eh...",
  str_homestory_chat_11225005 = "Son los arquitectos de Cloud Gardens.",
  str_homestory_chat_11225006 = "¿Arquitectos?",
  str_homestory_chat_11225007 = "Suspiro... Parece que aún no has descubierto sus buenas cualidades.",
  str_homestory_chat_11225008 = "¿Por ejemplo?",
  str_homestory_chat_11225009 = "Son disciplinados. Cuando les doy órdenes, siempre hacen el trabajo.",
  str_homestory_chat_11225010 = "Hubiera sido perfecto si pudieras organizarlos en una fuerza para mantener la seguridad pública aquí.",
  str_homestory_chat_11225011 = "Es una pena que no estuvieran interesados cuando hablé de ello. Todo lo que dijeron en respuesta fue, \"Chubb\".",
  str_homestory_chat_11225012 = "Supongo que rechazaron la idea...",
  str_homestory_chat_11226001 = "¿Algo en tu mente?",
  str_homestory_chat_11226002 = "Me pregunto si debería establecer algunas reglas aquí.",
  str_homestory_chat_11226003 = "¿Por ejemplo?",
  str_homestory_chat_11226004 = "Reglas sobre clasificación de basura, limpieza regular de habitaciones, etc.",
  str_homestory_chat_11226005 = "Creo que Cloud Gardens se convertirá gradualmente en Illumina si haces eso...",
  str_homestory_chat_11226006 = "¿Estás descontento con cómo es la vida aquí?",
  str_homestory_chat_11226007 = "No, es muy cómodo, pero siento que estoy fuera de lugar por alguna razón.",
  str_homestory_chat_11226008 = "No puedo dormir bien por la noche si no hago algo.",
  str_homestory_chat_11226009 = "Creo que estás demasiado acostumbrado a estar en Illumina... Trata tu tiempo aquí como si estuvieras de vacaciones.",
  str_homestory_chat_11226010 = "Las vacaciones también forman parte del sistema de Illumina. Tienes que seguirlo.",
  str_homestory_chat_11226011 = "Supongo que cuando lo pienso de esa manera... es permisible.",
  str_homestory_chat_12599999 = "¡Hola! Con el nuevo día vienen nuevas ideas.",
  str_homestory_chat_12521001 = "¿Para actuaciones?",
  str_homestory_chat_12521002 = "Ah... ¿Estás esperando mi actuación? PlayerName?",
  str_homestory_chat_12521003 = "Tienes un gusto excelente ya que mis actuaciones nunca dejan de decepcionar.",
  str_homestory_chat_12521004 = "... En realidad no he pensado en eso ...",
  str_homestory_chat_12521005 = "pero está bien si quieres actuar.",
  str_homestory_chat_12522001 = "¿Para guiones?",
  str_homestory_chat_12522002 = "¿Quieres escuchar las líneas?",
  str_homestory_chat_12522003 = "tendría que decir, PlayerName, tu sentido estético está mejorando gradualmente.",
  str_homestory_chat_12522004 = "Ejem. En la noche oscura sin límites, escucho el desgarramiento del corazón de uno...",
  str_homestory_chat_12522005 = "¿No es demasiado doloroso?",
  str_homestory_chat_12522006 = "Así es. A través del uso de mi espectacular vocabulario, lo que se necesita transmitir es...",
  str_homestory_chat_12522007 = "tristeza y desesperación...",
  str_homestory_chat_12522008 = "¡Así es como se ve realmente el mundo en el que vivimos!",
  str_homestory_chat_12522009 = "Parece que tengo razón sobre ti, PlayerName.",
  str_homestory_chat_12522010 = "Tu sentido estético está mejorando gradualmente bajo mi influencia.",
  str_homestory_chat_12522011 = "¿No es demasiado aterrador?",
  str_homestory_chat_12522012 = "¿Alarmante? ¿No me digas que no puedes detectarlo...?",
  str_homestory_chat_12522013 = "Debajo de la aterradora descripción se encuentra un fuerte trasfondo de tristeza y dolor.",
  str_homestory_chat_12522014 = "UH no...",
  str_homestory_chat_12522015 = "PlayerName, lamento tener que retractarme de mi evaluación anterior de su estética.",
  str_homestory_chat_12523001 = "¿Como has estado?",
  str_homestory_chat_12523002 = "PlayerName, ¿no es demasiado estrecho aquí?",
  str_homestory_chat_12523003 = "¿Por qué dices eso?",
  str_homestory_chat_12523004 = "¡Creo que Other End no puede pasar en absoluto!",
  str_homestory_chat_12523005 = "Si lo conducimos por aquí, definitivamente derribaremos una pared o derribaremos un árbol...",
  str_homestory_chat_12523006 = "No.",
  str_homestory_chat_12523007 = "Pero ni siquiera es lo suficientemente ancho como para dejar pasar el otro extremo.",
  str_homestory_chat_12523008 = "¿Se supone que mi querido Otro Fin flotará en el cielo entonces?",
  str_homestory_chat_12523009 = "¡Esperar! ¡¿Por qué quieres conducir un tren en un espacio donde la gente camina?!",
  str_homestory_chat_12524001 = "Escuché que tienes un plan...",
  str_homestory_chat_12524002 = "Sí. PlayerName, ¿no vas a construir algo en este terreno vacío?",
  str_homestory_chat_12524003 = "¿Construir qué?",
  str_homestory_chat_12524004 = "¡Una etapa!",
  str_homestory_chat_12524005 = "¡Un escenario que me pertenece a mí, al artista ya Otro Fin!",
  str_homestory_chat_12524006 = "¿Qué tal? ¿No es una propuesta súper apasionada y creativa?",
  str_homestory_chat_12524007 = "No estoy construyendo nada.",
  str_homestory_chat_12524008 = "PlayerName, mira esta tierra vacía. ¿No se ve tan pálido?",
  str_homestory_chat_12524009 = "Solo está esperando que la pasión artística le dé color—",
  str_homestory_chat_12524010 = "Entonces ... ¿Cuál es tu punto?",
  str_homestory_chat_12524011 = "¡Así que construyamos un escenario! ¡Por el arte y por el Otro Fin!",
  str_homestory_chat_12524012 = "Eh, lo pensaré.",
  str_homestory_chat_12525001 = "La pelota de hoy...",
  str_homestory_chat_12525002 = "¿Estás diciendo... que hay un baile esta noche?",
  str_homestory_chat_12525003 = "¡No me iré! El final predestinado de la vida de un artista malvado es la soledad.",
  str_homestory_chat_12525004 = "Pero parece que realmente quieres ir...",
  str_homestory_chat_12525005 = "Ejem, viste mal.",
  str_homestory_chat_12525006 = "Pero si insistes en invitarme, supongo que tendré la amabilidad de aceptar...",
  str_homestory_chat_12525007 = "Vale, entonces insisto en invitarte.",
  str_homestory_chat_12525008 = "Bueno. Hasta entonces.",
  str_homestory_chat_12525009 = "... ¿No vas a insistir en invitarme?",
  str_homestory_chat_12525010 = "Okay...",
  str_homestory_chat_12525011 = "Ejem. Charon, hay un baile esta noche. Insisto en que asistas.",
  str_homestory_chat_12525012 = "Bueno, supongo que lo aceptaré a regañadientes, por tu cuenta.",
  str_homestory_chat_12526001 = "Tengo una pregunta.",
  str_homestory_chat_12526002 = "¿Vaya? Haré todo lo posible para responder a la pregunta de PlayerName.",
  str_homestory_chat_12526003 = "Digame mi amigo. ¿Qué te preocupa?",
  str_homestory_chat_12526004 = "Todos los trenes circulan por vías...",
  str_homestory_chat_12526005 = "¿Por qué tu Otro Extremo no necesita ninguno?",
  str_homestory_chat_12526006 = "Hahahah... ¡Esa es una muy buena pregunta que tienes!",
  str_homestory_chat_12526007 = "Other End es un amigo mío. Puedes pensar en ello como mi inspiración. Y la inspiración debe ser libre.",
  str_homestory_chat_12526008 = "¿Cómo puedes llamarlo libre si está atrapado por los rieles?",
  str_homestory_chat_12526009 = "¡Pero no puede enloquecer en Eraveil!",
  str_homestory_chat_10699999 = "Quieres tener una charla conmigo, PlayerName?",
  str_homestory_chat_10601001 = "Sí.",
  str_homestory_chat_10601002 = "Sería un placer, pero debes vigilar la hora.",
  str_homestory_chat_10601003 = "Tienes varios planes más adelante, no lo olvides.",
  str_homestory_chat_10621001 = "En cuanto al postre...",
  str_homestory_chat_10621002 = "¿Tienes alguna sugerencia sobre el estilo?",
  str_homestory_chat_10621003 = "¿Ustedes van a hacer postres?",
  str_homestory_chat_10621004 = "Sí, queremos preparar unos bocadillos para todos.",
  str_homestory_chat_10621005 = "Mmm, te recomiendo la tarta de crema de coco y fresas...",
  str_homestory_chat_10621006 = "Pero si es demasiado complicado hacerlo, puedes elegir otra cosa.",
  str_homestory_chat_10621007 = "Tarta de fresas con crema de coco...",
  str_homestory_chat_10621008 = "Es CarleenEl postre favorito de ¿no?",
  str_homestory_chat_10621009 = "No es que quiera comerlo, solo... solo lo recomiendo sinceramente.",
  str_homestory_chat_10621010 = "¡Esta vez contamos con la ayuda de un experto!",
  str_homestory_chat_10621011 = "Esto definitivamente irá bien.",
  str_homestory_chat_10621012 = "Bueno, todo está terminado. ¡Tienes que venir a probarlo!",
  str_homestory_chat_10622001 = "¡Buen clima hoy!",
  str_homestory_chat_10622002 = "Sí, el tiempo aquí es tan bueno como siempre.",
  str_homestory_chat_10622003 = "Te gustan los días soleados, ¿eh?",
  str_homestory_chat_10622004 = "Un día soleado pone a la gente de buen humor.",
  str_homestory_chat_10622005 = "Pero tener solo días soleados también será un problema.",
  str_homestory_chat_10622006 = "Es porque no todos los días son soleados...",
  str_homestory_chat_10622007 = "Que tener un día soleado animará a la gente.",
  str_homestory_chat_10622008 = "PlayerName, has dicho algo muy filosófico.",
  str_homestory_chat_10622009 = "Sí.",
  str_homestory_chat_10622010 = "Quizás lo que mueve a la gente no son solo los días soleados...",
  str_homestory_chat_10622011 = "También es el ambiente tranquilo aquí.",
  str_homestory_chat_10622012 = "Ojalá días como estos duraran para siempre.",
  str_homestory_chat_10623001 = "¿Tienes tiempo?",
  str_homestory_chat_10623002 = "PlayerName, hay algo con lo que necesites mi ayuda?",
  str_homestory_chat_10623003 = "Oh sí.",
  str_homestory_chat_10623004 = "Sin embargo, no es nada particularmente importante.",
  str_homestory_chat_10623005 = "Si tienes algo más que hacer, entonces haz eso.",
  str_homestory_chat_10623006 = "Déjame pensar.",
  str_homestory_chat_10623007 = "Solo algunas cositas. No tienes que preocuparte por ellos.",
  str_homestory_chat_10623008 = "No creo que haya ninguno.",
  str_homestory_chat_10623009 = "¿Has terminado con lo que tienes que hacer?",
  str_homestory_chat_10623010 = "Todavía hay algunas cosas, pero no tienes que preocuparte por ellas.",
  str_homestory_chat_10623011 = "Pero me gustaría hacer lo que pueda por todos.",
  str_homestory_chat_10624001 = "¿Escuché que tienes algo que decirme?",
  str_homestory_chat_10624002 = "PlayerName, Vice me dijiste eso...",
  str_homestory_chat_10624003 = "Llegaste tarde a la competencia de pesca hace unos días.",
  str_homestory_chat_10624004 = "Si...",
  str_homestory_chat_10624005 = "Tenía media hora cuando me fui, y no pensé que el destino estaba tan lejos...",
  str_homestory_chat_10624006 = "Puedes pedirme ayuda la próxima vez que te encuentres en este tipo de situación.",
  str_homestory_chat_10624007 = "Puedo llamar a un caballo y traerte allí.",
  str_homestory_chat_10624008 = "De todos modos, no caigas en el mal hábito de llegar tarde.",
  str_homestory_chat_10625001 = "Escuché que quieres ir a pescar.",
  str_homestory_chat_10625002 = "Sí, ¿algún plan para un viaje de pesca pronto?",
  str_homestory_chat_10625003 = "¡Sí!",
  str_homestory_chat_10625004 = "Supongo que debería prepararme.",
  str_homestory_chat_10625005 = "Hablando de prepararte, estabas demasiado preparado la última vez.",
  str_homestory_chat_10625006 = "Incluso trajiste un paraguas de tienda y una lanza.",
  str_homestory_chat_10625007 = "El paraguas de la tienda es para protegernos de la lluvia cuando estamos pescando...",
  str_homestory_chat_10625008 = "La lanza se puede usar para lidiar con los peces que se escapan. ¡Una puñalada y listo!",
  str_homestory_chat_10625009 = "No me gusta que pasen cosas inesperadas.",
  str_homestory_chat_10625010 = "Estar preparado es la base del éxito seguro.",
  str_homestory_chat_10625011 = "Siento que he aprendido algo una vez más...",
  str_homestory_chat_10626001 = "¿Cualquier sugerencia?",
  str_homestory_chat_10626002 = "Me gustaría agregar algún adorno aquí, pero aún no estoy seguro de qué.",
  str_homestory_chat_10626003 = "¿Ornamento? Déjame pensar...",
  str_homestory_chat_10626004 = "¿Qué tal algunos equipos para el entrenamiento de artes marciales?",
  str_homestory_chat_10626005 = "¿Como un saco de arena?",
  str_homestory_chat_10626006 = "Hmm... Los sacos de arena son equipo de entrenamiento común. La mayoría de la gente se beneficiará de ello.",
  str_homestory_chat_10626007 = "¿Como una diana de tiro con arco?",
  str_homestory_chat_10626008 = "Hmm... A los arqueros aurorianos como Vice les encantaría.",
  str_homestory_chat_10626009 = "Esta bien, lo tengo.",
  str_homestory_chat_10626010 = "Una vez que firme un plan, el resto del trabajo se vuelve fácil.",
  str_homestory_chat_10626011 = "Busque planos, reúna materiales y construya lo que necesita.",
  str_homestory_chat_10626012 = "Así es. Y estos son los que mejor hago.",
  str_homestory_chat_12899999 = "¡Hola! ¿Tienes algún consejo que dar?",
  str_homestory_chat_12801001 = "No.",
  str_homestory_chat_12801002 = "No, solo quería saludarte.",
  str_homestory_chat_12801003 = "Tus saludos me hacen muy feliz!",
  str_homestory_chat_12801004 = "Ven, por favor toma estas Conchas de Agua Bendita. ¡Seguro que te serán de utilidad!",
  str_homestory_chat_12821001 = "¿Qué estás mirando?",
  str_homestory_chat_12821002 = "Vaya, mis colmillos parecen haber crecido más.",
  str_homestory_chat_12821003 = "No esperaba que la cruz se usara como un espejo...",
  str_homestory_chat_12821004 = "¿Quieres comparar la longitud de nuestros caninos?",
  str_homestory_chat_12821005 = "Ven aquí, párate frente a la cruz.",
  str_homestory_chat_12821006 = "No, gracias...",
  str_homestory_chat_12821007 = "¡Relájate, mi cruz se refleja muy claramente!",
  str_homestory_chat_12821008 = "¿Seguro que no quieres ver cuánto miden tus colmillos?",
  str_homestory_chat_12821009 = "¿O no tienes caninos?",
  str_homestory_chat_12822001 = "Rafael, ¿qué estás haciendo?",
  str_homestory_chat_12822002 = "Suspiro-",
  str_homestory_chat_12822003 = "Les voy a dar estas bombas de agua bendita a todos.",
  str_homestory_chat_12822004 = "¡Todo el mundo está recibiendo uno!",
  str_homestory_chat_12822005 = "¿Y cuál es la razón de esto?",
  str_homestory_chat_12822006 = "Bueno, por supuesto que es porque... La población auroriana de Eraveil está creciendo...",
  str_homestory_chat_12822007 = "En caso de que alguien resulte herido por accidente, y yo no estoy cerca...",
  str_homestory_chat_12822008 = "¡Estaría devastado si no pudiera ayudar a salvarlos a tiempo!",
  str_homestory_chat_12823001 = "Hola, Rafael.",
  str_homestory_chat_12823002 = "El pastel que hice el otro día estuvo buenísimo, ¿no?",
  str_homestory_chat_12823003 = "¡Puedo hacer más y darte un poco!",
  str_homestory_chat_12823004 = "Uh, voy a pasar...",
  str_homestory_chat_12823005 = "¡Entendido!",
  str_homestory_chat_12823006 = "¿Que entendiste tu?",
  str_homestory_chat_12823007 = "Debes pensar que la repostería que hago es demasiado refinada...",
  str_homestory_chat_12823008 = "¡Así que no puedes soportar comerlo!",
  str_homestory_chat_12823009 = "... Claro, puedes tomarlo de esa manera.",
  str_homestory_chat_12823010 = "¿Por qué venir a mí de nuevo?",
  str_homestory_chat_12823011 = "porque todo el mundo dice PlayerName tiene el mayor aprecio del mundo por la comida!",
  str_homestory_chat_12823012 = "¡¿Y a quién se le ocurrió eso?!",
  str_homestory_chat_12823013 = "¡Cuéntame y te recomendaré a alguien con un nivel de apreciación aún mayor!",
  str_homestory_chat_10799999 = "La, la-la, la... Oh, PlayerName! ¿Me llamaste?",
  str_homestory_chat_10721001 = "¿Estoy interrumpiendo tu canto?",
  str_homestory_chat_10721002 = "N-No, en absoluto. Yo solo estaba... Mmm.",
  str_homestory_chat_10721003 = "¿Querías verme por algo?",
  str_homestory_chat_10722001 = "¿Qué estás buscando?",
  str_homestory_chat_10722002 = "¿Habrá conejos aquí, PlayerName?",
  str_homestory_chat_10722003 = "¿Supongo?",
  str_homestory_chat_10722004 = "Creo que he visto a algunas personas organizar actividades de caza...",
  str_homestory_chat_10722005 = "Y entre las presas que traen de vuelta...",
  str_homestory_chat_10722006 = "¡Deténgase! ¡No continúes!",
  str_homestory_chat_10722007 = "Eso es terrible... ¡Cosas así deben detenerse!",
  str_homestory_chat_10722008 = "No creo que haya ninguno.",
  str_homestory_chat_10722009 = "No he visto uno de todos modos.",
  str_homestory_chat_10722010 = "... Esto también está bien. Al menos no los veré heridos aquí.",
  str_homestory_chat_10723001 = "¿Te has acostumbrado a este lugar?",
  str_homestory_chat_10723002 = "El viento aquí es muy suave...",
  str_homestory_chat_10723003 = "¿Tú también lo crees?",
  str_homestory_chat_10723004 = "que es la felicidad para ti, PlayerName?",
  str_homestory_chat_10723005 = "Quedarse aquí.",
  str_homestory_chat_10723006 = "Permanecer en mi ciudad natal y cuidar esta tierra. A mi...",
  str_homestory_chat_10723007 = "Esto es una cosa dichosa.",
  str_homestory_chat_10723008 = "Ok...",
  str_homestory_chat_10723009 = "Paz y tranquilidad.",
  str_homestory_chat_10723010 = "Sin mentiras, sin derramamiento de sangre y con sonrisas inquebrantables en los rostros de todos los niños...",
  str_homestory_chat_10723011 = "Eso es verdaderamente... una felicidad notable.",
  str_homestory_chat_10751001 = "¿Dónde está el pescado especial?",
  str_homestory_chat_10751002 = "¡Oh, la brisa, qué sensación!",
  str_homestory_chat_10751003 = "¿De qué estás hablando?",
  str_homestory_chat_10751004 = "Tal vez eres tú. ¿Estás de prisa?",
  str_homestory_chat_10751005 = "Estoy, en realidad... ¿Escuché que viste un pez especial?",
  str_homestory_chat_10751006 = "Sé que las palabras viajan rápido, pero esto sigue siendo una sorpresa.",
  str_homestory_chat_10751007 = "¿O venía de alguno en particular? Por ejemplo, ese conejo?",
  str_homestory_chat_10751008 = "No... Olvídalo. ¿Dónde está el pescado?",
  str_homestory_chat_10751009 = "El conejo... mencionó que el pez ama algún tipo de árbol.",
  str_homestory_chat_10751010 = "¿Podría ser... el árbol Quinlan de hoja enana?",
  str_homestory_chat_10751011 = "Parece que tengo que hacer otro viaje...",
  str_homestory_chat_10751012 = "¿Qué?",
  str_homestory_chat_10751013 = "¡No hay problema! Las semillas del árbol Quinlan de hoja enana, ¿verdad? ¡Pan comido!",
  str_homestory_chat_10751014 = "¡Gracias!",
  str_homestory_chat_10199999 = "Recibí tu saludo.",
  str_homestory_chat_10121001 = "Está bien.",
  str_homestory_chat_10121002 = "Estoy bien. ¿Hay algo más que quieras decir?",
  str_homestory_chat_10121003 = "Sí, eh... yo...",
  str_homestory_chat_10121004 = "Parece que necesitaré un poco de paciencia para esperar a que te expreses.",
  str_homestory_chat_10122001 = "¿Quieres verme?",
  str_homestory_chat_10122002 = "PlayerName, Me gustaría que tuvieras un hecho en mente.",
  str_homestory_chat_10122003 = "¿Qué hecho?",
  str_homestory_chat_10122004 = "El paseo marítimo aquí es muy adecuado para el cultivo de narcisos blancos.",
  str_homestory_chat_10122005 = "...",
  str_homestory_chat_10122006 = "¿Bien? ¿Necesita que enumere las razones una por una sobre por qué es adecuado?",
  str_homestory_chat_10122007 = "No es necesario... Lo consideraré.",
  str_homestory_chat_10123001 = "¿Cómo te llevas aquí?",
  str_homestory_chat_10123002 = "Sí... Aunque hay muchos lugares aquí que no se pueden comparar con Northland...",
  str_homestory_chat_10123003 = "Todavía tiene algo muy encomiable que ofrecer.",
  str_homestory_chat_10123004 = "¿Qué es?",
  str_homestory_chat_10123005 = "El cielo, el aire y el agua aquí están muy limpios.",
  str_homestory_chat_10123006 = "Viviendo aquí, las almas de los Aurorianos tendrán sus almas alimentadas.",
  str_homestory_chat_10123007 = "Eso suena muy parecido a un elogio...",
  str_homestory_chat_10123008 = "¿Qué quieres decir con que no se puede comparar con Northland?",
  str_homestory_chat_10123009 = "Espero que no te detengas en estos pequeños detalles...",
  str_homestory_chat_10123010 = "Y perder de vista lo que es verdaderamente valioso—",
  str_homestory_chat_10123011 = "Creo que una casa limpia nutre el alma de los aurorianos.",
  str_homestory_chat_10123012 = "Espero que siempre guardes la tranquilidad y la pureza de este lugar.",
  str_homestory_chat_10123013 = "Está bien... Claro, lo haré.",
  str_homestory_chat_10124001 = "¿Qué estás mirando?",
  str_homestory_chat_10124002 = "El espejo. Otra casa ha aparecido allí...",
  str_homestory_chat_10124003 = "¿No es eso algo normal?",
  str_homestory_chat_10124004 = "No trate el espejo del lago como un espejo ordinario.",
