  str_homestory_chat_13821002 = "PlayerName, ¿ya se construyó la sala de juegos?",
  str_homestory_chat_13821003 = "¿Eh?",
  str_homestory_chat_13821004 = "¿Quieres construir una sala de juegos?",
  str_homestory_chat_13821005 = "¿No es un hecho el plan de construir una sala de juegos?",
  str_homestory_chat_13821006 = "No lo creo...",
  str_homestory_chat_13821007 = "¡¿Cómo puede no haber una sala de juegos?!",
  str_homestory_chat_13821008 = "¿La máquina de juego no es suficiente para ti?",
  str_homestory_chat_13821009 = "¡Claro que no!",
  str_homestory_chat_13821010 = "¡Solo una sala de juegos puede crear una experiencia de juego inmersiva!",
  str_homestory_chat_13822001 = "Escuché que perdiste en el juego.",
  str_homestory_chat_13822002 = "Es pescar, no jugar.",
  str_homestory_chat_13822003 = "¡Pero no perderé con nadie, ni siquiera en la pesca!",
  str_homestory_chat_13822004 = "¿Qué es lo que estás sosteniendo?",
  str_homestory_chat_13822005 = "Jejeje, mi nuevo invento! Es una máquina de pesca...",
  str_homestory_chat_13822006 = "¡Simplemente colóquelo en el agua y todos los peces en un radio de diez metros se pondrán boca abajo!",
  str_homestory_chat_13822007 = "Y luego solo tengo que sacarlos a todos, y ganaré...",
  str_homestory_chat_13822008 = "Que loca sed de victoria...",
  str_homestory_chat_13822009 = "Voy a confiscar tu máquina de pescar.",
  str_homestory_chat_13822010 = "¡De ninguna manera!",
  str_homestory_chat_13823001 = "¿En un paseo?",
  str_homestory_chat_13823002 = "PlayerName, he caminado por todos los rincones de este lugar.",
  str_homestory_chat_13823003 = "Solo la superficie, por supuesto. Aún queda el metro...",
  str_homestory_chat_13823004 = "¿Qué estás haciendo?",
  str_homestory_chat_13823005 = "Solo explorando y viendo si quedan más elementos tecnológicos divertidos.",
  str_homestory_chat_13823006 = "Después de todo, la tecnología de ustedes Caelestites...",
  str_homestory_chat_13823007 = "¡Pero me aseguraré de avisarte si descubro algo!",
  str_homestory_chat_13823008 = "Tengo un mal presentimiento sobre esto...",
  str_homestory_chat_13823009 = "¿De qué estás hablando?",
  str_homestory_chat_13823010 = "Bueno, ¡me aseguraré de avisarte si descubro algo!",
  str_homestory_chat_13823011 = "...Te creeré.",
  str_homestory_chat_13824001 = "¿Qué estás haciendo?",
  str_homestory_chat_13824002 = "PlayerName, ¿has desarrollado algún juego nuevo recientemente?",
  str_homestory_chat_13824003 = "He terminado todos los juegos. Estoy aburrido...",
  str_homestory_chat_13824004 = "Ven a ayudar si no tienes nada que hacer—",
  str_homestory_chat_13824005 = "Ven a limpiar aquí.",
  str_homestory_chat_13824006 = "¡Guau, el ganador de la Copa del Emperador en realidad está siendo ordenado por Caelestite para limpiar!",
  str_homestory_chat_13824007 = "Regar las flores.",
  str_homestory_chat_13824008 = "¡Vaya, un Caelestite le está ordenando al Oficial Técnico de Illumina que riegue las flores!",
  str_homestory_chat_13824009 = "...",
  str_homestory_chat_13824010 = "Está bien, lo trataré como un juego de simulación.",
  str_homestory_chat_13825001 = "¿Jugando un juego nuevo?",
  str_homestory_chat_13825002 = "Sí. Adivina a qué estoy jugando.",
  str_homestory_chat_13825003 = "En este juego, debes tomar un arma y golpear al enemigo.",
  str_homestory_chat_13825004 = "¡Derrota a los enemigos para obtener materiales para que puedas construir herramientas!",
  str_homestory_chat_13825005 = "¿Podría ser?",
  str_homestory_chat_13825006 = "¿Un juego de rol?",
  str_homestory_chat_13825007 = "¿Un juego de acción?",
  str_homestory_chat_13825008 = "Cerca pero no. Déjame darte una pista más.",
  str_homestory_chat_13825009 = "¡El enemigo es bajo, corpulento y muy duro!",
  str_homestory_chat_13825010 = "¡Eso es bastante extraño!",
  str_homestory_chat_13825011 = "Algo corto, robusto y duro que puede dejar caer materiales...",
  str_homestory_chat_13825012 = "Esperar. ¿Estás minando?",
  str_homestory_chat_13825013 = "¡Correcto!",
  str_homestory_chat_14499999 = "¡Hola! ¿Qué planes tienes para hoy? ¿Necesitas mi supervisión?",
  str_homestory_chat_14401001 = "No por ahora.",
  str_homestory_chat_14401002 = "¡Si tienes planes, debes hacérmelo saber!",
  str_homestory_chat_14401003 = "Te ayudaré con tus planes y haré que salgan a la perfección.",
  str_homestory_chat_14421001 = "¿Cómo te llevas aquí?",
  str_homestory_chat_14421002 = "A Curie le encanta estar aquí.",
  str_homestory_chat_14421003 = "Los dragones son criaturas del cielo después de todo.",
  str_homestory_chat_14421004 = "¿Echa de menos Vivian ¿Te gusta aquí también?",
  str_homestory_chat_14421005 = "PlayerName les ha hecho a todos esta pregunta...",
  str_homestory_chat_14421006 = "Nadie responderá \"no\", ¿verdad?",
  str_homestory_chat_14421007 = "Me gusta mucho este lugar, como Curie.",
  str_homestory_chat_14422001 = "Hola, Vivian.",
  str_homestory_chat_14422002 = "¿Qué haces aquí, PlayerName?",
  str_homestory_chat_14422003 = "Ah, estoy calculando los ingresos recientes por alquiler y gastos.",
  str_homestory_chat_14422004 = "Que tarea tan preocupante...",
  str_homestory_chat_14422005 = "Te ayudare.",
  str_homestory_chat_14422006 = "...",
  str_homestory_chat_14422007 = "Hecho. Ven a echar un vistazo.",
  str_homestory_chat_14422008 = "¡Eso fue rápido!",
  str_homestory_chat_14422009 = "Todo lo que tenga que ver con los cálculos no es demasiado difícil para mí.",
  str_homestory_chat_14423001 = "¿Quieres verme?",
  str_homestory_chat_14423002 = "PlayerName, ¿tiene algún plan reciente para remodelar su casa?",
  str_homestory_chat_14423003 = "¡Por supuesto!",
  str_homestory_chat_14423004 = "He estado pensando tanto en qué cambios hacer que incluso sueño—",
  str_homestory_chat_14423005 = "Tengo tantas ideas que no puedo seguirles el ritmo.",
  str_homestory_chat_14423006 = "No por ahora...",
  str_homestory_chat_14423007 = "Mi inspiración se ha secado...",
  str_homestory_chat_14423008 = "Tómese su tiempo y no se esfuerce demasiado. Un equilibrio entre el trabajo y el juego es lo mejor.",
  str_homestory_chat_14423009 = "Pero si tienes planes, puedes venir a verme cuando quieras.",
  str_homestory_chat_14423010 = "Dame una lista y te ayudaré a hacerlos realidad con la mayor eficiencia.",
  str_homestory_chat_14424001 = "¿Qué ocurre?",
  str_homestory_chat_14424002 = "¡Haré que esos tipos se expliquen!",
  str_homestory_chat_14424003 = "¡¿Cómo terminaron haciendo un desastre con su trabajo?!",
  str_homestory_chat_14424004 = "¿Qué paso?",
  str_homestory_chat_14424005 = "Es el plan de renovación de la casa. Estaba seguro de dividir las tareas...",
  str_homestory_chat_14424006 = "Calculé el tiempo necesario para completarlos y se los asigné a la persona a cargo—",
  str_homestory_chat_14424007 = "Esto debería haber sido un trabajo muy fácil para ellos, pero...",
  str_homestory_chat_14424008 = "¡Nadie pudo terminar a tiempo!",
  str_homestory_chat_14424009 = "No hay necesidad de estar tan tenso.",
  str_homestory_chat_14424010 = "¡No, no puedo soportarlo! ¡Ajustaré cuentas con ellos!",
  str_homestory_chat_14425001 = "¿Cualquier sugerencia?",
  str_homestory_chat_14425002 = "He estado trabajando duro con el plan de renovación de Cloud Gardens.",
  str_homestory_chat_14425003 = "Pero el rendimiento de cada uno es diferente...",
  str_homestory_chat_14425004 = "Por lo tanto, tenemos un sinfín de problemas aquí.",
  str_homestory_chat_14425005 = "¿Cómo qué?",
  str_homestory_chat_14425006 = "Como Dove nunca puede completar su búsqueda de registro a tiempo.",
  str_homestory_chat_14425007 = "Ah... Dove siempre ha sido así.",
  str_homestory_chat_14425008 = "Hemos renunciado a la idea de hacerla menos perezosa.",
  str_homestory_chat_14425009 = "Supongo que debo mejorar mi plan de renovación de Cloud Gardens.",
  str_homestory_chat_14425010 = "¡Esta vez hay que tener en cuenta las características de las personas y los estilos de trabajo!",
  str_homestory_chat_14425011 = "No seas demasiado dura contigo misma, Vivian.",
  str_homestory_chat_12199999 = "Ah, puedo sentir el amor ilimitado en tu tono de tu saludo.",
  str_homestory_chat_12101001 = "No creo que haya...",
  str_homestory_chat_12101002 = "¿Negarías este amor?",
  str_homestory_chat_12101003 = "Mi corazón es desgarrado una vez más por las indiferentes espinas de una rosa...",
  str_homestory_chat_12101004 = "¡Oye! ¿Puedes por favor ser un poco más normal?",
  str_homestory_chat_12101005 = "¡Es solo un saludo!",
  str_homestory_chat_12121001 = "¿Has estado cultivando flores recientemente?",
  str_homestory_chat_12121002 = "Oh sí, PlayerName, ¿te gustaría visitar mi último jardín de rosas?",
  str_homestory_chat_12121003 = "¡Cada flor gira a la espera de tu llegada!",
  str_homestory_chat_12121004 = "Voy a pasar...",
  str_homestory_chat_12121005 = "Tengo demasiadas tareas para completar. Iré a verlo más tarde.",
  str_homestory_chat_12121006 = "Me alivia haber obtenido su promesa de visitarnos.",
  str_homestory_chat_12121007 = "Esperemos que las flores y yo no nos decepcionemos.",
  str_homestory_chat_12121008 = "¡Seguro!",
  str_homestory_chat_12121009 = "Aquí hay mucha luz solar, por lo que puede mostrar sus talentos de jardinería.",
  str_homestory_chat_12121010 = "Ah, qué palabras más reflexivas.",
  str_homestory_chat_12121011 = "Estás bien. Este lugar está lleno de la belleza de la naturaleza—",
  str_homestory_chat_12121012 = "¡Es un gran ajuste para mí!",
  str_homestory_chat_12122001 = "¿Qué te ríes?",
  str_homestory_chat_12122002 = "Tantos niños se han mudado a este lugar...",
  str_homestory_chat_12122003 = "¡Seguro que alegra el corazón!",
  str_homestory_chat_12122004 = "¿Te gustan los niños pequeños?",
  str_homestory_chat_12122005 = "¡Sí! Al ver sus ojos inocentes y rostros sonrosados...",
  str_homestory_chat_12122006 = "¡Me hace pensar en todo tipo de flores!",
  str_homestory_chat_12122007 = "Es una lástima que algunos niños desobedientes sean como flores que han crecido al revés.",
  str_homestory_chat_12122008 = "Cuando encuentro flores como estas, ¡las podo!",
  str_homestory_chat_12122009 = "Uh... ¿Acabo de escuchar algo terrible?",
  str_homestory_chat_11499999 = "PlayerName, es un placer conocerte.",
  str_homestory_chat_11401001 = "Hola, Schwartz.",
  str_homestory_chat_11401002 = "Gracias por invitarme a tu hermosa casa.",
  str_homestory_chat_11401003 = "No lo menciones.",
  str_homestory_chat_11401004 = "Espero que este lugar prospere bajo su gobierno.",
  str_homestory_chat_11421001 = "¿Qué opinas de este lugar?",
  str_homestory_chat_11421002 = "Es ordenado y genial. Parece que te has esforzado mucho en esto.",
  str_homestory_chat_11421003 = "PlayerName, inevitablemente encontrará dificultades al ejecutar este lugar.",
  str_homestory_chat_11421004 = "Si alguna vez necesita ayuda, siempre apartaré tiempo para usted.",
  str_homestory_chat_11421005 = "¡Gracias!",
  str_homestory_chat_11421006 = "Me gustaría pedir su guía en este sentido, Mi Señor.",
  str_homestory_chat_11421007 = "El orden está en el corazón de la gobernabilidad.",
  str_homestory_chat_11421008 = "Puede ser duro, pero es esencial.",
  str_homestory_chat_11421009 = "(Oh hombre... ¿Comenzamos esta discusión ahora...?)",
  str_homestory_chat_11421010 = "Es innecesario en este momento...",
  str_homestory_chat_11421011 = "Ya que todos somos amigos aquí, difícilmente puedo llamarlo \"gobernanza\".",
  str_homestory_chat_11421012 = "Pero espero que tu método pueda traer prosperidad a este lugar.",
  str_homestory_chat_11422001 = "Eres más que bienvenido a visitarnos.",
  str_homestory_chat_11422002 = "Su hogar, como Lumopolis, está bendecido con maravillosos días soleados.",
  str_homestory_chat_11422003 = "Hace un clima perfecto para...",
  str_homestory_chat_11422004 = "¡Pescar!",
  str_homestory_chat_11422005 = "Sentado junto al río, mientras esperas a que tu presa muerda el anzuelo...",
  str_homestory_chat_11422006 = "¿Es esta una actividad relajante popular en estas partes?",
  str_homestory_chat_11422007 = "¿Quiero probar?",
  str_homestory_chat_11422008 = "Me parece bien.",
  str_homestory_chat_11422009 = "¡Correr!",
  str_homestory_chat_11422010 = "Es un deporte para jóvenes.",
  str_homestory_chat_11422011 = "Estoy muy feliz de ver desde el margen.",
  str_homestory_chat_11423001 = "¿Lectura?",
  str_homestory_chat_11423002 = "En un hermoso día soleado como este, la lectura es sin duda el pasatiempo más relajante.",
  str_homestory_chat_11423003 = "PlayerName, Siempre puedo dejarte echar un vistazo si estás interesado.",
  str_homestory_chat_11423004 = "¡Gracias!",
  str_homestory_chat_11423005 = "Cualquier libro que te llame la atención debe ser interesante, ¿verdad?",
  str_homestory_chat_11423006 = "No leo por \"diversión\".",
  str_homestory_chat_11423007 = "Preferiría cuestionar los límites del universo y explorar las profundidades de la naturaleza humana en los libros.",
  str_homestory_chat_11423008 = "Pero es genial si puedes divertirte con él.",
  str_homestory_chat_11423009 = "Está bien...",
  str_homestory_chat_11423010 = "Me encantaría leer y tomarme un descanso, pero estoy saturado de trabajo...",
  str_homestory_chat_11423011 = "Siempre puedes confiarme algo si no puedes manejarlo.",
  str_homestory_chat_12999999 = "Oh, realmente eres tú...",
  str_homestory_chat_12921001 = "Ah, sí.",
  str_homestory_chat_12921002 = "He sentido tu llegada en el viento.",
  str_homestory_chat_12921003 = "¿Eso suena increíble?",
  str_homestory_chat_12921004 = "Tienes un aura peculiar.",
  str_homestory_chat_12922001 = "Pareces muy relajado.",
  str_homestory_chat_12922002 = "Me he dado cuenta de que... algo interesante ocurrirá si tomo el sol en una jaula...",
  str_homestory_chat_12922003 = "¿Qué es?",
  str_homestory_chat_12922004 = "Algunas partes de tu cara se sentirán calientes mientras que el resto permanece frío.",
  str_homestory_chat_12922005 = "¿Porqué crees?",
  str_homestory_chat_12922006 = "tampoco estoy seguro...",
  str_homestory_chat_12922007 = "No lo pensemos. Pensar es demasiado agotador.",
  str_homestory_chat_12922008 = "¿Es por la jaula?",
  str_homestory_chat_12922009 = "La jaula proyecta una sombra sobre tu rostro, por lo que las áreas donde no llega la luz se enfriarán.",
  str_homestory_chat_12922010 = "Tal vez, tienes razón.",
  str_homestory_chat_12922011 = "Pero no quiero analizar las cosas ya que pensar es demasiado agotador.",
  str_homestory_chat_12923001 = "Parece que te gusta estar aquí.",
  str_homestory_chat_12923002 = "Cálidos rayos de sol...",
  str_homestory_chat_12923003 = "Uf... Así es... Me siento como hilos de seda...",
  str_homestory_chat_12923004 = "Uf... Sí, no estoy dormido...",
  str_homestory_chat_12923005 = "(Será mejor que no perturbe su sueño.)",
  str_homestory_chat_12924001 = "¿Qué estás haciendo?",
  str_homestory_chat_12924002 = "¿Puedes oír eso?",
  str_homestory_chat_12924003 = "Este lugar produce una abundancia de sonidos...",
  str_homestory_chat_12924004 = "en una corriente continua desde el arroyo, el bosque y el valle.",
  str_homestory_chat_12924005 = "Eso es correcto.",
  str_homestory_chat_12924006 = "Lo que más se escucha en Lumopolis es el sonido del viento y los aurorianos.",
  str_homestory_chat_12924007 = "En comparación, prefiero mucho los sonidos aquí.",
  str_homestory_chat_12924008 = "Ni siquiera lo noté.",
  str_homestory_chat_12924009 = "Ahora que lo mencionas, puedo detectarlos...",
  str_homestory_chat_12924010 = "Escuchar puede traer una felicidad inesperada.",
  str_homestory_chat_12925001 = "¿Madera?",
  str_homestory_chat_12925002 = "Ah, de hecho, la madera. ¿Tienes algo ligero y resistente?",
  str_homestory_chat_12925003 = "Um... ¿Para qué planeas usar esta madera de repente?",
  str_homestory_chat_12925004 = "Quiero remodelar esta jaula, es demasiado grande y pesada.",
  str_homestory_chat_12925005 = "Bien, si la madera fuera más ligera, te facilitaría las cosas.",
  str_homestory_chat_12925006 = "Sin embargo, el tipo de madera que mencionaste parece bastante difícil de encontrar en Cloud Gardens.",
  str_homestory_chat_12925007 = "Los árboles aquí son un poco extraños, por lo que es difícil convertirlos en madera.",
  str_homestory_chat_12925008 = "Y... es posible que esos Chubbs tampoco estén de acuerdo en cortarlo en pedazos.",
  str_homestory_chat_12926001 = "¿En algún lugar alto?",
  str_homestory_chat_12926002 = "Estoy buscando un lugar pintoresco en Cloud Gardens. Después de pensarlo bien...",
  str_homestory_chat_12926003 = "Un lugar más alto sería bueno, y sería aún mejor si pudiera pasar por alto todos los Jardines de las Nubes.",
  str_homestory_chat_12926004 = "Ah... Entonces, quería preguntarte si existe un lugar así.",
  str_homestory_chat_12926005 = "Conozco un lugar.",
  str_homestory_chat_12926006 = "¿Quizás la Torre Jacinto serviría?",
  str_homestory_chat_12926007 = "¿Pero Chubb estará de acuerdo?",
  str_homestory_chat_12926008 = "Definitivamente no.",
  str_homestory_chat_12926009 = "No me parece.",
  str_homestory_chat_12926010 = "Ah... supongo que es imposible entonces.",
  str_homestory_chat_12926011 = "¿Qué estabas planeando hacer?",
  str_homestory_chat_12926012 = "Quiero colgar mi jaula en lo alto y disfrutar de la sensación de que se mece suavemente con la brisa.",
  str_homestory_chat_12926013 = "Sería muy relajante y más fácil para mí conciliar el sueño.",
  str_homestory_chat_12926014 = "Claro, pero puede haber fuertes vientos en altitudes más altas, por lo que la jaula podría ser propensa a ser sacudida violentamente.",
  str_homestory_chat_12926015 = "Tienes razón. Eso tiene sentido.",
  str_homestory_chat_12926016 = "Por lo tanto, sería mejor dejar las cosas como están.",
  str_homestory_chat_12699999 = "¡Ay! No te acerques demasiado.",
  str_homestory_chat_12601001 = "¿Por qué no?",
  str_homestory_chat_12601002 = "Mi poder... puede quemarte...",
  str_homestory_chat_12601003 = "Todo está bien. Seré cuidadoso.",
  str_homestory_chat_12601004 = "Con suerte... Esperemos no lastimarte.",
  str_homestory_chat_12621001 = "¿Quieres conversar?",
  str_homestory_chat_12621002 = "¿Charlar?",
  str_homestory_chat_12621003 = "¿Qué hay para charlar sobre...? Mmm... no estoy seguro...",
  str_homestory_chat_12621004 = "¿Como si algo hubiera pasado recientemente?",
  str_homestory_chat_12621005 = "No recordaré nada sin sentido...",
  str_homestory_chat_12621006 = "Pero, ¿qué se considera significativo...? No estoy seguro...",
  str_homestory_chat_12621007 = "¿Te gusta algún paisaje que hayas visto recientemente?",
  str_homestory_chat_12621008 = "¿Te refieres a las sombras negras en el cañón anti-explosión...?",
  str_homestory_chat_12621009 = "Será encendido por mis llamas de vez en cuando...",
  str_homestory_chat_12621010 = "Um... ¿Seguro?",
  str_homestory_chat_12622001 = "¿Que acabas de decir?",
  str_homestory_chat_12622002 = "...Qué decir...? Vamos a ver...",
  str_homestory_chat_12622003 = "¡O-Oye!",
  str_homestory_chat_12622004 = "...¿Qué ocurre?",
  str_homestory_chat_12622005 = "Te quedaste dormido mientras hablabas.",
  str_homestory_chat_12622006 = "...No me quedé dormido... Estaba... solo pensando...",
  str_homestory_chat_12622007 = "Debe ser difícil hablar con alguien como yo, ¿verdad...?",
  str_homestory_chat_12622008 = "¡Sip!",
  str_homestory_chat_12622009 = "Cuando estés atrapado en tu propio mundo, míranos de vez en cuando...",
  str_homestory_chat_12622010 = "No es tan difícil, ¡así que pruébalo!",
  str_homestory_chat_12622011 = "Realmente no...",
  str_homestory_chat_12622012 = "El silencio ocasional permite relajarse...",
  str_homestory_chat_12622013 = "Disfruten este momento juntos entonces.",
  str_homestory_chat_12623001 = "Hablemos de su Anillo de Fuego.",
  str_homestory_chat_12623002 = "¿Esta cosa? Está conectado con mi pasado...",
  str_homestory_chat_12623003 = "Recordar el pasado es algo doloroso...",
  str_homestory_chat_12623004 = "E-Entonces no hablemos de eso.",
  str_homestory_chat_12623005 = "Pero saborear el dolor no es nada inusual para mí.",
  str_homestory_chat_12623006 = "Tampoco es gran cosa hablar contigo sobre eso.",
  str_homestory_chat_12624001 = "¿Pasó algo interesante?",
  str_homestory_chat_12624002 = "...¿De qué quieres hablar?",
  str_homestory_chat_12624003 = "escuché eso Vice y los demás accidentalmente un mantel en llamas en un picnic.",
  str_homestory_chat_12624004 = "Usaste tu Anillo de Fuego para ayudarlos a apagar el fuego.",
  str_homestory_chat_12624005 = "Si...",
  str_homestory_chat_12624006 = "Tu anillo de fuego puede absorber las llamas...",
  str_homestory_chat_12624007 = "¡Eso es tan cool!",
  str_homestory_chat_12624008 = "¿Está? Ah... Gracias por el cumplido.",
  str_homestory_chat_12625001 = "¿Cómo va todo?",
  str_homestory_chat_12625002 = "No muy bueno...",
  str_homestory_chat_12625003 = "¿Hay algo que pueda hacer mejor?",
  str_homestory_chat_12625004 = "No es que... estoy un poco confundido...",
  str_homestory_chat_12625005 = "Hay tantas plantas y árboles en Eraveil...",
  str_homestory_chat_12625006 = "Si me quedo dormido sin cuidado... podría...",
  str_homestory_chat_12625007 = "Prende fuego a la hierba o a los árboles...",
  str_homestory_chat_12625008 = "¡¿Qué?!",
  str_homestory_chat_12625009 = "Aunque usé mi Anillo de Fuego para apagar el fuego cada vez...",
  str_homestory_chat_12625010 = "La hierba todavía estaba quemada...",
  str_homestory_chat_12625011 = "No te preocupes.",
  str_homestory_chat_12625012 = "¡La hierba volverá a crecer!",
  str_homestory_chat_12625013 = "Mientras estés a salvo y los edificios no se quemen, no hay problema.",
  str_homestory_chat_14699999 = "¿Cómo estás?",
  str_homestory_chat_14601001 = "hola donde estan los demas",
  str_homestory_chat_14601002 = "Están ocupados con algo.",
  str_homestory_chat_14601003 = "¿No tienes nada que hacer?",
  str_homestory_chat_14601004 = "...Adiós.",
  str_homestory_chat_14621001 = "¿Has comido?",
  str_homestory_chat_14621002 = "Yo no como verduras ♪",
  str_homestory_chat_14621003 = "Ya que odio el sabor amargo ♪",
  str_homestory_chat_14621004 = "¡Las verduras son buenas para ti!",
  str_homestory_chat_14621005 = "Gozo de buena salud, mi querido Navegante.",
  str_homestory_chat_14621006 = "Tú, por otro lado, necesitas comer más vegetales, Unhealthy Navigator.",
  str_homestory_chat_14621007 = "¡Mírate! Realmente podrías usar algunas verduras en tu sistema.",
  str_homestory_chat_14622001 = "¿Has leído algún libro últimamente?",
  str_homestory_chat_14622002 = "Necesito leer libros de cuentos ♪",
  str_homestory_chat_14622003 = "Porque esos días largos son difíciles de soportar ♪",
  str_homestory_chat_14622004 = "Ustedes pueden encontrar algo que hacer.",
  str_homestory_chat_14622005 = "Mi querido Navegante, te insto a que leas más libros de cuentos...",
  str_homestory_chat_14622006 = "para desarrollar una virtud para ayudar a los demás!",
  str_homestory_chat_14622007 = "¡Te ayudaré a encontrarlo en un momento!",
  str_homestory_chat_14622008 = "Si tomas acción en un momento ♪",
  str_homestory_chat_14622009 = "Lo olvidarás después de un tiempo ♪",
  str_homestory_chat_14623001 = "¿Que tal aquí?",
  str_homestory_chat_14623002 = "¿Me estás preguntando si me gusta aquí ♪",
  str_homestory_chat_14623003 = "Por supuesto, me encanta aquí ♪",
  str_homestory_chat_14623004 = "¡Gracias por tu afirmación!",
  str_homestory_chat_14623005 = "Estoy diciendo las palabras que amas escuchar ♪",
  str_homestory_chat_14623006 = "entiendes ♪",
  str_homestory_chat_14623007 = "...",
  str_homestory_chat_14623008 = "Pero... hay momentos en que es verdad ♪",
  str_homestory_chat_14623009 = "Cuando la verdad también se dice ♪",
  str_homestory_chat_14624001 = "¿Qué estás buscando?",
  str_homestory_chat_14624002 = "¡Falta mi libro!",
  str_homestory_chat_14624003 = "¿Lo has visto, Navegante?",
  str_homestory_chat_14624004 = "Justo allí.",
  str_homestory_chat_14624005 = "Deberías ir más allá y ayudarme ♪",
  str_homestory_chat_14624006 = "Encuentra el libro juntos ♪",
  str_homestory_chat_14624007 = "... ¿Puedo negarme?",
  str_homestory_chat_14624008 = "no lo veo",
  str_homestory_chat_14624009 = "La vista del navegante no es muy buena ♪",
  str_homestory_chat_14624010 = "Tal vez sea porque te levantaste muy temprano ♪",
  str_homestory_chat_14624011 = "Levántate muy temprano ♪",
  str_homestory_chat_14624012 = "El cabello se caerá ♪",
  str_homestory_chat_14624013 = "¡Tú!",
  str_homestory_chat_14625001 = "¡Yo... tengo cosas que hacer!",
  str_homestory_chat_14625002 = "¡Adiós!",
  str_homestory_chat_14625003 = "El Navegante huyó en confusión.",
  str_homestory_chat_14625004 = "El Navegante se sintió culpable.",
  str_homestory_chat_14625005 = "¡No estoy!",
  str_homestory_chat_14625006 = "¡Solo necesito seguir construyendo Eraveil!",
  str_homestory_chat_14625007 = "Ocupado como una abeja.",
  str_homestory_chat_14625008 = "Pero no hay meta que alcanzar.",
  str_homestory_chat_14625009 = "No te enojes con los niños, no...",
  str_homestory_chat_14625010 = "El Navegante pretende ser maduro.",
  str_homestory_chat_14625011 = "no es viejo...",
  str_homestory_chat_14625012 = "Sin embargo, no le queda mucho pelo.",
  str_homestory_chat_14625013 = "¡Por qué tú...!",
  str_homestory_chat_12399999 = "A-¿Me estás saludando? E-Entonces... ¡Hola!",
  str_homestory_chat_12301001 = "No hay necesidad de estar tan nervioso.",
  str_homestory_chat_12301002 = "O-Está bien, necesito reunir mi coraje...",
  str_homestory_chat_12301003 = "Hola, PlayerName!!",
  str_homestory_chat_12301004 = "¡Guau! ¡Eso es ruidoso!",
  str_homestory_chat_12321001 = "Puedes tocar un instrumento musical, ¿verdad?",
  str_homestory_chat_12321002 = "Escuché que eres un gran clarinetista.",
  str_homestory_chat_12321003 = "¿Eh? ¿Q-Qué? ¿Quieres que toque para la fiesta?",
  str_homestory_chat_12321004 = "Todo el mundo espera con ansias tu actuación.",
  str_homestory_chat_12321005 = "Pero.",
  str_homestory_chat_12321006 = "¿No quieres?",
  str_homestory_chat_12321007 = "N-No, solo estoy un poco nervioso.",
  str_homestory_chat_12321008 = "Pero si todos están deseando que llegue, haré lo mejor que pueda...",
  str_homestory_chat_12321009 = "¡Cree en ti mismo y estarás bien!",
  str_homestory_chat_12321010 = "¿Por qué no le das una oportunidad?",
  str_homestory_chat_12321011 = "O-Está bien, ya que es una invitación de PlayerName...",
  str_homestory_chat_12321012 = "Daré lo mejor de mí.",
  str_homestory_chat_12321013 = "¡Esperaremos tu actuación!",
  str_homestory_chat_12322001 = "Tengo un poco de sed.",
  str_homestory_chat_12322002 = "PlayerName, d-quieres probar un poco de café?",
  str_homestory_chat_12322003 = "Está bien si no quieres... Siempre puedo tirarlo...",
  str_homestory_chat_12322004 = "¡Claro que me gustaría un poco!",
  str_homestory_chat_12322005 = "Pero... si sabe mal...",
  str_homestory_chat_12322006 = "¿Por qué tirarlo?",
  str_homestory_chat_12322007 = "Estaba practicando mis habilidades para preparar café antes, así que he hecho un montón...",
  str_homestory_chat_12322008 = "Um... Creo que es mejor verterlos ya que pueden tener un sabor horrible...",
  str_homestory_chat_12322009 = "¡Espera!",
  str_homestory_chat_12322010 = "No puedo diferenciar entre un buen y un mal café, así que no te preocupes.",
  str_homestory_chat_12322011 = "Es bueno mientras me mantenga despierto.",
  str_homestory_chat_12322012 = "Está bien...",
  str_homestory_chat_12323001 = "¿Qué tal?",
  str_homestory_chat_12323002 = "Es tan brillante...",
  str_homestory_chat_12323003 = "El sol aquí es demasiado brillante...",
  str_homestory_chat_12323004 = "Si tan solo hubiera un lugar más sombrío...",
  str_homestory_chat_12323005 = "¿La sombra te hará sentir mejor?",
  str_homestory_chat_12323006 = "¿Supongo...?",
  str_homestory_chat_12324001 = "¿Con quién estás hablando?",
  str_homestory_chat_12324002 = "Está bien, lo entiendo... ¡Uf, lo siento!",
  str_homestory_chat_12324003 = "Son los Anton... ¿Quieres charlar con ellos?",
  str_homestory_chat_12324004 = "No hay necesidad...",
  str_homestory_chat_12324005 = "Ellos... pueden dar bastante miedo a veces...",
  str_homestory_chat_12324006 = "Pero los Anton son todos buenos niños, ¡créeme!",
  str_homestory_chat_12324007 = "¡Está bien!",
  str_homestory_chat_12324008 = "E-Entonces los llamaré por ti...",
  str_homestory_chat_12325001 = "¿Qué estás ocupado haciendo?",
  str_homestory_chat_12325002 = "Oye, PlayerName...",
  str_homestory_chat_12325003 = "Me he mudado por un tiempo. Muchas personas me han ayudado...",
  str_homestory_chat_12325004 = "Me gustaría preparar un poco de café para todos. Pero yo...",
  str_homestory_chat_12325005 = "¿Hay alguna dificultad que está enfrentando?",
  str_homestory_chat_12325006 = "Sí... yo... no sé si les gusta el café...",
  str_homestory_chat_12325007 = "Así que sigo pensando...",
  str_homestory_chat_12325008 = "¡Relájate, Connolly!",
  str_homestory_chat_12325009 = "Siempre has estado haciendo un gran café. Además...",
  str_homestory_chat_12325010 = "¡Es el corazón de Connolly lo que realmente importa!",
  str_homestory_chat_13699999 = "Estoy tan aburrida... ¿Finalmente vas a encontrar algo para que yo haga?",
  str_homestory_chat_13601001 = "No, solo estoy aquí para decir hola.",
  str_homestory_chat_13601002 = "¿Solo para saludar?",
  str_homestory_chat_13601003 = "... No debí animarme a responder tu aburrida pregunta.",
  str_homestory_chat_13621001 = "¿Cómo te va últimamente?",
  str_homestory_chat_13621002 = "La comida aquí es tan sosa que ni siquiera vale la pena dársela a los perros.",
  str_homestory_chat_13621003 = "¿Qué quieres comer?",
  str_homestory_chat_13621004 = "Cualquier cosa.",
  str_homestory_chat_13621005 = "¿Quién es el que desprecia la comida en este momento?",
  str_homestory_chat_13621006 = "De todos modos, solo agregue más especias, como chile y sal.",
  str_homestory_chat_13621007 = "¿Sólo esta?",
  str_homestory_chat_13621008 = "Mi perro y yo tenemos requisitos muy bajos.",
  str_homestory_chat_13622001 = "¿Entonces, qué estás haciendo?",
  str_homestory_chat_13622002 = "...Tranquilo. Las sombras están descansando.",
  str_homestory_chat_13622003 = "¿Las sombras también necesitan descansar?",
  str_homestory_chat_13622004 = "Sí.",
  str_homestory_chat_13622005 = "¿Ninguna otra razón?",
  str_homestory_chat_13622006 = "...No.",
  str_homestory_chat_13622007 = "Simplemente no quieres hablar conmigo.",
  str_homestory_chat_13622008 = "Puedes interpretarlo de esa manera por ahora.",
  str_homestory_chat_13622009 = "Ven a buscarme cuando las sombras estén bien descansadas.",
  str_homestory_chat_13623001 = "Hola, Hydrad.",
  str_homestory_chat_13623002 = "Bastantes de las personas aquí tienen perros.",
  str_homestory_chat_13623003 = "¿Tienes algún problema con eso?",
  str_homestory_chat_13623004 = "¿Porque los perros pueden morder?",
  str_homestory_chat_13623005 = "No.",
  str_homestory_chat_13623006 = "¿Porque los perros pueden ladrar?",
  str_homestory_chat_13623007 = "Todos los perros volubles ladran.",
  str_homestory_chat_13623008 = "Entonces, ¿con qué tienes un problema?",
  str_homestory_chat_13623009 = "¿Cuándo he dicho que tengo un problema con la gente que tiene perros?",
  str_homestory_chat_13623010 = "...",
  str_homestory_chat_14999999 = "Jefe, ¿qué necesita? ¿Necesitas que golpee a alguien por ti?",
  str_homestory_chat_14901001 = "Sólo aquí para decir hola.",
  str_homestory_chat_14901002 = "¿Ah, entonces es así?",
  str_homestory_chat_14901003 = "¡No olvides avisarme cuando estés a punto de golpear a alguien!",
  str_homestory_chat_14921001 = "¿Necesitas ayuda?",
  str_homestory_chat_14921002 = "¿Ve alguna mota de polvo en mi armadura, jefe?",
  str_homestory_chat_14921003 = "No, está muy limpio.",
  str_homestory_chat_14921004 = "¿No hay ninguno?",
  str_homestory_chat_14921005 = "Pensar que estaba ansioso por pulir mi armadura para pasar el tiempo.",
  str_homestory_chat_14921006 = "¿Estas aburrido?",
  str_homestory_chat_14921007 = "No hay nadie que pueda pelear conmigo aquí.",
  str_homestory_chat_14921008 = "Por supuesto, estoy aburrido.",
  str_homestory_chat_14921009 = "Hay algunos aquí, en realidad.",
  str_homestory_chat_14921010 = "Déjame ver... Gracias, jefe.",
  str_homestory_chat_14922001 = "no te ves bien...",
  str_homestory_chat_14922002 = "Jefe, tengo tanta hambre...",
  str_homestory_chat_14922003 = "Llevo varios días seguidos comiendo verdura...",
  str_homestory_chat_14922004 = "Las verduras son buenas para ti.",
  str_homestory_chat_14922005 = "Jefe, para la gente, como yo, que no puede vivir sin carne...",
  str_homestory_chat_14922006 = "¿No crees que esas palabras son demasiado crueles?",
  str_homestory_chat_14922007 = "¡Yo tampoco quiero comer verduras!",
  str_homestory_chat_14922008 = "¡Pero estoy casi arruinado, así que tendrás que soportarlo!",
  str_homestory_chat_14922009 = "¡Jefe, lo estamos pasando tan mal!",
  str_homestory_chat_14951001 = "Esos son unos camarones enormes...",
  str_homestory_chat_14951002 = "¿¡Tú también los viste, Kingpin of Cloud Gardens!?",
  str_homestory_chat_14951003 = "no me llames asi...",
  str_homestory_chat_14951004 = "¡Muy bien, entonces! ¡Jefe, apuesto a que no esperaba ver camarones enormes como esos aquí!",
  str_homestory_chat_14951005 = "¡Son gigantes! Si los vendes en Umbraton, ¡harás un paquete!",
  str_homestory_chat_14951006 = "¿En serio?",
  str_homestory_chat_14951007 = "¡Así es! Estos camarones son del tipo súper agresivo, por lo que son muy divertidos de ver.",
  str_homestory_chat_14951008 = "¡Cuando los vi golpearse entre sí, fue como ver un par de tortugas enormes en la temporada de apareamiento! Se parecían a mis dos cuchillas, ¡lo hicieron!",
  str_homestory_chat_14951009 = "Dios mío, hace que me piquen los dedos... No puedo evitar preguntarme si tendría una oportunidad contra ellos...",
  str_homestory_chat_14951010 = "Probablemente no sea una buena idea, sois especies diferentes...",
  str_homestory_chat_14951011 = "Supongo que todo lo que puedo hacer es mirarlos... Hay mucha gente en Umbraton que no se cansa de ellos.",
  str_homestory_chat_14951012 = "¡A veces sus batallas son realmente emocionantes!",
  str_homestory_chat_14951013 = "¿Todavía son populares en Umbraton?",
  str_homestory_chat_14951014 = "(Podríamos hacer una fortuna...)",
  str_homestory_chat_14951015 = "¿Pareces estar bastante familiarizado con este tipo de camarones?",
  str_homestory_chat_14951016 = "¡Naturalmente! En primer lugar, se llaman \"gambas emperador\".",
  str_homestory_chat_14951017 = "En segundo lugar, los he encontrado al acecho en varios lugares hasta ahora.",
  str_homestory_chat_14951018 = "¿¡Varios lugares!?",
  str_homestory_chat_14951019 = "Y hay diferentes tipos.",
  str_homestory_chat_14951020 = "¿Muchos tipos diferentes?",
  str_homestory_chat_14951021 = "En realidad, sólo hay dos tipos. El más común es el azul.",
  str_homestory_chat_14951022 = "Correcto, ese es el tipo que vi.",
  str_homestory_chat_14951023 = "Por supuesto que es. Además del azul, también existe una variedad marrón. Ahora, eso es lo que uno podría llamar un producto de alta calidad.",
  str_homestory_chat_14951024 = "Pero es mucho más difícil de encontrar...",
  str_homestory_chat_14951025 = "¿Donde puedo encontrarlos?",
  str_homestory_chat_14951026 = "Primero, necesitas el camarón peleador azul, o como se le conoce oficialmente, el camarón emperador cobalto.",
  str_homestory_chat_14951027 = "Si me traes uno de esos, puedes cambiarlo por los lugares de pesca del camarón marrón más grande.",
  str_homestory_chat_14951028 = "¿Eso es todo lo que me vas a dar?",
  str_homestory_chat_14951029 = "¡Oye, has aprendido a regatear! Por supuesto, el jefe de Cloud Gardens merece una bonificación especial adicional.",
  str_homestory_chat_14951030 = "¡Tenga la seguridad de que me aseguraré de que obtenga lo que se merece!",
  str_homestory_chat_14951031 = "Pero, ¿dónde puedo pescar camarones emperador cobalto?",
  str_homestory_chat_14951032 = "¿Eh? ¿No acabas de decir que viste algunos?",
  str_homestory_chat_14951033 = "Pero, ¿no es mejor tener algunos lugares de pesca más bajo la manga, por si acaso?",
  str_homestory_chat_14951034 = "¡Está bien! Conozco muchos lugares de pesca. Deberías poder encontrar algunas gambas emperador cobalto.",
  str_homestory_chat_14951035 = "Por supuesto, con tu talento, ¡no debería ser ningún problema! Luego, ¡podrás canjearlos por un lugar de pesca \"Gamba emperador ocre\"!",
  str_homestory_chat_14951036 = "Entonces, ese es el nombre correcto para los camarones marrones...",
  str_homestory_chat_14951037 = "¿Todo claro ahora? ¡Con tu habilidad, puedes ganar mucho dinero! Y yo también puedo...",
  str_homestory_chat_14951038 = "Ejem.",
  str_homestory_chat_14951039 = "Entonces, Kingpin de Cloud Gardens, ¿tienes más preguntas?",
  str_homestory_chat_14951040 = "Quiero pescar langostinos emperador ocre.",
  str_homestory_chat_14951041 = "Entonces, ¿trajiste camarones emperador cobalto?",
  str_homestory_chat_14951042 = "Sip.",
  str_homestory_chat_14951043 = "¡Déjame ver la mercancía!",
  str_homestory_chat_14951044 = "Dar Langostino Emperador Cobalto ({1}/1).",
  str_homestory_chat_14951045 = "¡Lindo! Te diré dónde está el lugar de pesca ahora... ¡Lo he marcado en tu mapa!",
  str_homestory_chat_14951046 = "Dejame pensarlo.",
  str_homestory_chat_14951047 = "No...",
  str_homestory_chat_14951048 = "Bueno, supongo que eso es muy malo. La información no viene gratis. Esperaré hasta que consigas uno.",
  str_homestory_chat_14951049 = "Bien entonces.",
  str_homestory_chat_14951050 = "Estoy aquí por los camarones.",
  str_homestory_chat_14951051 = "Bueno, en Umbraton, ¡hay un cargo por compartir este tipo de información!",
  str_homestory_chat_14951052 = "¿No es este Jardín de Nubes...?",
  str_homestory_chat_14951053 = "El trato es que puedes intercambiar un langostino emperador de cobalto por información sobre un lugar de pesca donde puedes pescar langostinos emperador de Oche.",
  str_homestory_chat_14951054 = "Por supuesto, te daré algunas recompensas adicionales por ello. ¿Entiendo?",
  str_homestory_chat_14951055 = "Entiendo.",
  str_homestory_chat_14951056 = "Quiero pescar langostinos emperador cobalto.",
  str_homestory_chat_14951057 = "¿Estás seguro?",
  str_homestory_chat_14951058 = "Es correcto.",
  str_homestory_chat_14951059 = "¡Bueno! Lo he marcado. ¡Recuerde, puede canjearlo por información sobre un lugar de pesca de langostino emperador ocre!",
  str_homestory_chat_14951060 = "¿Entiendo? ¡Entonces me iré ahora!",
  str_homestory_chat_14951061 = "Todavía tengo que pensar en ello...",
  str_homestory_chat_14952001 = "Quiero saber acerca de esos \"Langostinos Emperador\".",
  str_homestory_chat_14952002 = "Está bien, está bien... ¿Quién murió y te convirtió en el señor de Cloud Gardens? ¡Pregunta lejos!",
  str_homestory_chat_14952003 = "¿Entonces, qué es lo que quieres saber?",
  str_homestory_chat_14952004 = "Quiero pescar langostinos emperador ocre.",
  str_homestory_chat_14952005 = "Entonces, ¿trajiste camarones emperador cobalto?",
  str_homestory_chat_14952006 = "Sip.",
  str_homestory_chat_14952007 = "¡Déjame ver la mercancía!",
  str_homestory_chat_14952008 = "Dar Langostino Emperador Cobalto ({1}/1).",
  str_homestory_chat_14952009 = "¡Lindo! Te diré dónde está el lugar de pesca ahora... ¡Lo he marcado en tu mapa!",
  str_homestory_chat_14952010 = "Dejame pensarlo.",
  str_homestory_chat_14952011 = "No...",
  str_homestory_chat_14952012 = "Bueno, supongo que eso es muy malo. La información no viene gratis. Esperaré hasta que consigas uno.",
  str_homestory_chat_14952013 = "Bien entonces.",
  str_homestory_chat_14952014 = "Estoy aquí por los camarones.",
  str_homestory_chat_14952015 = "De nuevo...? ¡Mi boca ya está tan seca como una cuchilla oxidada!",
  str_homestory_chat_14952016 = "Lo lamento. Solo quiero entender un poco más.",
  str_homestory_chat_14952017 = "Bueno, puedes intercambiar un langostino emperador de cobalto por información sobre un lugar de pesca donde puedes pescar langostinos emperador de Oche. ¿Recordar?",
  str_homestory_chat_14952018 = "Lo recuerdo.",
