  str_homestory_chat_14952021 = "Quiero pescar langostinos emperador cobalto.",
  str_homestory_chat_14952022 = "¿Estás seguro?",
  str_homestory_chat_14952023 = "Estoy seguro de que.",
  str_homestory_chat_14952024 = "Te lo marco. Además, después de pescar uno, ¡puedes canjearlo por información sobre un lugar de pesca de langostino emperador ocre!",
  str_homestory_chat_14952025 = "Recuerdo...",
