  str_homestory_chat_14952028 = "¡Entonces sal de aquí!",
  str_homestory_chat_14953001 = "Ese camarón...",
  str_homestory_chat_14953002 = "De nuevo, ¿eh...? ¡He marcado todos los lugares donde puedes pescar camarones!",
  str_homestory_chat_14953003 = "¿Algo más?",
  str_homestory_chat_14953004 = "Estoy aquí por los camarones.",
  str_homestory_chat_14953005 = "*suspiro* Está bien, está bien. Después de todo, tú eres el jefe aquí.",
  str_homestory_chat_14953006 = "Primero, captura el camarón emperador cobalto y luego dámelo.",
  str_homestory_chat_14953007 = "Entonces te diré dónde está el lugar de pesca y te daré algo extra.",
  str_homestory_chat_14953008 = "¿Crees que serás capaz de recordar esta vez?",
  str_homestory_chat_14953009 = "¡Gracias!",
  str_homestory_chat_14953010 = "Me temo que no.",
  str_homestory_chat_14953011 = "Excelente. ¡Corre, entonces!",
  str_homestory_chat_11899999 = "¿Qué? Deja de molestarme con cosas triviales. ¿No ves que estoy ocupado?",
  str_homestory_chat_11801001 = "solo digo hola!",
  str_homestory_chat_11801002 = "Lo tengo.",
  str_homestory_chat_11801003 = "Pero no creo que vaya a haber ningún \"evento importante\" aquí.",
  str_homestory_chat_11801004 = "Así es.",
  str_homestory_chat_11821001 = "Hola. ¿Me estás buscando?",
  str_homestory_chat_11821002 = "PlayerName, debes escuchar mi nueva canción.",
  str_homestory_chat_11821003 = "¿Puedo decir no?",
  str_homestory_chat_11821004 = "¿De verdad te atreves a negarte? ¡Por supuesto que no!",
  str_homestory_chat_11821005 = "¡Parece que hay una necesidad apremiante de mejorar tu gusto musical!",
  str_homestory_chat_11821006 = "Vamos a oírlo.",
  str_homestory_chat_11821007 = "Ah, ciertamente tienes un gusto tan refinado.",
  str_homestory_chat_11821008 = "Pero necesito una banda.",
  str_homestory_chat_11821009 = "Te avisaré una vez que todo esté listo.",
  str_homestory_chat_11822001 = "Parece que no hay nada que hacer.",
  str_homestory_chat_11822002 = "¡Así es! Dios, soy tan aburrido!",
  str_homestory_chat_11822003 = "Yo también...",
  str_homestory_chat_11822004 = "¿Tienes alguna idea brillante?",
  str_homestory_chat_11822005 = "¡En momentos como estos necesitas un concierto mental!",
  str_homestory_chat_11822006 = "¡Mi guitarra eléctrica acabará con todo aburrimiento!",
  str_homestory_chat_11822007 = "Cómo es eso, PlayerName? No es mala idea, ¿eh?",
  str_homestory_chat_11822008 = "Eh... lo pensaré.",
  str_homestory_chat_11823001 = "¿De qué estás hablando?",
  str_homestory_chat_11823002 = "Melón, mayonesa...",
  str_homestory_chat_11823003 = "¿Es eso un encantamiento?",
  str_homestory_chat_11823004 = "¡No, son las cosas más deliciosas de este mundo!",
  str_homestory_chat_11823005 = "Rocíe mayonesa sobre los trozos fríos de melón...",
  str_homestory_chat_11823006 = "Todas tus preocupaciones se desvanecerán con solo un bocado...",
  str_homestory_chat_11823007 = "¿Es realmente tan bueno?",
  str_homestory_chat_11823008 = "¿Pruebo algunos también?",
  str_homestory_chat_11823009 = "No tengas esto delante de mí, o temo robártelos.",
  str_homestory_chat_11824001 = "¿Cómo va todo?",
  str_homestory_chat_11824002 = "PlayerName, ¿podrías construir un escenario lo suficientemente alto como para ver todo el Eraveil?",
  str_homestory_chat_11824003 = "¿Vaya? ¿Para qué sirve?",
  str_homestory_chat_11824004 = "¡El mejor concierto de metal, por supuesto!",
  str_homestory_chat_11824005 = "Mi guitarra eléctrica les dirá a todos de qué se trata realmente la música.",
  str_homestory_chat_11824006 = "No tengo nada en contra de esta idea, siempre y cuando estés de acuerdo en compartirla con Bárbara...",
  str_homestory_chat_10899999 = "¿Estás aquí? ¿Algo necesita arreglarse?",
  str_homestory_chat_10801001 = "Ahora que lo mencionas... tengo algo.",
  str_homestory_chat_10801002 = "Pero no hay prisa.",
  str_homestory_chat_10801003 = "Muéstrame más tarde.",
  str_homestory_chat_10821001 = "¿Qué te apetece comer?",
  str_homestory_chat_10821002 = "¿Por qué me preguntas esto de repente?",
  str_homestory_chat_10821003 = "Solo esas cosas que normalmente tengo ya que no soy exigente.",
  str_homestory_chat_10821004 = "¿Quieres tener más platos de huevo?",
  str_homestory_chat_10821005 = "Claro.",
  str_homestory_chat_10821006 = "Pero, ¿qué efectos especiales tienen estos platos de huevo en mí?",
  str_homestory_chat_10821007 = "No te preocupes, es todo por tu propio bien.",
  str_homestory_chat_10821008 = "¿Quieres tomar un vaso de leche todos los días?",
  str_homestory_chat_10821009 = "Claro.",
  str_homestory_chat_10821010 = "Pero, ¿por qué eso suena bastante extraño?",
  str_homestory_chat_10821011 = "...Lo tengo.",
  str_homestory_chat_10821012 = "¡Te estás riendo de mi altura indirectamente!",
  str_homestory_chat_10821013 = "¡No! ¡Absolutamente no!",
  str_homestory_chat_10822001 = "¿Qué tienes en mente?",
  str_homestory_chat_10822002 = "PlayerName¡Se me acaba de ocurrir una gran idea!",
  str_homestory_chat_10822003 = "Podemos instalar algunas luces fuertes en estos edificios.",
  str_homestory_chat_10822004 = "¿Por qué?",
  str_homestory_chat_10822005 = "...Está bien, es porque no tengo nada que hacer ahora.",
  str_homestory_chat_10822006 = "PlayerName, ¿tiene necesidades de nueva construcción?",
  str_homestory_chat_10822007 = "Déjame pensar en ello.",
  str_homestory_chat_11799999 = "Hola, PlayerName!",
  str_homestory_chat_11701001 = "Hola, Rabbie!",
  str_homestory_chat_11701002 = "¿Algún plan hoy?",
  str_homestory_chat_11701003 = "No en este momento.",
  str_homestory_chat_11701004 = "¿Quieres perforar agujeros conmigo?",
  str_homestory_chat_11701005 = "M-Quizás más tarde?",
  str_homestory_chat_11721001 = "¿Parece que tienes algo en mente?",
  str_homestory_chat_11721002 = "PlayerName, ¿quieres escuchar mi plan de evacuación?",
  str_homestory_chat_11721003 = "¿Evacuación?",
  str_homestory_chat_11721004 = "¡Ningún hogar establecido debe estar sin un plan de evacuación!",
  str_homestory_chat_11721005 = "¡Es por la seguridad de todos!",
  str_homestory_chat_11721006 = "Vale, echaré un vistazo.",
  str_homestory_chat_11721007 = "¡Ya terminé con una parte y perforé tres agujeros!",
  str_homestory_chat_11721008 = "¡¿De ninguna manera?!",
  str_homestory_chat_11722001 = "¿Qué estás mirando?",
  str_homestory_chat_11722002 = "PlayerName¡Tengo una broca nueva!",
  str_homestory_chat_11722003 = "¡Realmente me encantaría probarlo ahora!",
  str_homestory_chat_11722004 = "N-No...",
  str_homestory_chat_11722005 = "¡El agujero que perforaste la última vez ni siquiera ha sido rellenado todavía!",
  str_homestory_chat_11722006 = "¿Está insatisfecho con mi plan de evacuación subterránea?",
  str_homestory_chat_11722007 = "N-No realmente. De todos modos, házmelo saber antes de taladrar agujeros.",
  str_homestory_chat_11722008 = "¡Está bien, lo tengo! ¡Lo tendré en mente!",
  str_homestory_chat_11751001 = "¿Dónde está ese pez?",
  str_homestory_chat_11751002 = "¡Ay! ¡Retiro!",
  str_homestory_chat_11751003 = "¿Retiro? Ey...",
  str_homestory_chat_11751004 = "A-¿Estás aquí para atraparme?",
  str_homestory_chat_11751005 = "atraparte? ¿Qué hiciste?",
  str_homestory_chat_11751006 = "Bueno... por el bien de facilitar los retiros de emergencia, solo quería cavar un túnel debajo de Cloud Gardens.",
  str_homestory_chat_11751007 = "Cuando llegue el momento, si no creo que podamos aguantar, haré como un árbol y correré— ¡Ah, retírate, sí!",
  str_homestory_chat_11751008 = "Oh, eso es muy considerado de tu parte.",
  str_homestory_chat_11751009 = "Y vi ese pez mientras cavaba el túnel... ¡Oh, sí! ¿Es por eso que viniste?",
  str_homestory_chat_11751010 = "¿Eh? Ah, cierto... De todos modos, ese túnel no parecía ser muy útil, así que los Chubbs lo están llenando de nuevo.",
  str_homestory_chat_11751011 = "¿Llenarlo?",
  str_homestory_chat_11751012 = "¡¿Cómo vamos a retirarnos?! ¿Qué pasa si algo terrible realmente sucede?",
  str_homestory_chat_11751013 = "No va a pasar nada. Además, cavaste ese túnel sin siquiera preguntarme si estaba bien.",
  str_homestory_chat_11751014 = "Supongo...",
  str_homestory_chat_11751015 = "Pero de todos modos, vine a preguntarte por ese pez. ¿Dónde lo viste? ¿Cerca del túnel?",
  str_homestory_chat_11751016 = "En realidad, estaba un poco más lejos que eso. Realmente no tengo la energía para explicarlo en este momento. Cavar túneles es un trabajo duro...",
  str_homestory_chat_11751017 = "No estás buscando una compensación, ¿verdad?",
  str_homestory_chat_11751018 = "¡Claro que soy yo! ¡Dame algunas semillas del árbol Quinlan de hoja gigante y nos consideraré a mano!",
  str_homestory_chat_11751019 = "De lo contrario... ¡Oye, creo que acabo de descubrir una nueva ruta de retirada!",
  str_homestory_chat_11751020 = "Está bien, está bien... ¿Cómo es que algo de esto tiene algo que ver conmigo...?",
  str_homestory_chat_14099999 = "¿Quieres algunas rocas pop?",
  str_homestory_chat_14001001 = "¿Pop Rocks?",
  str_homestory_chat_14001002 = "¿Son realmente dulces y no bombas?",
  str_homestory_chat_14001003 = "¿Quieres que te muestre?",
  str_homestory_chat_14001004 = "Pero puedo terminarlo todo de un bocado.",
  str_homestory_chat_14021001 = "¿Hola que tal?",
  str_homestory_chat_14021002 = "PlayerName, les sugiero que promuevan la clasificación de residuos.",
  str_homestory_chat_14021003 = "¿Por qué?",
  str_homestory_chat_14021004 = "Es tan problemático tener toda la basura mezclada.",
  str_homestory_chat_14021005 = "Eso es realmente una buena idea.",
  str_homestory_chat_14021006 = "¿Entonces que estás esperando?",
  str_homestory_chat_14021007 = "Bueno, puedo ayudarte si quieres.",
  str_homestory_chat_14021008 = "Tan ansioso, ¿eh?",
  str_homestory_chat_14021009 = "Quería agarrar algo útil de la basura pero mi mano estaba manchada con salsa picante.",
  str_homestory_chat_14021010 = "¿Quién no estaría molesto?",
  str_homestory_chat_14022001 = "¿Me estabas buscando?",
  str_homestory_chat_14022002 = "Cuando es la fiesta, PlayerName?",
  str_homestory_chat_14022003 = "En unos dias...",
  str_homestory_chat_14022004 = "¿Necesitas fuegos artificiales?",
  str_homestory_chat_14022005 = "¡Vamos, di que \"lo necesitas\"!",
  str_homestory_chat_14022006 = "Sí... Espera, ¿por qué lo necesitaría?",
  str_homestory_chat_14022007 = "¡Porque no puedo esperar para probar mis nuevos fuegos artificiales, por supuesto!",
  str_homestory_chat_14022008 = "No por el momento.",
  str_homestory_chat_14022009 = "¡No, tienes que hacerlo!",
  str_homestory_chat_14022010 = "De lo contrario, ¿dónde se supone que debo ir a probar los nuevos fuegos artificiales?",
  str_homestory_chat_14022011 = "¡Oye, puedes activarlos en cualquier espacio abierto!",
  str_homestory_chat_14022012 = "¡Ahora estas hablando!",
  str_homestory_chat_14022013 = "... Espera, ¿puedo retirar eso?",
  str_homestory_chat_14023001 = "¿Qué estás haciendo?",
  str_homestory_chat_14023002 = "PlayerName, quieres ver mi nueva bomba?",
  str_homestory_chat_14023003 = "Nop.",
  str_homestory_chat_14023004 = "Volaste un árbol la vez anterior...",
  str_homestory_chat_14023005 = "y media ladera la ultima vez...",
  str_homestory_chat_14023006 = "¿Qué quieres destruir esta vez?",
  str_homestory_chat_14023007 = "... ¡Definitivamente no tenía intención destructiva!",
  str_homestory_chat_14023008 = "¡No tuviste la intención porque lo hiciste a propósito!",
  str_homestory_chat_15199999 = "¿Te animas a los juegos de mesa desde que viniste a saludarnos?",
  str_homestory_chat_15121001 = "No, gracias. ¿Cómo te va?",
  str_homestory_chat_15121002 = "PlayerName, si quieres que todos vivan cómodamente aquí, deberías tener algo para comer al menos, ¿verdad?",
  str_homestory_chat_15121003 = "¿No hay suficiente para comer?",
  str_homestory_chat_15121004 = "No es que no haya suficiente, sino que simplemente no hay nada comestible...",
  str_homestory_chat_15121005 = "¿Qué quieres comer?",
  str_homestory_chat_15121006 = "Comencemos con diez latas de aceite de motor de 5 años...",
  str_homestory_chat_15121007 = "y cinco frascos de lodo de armas.",
  str_homestory_chat_15122001 = "Pareces bastante libre.",
  str_homestory_chat_15122002 = "Sí, PlayerName. He estado aquí tanto tiempo que mis armas están oxidadas.",
  str_homestory_chat_15122003 = "Siempre puedes conseguir que alguien lo arregle.",
  str_homestory_chat_15122004 = "Sí, puedo... Pero es simplemente una solución temporal.",
  str_homestory_chat_15122005 = "Después de todo, solo se oxidó por aburrimiento.",
  str_homestory_chat_15122006 = "Yo diría que será mejor construir un campo de tiro.",
  str_homestory_chat_15122007 = "¿Alguna buena solución?",
  str_homestory_chat_15122008 = "Es para construir un campo de tiro. Tómate un tiempo para pensarlo bien, PlayerName.",
  str_homestory_chat_15122009 = "Sí lo haré.",
  str_homestory_chat_15123001 = "¿Juegos de mesa?",
  str_homestory_chat_15123002 = "¡También podemos incluir apuestas!",
  str_homestory_chat_15123003 = "No son algo aterrador, ¿verdad?",
  str_homestory_chat_15123004 = "No, puedes elegir lo que quieras apostar esta vez.",
  str_homestory_chat_15123005 = "Cualquier cosa está bien, como tus manos y piernas.",
  str_homestory_chat_15124001 = "¿Cómo es este lugar?",
  str_homestory_chat_15124002 = "No está nada mal, pero es demasiado silencioso.",
  str_homestory_chat_15124003 = "¿Tranquilo?",
  str_homestory_chat_15124004 = "Solo puedo escuchar el sonido de la naturaleza, pero no disparos ni autos.",
  str_homestory_chat_15124005 = "Necesito acostumbrarme a esto.",
  str_homestory_chat_15124006 = "Creo que tendré que volver al desierto de vez en cuando, para recuperar mi toque.",
  str_homestory_chat_15124007 = "Pero es demasiado lejos para ir y venir.",
  str_homestory_chat_15124008 = "Si puedo tener mi arma aquí, sería genial.",
  str_homestory_chat_15124009 = "¡¡No!!",
  str_homestory_chat_15399999 = "¿Qué puedo ofrecerte, mi querido jefe?",
  str_homestory_chat_15321001 = "Oh...",
  str_homestory_chat_15321002 = "Tengo un osito de peluche nuevo, un cuerno de gusano de arena en perfecto estado...",
  str_homestory_chat_15321003 = "¡Esperar! Solo estoy aquí para decir hola.",
  str_homestory_chat_15321004 = "No se preocupe, ¡un simple saludo siempre puede conducir a un trato satisfactorio también!",
  str_homestory_chat_15322001 = "¿Qué estás haciendo?",
  str_homestory_chat_15322002 = "Jefe, ¿escucha un ladrido?",
  str_homestory_chat_15322003 = "No...",
  str_homestory_chat_15322004 = "¿Estoy escuchando cosas?",
  str_homestory_chat_15322005 = "Caray... Ya que no hay cachorros, ¿dónde debo buscar consuelo?",
  str_homestory_chat_15322006 = "A menos que, jefe, me compre más artículos.",
  str_homestory_chat_15322007 = "Bueno.",
  str_homestory_chat_15322008 = "Eso creo...",
  str_homestory_chat_15322009 = "¡Sí, sabía que lo había oído bien!",
  str_homestory_chat_15322010 = "Primero voy a buscar al cachorro, jefe. ¡Asegúrate de venir a mí si quieres comprar algo!",
  str_homestory_chat_15322011 = "Bien bien. Solo sigue adelante.",
  str_homestory_chat_15323001 = "¿Encontrar algo nuevo?",
  str_homestory_chat_15323002 = "¡Si jefe! ¡Hay una gran oportunidad de negocio escondida en casa!",
  str_homestory_chat_15323003 = "Ven, cuéntame. ¿Qué es esta oportunidad de negocio?",
  str_homestory_chat_15323004 = "¡Dios mío, no lo has notado en absoluto!?",
  str_homestory_chat_15323005 = "Si alguna vez encuentra una oportunidad de negocio, podemos conversar al respecto...",
  str_homestory_chat_15323006 = "¿No me quedaría con el extremo corto del palo si te lo dijera ahora? Esto también va en contra de mis principios.",
  str_homestory_chat_15323007 = "A menos que quiera pagar una tarifa de consulta...",
  str_homestory_chat_15323008 = "¡Entonces seré muy comunicativo con la oportunidad de negocio!",
  str_homestory_chat_15323009 = "...Todo está bien.",
  str_homestory_chat_11399999 = "Hola, PlayerName! ¿Quieres limpiar el lugar conmigo?",
  str_homestory_chat_11321001 = "Wow, seguro que trabajas duro!",
  str_homestory_chat_11321002 = "¡Por supuesto, tenemos que ser diligentes en mantener el lugar limpio!",
  str_homestory_chat_11322001 = "¡Oye, es hora de hacer una fiesta!",
  str_homestory_chat_11322002 = "PlayerName, ¿has decidido un tema para tu próxima fiesta?",
  str_homestory_chat_11322003 = "¡Sip!",
  str_homestory_chat_11322004 = "¿Quieres que agregue otra idea a la mezcla?",
  str_homestory_chat_11322005 = "¿Como... \"Un hogar en la nieve\"?",
  str_homestory_chat_11322006 = "Aún no...",
  str_homestory_chat_11322007 = "¡He pensado en un tema para ti!",
  str_homestory_chat_11322008 = "\"Un hogar en la nieve\"!",
  str_homestory_chat_11322009 = "¡Puedo proporcionar los cristales de hielo que revolotean y los muñecos de nieve que bailan claqué!",
  str_homestory_chat_11322010 = "Eso suena bien. Podemos intentarlo.",
  str_homestory_chat_11323001 = "¿Qué estás mirando?",
  str_homestory_chat_11323002 = "Allí... ¡Parece que algo brilla!",
  str_homestory_chat_11323003 = "Es solo una gota de rocío en una brizna de hierba...",
  str_homestory_chat_11323004 = "Incluso si es solo una gota de rocío, ¡es muy lindo!",
  str_homestory_chat_11323005 = "¡Lo congelaré y lo guardaré como recuerdo!",
  str_homestory_chat_11323006 = "Son solo fragmentos de vidrio...",
  str_homestory_chat_11323007 = "¡Fragmentos de vidrio transparentes y brillantes!",
  str_homestory_chat_11323008 = "Adiós, PlayerName! ¡Voy a ir a coleccionarlos todos!",
  str_homestory_chat_11324001 = "¿Qué estás haciendo?",
  str_homestory_chat_11324002 = "PlayerName! ¡Hice muchos adornos de muñecos de nieve!",
  str_homestory_chat_11324003 = "¡Te los puedo regalar si quieres!",
  str_homestory_chat_11324004 = "¿No se derretirán?",
  str_homestory_chat_11324005 = "¡Por supuesto que no! ¡Incluso puedo hacerlos bailar si eso es lo que quieres!",
  str_homestory_chat_11324006 = "¡Se los traeré más tarde!",
  str_homestory_chat_11325001 = "Qué gran día.",
  str_homestory_chat_11325002 = "¡Sí, es tan diferente de la nevada Northland!",
  str_homestory_chat_11325003 = "Pero, lamentablemente, no podemos hacer un muñeco de nieve aquí...",
  str_homestory_chat_11325004 = "¿Quieres ir a pescar conmigo?",
  str_homestory_chat_11325005 = "¿Ir a pescar?",
  str_homestory_chat_11325006 = "¡Me pregunto si hay algún pez aquí que brille como el copo de nieve!",
  str_homestory_chat_11325007 = "¡Vamos a descubrirlo!",
  str_homestory_chat_11325008 = "¿Quieres jugar en el columpio?",
  str_homestory_chat_11325009 = "¿Te refieres a la silla en la que puedes volar y colgar las piernas?",
  str_homestory_chat_11325010 = "¡Parece que bailo en el aire como un copo de nieve!",
  str_homestory_chat_11325011 = "¡Me encantaría ser ligera y brillante como la nieve!",
  str_homestory_chat_11099999 = "Hola, PlayerName. Te ves bien hoy.",
  str_homestory_chat_11021001 = "¿Estás buscando algo?",
  str_homestory_chat_11021002 = "Dulces. ¿Te gustaría uno?",
  str_homestory_chat_11021003 = "No son dulces de madera creados con magia. Pero en cambio, son dulces reales.",
  str_homestory_chat_11021004 = "Claro, tendré uno.",
  str_homestory_chat_11021005 = "Um... Espera, déjame buscarlo. Mis bolsillos son tan grandes que siempre tengo problemas para encontrar cosas.",
  str_homestory_chat_11022001 = "¿Tienes una pregunta para mí?",
  str_homestory_chat_11022002 = "PlayerName, ¿preferirías ser un elfo o un hada?",
  str_homestory_chat_11022003 = "¿De dónde viene esto?",
  str_homestory_chat_11022004 = "¡Eso es porque estoy trabajando en una nueva historia!",
  str_homestory_chat_11022005 = "¿Te gustaría aparecer en mi historia?",
  str_homestory_chat_11022006 = "Por supuesto.",
  str_homestory_chat_11022007 = "Hmm, veamos... Prefiero ser un hada.",
  str_homestory_chat_11022008 = "¡No hay problema! ¡Un hada mística que puede ver los rastros de luz!",
  str_homestory_chat_11022009 = "¿Cuál es la diferencia entre duendes y hadas?",
  str_homestory_chat_11022010 = "¡Gran diferencia!",
  str_homestory_chat_11022011 = "¡Te buscaré algunos libros sobre ellos y verás!",
  str_homestory_chat_11023001 = "¿Estás buscando algo?",
  str_homestory_chat_11023002 = "PlayerName, ¿has comido dulces últimamente?",
  str_homestory_chat_11023003 = "Sí.",
  str_homestory_chat_11023004 = "¿Viste algún papel de caramelo bonito?",
  str_homestory_chat_11023005 = "Realmente no...",
  str_homestory_chat_11023006 = "Oh...",
  str_homestory_chat_11023007 = "¿Qué pasa?",
  str_homestory_chat_11023008 = "Esperaba que tuvieras unos bonitos envoltorios de caramelos...",
  str_homestory_chat_11023009 = "Relucientes envoltorios de vidrio, suaves envoltorios impresos, ¡cualquier cosa por el estilo!",
  str_homestory_chat_11023010 = "no le presté mucha atención...",
  str_homestory_chat_11023011 = "La próxima vez buscaré bonitos envoltorios para ti.",
  str_homestory_chat_11024001 = "¿Cómo dormiste anoche?",
  str_homestory_chat_11024002 = "PlayerName, Tuve un sueño muy dulce anoche.",
  str_homestory_chat_11024003 = "¿De qué se trata?",
  str_homestory_chat_11024004 = "Estaba sentado dentro de una casa de dulces con ustedes...",
  str_homestory_chat_11024005 = "¡En un proyecto de arte!",
  str_homestory_chat_11024006 = "Tus ojos están tan llenos de expectación.",
  str_homestory_chat_11024007 = "PlayerName, ¿organizamos un concurso de bricolaje?",
  str_homestory_chat_11025001 = "¿Qué estás haciendo?",
  str_homestory_chat_11025002 = "¡Estoy coleccionando dientes de león!",
  str_homestory_chat_11025003 = "El diente de león es tan ligero que una suave brisa puede hacerlo bailar en el cielo...",
  str_homestory_chat_11025004 = "¡Esto haría que Northland fuera mucho más hermoso!",
  str_homestory_chat_11025005 = "¿Sería posible crecer en el norte?",
  str_homestory_chat_11025006 = "No estoy seguro, pero me gustaría probar!",
  str_homestory_chat_11025007 = "Espero que estos dientes de león se conviertan en duendes del norte como el copo de nieve.",
  str_homestory_chat_11025008 = "¡Buena suerte!",
  str_homestory_chat_11025009 = "¡Me esforzaré más!",
  str_homestory_chat_11025010 = "Aunque no es fácil.",
  str_homestory_chat_11025011 = "Los dientes de león se irían volando incluso con el viento más suave.",
  str_homestory_chat_11025012 = "¡Debo darme prisa!",
  str_homestory_chat_11999999 = "PlayerName, es otro nuevo día para buscar la verdad.",
  str_homestory_chat_11901001 = "Ah, sí.",
  str_homestory_chat_11901002 = "¿Estás listo para aceptar mi invitación esta vez?",
  str_homestory_chat_11901003 = "Hmm... Ahora no... Tal vez la próxima vez.",
  str_homestory_chat_11921001 = "¿Como esta tu dia?",
  str_homestory_chat_11921002 = "Es bueno verte vivo y coleando.",
  str_homestory_chat_11921003 = "¿Le gustaría saber su fortuna para los próximos días?",
  str_homestory_chat_11921004 = "¡Seguro!",
  str_homestory_chat_11921005 = "Eso es muy atrevido de tu parte.",
  str_homestory_chat_11921006 = "Me emociona verte tan lleno de esperanza sobre el futuro.",
  str_homestory_chat_11921007 = "Realmente no...",
  str_homestory_chat_11921008 = "No tienes por qué temer el futuro si la verdad está contigo...",
  str_homestory_chat_11921009 = "¿Por qué no ofrecer tu alma y convertirte en un seguidor de la verdad?",
  str_homestory_chat_11922001 = "¡Hola! ¿Qué estás haciendo?",
  str_homestory_chat_11922002 = "PlayerName, te apetece un trago conmigo?",
  str_homestory_chat_11922003 = "En esta noche interminable en que la oscuridad lo silencia todo...",
  str_homestory_chat_11922004 = "Espera...",
  str_homestory_chat_11922005 = "¿De qué bebida estamos hablando?",
  str_homestory_chat_11922006 = "Si me dejas la elección...",
  str_homestory_chat_11922007 = "Sugeriría una taza caliente...",
  str_homestory_chat_11922008 = "No... yo paso...",
  str_homestory_chat_11922009 = "Preferiría no...",
  str_homestory_chat_11922010 = "Veo miedo en tus ojos.",
  str_homestory_chat_11922011 = "¿Por que tienes miedo? Puedes elegir tu propia bebida esta vez.",
  str_homestory_chat_11923001 = "¿Lectura?",
  str_homestory_chat_11923002 = "Realmente disfruto leyendo aquí.",
  str_homestory_chat_11923003 = "Aquí siempre hay algún rincón tranquilo donde ningún clamor puede llegar...",
  str_homestory_chat_11923004 = "Esto me permite explorar el conocimiento más profundo en los libros antiguos.",
  str_homestory_chat_11923005 = "¿Fue una crítica positiva?",
  str_homestory_chat_11923006 = "Definitivamente.",
  str_homestory_chat_11923007 = "Como guardián de este lugar, mereces todos mis elogios.",
  str_homestory_chat_11924001 = "¿Tienes algo que decirme?",
  str_homestory_chat_11924002 = "Aquí hay una cosa que necesito discutir contigo.",
  str_homestory_chat_11924003 = "Adelante.",
  str_homestory_chat_11924004 = "En el futuro, si se va a distribuir comida a todos...",
  str_homestory_chat_11924005 = "Por favor, exclúyame.",
  str_homestory_chat_11924006 = "¿Pero por qué?",
  str_homestory_chat_11924007 = "Como saben, nunca diría que sí a una invitación así.",
  str_homestory_chat_11924008 = "Prefiero elegir mi propia comida.",
  str_homestory_chat_10999999 = "Mi amigo, debes escuchar la verdad hoy.",
  str_homestory_chat_10901001 = "Err... Supongo que lo haré.",
  str_homestory_chat_10901002 = "Mi amigo, puedo sentir tu sinceridad...",
  str_homestory_chat_10901003 = "Creo que está ansioso por discutir la verdad conmigo.",
  str_homestory_chat_10901004 = "Realmente no...",
  str_homestory_chat_10921001 = "¿Está todo bien?",
  str_homestory_chat_10921002 = "Amigo, ¿puedo confiar temporalmente la Maleta Blanca a tu cuidado?",
  str_homestory_chat_10921003 = "por favor no...",
  str_homestory_chat_10921004 = "Tu rechazo es tan frío en este tiempo.",
  str_homestory_chat_10921005 = "No te preocupes. No te dará ningún mal recuerdo.",
  str_homestory_chat_10921006 = "Esto suena muy parecido a una estafa.",
  str_homestory_chat_10921007 = "Necesito pensarlo.",
  str_homestory_chat_10921008 = "¿Recuerdas la Guía de Cuidados de la Maleta Blanca?",
  str_homestory_chat_10921009 = "Prefiere una temperatura moderada, limpieza diaria y alimentación al mediodía...",
  str_homestory_chat_10921010 = "... Esperar. ¿Ya es demasiado tarde para decir que no?",
  str_homestory_chat_10922001 = "¿Qué estás buscando?",
  str_homestory_chat_10922002 = "Amigo, ¿tenemos ruinas antiguas aquí?",
  str_homestory_chat_10922003 = "No.",
  str_homestory_chat_10922004 = "Me temo que harías algo inusual y absurdo.",
  str_homestory_chat_10922005 = "Eso es una tontería.",
  str_homestory_chat_10922006 = "Como buscador de la verdad, hago todo por una razón.",
  str_homestory_chat_10922007 = "Si usted está interesado en aprender más, estoy feliz de explicar.",
  str_homestory_chat_10922008 = "Eso no será necesario.",
  str_homestory_chat_10922009 = "Déjame pensar.",
  str_homestory_chat_10922010 = "Me temo que te cuesta recordar los recuerdos correctos.",
  str_homestory_chat_10922011 = "Avísame cuando finalmente te venga a la mente.",
  str_homestory_chat_10923001 = "Parece que estás pensando.",
  str_homestory_chat_10923002 = "Amigo, ¿no crees que al aire de aquí le falta algo?",
  str_homestory_chat_10923003 = "¿De qué estás hablando?",
  str_homestory_chat_10923004 = "La predicación de la verdad.",
  str_homestory_chat_10923005 = "¿No crees que necesitamos organizar una sesión de información...",
  str_homestory_chat_10923006 = "Para liberar a todos de su vida sin sentido...",
  str_homestory_chat_10923007 = "¿Para ayudarlos a avanzar hacia la tierra de la verdad?",
  str_homestory_chat_10923008 = "... Creo que lo estamos haciendo bien.",
  str_homestory_chat_10599999 = "¡Hola! Hola...",
  str_homestory_chat_10521001 = "Es esto Mia ¿Este Dia?",
  str_homestory_chat_10521002 = "Sí, está profundamente dormida.",
  str_homestory_chat_10522001 = "Es un hermoso día hoy.",
  str_homestory_chat_10522002 = "Si, muy bonito...",
  str_homestory_chat_10522003 = "Todos los días que pasamos en casa son acogedores y confortables...",
  str_homestory_chat_10522004 = "Mmm... Lo siento. No quiero confundirte.",
  str_homestory_chat_10522005 = "Para nada.",
  str_homestory_chat_10522006 = "No he visto a Baba Yaga por un tiempo.",
  str_homestory_chat_10522007 = "Porque... Es tan tranquilo y pacífico en casa. ella duerme mucho...",
  str_homestory_chat_10522008 = "Si realmente quieres verla, podría...",
  str_homestory_chat_10522009 = "Esperar. ¡Eso no es lo que quise decir!",
  str_homestory_chat_10523001 = "¿Qué le gustaría beber?",
  str_homestory_chat_10523002 = "¿Algún té negro de caballero?",
  str_homestory_chat_10523003 = "Sírvelo de inmediato. No me hagas preguntar cada vez.",
  str_homestory_chat_10523004 = "Baba Yaga?",
  str_homestory_chat_10523005 = "No cambies de tema.",
  str_homestory_chat_10523006 = "recuerdo que es Mia a quien le gusta el té negro de Knight.",
  str_homestory_chat_10523007 = "No digas más, o tendrás que lidiar con una garra de acero.",
  str_homestory_chat_10523008 = "Por favor dame un minuto...",
  str_homestory_chat_10523009 = "Puede llevar algo de tiempo.",
  str_homestory_chat_10523010 = "Será mejor que reces para que no tarde mucho.",
  str_homestory_chat_10524001 = "Escuché que había una araña últimamente...",
  str_homestory_chat_10524002 = "¿Una araña negra en la noche? ¿También lo viste? ¿Quién crees que fue?",
  str_homestory_chat_10524003 = "¿Eras tú?",
  str_homestory_chat_10524004 = "Parece que te gustan mucho las historias de misterio.",
  str_homestory_chat_10524005 = "Verás más después del anochecer.",
  str_homestory_chat_10524006 = "Ni idea...",
  str_homestory_chat_10524007 = "Mantente despierto y quizás encuentres la verdad detrás del misterio.",
  str_homestory_chat_10524008 = "¿No quieres ver?",
  str_homestory_chat_10524009 = "No, definitivamente no...",
  str_homestory_chat_10499999 = "¡Oye! ¿Estás aquí con comida?",
  str_homestory_chat_10401001 = "... No.",
  str_homestory_chat_10401002 = "Solo vine a saludar.",
  str_homestory_chat_10401003 = "Hmm... Por favor, apártense. La comida es la prioridad ahora.",
  str_homestory_chat_10421001 = "Estás sudando.",
  str_homestory_chat_10421002 = "Sí... Hace mucho calor.",
  str_homestory_chat_10421003 = "¿Cerveza fría, pescado congelado o lata de hielo?",
  str_homestory_chat_10421004 = "necesito mirar...",
  str_homestory_chat_10421005 = "¡Apuro! ¡Empieza a buscar ahora!",
  str_homestory_chat_10421006 = "¡Tómate tu tiempo si quieres verme derretirme en un charco!",
  str_homestory_chat_10421007 = "No...",
  str_homestory_chat_10421008 = "De ninguna manera, ¡la vida no puede seguir así!",
  str_homestory_chat_10422001 = "¿Fuiste a nadar recientemente?",
  str_homestory_chat_10422002 = "Sí, fue hermoso nadar en el río...",
  str_homestory_chat_10422003 = "¿Río?",
  str_homestory_chat_10422004 = "Sí, el propósito de un río es que la gente nade. ¿Tienes algún problema?",
  str_homestory_chat_10422005 = "No... De repente me di cuenta de que eres un buen nadador.",
  str_homestory_chat_10422006 = "Ese río poco profundo es perfectamente seguro para ti.",
  str_homestory_chat_10423001 = "¿Cubos de hielo?",
  str_homestory_chat_10423002 = "Sí, ¿tienes cubitos de hielo?",
  str_homestory_chat_10423003 = "Los que son tan grandes como una casa.",
  str_homestory_chat_10423004 = "¡No!",
  str_homestory_chat_10423005 = "Entonces, ¿cómo se supone que debo pasar mi verano?",
  str_homestory_chat_10423006 = "¿Cómo lo hiciste?",
  str_homestory_chat_10423007 = "Hizo trabajos en todas partes, luego compró cubitos de hielo con el dinero.",
  str_homestory_chat_10423008 = "Entonces, deberías estar trabajando y ganando dinero.",
  str_homestory_chat_10423009 = "¡Sí!",
  str_homestory_chat_10423010 = "¡Y eran más grandes que casas! ¡Eran tan grandes como las montañas!",
  str_homestory_chat_10423011 = "¡¿En serio?!",
  str_homestory_chat_10423012 = "No en realidad no.",
  str_homestory_chat_15099999 = "¡Hola hermano!",
  str_homestory_chat_15001001 = "¡Hola! Hola...",
  str_homestory_chat_15001002 = "Por favor, no te preocupes por mis dientes. No quise desnudarlos.",
  str_homestory_chat_15001003 = "Lo sé... Solo escóndelos, por favor...",
  str_homestory_chat_15021001 = "¿Qué estás buscando?",
  str_homestory_chat_15021002 = "¿Tenemos un gato aquí?",
  str_homestory_chat_15021003 = "Supongo que sí...",
  str_homestory_chat_15021004 = "Por favor muéstrame cuando tengas tiempo.",
  str_homestory_chat_15021005 = "Está seguro. Yo no como gatos.",
  str_homestory_chat_15021006 = "Soy principalmente vegetariano, ¿recuerdas?",
  str_homestory_chat_15021007 = "Sí, lo recuerdo...",
  str_homestory_chat_15021008 = "No lo creo...",
  str_homestory_chat_15021009 = "¿Cuándo tendremos algunos gatos?",
  str_homestory_chat_15021010 = "Una vez que vengan los gatos, no habrá ningún aburrimiento...",
  str_homestory_chat_15022001 = "¿Quieres hablar conmigo?",
  str_homestory_chat_15022002 = "¿Necesitas un poco de polvo de dientes de tiburón, hermano?",
  str_homestory_chat_15022003 = "¿Para qué es esto?",
  str_homestory_chat_15022004 = "Puedes ponerlo en tus bocadillos nocturnos.",
  str_homestory_chat_15022005 = "¡Pruébalo y verás!",
  str_homestory_chat_15022006 = "no lo tengo conmigo La próxima vez.",
  str_homestory_chat_15023001 = "tu diente...",
  str_homestory_chat_15023002 = "¿Hmm? Oh, está un poco flojo otra vez.",
  str_homestory_chat_15023003 = "Parece que voy a necesitar un nuevo lote. ¿Tomas esto?",
  str_homestory_chat_15023004 = "¿Qué hace esto?",
  str_homestory_chat_15023005 = "No.",
  str_homestory_chat_15023006 = "¡Vamos! Es muy útil.",
  str_homestory_chat_15023007 = "Puedes hacer esculturas con ellos, o puedes triturarlos y usarlos como especias.",
  str_homestory_chat_15023008 = "Es posible que pueda ganar algo de dinero vendiéndoselos a Umbraton.",
  str_homestory_chat_15023009 = "Entonces, ¿por qué no te los quedas para ti?",
  str_homestory_chat_15023010 = "Porque te estoy pagando por protección.",
  str_homestory_chat_15031001 = "Peces raros...",
  str_homestory_chat_15031002 = "¿Mmm? ¿Viste algo, jefe?",
  str_homestory_chat_15031003 = "Hace unos días, vi un montón de peces en el arroyo que nunca antes había visto.",
  str_homestory_chat_15031004 = "Sus ojos eran enormes y sus cuerpos eran algo redondos.",
  str_homestory_chat_15031005 = "¡Oh, debes estar hablando de la carpa cabezona! En realidad, fui yo quien los puso ahí...",
  str_homestory_chat_15031006 = "¿Ah?",
  str_homestory_chat_15031007 = "Bueno, noté que a la carpa cabezona le va muy bien por aquí.",
  str_homestory_chat_15031008 = "¡El agua, el clima, la velocidad de la corriente son perfectos para ellos! ¡Pero lo más importante es que son muy raros!",
  str_homestory_chat_15031009 = "Y aquí pensé que te los querías comer...",
  str_homestory_chat_15031010 = "¡Vamos jefe! Con los dientes afilados que soy, ¡nunca como carne!",
  str_homestory_chat_15031011 = "¿Cuántas veces más van a juzgarme mal por mi apariencia?",
  str_homestory_chat_15031012 = "¿Tengo que lidiar con esto por el resto de mi vida?",
  str_homestory_chat_15031013 = "Aquí tienes de nuevo...",
  str_homestory_chat_15031014 = "¡No seas tan sensible! Antes estabas en una pandilla, ¿no?",
  str_homestory_chat_15031015 = "Sí, pero sigues haciéndolo una y otra vez...",
  str_homestory_chat_15031016 = "Uh... Korgon, ¿por qué trajiste a estas carpas cabezonas aquí en primer lugar?",
  str_homestory_chat_15031017 = "¡Para dejarlos reproducirse, por supuesto! Y una vez que haya muchos de ellos, los traeré a todos de vuelta a la Isla Colmillo de Tiburón.",
  str_homestory_chat_15031018 = "La reconstrucción me ha estado desgastando últimamente. ¡Parece que el trabajo nunca termina!",
  str_homestory_chat_15031019 = "¡Pero solo ver a estos lindos pequeños hace que toda mi fatiga desaparezca! Por eso quiero traerlos a la isla.",
  str_homestory_chat_15031020 = "Verlos nadar en todas las formas y tamaños—",
  str_homestory_chat_15031021 = "¡Esperar! Vienen en diferentes tamaños?",
  str_homestory_chat_15031022 = "Sí, ¿ves? Se ve de esa manera.",
  str_homestory_chat_15031023 = "Pero solo veo una talla...",
  str_homestory_chat_15031024 = "De todos modos, Bighead Carp es extremadamente asustadizo. Me tomó una eternidad encontrar algunos lugares donde viven.",
  str_homestory_chat_15031025 = "Tampoco son fáciles de atrapar...",
  str_homestory_chat_15031026 = "Si necesitas a alguien que los pesque, puedo encargarme de eso.",
  str_homestory_chat_15031027 = "¡¿R-En serio, jefe?! Eso sería una gran carga de mis hombros. ¡Gracias!",
  str_homestory_chat_15031028 = "Pero como dije, la carpa cabezona es extremadamente rara. Soy un poco reacio a ver que alguno de ellos se vaya, para ser honesto...",
  str_homestory_chat_15031029 = "Bien, bien... ¿Cuál es el truco?",
  str_homestory_chat_15031030 = "¡Rápido como un zorro, como siempre! Así que el trato es que me traigas una de estas carpas cabezonas más pequeñas y compartiré información valiosa contigo.",
  str_homestory_chat_15031031 = "¡Te diré exactamente dónde puedes pescar una carpa cabezona aún más grande! Pero lo que suceda después depende de tus habilidades de pesca, jefe.",
  str_homestory_chat_15031032 = "Por supuesto, también estoy dispuesto a ofrecer otras recompensas por traerme más carpas cabezonas. ¡Soy un buen tipo, después de todo!",
  str_homestory_chat_15031033 = "¡Por cada carpa cabezona que me traigas, te diré dónde encontrar una más grande!",
  str_homestory_chat_15031034 = "¡Escuché que algunos pesan hasta 50 kilos! ¡¿Puedes creerlo?!",
  str_homestory_chat_15031035 = "Además, existe la posibilidad de que puedas pescar una carpa cabezona especialmente rara y brillante.",
  str_homestory_chat_15031036 = "Bueno, definitivamente me estás vendiendo esto como alguien de Umbraton...",
  str_homestory_chat_15031037 = "Pero no tengo ni el pez más pequeño para darte ahora mismo.",
  str_homestory_chat_15031038 = "¡Está bien, jefe! Conozco muchos lugares donde puedes encontrar a estos pequeños, aunque solo atraparás a los más pequeños del grupo en esas áreas.",
  str_homestory_chat_15031039 = "Pero si tienes las habilidades para el trabajo, solo necesitas traerme el pequeño, ¡y estaré más que feliz de cambiarlo!",
  str_homestory_chat_15031040 = "Van desde pequeños, a pequeños, a medianos, a grandes...",
  str_homestory_chat_15031041 = "¡Y si llegas tan lejos, me aseguraré de atrapar uno aún más grande! ¡Incluso podrías tener la suerte de atrapar ese raro y brillante también!",
  str_homestory_chat_15031042 = "Comprendo.",
  str_homestory_chat_15031043 = "Entonces, ¿está dispuesto a hacerlo, jefe? ¡Apuesto a que puedes manejarlo!",
  str_homestory_chat_15031044 = "¿Alguna otra pregunta?",
  str_homestory_chat_15031045 = "Quiero atrapar una carpa cabezona aún más grande.",
  str_homestory_chat_15031046 = "¡No es un problema! Hay un montón de lugares de pesca por ahí. ¡Todo se reduce a qué tan grande estamos hablando aquí!",
  str_homestory_chat_15031047 = "Quiero atrapar una carpa cabezona pequeña.",
  str_homestory_chat_15031048 = "Si quieres saber dónde pescar una carpa cabezona pequeña, primero tendrás que traerme una carpa cabezona pequeña. ¿Ya conseguiste uno?",
  str_homestory_chat_15031049 = "Give carpa cabezona diminuta ({1}/1)",
  str_homestory_chat_15031050 = "Dejame pensarlo.",
  str_homestory_chat_15031051 = "Quiero atrapar una carpa cabezona mediana.",
  str_homestory_chat_15031052 = "Si quieres saber dónde pescar una carpa cabezona mediana, primero tendrás que traerme una carpa cabezona pequeña. ¿Ya conseguiste uno?",
  str_homestory_chat_15031053 = "Give Carpa cabezona pequeña ({1}/1)",
  str_homestory_chat_15031054 = "Dejame pensarlo.",
  str_homestory_chat_15031055 = "Quiero atrapar una carpa cabezona grande.",
  str_homestory_chat_15031056 = "Si quieres saber dónde pescar carpa cabezona grande, primero tendrás que traerme una carpa cabezona mediana. ¿Ya conseguiste uno?",
  str_homestory_chat_15031057 = "Give Carpa cabezona mediana ({1}/1)",
  str_homestory_chat_15031058 = "Dejame pensarlo.",
  str_homestory_chat_15031059 = "Quiero atrapar una carpa cabezona gigante.",
  str_homestory_chat_15031060 = "Si quieres saber dónde pescar carpa cabezona gigante, primero tendrás que traerme una carpa cabezona grande. ¿Ya conseguiste uno?",
  str_homestory_chat_15031061 = "Give Carpa cabezona grande ({1}/1)",
  str_homestory_chat_15031062 = "Dejame pensarlo.",
  str_homestory_chat_15031063 = "¡Eres el hombre, jefe! ¡No puedo decirte lo feliz que estoy!",
  str_homestory_chat_15031064 = "Consulta tu mapa. ¡Marcaré dónde puedes encontrar peces aún más grandes!",
  str_homestory_chat_15031065 = "aun no tengo uno...",
  str_homestory_chat_15031066 = "Ah, qué pena, jefe. Vuelve a mí cuando tengas uno.",
  str_homestory_chat_15031067 = "Cosa segura.",
  str_homestory_chat_15031068 = "Recuérdame nuestro trato con la carpa cabezona.",
  str_homestory_chat_15031069 = "¡Claro, jefe! ¡Puedo repetirme cuantas veces quieras!",
  str_homestory_chat_15031070 = "El trato es simple: solo tráeme carpa cabezona de cualquier tamaño.",
  str_homestory_chat_15031071 = "Dame el pescado y te diré dónde encontrar el siguiente tamaño más grande de carpa cabezona.",
  str_homestory_chat_15031072 = "¡Incluso te daré otras recompensas por tus problemas! ¡No te decepcionará!",
  str_homestory_chat_15031073 = "Lo tengo.",
