  str_homestory_chat_15032034 = "Quiero pescar carpa cabezona.",
  str_homestory_chat_15032035 = "¿Listo para comenzar con una carpa cabezona diminuta? ¡Puedes venir a buscarme en cualquier momento una vez que atrapes uno! ¡Te diré dónde encontrar el siguiente tamaño después de ese!",
