  str_homestory_chat_15033001 = "Cuéntame más sobre la carpa cabezona.",
  str_homestory_chat_15033002 = "¡No hay problema, jefe! Ya marqué los lugares de pesca para ese tamaño de carpa cabezona en su mapa. ¡Ve a echar un vistazo!",
