  str_homestory_chat_15033008 = "¡Incluso te daré otras recompensas por tus problemas! ¡Eres el jefe, después de todo!",
  str_homestory_chat_15033009 = "Lo tengo.",
  str_homestory_chat_15033010 = "¡Gracias de nuevo, Korgon!",
  str_homestory_chat_15033011 = "¡Cuando quieras, jefe! ¡Siempre dispuesto a ayudar!",
  str_homestory_chat_13599999 = "¡Hola! ¿No trabajas hoy?",
  str_homestory_chat_13501001 = "Me estoy tomando un descanso.",
  str_homestory_chat_13501002 = "¡Estoy feliz de ayudar si tienes dificultades para terminar tu trabajo!",
