  str_homestory_chat_13521002 = "¡A Yoshi le encanta estar aquí!",
  str_homestory_chat_13521003 = "Libremente ella puede volar en el cielo.",
  str_homestory_chat_13521004 = "¿Y usted?",
  str_homestory_chat_13521005 = "Yo también... Tos... Definitivamente.",
  str_homestory_chat_13521006 = "Es bueno escuchar",
  str_homestory_chat_13522001 = "Te ves muy cansado...",
  str_homestory_chat_13522002 = "¿Eh? ¿En serio?",
  str_homestory_chat_13522003 = "¡Mirar! ¿Mis ojeras ahora no son más pequeñas?",
  str_homestory_chat_13522004 = "Creo que sí.",
  str_homestory_chat_13522005 = "¡Porque no he trabajado ningún turno extra últimamente!",
  str_homestory_chat_13522006 = "Hay tan poco trabajo que hacer aquí. No necesito quedarme despierto hasta tarde en absoluto.",
  str_homestory_chat_13522007 = "¡Eso es genial! ¡Bien por usted!",
  str_homestory_chat_13522008 = "Realmente no.",
  str_homestory_chat_13522009 = "Hmm... ¿Cómo podría ser esto?",
  str_homestory_chat_13522010 = "No me quedé hasta tarde trabajando en absoluto...",
  str_homestory_chat_13522011 = "Acostarse temprano podría ayudar.",
  str_homestory_chat_13522012 = "Tienes razón.",
  str_homestory_chat_13551001 = "¿Quieres hablarme de un pez especial?",
  str_homestory_chat_13551002 = "¡Así es! Y tengo que hacer una entrega después de que te lo cuente.",
  str_homestory_chat_13551003 = "Pero, ¿por qué alguien en Cloud Gardens necesitaría algo entregado?",
  str_homestory_chat_13551004 = "¿No estás aquí para descansar?",
  str_homestory_chat_13551005 = "¡No, estoy aquí para entrenar! ¡Y no puedo parar! De todos modos, ¡este pez especial también es un tema de mi entrenamiento!",
  str_homestory_chat_13551006 = "¿Un sujeto? Lo dices bastante en serio, ¿no?",
  str_homestory_chat_13551007 = "¡Por supuesto, es por eso que no te diré nada hasta que me des las semillas de los árboles florecientes sonoros!",
  str_homestory_chat_13551008 = "¿Ah?",
  str_homestory_chat_13551009 = "A veces se requiere un poco de espera como parte del entrenamiento.",
  str_homestory_chat_13551010 = "¡El tiempo perdido también se tiene en cuenta! ¡Entonces ve! ¡Ahora!",
  str_homestory_chat_13551011 = "Um, entonces, ¿tienes prisa o no? Esto es... raro.",
  str_homestory_chat_13551012 = "¡Solo vamos! ¡Semillas de Árboles Florecientes Sonoros! ¡Ahora!",
  str_homestory_chat_13551013 = "¡Okey, okey!",
  str_homestory_chat_14299999 = "PlayerName, ¿cómo estás?",
  str_homestory_chat_14201001 = "Hola...",
