  str_homestory_chat_15822008 = "¡Te prometo que una pancarta mejorará nuestro hogar!",
  str_homestory_chat_15851001 = "¿Conoces los pescados especiales?",
  str_homestory_chat_15851002 = "¡Eso fue rápido! Supongo que quieres mucho esos pescados especiales.",
