  str_homestory_chat_17622004 = "Estás lleno de mentiras.",
  str_homestory_chat_17622005 = "Bien, esta vez te dejaré hablar primero.",
  str_homestory_chat_17622006 = "... No tengo mucho que decir.",
  str_homestory_chat_17622007 = "... Hmm... Err... ¿Qué se supone que debo decir?",
  str_homestory_chat_17622008 = "Realmente sabes cómo mantener una conversación.",
  str_homestory_chat_17623001 = "¿Qué estás mirando?",
  str_homestory_chat_17623002 = "Este río... ¿Hacia dónde va?",
  str_homestory_chat_17623003 = "no tengo respuesta para eso...",
  str_homestory_chat_17623004 = "Tal vez este río me lleve al océano que leí en libros antiguos...",
  str_homestory_chat_17623005 = "Bajo las olas se alza un palacio silencioso...",
  str_homestory_chat_17623006 = "Este río no tiene nada de especial... No esperes cosas tan fantásticas de él...",
  str_homestory_chat_17623007 = "Yo se la respuesta...",
  str_homestory_chat_17623008 = "Pero ahora mismo no me llega...",
  str_homestory_chat_17623009 = "Umm... Tu memoria debe ser excepcional.",
  str_homestory_chat_17899999 = "Ah... Hola.",
  str_homestory_chat_17801001 = "Hola, Robyn.",
  str_homestory_chat_17801002 = "Por favor, mantenga esta distancia. No te acerques demasiado... ni te alejes demasiado.",
  str_homestory_chat_17801003 = "¿Está bien que me pare aquí?",
  str_homestory_chat_17801004 = "Sí.",
  str_homestory_chat_17821001 = "¿Estas buscando a alguien?",
  str_homestory_chat_17821002 = "Sabes donde Dayna ¿es?",
  str_homestory_chat_17821003 = "Por ahí...",
  str_homestory_chat_17821004 = "Ah, ya veo... Muchas gracias.",
  str_homestory_chat_17821005 = "Será mejor que me vaya... Perdona si te hice perder el tiempo.",
  str_homestory_chat_17821006 = "No te preocupes.",
  str_homestory_chat_17821007 = "No lo sé...",
  str_homestory_chat_17821008 = "¿Cómo podría ser esto? Debe estar muy preocupada...",
  str_homestory_chat_17821009 = "Ustedes dos siempre se están buscando...",
  str_homestory_chat_17821010 = "Porque solo nos tenemos el uno al otro.",
  str_homestory_chat_17822001 = "¿Parece que te gusta mucho aquí?",
  str_homestory_chat_17822002 = "Sí mucho.",
  str_homestory_chat_17822003 = "Esto es muy lindo aquí... De hecho anhelábamos un lugar como este.",
  str_homestory_chat_17822004 = "Lo siento... no soy muy bueno elogiando...",
  str_homestory_chat_17822005 = "Si pudieras entender...",
  str_homestory_chat_17822006 = "Sí.",
  str_homestory_chat_17823001 = "¿Qué estás tratando de decir?",
  str_homestory_chat_17823002 = "... Gracias por tenerme aquí.",
  str_homestory_chat_17823003 = "Por favor, avíseme si hay algo en lo que pueda ayudarlo.",
  str_homestory_chat_17823004 = "ahora mismo no se me ocurre nada...",
  str_homestory_chat_17823005 = "Ah, ya veo... te dejo.",
  str_homestory_chat_17823006 = "¡Necesito tu ayuda!",
  str_homestory_chat_17823007 = "Pero no ahora. Te avisaré cuando esté listo.",
  str_homestory_chat_17823008 = "Sí. Eso seria genial.",
  str_homestory_chat_17399999 = "¿Nos trajiste alguna golosina?",
  str_homestory_chat_17301001 = "No...",
  str_homestory_chat_17301002 = "¡Esta bien!",
  str_homestory_chat_17301003 = "¡No lo olvides la próxima vez!",
  str_homestory_chat_17321001 = "¿Te gusta aquí?",
  str_homestory_chat_17321002 = "¡Sí! ¡Es perfecto para jugar al escondite!",
  str_homestory_chat_17321003 = "¿Quiero jugar?",
  str_homestory_chat_17321004 = "¡Cuenta hasta diez!",
  str_homestory_chat_17321005 = "¡Y comienza el juego!",
  str_homestory_chat_17321006 = "¡Corre!",
  str_homestory_chat_17321007 = "¡Viniendo tras de ti!",
  str_homestory_chat_17321008 = "¡No! ¡Me niego a jugar!",
  str_homestory_chat_17322001 = "Pareces muy feliz.",
  str_homestory_chat_17322002 = "¡Sí! ¡Aquí hay agua fresca!",
  str_homestory_chat_17322003 = "¡A Doggy le encanta estar aquí!",
  str_homestory_chat_17322004 = "Espera...",
  str_homestory_chat_17322005 = "¿Bebiste del río?",
  str_homestory_chat_17322006 = "¿No debería?",
  str_homestory_chat_17322007 = "¿Qué pasaría?",
  str_homestory_chat_17322008 = "Porque... ¡A alguien le gusta nadar en el río!",
  str_homestory_chat_11699999 = "Hola. Duerme bien esta noche.",
  str_homestory_chat_11601001 = "Ah... hola.",
  str_homestory_chat_11601002 = "¿Qué tal?",
  str_homestory_chat_11601003 = "No mucho.",
  str_homestory_chat_11601004 = "En ese caso, tomaré una siesta.",
  str_homestory_chat_11601005 = "Bien. Descansa bien.",
  str_homestory_chat_11621001 = "Tus ojos...",
  str_homestory_chat_11621002 = "Mis ojeras prácticamente se han ido.",
  str_homestory_chat_11621003 = "Una buena noche de sueño mejora mi estado de ánimo.",
  str_homestory_chat_11621004 = "¿Te acabas de levantar?",
  str_homestory_chat_11621005 = "Sí. Es mucho más fácil encontrar un lugar tranquilo para tomar una siesta aquí que en el desierto.",
  str_homestory_chat_11621006 = "Hablando de eso, me gustaría darte las gracias.",
  str_homestory_chat_11621007 = "jajaja Eres muy bienvenido.",
  str_homestory_chat_11622001 = "¿Puedo ayudarte?",
  str_homestory_chat_11622002 = "PlayerName, ¿tienes alguna merienda?",
  str_homestory_chat_11622003 = "¡Sí!",
  str_homestory_chat_11622004 = "Dame algo.",
  str_homestory_chat_11622005 = "Pero no lo tengo conmigo.",
  str_homestory_chat_11622006 = "Tráeme un poco si puedes uno de estos días.",
  str_homestory_chat_11622007 = "No...",
  str_homestory_chat_11622008 = "Te traeré un poco cuando tenga.",
  str_homestory_chat_11622009 = "Gracias de antemano.",
  str_homestory_chat_11622010 = "Los bocadillos son la única forma de matar el tiempo.",
  str_homestory_chat_11623001 = "¿Qué estás buscando?",
  str_homestory_chat_11623002 = "Tantas criaturas esponjosas aquí...",
  str_homestory_chat_11623003 = "¿No te gustan estos?",
  str_homestory_chat_11623004 = "No puedo decir que sí... Tampoco me desagradan.",
  str_homestory_chat_11623005 = "Pero si alguien se atreve a maltratarlos, lo haré sufrir.",
  str_homestory_chat_17799999 = "La persona en la que he estado pensando, encantada de verte.",
  str_homestory_chat_17701001 = "Me está halagando, Su Majestad.",
  str_homestory_chat_17701002 = "¡Que la paz permanezca en esta tierra!",
  str_homestory_chat_17701003 = "Del mismo modo, Su Majestad.",
  str_homestory_chat_17721001 = "Su Majestad, ¿qué tiene en mente?",
  str_homestory_chat_17721002 = "Me alegra ver a tanta gente haciéndote compañía en este viaje.",
  str_homestory_chat_17721003 = "Muchas personas en esta tierra están felices de seguirte.",
  str_homestory_chat_17721004 = "Todos somos amigos.",
  str_homestory_chat_17721005 = "Creo que nuestra amistad nos ha unido. No son mis seguidores.",
  str_homestory_chat_17721006 = "Me agrada que lo veas así.",
  str_homestory_chat_17721007 = "¿También soy amigo tuyo?",
  str_homestory_chat_17721008 = "¡Por supuesto!",
  str_homestory_chat_17722001 = "Su Majestad, ¿está todo bien aquí para usted?",
  str_homestory_chat_17722002 = "El paisaje aquí es muy diferente al de Northland, pero estoy relajado y feliz.",
  str_homestory_chat_17722003 = "Eres un anfitrión fantástico.",
  str_homestory_chat_17722004 = "Tu té negro es bastante amargo, la colección de libros es muy limitada y la temperatura es incómodamente alta...",
  str_homestory_chat_17722005 = "Estoy muy contento con todo lo demás aquí.",
  str_homestory_chat_17722006 = "¡Ay! Ya veo...",
  str_homestory_chat_17723001 = "Aquí estoy.",
  str_homestory_chat_17723002 = "El libro que te envié... ¿Cuánto has leído?",
  str_homestory_chat_17723003 = "¡He terminado todo!",
  str_homestory_chat_17723004 = "Debes haber aprendido mucho.",
  str_homestory_chat_17723005 = "Déjame ayudarte a probar tu absorción de conocimiento.",
  str_homestory_chat_17723006 = "No... Eso no será necesario, Su Majestad...",
  str_homestory_chat_17723007 = "Solo leí la mitad...",
  str_homestory_chat_17723008 = "La mitad de este libro tan útil es suficiente para digerirlo.",
  str_homestory_chat_17723009 = "Dime cómo te sientes al respecto.",
  str_homestory_chat_17723010 = "Yo... yo... ¿Puedo tener un minuto para pensar?",
  str_homestory_chat_17723011 = "no he empezado...",
  str_homestory_chat_17723012 = "...",
  str_homestory_chat_17723013 = "Quería leer pero pasaron muchas cosas...",
  str_homestory_chat_17723014 = "Te consultaré de nuevo en un futuro próximo. Será mejor que lo hagas.",
  str_homestory_chat_17723015 = "¿Ah?",
  str_homestory_chat_17724001 = "Su Majestad, ¿está dando un paseo tranquilo?",
  str_homestory_chat_17724002 = "Sí, PlayerName. ¿Qué haces por placer?",
  str_homestory_chat_17724003 = "Apenas tengo tiempo libre...",
  str_homestory_chat_17724004 = "Hmm... Supongo que volverás al trabajo después de nuestra charla.",
  str_homestory_chat_17724005 = "Eso es correcto.",
  str_homestory_chat_17724006 = "Su Majestad, ¿puedo ofrecerle algo?",
  str_homestory_chat_17724007 = "Hoy no. Charlaremos más la próxima vez.",
  str_homestory_chat_17724008 = "Muchas cosas...",
  str_homestory_chat_17724009 = "Jugaría, iría a pescar y haría algo de ejercicio...",
  str_homestory_chat_17724010 = "¿Practicas esgrima?",
  str_homestory_chat_17724011 = "¿Oh? ¿Esgrima?",
  str_homestory_chat_17724012 = "¡Ay! Lo tengo. ¿Su majestad necesita espacio para hacer ejercicios de esgrima?",
  str_homestory_chat_17724013 = "Tu inteligencia nunca deja de sorprenderme.",
  str_homestory_chat_17725001 = "¿Me está buscando, su majestad?",
  str_homestory_chat_17725002 = "Sí, he estado contemplando tus habilidades personales.",
  str_homestory_chat_17725003 = "Habilidades personales...?",
  str_homestory_chat_17725004 = "Tu destreza en las artes marciales, especialmente en defensa personal.",
  str_homestory_chat_17725005 = "Porque estuviste en situaciones peligrosas muchas veces y no tuviste lo necesario para proteger a tus compañeros.",
  str_homestory_chat_17725006 = "En situaciones como estas, lo menos que puedes hacer es protegerte. Después de pensar en esto por un tiempo...",
  str_homestory_chat_17725007 = "Creo que te enseñaré algunas técnicas de espada para defensa personal.",
  str_homestory_chat_17725008 = "¿Técnicas de espada? Eso suena bien... Pero creo que tendré que desarrollar mi fuerza primero.",
  str_homestory_chat_17725009 = "Las técnicas son secundarias. La parte más importante es tu resistencia.",
  str_homestory_chat_17725010 = "Por ejemplo, ¿por qué no empezamos con diez vueltas? Aumentará tu resistencia y podrás correr más rápido cuando huyas del peligro.",
  str_homestory_chat_17725011 = "Um, eso es lo que realmente quiere que haga, ¿no es así, su majestad?",
  str_homestory_chat_17726001 = "¿El cielo?",
  str_homestory_chat_17726002 = "Sí, estuve mirando al cielo y me di cuenta de que hay algo mal con Cloud Gardens.",
  str_homestory_chat_17726003 = "¿Qué quieres decir?",
  str_homestory_chat_17726004 = "El cielo está indefenso. Cloud Gardens está rodeado de montañas, por lo que es difícil para los ataques terrestres.",
  str_homestory_chat_17726005 = "Pero los ataques desde arriba son difíciles de defender.",
  str_homestory_chat_17726006 = "Y tampoco tenemos a nadie patrullando los cielos.",
  str_homestory_chat_17726007 = "Um, ¿qué tal el Coloso?",
  str_homestory_chat_17726008 = "¿Tiene alguna capacidad de combate?",
  str_homestory_chat_17726009 = "Bueno, al menos puede emitir una advertencia.",
  str_homestory_chat_17726010 = "Estás en lo correcto. Estaba pensando demasiado en las cosas.",
  str_homestory_chat_17727001 = "Chubbs?",
  str_homestory_chat_17727002 = "¿Qué piensas de ellos?",
  str_homestory_chat_17727003 = "son compañeros",
  str_homestory_chat_17727004 = "¿Te gustan los aurorianos?",
  str_homestory_chat_17727005 = "Hmm, tal vez un poco diferente, porque pasan el rato principalmente en Cloud Gardens.",
  str_homestory_chat_17727006 = "Ellos son ayudantes.",
  str_homestory_chat_17727007 = "¿Solo ayudantes?",
  str_homestory_chat_17727008 = "Tal vez también lo sean...",
  str_homestory_chat_17727009 = "¿Administradores de este lugar?",
  str_homestory_chat_17727010 = "¿Has pensado en darles más responsabilidades?",
  str_homestory_chat_17727011 = "Por ejemplo, permitirles abordar el Coloso o enviarlos a otros pueblos como mensajeros de Cloud Gardens.",
  str_homestory_chat_17727012 = "Creo... que es un poco demasiado pronto.",
  str_homestory_chat_16499999 = "PlayerName, te ves relajado y despreocupado hoy..",
  str_homestory_chat_16421001 = "¿Me estás vigilando?",
  str_homestory_chat_16421002 = "Te importa, PlayerName?",
  str_homestory_chat_16421003 = "Uf... yo nunca dije eso...",
  str_homestory_chat_16421004 = "Parece que mi supervisión te está impulsando a seguir adelante.",
  str_homestory_chat_16422001 = "Sí, me estoy tomando un descanso.",
  str_homestory_chat_16422002 = "... ¿Ya es la pausa para el café?",
  str_homestory_chat_16422003 = "Eso es correcto.",
  str_homestory_chat_16422004 = "Su horario está planificado demasiado libremente. ¿Cómo podrías tomarte un descanso ahora?",
  str_homestory_chat_16422005 = "Me temo que no...",
  str_homestory_chat_16422006 = "En este caso, termina nuestra conversación de inmediato y vuelve al trabajo.",
  str_homestory_chat_16422007 = "Tienes que mantenerte ocupado como yo.",
  str_homestory_chat_16422008 = "Pero... no creo que estés haciendo mucho en este momento.",
  str_homestory_chat_16422009 = "... No te dejes engañar por mi apariencia. Estoy muy concentrado.",
  str_homestory_chat_16423001 = "¿Qué estás haciendo?",
  str_homestory_chat_16423002 = "Meditación.",
  str_homestory_chat_16423003 = "... No me mires así.",
  str_homestory_chat_16423004 = "Si te enfrentas a la misma cantidad de presión que yo, estoy seguro de que también meditarías para tu paz interior.",
  str_homestory_chat_16423005 = "Bien. Supongo que te dejaré a ti.",
  str_homestory_chat_16424001 = "¿Buscándome?",
  str_homestory_chat_16424002 = "Hay algo que debes saber.",
  str_homestory_chat_16424003 = "¿Qué es?",
  str_homestory_chat_16424004 = "No puedo encontrar ningún lugar para usar el poder del Barón Rojo.",
  str_homestory_chat_16424005 = "Necesitas construir un campo de entrenamiento.",
  str_homestory_chat_16424006 = "¿Se me permite rechazar esta idea?",
  str_homestory_chat_16424007 = "Es mejor no usar esta peligrosa arma aquí.",
  str_homestory_chat_16424008 = "... ¿Tú crees que sí? Bueno, creo que es mejor tener un campo de entrenamiento.",
  str_homestory_chat_16424009 = "¡Seguro!",
  str_homestory_chat_16424010 = "Un campo de entrenamiento es bueno para todos nosotros.",
  str_homestory_chat_16424011 = "Estaré esperando una invitación para su gira de campo de entrenamiento.",
  str_homestory_chat_15799999 = "Hola. ¿Qué pasa, miau?",
  str_homestory_chat_15701001 = "Hola.",
  str_homestory_chat_15701002 = "No mucho. Solo vine a saludar.",
  str_homestory_chat_15701003 = "Ya veo. Yo también te saludaría entonces...",
  str_homestory_chat_15701004 = "¡Hola! hola, miau...",
  str_homestory_chat_15721001 = "¿Te gusta aquí?",
  str_homestory_chat_15721002 = "Sí, me encanta, miau.",
  str_homestory_chat_15721003 = "Puedo dormir a gusto aquí, miau.",
  str_homestory_chat_15721004 = "¿Siempre tienes sueño?",
  str_homestory_chat_15721005 = "No tengo sueño, simplemente me encanta dormir, ¡miau!",
  str_homestory_chat_15721006 = "Una cama suave y cómoda lo hará aún mejor, miau.",
  str_homestory_chat_15721007 = "Señalado.",
  str_homestory_chat_15722001 = "¿Qué estás haciendo?",
  str_homestory_chat_15722002 = "Nadie me da de comer pescado seco...",
  str_homestory_chat_15722003 = "He decidido cocinar para mí, ¡miau!",
  str_homestory_chat_15722004 = "¿Cuál es el plan?",
  str_homestory_chat_15722005 = "Iré a pescar primero, miau.",
  str_homestory_chat_15722006 = "Pero, ¿y si me duermo y me ahogo en el río?",
  str_homestory_chat_15722007 = "¡Tengo algo de pescado seco!",
  str_homestory_chat_15722008 = "Comparte conmigo, miau.",
  str_homestory_chat_15722009 = "Te lo devolveré, miau.",
  str_homestory_chat_15722010 = "Aunque no lo tengo conmigo...",
  str_homestory_chat_15722011 = "Suspiro... Te visitaré en breve, miau.",
  str_homestory_chat_15723001 = "Tu cabello...",
  str_homestory_chat_15723002 = "Mi cabello se ve desordenado pero se siente muy suave, miau.",
  str_homestory_chat_15723003 = "¿Puedo probar?",
  str_homestory_chat_15723004 = "Pero acabo de lamer limpio...",
  str_homestory_chat_15723005 = "Adelante si no te importa, miau.",
  str_homestory_chat_15723006 = "Err...",
  str_homestory_chat_15723007 = "Vamos a cepillarte un poco...",
  str_homestory_chat_15723008 = "Puede sentirse incluso mejor después.",
  str_homestory_chat_15723009 = "No. Arreglar es agotador, miau.",
  str_homestory_chat_15724001 = "¿Como estuvo tu sueño?",
  str_homestory_chat_15724002 = "Fue un largo sueño. No puedo quedarme despierto aquí, miau.",
  str_homestory_chat_15724003 = "¿Yumi?",
  str_homestory_chat_15724004 = "¿No es obvio, miau?",
  str_homestory_chat_15724005 = "... Me acabo de despertar y estoy lista para dormir más, miau.",
  str_homestory_chat_15724006 = "Qué tal si Philyshy?",
  str_homestory_chat_15724007 = "Philyshy ya está dormido, miau.",
  str_homestory_chat_15724008 = "Estuvo alerta durante demasiado tiempo, miau. Es su turno de descansar.",
  str_homestory_chat_15724009 = "No la despertaré por ti, miau.",
  str_homestory_chat_18399999 = "Hola maestro. Declaración. Las tareas de hoy están completas.",
  str_homestory_chat_18321001 = "Hmm...",
  str_homestory_chat_18321002 = "Solo vine a saludar. No es una inspección...",
  str_homestory_chat_18321003 = "Traducir y convertir. Lilliam comprendido.",
  str_homestory_chat_18322001 = "¿Que piensas de este lugar?",
  str_homestory_chat_18322002 = "Traducir y convertir. Puede usar algo de limpieza. Maestro, por favor dé una orden de limpieza.",
  str_homestory_chat_18322003 = "Eso no será necesario...",
  str_homestory_chat_18322004 = "Limpiar es mucho trabajo...",
  str_homestory_chat_18322005 = "Organizaré algo más para que hagas, ¿de acuerdo?",
  str_homestory_chat_18322006 = "Exageración. Bueno.",
  str_homestory_chat_18322007 = "Buena idea.",
  str_homestory_chat_18322008 = "Pero espere hasta que todos los demás terminen su trabajo.",
  str_homestory_chat_18322009 = "Determinando... Tienes razón.",
  str_homestory_chat_18323001 = "¿Qué estás haciendo?",
  str_homestory_chat_18323002 = "Pidiendo. ¿Como puedo ayudarte?",
  str_homestory_chat_18323003 = "Ah... Nada en particular...",
  str_homestory_chat_18323004 = "Declaración. Lilliam Cree que necesita muchas cosas pero decide ignorarlas.",
  str_homestory_chat_18323005 = "Declaración. Necesitas un poco de ejercicio de pensamiento para hacer mejores demandas.",
  str_homestory_chat_18323006 = "No lo creo...",
  str_homestory_chat_18323007 = "Lo pensare...",
  str_homestory_chat_18323008 = "Exageración. Necesitas pensar claramente lo que quieres de antemano para que Lilliam puede ponerse a trabajar rápidamente.",
  str_homestory_chat_18323009 = "Ah bien. Trabajaré en eso.",
  str_homestory_chat_18324001 = "¿Quieres tomar un descanso?",
  str_homestory_chat_18324002 = "Traduciendo y convirtiendo... Lilliam todavía está lo suficientemente motivada para completar el próximo trabajo.",
  str_homestory_chat_18324003 = "Maestro, ¿hay un nuevo trabajo?",
  str_homestory_chat_18324004 = "No en realidad no.",
  str_homestory_chat_18324005 = "Solo te veo limpiando o haciendo otro trabajo todo el tiempo.",
  str_homestory_chat_18324006 = "Cloud Gardens está destinado a ser un lugar para descansar. Puedes tomar un descanso aquí.",
  str_homestory_chat_18324007 = "Maestro, ¿me está ordenando que tome un descanso?",
  str_homestory_chat_18324008 = "Sí.",
  str_homestory_chat_18324009 = "Comprendido. Lilliam tomará un descanso ahora.",
  str_homestory_chat_18325001 = "¿Escuché que tenías una hermana?",
  str_homestory_chat_18325002 = "¿Te refieres al número 2?",
  str_homestory_chat_18325003 = "Sí.",
  str_homestory_chat_18325004 = "No. 2 no es mi hermana.",
  str_homestory_chat_18325005 = "No.",
  str_homestory_chat_18325006 = "¿A quién te refieres?",
  str_homestory_chat_18325007 = "Bueno... Olvídalo, hice la pregunta equivocada.",
  str_homestory_chat_18325008 = "Solo quería preguntarte si había alguien cercano a ti, como un buen amigo.",
  str_homestory_chat_18325009 = "Podemos invitarlos aquí como nuestros invitados porque siempre estás solo.",
  str_homestory_chat_18325010 = "Traduciendo y convirtiendo... Maestro, ¿está encontrando un socio para Lilliam?",
  str_homestory_chat_18325011 = "Er... ¿Sabes qué, Lilliam? Sigue como siempre lo haces.",
