  str_homestory_chat_19601004 = "Está bien.",
  str_homestory_chat_19601005 = "Más vale tarde que nunca... Hola.",
  str_homestory_chat_19621001 = "Que tienes que decir?",
  str_homestory_chat_19621002 = "Tengo una solicitud que hacer, pero no estoy seguro de si está bien preguntar...",
  str_homestory_chat_19621003 = "Pruébame.",
  str_homestory_chat_19621004 = "¿Podrías acercarte?",
  str_homestory_chat_19621005 = "Ahh... Eh...",
  str_homestory_chat_19621006 = "¿Por qué tu cara se pone roja?",
  str_homestory_chat_19621007 = "Por favor, no me tomes a mal. Solo quería que te pararas más cerca...",
  str_homestory_chat_19621008 = "El paisaje detrás de ti se vería más simétrico.",
  str_homestory_chat_19622001 = "¿Qué estás buscando?",
  str_homestory_chat_19622002 = "¿Has visto un gato negro hace un momento?",
  str_homestory_chat_19622003 = "¡Sí!",
  str_homestory_chat_19622004 = "¿Dónde? ¡Muéstrame!",
