  str_homestory_chat_19622006 = "Ok...",
  str_homestory_chat_19622007 = "No...",
  str_homestory_chat_19622008 = "Lo vi correr de esta manera...",
  str_homestory_chat_19622009 = "Ah... Olvídalo si nadie más lo vio.",
  str_homestory_chat_19623001 = "¿Qué estás haciendo?",
