  str_homestory_chat_19624003 = "¡Qué alegría escuchar!",
  str_homestory_chat_19624004 = "Cuando llegué por primera vez a Umbraton, me estafaron y perdí mucho dinero.",
  str_homestory_chat_19624005 = "No he conocido a un solo estafador aquí.",
  str_homestory_chat_19624006 = "... ¿En serio?",
  str_homestory_chat_19624007 = "¡Hay estafadores que no buscan su dinero!",
  str_homestory_chat_20399999 = "PlayerName, ¿cuál es el plan para hoy?",
