  str_homestory_chat_20301002 = "Bueno. ¿Algún sospechoso para interrogar hoy?",
  str_homestory_chat_20301003 = "¿Cuándo tuvimos alguno?",
  str_homestory_chat_20301004 = "Entonces no?",
  str_homestory_chat_20301005 = "¡Claro que no!",
  str_homestory_chat_20321001 = "Tu parche en el ojo...",
