  str_homestory_chat_20321008 = "Te pedí que dejaras de mirar mi parche en el ojo porque...",
  str_homestory_chat_20321009 = "¡Tu mirada es muy extraña!",
  str_homestory_chat_20322001 = "¿Qué tienes en mente?",
  str_homestory_chat_20322002 = "No he visto eso por un tiempo.",
  str_homestory_chat_20322003 = "¿De qué estás hablando?",
  str_homestory_chat_20322004 = "Sabes. Esos rostros ensangrentados se retorcieron de dolor.",
  str_homestory_chat_20322005 = "Me estoy aburriendo.",
  str_homestory_chat_20322006 = "...",
  str_homestory_chat_20323001 = "¿Está pidiendo una sala de interrogatorios?",
  str_homestory_chat_20323002 = "Así es. ¿Cuándo podemos construir uno?",
  str_homestory_chat_20323003 = "¿Por qué necesitamos uno?",
  str_homestory_chat_20323004 = "Porque es esencial para mi trabajo.",
  str_homestory_chat_20323005 = "No estamos construyendo una sala de interrogatorios.",
