  str_homestory_chat_20324001 = "¿Estás comprando algo?",
  str_homestory_chat_20324002 = "¡Sí, una máscara para los ojos!",
  str_homestory_chat_20324003 = "¿Un parche en el ojo?",
  str_homestory_chat_20324004 = "Siempre llevo este parche en el ojo. Creo que me estoy cansando de eso.",
