  str_homestory_chat_20324009 = "Creo que le estoy preguntando a la persona equivocada. tal vez debería preguntar Vice?",
  str_homestory_chat_20324010 = "ella es...",
  str_homestory_chat_20324011 = "Oh, ¿crees que hay algo mal con ella? Lo anotaré primero, jeje.",
  str_homestory_chat_20324012 = "¡No!",
  str_homestory_chat_20325001 = "¿Quieres entrenar?",
  str_homestory_chat_20325002 = "Sí, siento que he estado aquí por mucho tiempo recientemente. Mis habilidades de interrogatorio se sienten oxidadas.",
  str_homestory_chat_20325003 = "Realmente no necesitas practicar eso...",
  str_homestory_chat_20325004 = "¡De ninguna manera! Eso es lo único que me encanta hacer, quiero decir, es lo que mejor hago.",
