  str_homestory_chat_20325006 = "¡No puedes hacerme eso!",
  str_homestory_chat_20325007 = "Ya que estás en Cloud Gardens, también podrías disfrutar de la vida aquí...",
  str_homestory_chat_20325008 = "Disfruta... Sin embargo, disfruto los interrogatorios.",
  str_homestory_chat_20325009 = "¿Qué tal si... practico con los Chubbs? Se ven tan blancos y regordetes.",
  str_homestory_chat_20325010 = "¡Absolutamente no! ¡Nunca!",
  str_homestory_chat_20326001 = "Dormitorio...",
  str_homestory_chat_20326002 = "¿Como lo descubriste? Solo lo mencioné una vez y acabas de escuchar sobre él.",
  str_homestory_chat_20326003 = "Pero me ahorra la molestia de acudir a ti ya que me lo pides. Quiero construir un dormitorio. ¿Qué opinas?",
