  str_homestory_chat_20326012 = "ella es la dama Victoria!",
  str_homestory_chat_20326013 = "D-Déjame pensarlo.",
  str_homestory_chat_19399999 = "Hola, joven hombre.",
  str_homestory_chat_19301001 = "Hola, Migard.",
  str_homestory_chat_19301002 = "¿Finalmente has decidido ofrecerte por mi anatomía?",
  str_homestory_chat_19301003 = "¡No! ¡Nunca!",
  str_homestory_chat_19301004 = "Bueno, piénsalo un poco más.",
