  str_homestory_chat_19321002 = "Claro, joven. ¿Qué te gustaría hablar?",
  str_homestory_chat_19321003 = "Es mejor que sea algo divertido. No estoy de humor para asuntos triviales.",
  str_homestory_chat_19321004 = "Ah... ¿Qué debo hacer?",
  str_homestory_chat_19321005 = "Lo que sea que estés a punto de decir, pruébalo primero en tu corazón y ve si es divertido.",
  str_homestory_chat_19321006 = "...",
  str_homestory_chat_19321007 = "Decido no decir nada.",
  str_homestory_chat_19321008 = "Mmm. Excelente.",
  str_homestory_chat_19322001 = "¿Cómo te llevas aquí?",
