  str_homestory_chat_19323007 = "Nunca puedo dormir lo suficiente.",
  str_homestory_chat_19323008 = "Aquí igual.",
  str_homestory_chat_19323009 = "Vamos. Hora de acostarse.",
  str_homestory_chat_19323010 = "... ¡Esperar! ¡Tengo cosas que hacer!",
