  str_homestory_chat_19701001 = "Hola.",
  str_homestory_chat_19701002 = "¿Estás enfermo?",
  str_homestory_chat_19701003 = "... No. ¿Por qué preguntaste?",
  str_homestory_chat_19701004 = "Si alguien me hace esta pregunta, lo más probable es que esté aquí buscando tratamiento.",
  str_homestory_chat_19721001 = "Eres muy limpio.",
  str_homestory_chat_19721002 = "Puedo compartir mi procedimiento de lavado de manos aquí si es necesario.",
