  str_homestory_chat_19722001 = "¿Te desagrada el sol?",
  str_homestory_chat_19722002 = "Es un poco demasiado brillante.",
  str_homestory_chat_19722003 = "Precisamente hablando, no me disgusta particularmente la luz del sol...",
