  str_homestory_chat_19899999 = "PlayerName, bueno verte de nuevo hoy.",
  str_homestory_chat_19801001 = "Hola, Cuscuta.",
  str_homestory_chat_19801002 = "¿Cómo te trata la vida aquí?",
