  str_homestory_chat_19821002 = "Creo que uno debe desarrollar sentimientos para expresar sentimientos.",
  str_homestory_chat_19821003 = "Pero yo... Es difícil para mí tener emociones.",
  str_homestory_chat_19821004 = "Algunos me llamaron un buen oyente.",
