  str_homestory_chat_19921001 = "¿Como te sientes hoy?",
  str_homestory_chat_19921002 = "No te preocupes por mí. Las espinas negras en mi cuerpo no están creciendo.",
  str_homestory_chat_19922001 = "¿Qué tienes en mente?",
