  str_homestory_chat_19923006 = "¡Eso es genial!",
  str_homestory_chat_19923007 = "¡No necesito pedir otro!",
  str_homestory_chat_19923008 = "Verdadero...",
  str_homestory_chat_19923009 = "Pero es diminuto. Apenas puedes verlo.",
