  str_homestory_chat_20025005 = "No he pensado tan lejos todavía.",
  str_homestory_chat_20025006 = "Probablemente deberías hacerlo a veces. Esto es solo una parada, después de todo.",
  str_homestory_chat_20025007 = "Puedo sentir que tienes un largo futuro lleno de posibilidades por delante.",
  str_homestory_chat_20025008 = "Eso es... algo serio de tu parte.",
  str_homestory_chat_20025009 = "Sí. Y cuando llegue el momento, puedo velar por este lugar por ti.",
  str_homestory_chat_20025010 = "Justo como protegí la Cripta antes.",
  str_homestory_chat_20025011 = "Correcto... Gracias.",
  str_homestory_chat_18799999 = "No hace falta que me saludes. Di lo que tengas que decir.",
  str_homestory_chat_18701001 = "Ah bien...",
  str_homestory_chat_18701002 = "Saludar es una pérdida de tiempo.",
  str_homestory_chat_18701003 = "Hmm... ¿Qué estaba diciendo?",
  str_homestory_chat_18721001 = "¿Qué estás buscando?",
  str_homestory_chat_18721002 = "¿No tenemos óperas tradicionales para ver aquí?",
  str_homestory_chat_18721003 = "No...",
  str_homestory_chat_18721004 = "Lamentablemente, las óperas tradicionales a menudo se consideran anticuadas.",
  str_homestory_chat_18721005 = "No creo que tengamos mucho interés aquí.",
  str_homestory_chat_18721006 = "No importa. Me buscaré otra cosa que hacer.",
  str_homestory_chat_18721007 = "Puedo organizar uno.",
  str_homestory_chat_18721008 = "Me sorprendes todo el tiempo.",
  str_homestory_chat_18721009 = "No es barato preparar la escena y conseguir actores profesionales.",
  str_homestory_chat_18721010 = "Y no creo que tengamos una gran audiencia aquí.",
  str_homestory_chat_18721011 = "¿Hablas en serio sobre esto?",
  str_homestory_chat_18721012 = "Por supuesto.",
  str_homestory_chat_18721013 = "Esperaré el espectáculo pacientemente.",
  str_homestory_chat_18722001 = "¿Estás practicando?",
  str_homestory_chat_18722002 = "PlayerName, juegas a los dardos?",
  str_homestory_chat_18722003 = "¡Sí!",
  str_homestory_chat_18722004 = "¿Vaya? Contento de escuchar.",
  str_homestory_chat_18722005 = "Ven y únete a mi.",
  str_homestory_chat_18722006 = "¿Ahora?",
  str_homestory_chat_18722007 = "¿Tienes cosas que hacer? La próxima vez entonces.",
  str_homestory_chat_18722008 = "Claro.",
  str_homestory_chat_18722009 = "Nunca...",
  str_homestory_chat_18722010 = "Esta bien. Puedes sostener el tablero por mí.",
  str_homestory_chat_18722011 = "... ¿Se me permite decir que no?",
  str_homestory_chat_18722012 = "¿Qué pasa? ¿Tienes miedo de mis dardos?",
  str_homestory_chat_18723001 = "Relax.",
  str_homestory_chat_18723002 = "Es seguro aquí. No tienes que estar alerta todo el tiempo.",
  str_homestory_chat_18723003 = "He venido aquí por su invitación. Ahora es mi deber proteger al civil.",
  str_homestory_chat_18723004 = "Gracias por tu servicio.",
  str_homestory_chat_18723005 = "De nada. La sangre azul viene con grandes responsabilidades.",
  str_homestory_chat_18723006 = "Aunque todos son iguales aquí...",
  str_homestory_chat_18723007 = "Mi fuerza sigue siendo parte de mi identidad.",
  str_homestory_chat_15699999 = "¿Qué tal tu día, chico?",
  str_homestory_chat_15601001 = "¡Bastante bien!",
  str_homestory_chat_15601002 = "Eso es adorable.",
  str_homestory_chat_15621001 = "¿Qué estás pensando?",
  str_homestory_chat_15621002 = "Una noche como esta es perfecta para la meditación.",
  str_homestory_chat_15621003 = "¿Te gustaría intentarlo?",
  str_homestory_chat_15621004 = "¡Seguro!",
  str_homestory_chat_15621005 = "Elegiré un lugar tranquilo para ti.",
  str_homestory_chat_15621006 = "No olvides nuestra promesa.",
  str_homestory_chat_15621007 = "Voy a pasar...",
  str_homestory_chat_15621008 = "¿Estás con miedo?",
  str_homestory_chat_15621009 = "No te preocupes. Aquí nada puede hacerte daño.",
  str_homestory_chat_15622001 = "¿Cómo te llevas aquí?",
  str_homestory_chat_15622002 = "Para mi sorpresa, me gusta más que Northland...",
  str_homestory_chat_15622003 = "No puedo creer que me haya establecido aquí.",
  str_homestory_chat_15622004 = "No hace mucho tiempo, sentar cabeza parecía estar muy lejos de mí.",
  str_homestory_chat_15622005 = "Eso es bueno...",
  str_homestory_chat_15622006 = "Para ser honesto, prefiero este clima templado.",
  str_homestory_chat_15622007 = "La Tierra del Norte es demasiado fría y dura...",
  str_homestory_chat_15622008 = "Eso es un alivio.",
  str_homestory_chat_19599999 = "¡Saludos señor! ¿Hay algo que pueda hacer por ti?",
  str_homestory_chat_19501001 = "No en este momento.",
  str_homestory_chat_19501002 = "Cualquier cosa que esté a mi alcance... daré lo mejor de mí.",
  str_homestory_chat_19501003 = "Yo aprecio.",
  str_homestory_chat_19521001 = "¿Qué es eso en tu mano?",
  str_homestory_chat_19521002 = "Frutas silvestres, señor.",
  str_homestory_chat_19521003 = "Encontré mucho en el bosque últimamente.",
  str_homestory_chat_19521004 = "¿Te gustaría echar un vistazo?",
  str_homestory_chat_19521005 = "¡Seguro!",
  str_homestory_chat_19521006 = "Pero tengo otras cosas de las que ocuparme...",
  str_homestory_chat_19521007 = "Lo dejo a usted, señor.",
  str_homestory_chat_19521008 = "Podemos ir cuando estés libre.",
  str_homestory_chat_19521009 = "Realmente no...",
  str_homestory_chat_19521010 = "No hay problema. Puedo traer algo para ti.",
  str_homestory_chat_19521011 = "¡Eso sería fantástico! Gracias.",
  str_homestory_chat_19522001 = "¿Cómo te estás acomodando?",
  str_homestory_chat_19522002 = "La cueva es muy cómoda. He puesto muchas cosas dentro.",
  str_homestory_chat_19522003 = "Me complace brindarte un recorrido cuando tengas tiempo.",
  str_homestory_chat_19522004 = "¿Prefieres quedarte en una cueva?",
  str_homestory_chat_19522005 = "Sí. Pero a la mayoría de los Aurorianos no les gusta el ambiente sombrío y húmedo.",
  str_homestory_chat_19522006 = "Tal vez no te importe.",
  str_homestory_chat_16299999 = "Hola, PlayerName. Encantado de verte.",
  str_homestory_chat_16201001 = "¿Cuál es tu plan para el día?",
  str_homestory_chat_16201002 = "Podría dar un paseo por el bosque.",
  str_homestory_chat_16221001 = "Parece que te gusta estar aquí.",
  str_homestory_chat_16221002 = "Gracias, PlayerName, por invitarme aquí.",
  str_homestory_chat_16221003 = "He hecho muchos amigos desde que llegué.",
  str_homestory_chat_16221004 = "Bueno saberlo.",
  str_homestory_chat_16221005 = "No importa dónde nos quedemos siempre y cuando tengamos amigos sinceros alrededor.",
  str_homestory_chat_16221006 = "Dicho esto, la vida aquí es muy cómoda y relajante.",
  str_homestory_chat_16222001 = "¿Tiene preguntas que hacer?",
  str_homestory_chat_16222002 = "¿Te importa si planto más enredaderas en la habitación?",
  str_homestory_chat_16222003 = "Para nada.",
  str_homestory_chat_16222004 = "¿Algún tipo en particular que tengas en mente? Puedo ayudarte a buscar.",
  str_homestory_chat_16222005 = "Muchísimas gracias. Su aprobación ya es una gran ayuda.",
  str_homestory_chat_16222006 = "no creo que sea una buena idea...",
  str_homestory_chat_16222007 = "Ah, ya veo...",
  str_homestory_chat_16222008 = "¿Y si las cultivo en macetas?",
  str_homestory_chat_16223001 = "¿Fue esto simplemente espontáneo?",
  str_homestory_chat_16223002 = "Sí, cada vez que vengo aquí, no puedo evitar maravillarme con las ventajas de este lugar.",
  str_homestory_chat_16223003 = "¿Ventajas?",
  str_homestory_chat_16223004 = "Es aislado, seguro, con un clima agradable y abundante agua y pasto.",
  str_homestory_chat_16223005 = "Si hubiera un lugar así en Northland... sería genial.",
  str_homestory_chat_16223006 = "El lugar que solías montar guardia, el Bosque de Barlovento, ¿no era así?",
  str_homestory_chat_16223007 = "Recuerdo que era una parte particularmente agradable de Northland.",
  str_homestory_chat_16223008 = "Sin embargo, eso solo se compara con otras partes de Northland. Sigo pensando que Cloud Gardens es mejor.",
  str_homestory_chat_16223009 = "A veces, incluso me pregunto si me convertiría en el guardián de este lugar...",
  str_homestory_chat_16223010 = "Me temo que las cosas serían mucho más fáciles y también tendría tiempo para pensar en algunos de mis propios problemas.",
  str_homestory_chat_16223011 = "Estás en Cloud Gardens ahora, no tienes que preocuparte por cosas como hacer guardia.",
  str_homestory_chat_16223012 = "Puedes tomarte un tiempo para reflexionar y relajarte.",
  str_homestory_chat_16223013 = "En efecto. Muchas gracias por la invitación.",
  str_homestory_chat_16223014 = "No lo menciones.",
  str_homestory_chat_16224001 = "¿Agua?",
  str_homestory_chat_16224002 = "Sí. May Pregunto, ¿entiendes el agua, Navegante?",
  str_homestory_chat_16224003 = "Yo entiendo el agua.",
  str_homestory_chat_16224004 = "Entonces, ¿qué pasa con la burbuja? Leah ¿hecho? ¿Sabes lo que significa?",
  str_homestory_chat_16224005 = "Erm... Realmente no tengo idea.",
  str_homestory_chat_16224006 = "No entiendo.",
  str_homestory_chat_16224007 = "Ah... Así que si quiero saber sobre la burbuja de Leah, tendré que preguntarle a alguien más.",
  str_homestory_chat_16224008 = "Pero, ¿por qué quieres saber sobre esa burbuja de repente?",
  str_homestory_chat_16224009 = "Lo encuentro muy interesante, muy parecido al rocío en el bosque después de haber sido expuesto a la luz del sol.",
  str_homestory_chat_16224010 = "Cierto.",
  str_homestory_chat_16224011 = "Una vez encontré una semilla en una gota de rocío. Probablemente lo había llevado allí el viento.",
  str_homestory_chat_16224012 = "Estas semillas suelen tener un aspecto turquesa, marrón o incluso negro.",
  str_homestory_chat_16224013 = "Lo que estoy tratando de decir es que parecía tener un cierto aura natural. ¿Entiendes, Navegante?",
  str_homestory_chat_16224014 = "Sí.",
  str_homestory_chat_16224015 = "Pero la semilla que vi parecía una esmeralda a la luz del sol.",
  str_homestory_chat_16224016 = "El agua... es milagrosa, como Leah.",
  str_homestory_chat_16224017 = "Entiendo...",
  str_homestory_chat_16225001 = "¿Profesor de esgrima?",
  str_homestory_chat_16225002 = "Un entrenador, para ser precisos.",
  str_homestory_chat_16225003 = "Mi padre dijo una vez que si quieres mejorar tu manejo de la espada, necesitas un entrenador.",
