  str_homestory_chat_16225005 = "Entonces, ¿qué tipo de entrenador quieres?",
  str_homestory_chat_16225006 = "Alguien cuyo manejo de la espada esté al mismo nivel que el mío. ¿Hay alguien así en Cloud Gardens en este momento?",
  str_homestory_chat_16225007 = "Si",
  str_homestory_chat_16225008 = "Debe haber muchos candidatos potenciales. Lumopolis e Illumina tienen bastantes...",
  str_homestory_chat_16225009 = "No",
  str_homestory_chat_16225010 = "¿También está bien el entrenamiento de batalla? No hay necesidad de que apuntes tan alto.",
  str_homestory_chat_16225011 = "debería estar bien...",
  str_homestory_chat_16225012 = "Pero, ¿por qué de repente quisiste mejorar tu habilidad con la espada?",
  str_homestory_chat_16225013 = "Si solo se trata de un entrenamiento diario, puede hacerlo usted mismo y disfrutar de una vida más relajada en Cloud Gardens.",
  str_homestory_chat_16225014 = "Hace sentido...",
