  str_homestory_chat_22901001 = "¡Oye! Muy contento de verte.",
  str_homestory_chat_22901002 = "¿Alguna misión nueva para mí?",
  str_homestory_chat_22901003 = "Realmente no...",
  str_homestory_chat_22901004 = "Multa. Puedo descansar un poco.",
