  str_homestory_chat_26704007 = "Pero, ¿y si el mago ya lo resolvió con la persona?",
  str_homestory_chat_26704008 = "Ya veo, es cuestión de perspectiva.",
  str_homestory_chat_26705001 = "¿Cuál es tu bebida favorita?",
  str_homestory_chat_26705002 = "Café solo, sin azúcar y sin leche.",
  str_homestory_chat_26705003 = "Pero es amargo.",
  str_homestory_chat_26705004 = "La dulzura viene después de la amargura.",
  str_homestory_chat_26705005 = "Y no me hace subir de peso.",
  str_homestory_chat_26705006 = "¿Asi que es por eso?",
  str_homestory_chat_26705007 = "Como mago, debo mantenerme ágil en todo momento.",
  str_homestory_chat_26899999 = "¿Como va tu dia?",
  str_homestory_chat_26801001 = "¿Qué estás haciendo?",
  str_homestory_chat_26801002 = "¡Estoy afinando mi pistola de agua y preparándome para refrescar a todos!",
  str_homestory_chat_26801003 = "¿Cómo?",
  str_homestory_chat_26801004 = "¡Quizás crear una llovizna! También puedo regar las plantas de esa manera.",
  str_homestory_chat_26801005 = "Regar las plantas está bien, pero si se trata de lluvia, necesitaremos paraguas, y eso es un fastidio.",
  str_homestory_chat_26802001 = "¿Quieres nadar?",
  str_homestory_chat_26802002 = "Sí, hay un río cerca, ¿verdad?",
  str_homestory_chat_26802003 = "Las aguas no parecen turbulentas y la profundidad parece perfecta.",
  str_homestory_chat_26802004 = "Te gusta mucho nadar, ¿no?",
  str_homestory_chat_26802005 = "Porque crecí en... no, EN el mar.",
  str_homestory_chat_26802006 = "El océano es mi familia.",
  str_homestory_chat_26802007 = "Pero el agua del río es fresca, ¿puedes nadar en ella?",
  str_homestory_chat_26802008 = "¡No soy un pez!",
  str_homestory_chat_26802009 = "Correcto. Lo lamento.",
  str_homestory_chat_26802010 = "De todos modos, vamos a nadar cuando tengamos la oportunidad.",
  str_homestory_chat_26803001 = "¿Qué estás haciendo?",
  str_homestory_chat_26803002 = "Estoy tratando de practicar mi vista y agilidad.",
  str_homestory_chat_26803003 = "¿Por qué?",
  str_homestory_chat_26803004 = "Es muy difícil pescar en el río.",
  str_homestory_chat_26803005 = "Son rápidos, y no sé qué hay debajo del agua. Pero también...",
  str_homestory_chat_26803006 = "Los peces no están exactamente donde están cuando se ven desde arriba.",
  str_homestory_chat_26803007 = "Correcto, algo sobre la refracción.",
  str_homestory_chat_26803008 = "Espera, ¿no creciste en el mar? Debes ser un veterano cuando se trata de pescar.",
  str_homestory_chat_26803009 = "Sí, pero solía sumergirme en el océano para hacer eso, así que no hay refracción.",
  str_homestory_chat_26803010 = "Y están en escuelas grandes, por lo que fueron fáciles de atrapar.",
  str_homestory_chat_26803011 = "Ya veo. Supongo que tendrás que practicar.",
  str_homestory_chat_26804001 = "¿Quieres verme?",
  str_homestory_chat_26804002 = "Así es. ¿Puedes por favor encontrarme un poco de madera?",
  str_homestory_chat_26804003 = "¡¿Qué hiciste?!",
  str_homestory_chat_26804004 = "Quiero construir una flota en el agua.",
  str_homestory_chat_26804005 = "¿Una flota? ¿Dónde?",
  str_homestory_chat_26804006 = "¡En el río! Para proteger los Jardines de las Nubes.",
  str_homestory_chat_26804007 = "La flota llenará el río, porque no es muy ancho.",
  str_homestory_chat_26804008 = "Tal vez una pequeña... o una micro flota.",
  str_homestory_chat_26804009 = "Construye algunos botes pequeños para patrullar...",
  str_homestory_chat_26804010 = "¿Quién los pilotará?",
  str_homestory_chat_26804011 = "¡Buena pregunta! Chubbs?",
  str_homestory_chat_26804012 = "Son cortos, por lo que las cabañas pueden ser más pequeñas.",
  str_homestory_chat_26804013 = "¿Qué pasa si se topan con enemigos?",
  str_homestory_chat_26804014 = "Ese es otro buen problema. ¿Honda? ¿Piedras?",
  str_homestory_chat_26804015 = "Esperemos que nunca llegue a eso.",
  str_homestory_chat_27099999 = "¿Cómo has estado últimamente, PlayerName?",
  str_homestory_chat_27001001 = "Nada mal. ¿Tú?",
  str_homestory_chat_27001002 = "Algo decepcionado, para ser honesto.",
  str_homestory_chat_27001003 = "¿Decepcionado?",
  str_homestory_chat_27001004 = "¡Sobre todo porque no llovió lo suficiente! ¡Y solo lloviznó!",
  str_homestory_chat_27001005 = "Te gusta ver la lluvia, ya veo...",
  str_homestory_chat_27021001 = "¿Escuché que me has estado buscando?",
  str_homestory_chat_27021002 = "Así es. Quiero construir un enorme parque infantil.",
  str_homestory_chat_27021003 = "Con toboganes, carruseles, balancines y otros para que los niños jueguen todo el día.",
  str_homestory_chat_27021004 = "¿Por qué la idea repentina?",
  str_homestory_chat_27021005 = "Porque no es solo para niños, a muchos adultos también les gusta.",
  str_homestory_chat_27021006 = "Especialmente algunos de tus amigos que son jóvenes de corazón.",
  str_homestory_chat_27021007 = "La forma en que lo dices tiene sentido... Déjame pensarlo.",
  str_homestory_chat_27022001 = "¿Qué te gustaría saber?",
  str_homestory_chat_27022002 = "¿Hay algún herrero familiarizado con las armas por aquí?",
  str_homestory_chat_27022003 = "Nop.",
  str_homestory_chat_27022004 = "Sí.",
  str_homestory_chat_27022005 = "Pero tengo que buscar uno.",
  str_homestory_chat_27022006 = "¿Tu arma está rota?",
  str_homestory_chat_27022007 = "Necesita recalibrar. Al igual que las personas, las armas a veces se \"enferman\".",
  str_homestory_chat_27022008 = "Aquí es cuando se necesita un herrero. Son médicos de las armas.",
  str_homestory_chat_27022009 = "¿Por qué no echas un vistazo a Umbraton?",
  str_homestory_chat_27022010 = "Está demasiado lejos y sería bueno que Cloud Gardens tuviera un armero residente.",
  str_homestory_chat_27022011 = "Estoy seguro de que muchos de tus amigos también necesitarían uno. Entonces, ¿qué tal contratar a un herrero?",
  str_homestory_chat_27022012 = "Te puedo recomendar uno, que no es nada caro.",
  str_homestory_chat_27022013 = "¿A qué te refieres ahora...?",
  str_homestory_chat_27023001 = "¿Qué estás mirando?",
  str_homestory_chat_27023002 = "Todo es genial en Cloud Gardens, excepto que es un poco remoto.",
  str_homestory_chat_27023003 = "Eso hace que sea difícil mantenerse al día con las tendencias en Umbraton.",
  str_homestory_chat_27023004 = "¿Has estado en Umbraton últimamente? ¿Alguna novedad en las tiendas de moda?",
  str_homestory_chat_27023005 = "Seguro.",
  str_homestory_chat_27023006 = "¿Qué nuevo estilo tienen ahora? ¿Qué es tendencia?",
  str_homestory_chat_27023007 = "Uh, no le presté atención a eso...",
  str_homestory_chat_27023008 = "Nop.",
  str_homestory_chat_27023009 = "Argh, sabía que no podía contar contigo.",
  str_homestory_chat_27023010 = "Deberías ganar más dinero y decirle a Chubbs que abra una tienda de moda aquí.",
  str_homestory_chat_27023011 = "O al menos dejar que los mensajeros entreguen algunas revistas de moda...",
  str_homestory_chat_27024001 = "¿Qué estás haciendo?",
  str_homestory_chat_27024002 = "No es una cosa. Hacía mucho tiempo que no me sentía tan relajado.",
  str_homestory_chat_27024003 = "Este es de hecho un lugar pacífico, y eso puede ser aterrador.",
  str_homestory_chat_27024004 = "¿Porqué crees?",
  str_homestory_chat_27024005 = "La paz te haría complaciente. Necesitas estar alerta de vez en cuando.",
  str_homestory_chat_27024006 = "Es muy seguro aquí. Tampoco es bueno estar tenso todo el tiempo.",
  str_homestory_chat_27024007 = "Vale... ya veo.",
  str_homestory_chat_27024008 = "No.",
  str_homestory_chat_27024009 = "La paz es agradable. No puedes estar peleando y matando día tras día.",
  str_homestory_chat_27024010 = "Pero tienes que estar preparado para el peligro...",
  str_homestory_chat_27199999 = "¿Qué tal?",
  str_homestory_chat_27101001 = "Nada.",
  str_homestory_chat_27101002 = "Esta bien, nos vemos.",
  str_homestory_chat_27101003 = "Eh, Casta...",
  str_homestory_chat_27101004 = "¿Sí?",
  str_homestory_chat_27101005 = "Bueno, no me sienta bien seguir terminando nuestras conversaciones así.",
  str_homestory_chat_27101006 = "¿Estábamos conversando?",
  str_homestory_chat_27101007 = "Tengo un punto allí. Bueno, te hablo después.",
  str_homestory_chat_27121001 = "¿Algún plan últimamente?",
  str_homestory_chat_27121002 = "Estoy buscando un punto de vista elevado, como un árbol alto o un edificio. ¿Tienes algo de eso por aquí?",
  str_homestory_chat_27121003 = "Sí.",
  str_homestory_chat_27121004 = "¿Qué tal el dormitorio Gardens?",
  str_homestory_chat_27121005 = "No, eso es demasiado bajo... Pero la Torre Jacinto funcionará bien.",
  str_homestory_chat_27121006 = "No lo creas.",
  str_homestory_chat_27121007 = "¿En serio? Pero creo que la Torre Jacinto funcionará bien.",
  str_homestory_chat_27121008 = "Sin embargo, es posible que los Chubbs no me den acceso.",
  str_homestory_chat_27121009 = "¿Por qué quieres hacer eso?",
  str_homestory_chat_27121010 = "Convierte el terreno elevado en una torre de vigilancia que se dobla como un nido de francotiradores.",
  str_homestory_chat_27121011 = "Esa es la posición defensiva más básica.",
  str_homestory_chat_27121012 = "Uh, no creo que eso sea necesario aquí...",
  str_homestory_chat_27122001 = "Escuché que te gusta el café.",
  str_homestory_chat_27122002 = "Sí, especialmente negro puro, sin azúcar ni crema. ¿Tú?",
  str_homestory_chat_27122003 = "A mí también me gusta.",
  str_homestory_chat_27122004 = "También eres adicto al sabor, ya veo.",
  str_homestory_chat_27122005 = "Especialmente cuando te pone a pensar en muchas otras cosas...",
  str_homestory_chat_27122006 = "Uh... Es uno de mis gustos, eso es todo.",
  str_homestory_chat_27122007 = "Eso es muy malo. Espero que puedas expandir tus horizontes pronto.",
  str_homestory_chat_27122008 = "no me gusta",
  str_homestory_chat_27122009 = "Es demasiado amargo si no le agregas nada.",
  str_homestory_chat_27122010 = "Esa es la opinión popular, así que supongo que estoy en minoría.",
  str_homestory_chat_27122011 = "No pasa nada, solo opiniones.",
  str_homestory_chat_27123001 = "Pareces distraído.",
  str_homestory_chat_27123002 = "Me han dicho que soy franco y eso hace que la gente se sienta incómoda. ¿Es eso cierto?",
  str_homestory_chat_27123003 = "No.",
  str_homestory_chat_27123004 = "Está bien, me siento mejor ahora.",
  str_homestory_chat_27123005 = "Sí, un poco.",
  str_homestory_chat_27123006 = "Pero creo que eso es genial.",
  str_homestory_chat_27123007 = "Así es como eres, y una gran parte de lo que eres en este momento.",
  str_homestory_chat_27123008 = "Así que sigue siendo tú.",
  str_homestory_chat_23099999 = "¿Algún caso hoy?",
  str_homestory_chat_23001001 = "Oh...",
  str_homestory_chat_23001002 = "Lo tomo como un \"sí\". Comenzaré los trámites entonces.",
  str_homestory_chat_23001003 = "Primero, tenemos al juez, soy yo, por supuesto, luego necesitamos alguaciles para proteger la corte...",
  str_homestory_chat_23001004 = "Espera, nunca dije que tuviéramos un caso. Solo estaba reflexionando sobre mi respuesta.",
  str_homestory_chat_23001005 = "Argh, qué aburrido.",
  str_homestory_chat_23021001 = "¿Qué estás haciendo últimamente?",
  str_homestory_chat_23021002 = "Necesito que me hagas un favor. ¿Me prestas unos Chubbs?",
  str_homestory_chat_23021003 = "¿Para qué los necesitas?",
  str_homestory_chat_23021004 = "Son la forma perfecta para los componentes.",
  str_homestory_chat_23021005 = "Parece que quieres hacerles algo... Por favor, no les hagas daño.",
  str_homestory_chat_23021006 = "¿No puedo? Pero quiero hacer estatuas con ellos...",
  str_homestory_chat_23021007 = "Entonces todos podremos apreciarlos como estatuas ambulantes.",
  str_homestory_chat_23021008 = "Permítanme reiterar, ¡por favor no los lastimen!",
  str_homestory_chat_23021009 = "¿Estás molesto? Bien bien.",
  str_homestory_chat_23022001 = "¿Necesita mi ayuda?",
  str_homestory_chat_23022002 = "Sí. ¿Puedes ir a Umbraton y comprarme revistas?",
  str_homestory_chat_23022003 = "Nop.",
  str_homestory_chat_23022004 = "¿Estás seguro? No pareces ocupado en absoluto y pasas el rato todo el día todos los días...",
  str_homestory_chat_23022005 = "Sólo hazme el favor y trátalo como una excursión.",
  str_homestory_chat_23022006 = "Tengo mucho que hacer aquí, sin mencionar que Umbraton está bastante lejos.",
  str_homestory_chat_23022007 = "Bien, cerdo perezoso...",
  str_homestory_chat_23022008 = "¿Qué tipo de revistas?",
  str_homestory_chat_23022009 = "Del tipo con portadas, contenido y calidad de impresión premium...",
  str_homestory_chat_23022010 = "Eso suena interesante.",
  str_homestory_chat_23022011 = "Sí, puedes imaginar eso, ¿no?",
  str_homestory_chat_23022012 = "¿Te refieres al arte escultórico? Recuerdo haberlo visto.",
  str_homestory_chat_23022013 = "¿Eh? que... ah...",
  str_homestory_chat_23023001 = "¿Estás buscando algo?",
  str_homestory_chat_23023002 = "Quiero comprar una gran cantidad de papel y tinta...",
  str_homestory_chat_23023003 = "¿Para qué? ¿Escribir libros?",
  str_homestory_chat_23023004 = "Sí. Como juez, me duele ver que aquí no hay leyes escritas.",
  str_homestory_chat_23023005 = "No creo que necesitemos leyes escritas reales...",
  str_homestory_chat_23023006 = "¡Los acuerdos verbales son inferiores a los contratos escritos!",
  str_homestory_chat_23023007 = "Estoy seguro de que solo quieres hacer algunas reglas, especialmente las que te benefician.",
  str_homestory_chat_23023008 = "¡De ninguna manera, todas las reglas que haga serán justas!",
  str_homestory_chat_23023009 = "Por ejemplo, uno siempre debe seguir las órdenes de un juez de Lumopolis...",
  str_homestory_chat_23023010 = "Yo descanso mi caso.",
  str_homestory_chat_27299999 = "¿Hay algo que pueda filmar, PlayerName?",
  str_homestory_chat_27221001 = "No.",
  str_homestory_chat_27221002 = "¿Alguna vez dejas de pensar en filmar...?",
  str_homestory_chat_27221003 = "¡Oye, no es mi culpa que el paisaje por aquí sea tan increíble! Ahora, si pudiera contarles una historia...",
  str_homestory_chat_27221004 = "¡Argh, qué dolor! ¿Por qué tengo que ser guionista también?",
  str_homestory_chat_27221005 = "¿Estás seguro de que no pasa nada interesante aquí? ¿Quizás algo como \"Las Nueve Leyendas Increíbles de los Jardines de las Nubes\"?",
  str_homestory_chat_27221006 = "N-Nada de eso, no...",
  str_homestory_chat_27222001 = "¿Qué quieres comprar?",
  str_homestory_chat_27222002 = "¿Tienes un puesto por ahí? Preferiblemente uno con ruedas, así puedo moverlo.",
  str_homestory_chat_27222003 = "¿Para qué necesitas uno?",
  str_homestory_chat_27222004 = "¡Para filmar, por supuesto! Los brazos de Cellulo se cansan de sostener la cámara todo el tiempo, ¿sabes?",
  str_homestory_chat_27222005 = "Nuestro presupuesto también es bastante ajustado. De lo contrario, contrataría a un profesional para hacerlo.",
  str_homestory_chat_27222006 = "Ya veo... ¿No sería mejor buscar ese tipo de cosas en Umbraton?",
  str_homestory_chat_27222007 = "¡Sí, pero Umbraton es caro!",
  str_homestory_chat_27223001 = "¿No pareces demasiado ocupado hoy?",
  str_homestory_chat_27223002 = "Eso es porque no tengo buenas historias para leer. De todos modos, ¿tienes cosas que te gusta leer?",
  str_homestory_chat_27223003 = "Para nada.",
  str_homestory_chat_27223004 = "Supongo...?",
  str_homestory_chat_27223005 = "A veces leo los libros Vice y los demás me regalan.",
  str_homestory_chat_27223006 = "Suspiro. De alguna manera, siento que estoy hablando con la persona equivocada aquí.",
  str_homestory_chat_27223007 = "¡Estoy buscando recomendaciones de cuentos cortos! Especialmente buenos thrillers, si conoces alguno...",
  str_homestory_chat_27223008 = "Parece que te gusta mucho el terror. ¿No te asustas?",
  str_homestory_chat_27223009 = "¡Ja! ¿Qué es más aterrador que estar arruinado?",
  str_homestory_chat_27223010 = "Además, ¿y si algún día hacen adaptaciones cinematográficas de algunas de estas historias? ¡Podrían elegirme como la protagonista femenina si conozco el material por dentro y por fuera!",
  str_homestory_chat_27223011 = "Entonces, finalmente puedo ser la estrella que estoy destinada a ser... Jejejeje...",
  str_homestory_chat_27223012 = "Derecha. Me voy a despedir ahora.",
  str_homestory_chat_27224001 = "¿Aficionados?",
  str_homestory_chat_27224002 = "Tú también eres un poco famoso. Tienes fans, ¿verdad?",
  str_homestory_chat_27224003 = "¿Creo que sí?",
  str_homestory_chat_27224004 = "¡Oh! ¿Como quién?",
  str_homestory_chat_27224005 = "Yo... realmente no sé...",
  str_homestory_chat_27224006 = "Para nada.",
  str_homestory_chat_27224007 = "Que desafortunado.",
  str_homestory_chat_27224008 = "Bueno, tengas o no fans, ¡siempre debes trabajar duro por tu propio bien, no por el de ellos!",
  str_homestory_chat_27224009 = "¡Claro!",
  str_homestory_chat_27224010 = "Es por eso que tienes que animarte a ti mismo de vez en cuando, ¿verdad?",
  str_homestory_chat_27224011 = "Claro, pero... ¿Por qué me dices esto? ¿Paso algo?",
  str_homestory_chat_27224012 = "Yo sólo... a veces me canso, eso es todo.",
  str_homestory_chat_27225001 = "¿Qué quieres comprar?",
  str_homestory_chat_27225002 = "tengo antojo de pescado...",
  str_homestory_chat_27225003 = "¿No hay muchos peces en el río? ¿Cellulo no puede atrapar algo para ti?",
  str_homestory_chat_27225004 = "Pero no quiero comer pescado de agua dulce... ¡Quiero algo del mar!",
  str_homestory_chat_27225005 = "Como sopa de almejas... ¡O tal vez un plato de estofado de mariscos sobre arroz!",
  str_homestory_chat_27225006 = "Podrías hacer esas cosas con pescado de agua dulce.",
  str_homestory_chat_27225007 = "¡Absolutamente no! ¡¿Estás bromeando?!",
  str_homestory_chat_27225008 = "¡Los mariscos son totalmente diferentes! ¡Solo un bocado y prácticamente puedes saborear el océano!",
  str_homestory_chat_27225009 = "¡Ese sabor solo es suficiente para hacerte sentir invencible! ¡Como si pudieras lograr incluso tus sueños más salvajes!",
  str_homestory_chat_27225010 = "¿Estamos... todavía hablando de comida?",
  str_homestory_chat_27399999 = "Buenos días, PlayerName. Estoy a su servicio, si necesita cualquier cosa.",
  str_homestory_chat_27301001 = "Hola Minos.",
  str_homestory_chat_27301002 = "No tienes que ser tan cortés aquí en Cloud Gardens todo el tiempo. Solo tómatelo con calma, ¿de acuerdo?",
  str_homestory_chat_27301003 = "Imposible. Como mayordomo orgulloso, debo estar preparado para servir a mi amo en cualquier momento.",
  str_homestory_chat_27301004 = "Pero tu maestro no está aquí ahora... ¿o sí?",
  str_homestory_chat_27301005 = "No, pero también debo estar preparado en caso de que decida venir aquí.",
  str_homestory_chat_27321001 = "tu arma...",
  str_homestory_chat_27321002 = "Ah, te he estado buscando, mi amigo. Dime, ¿hay algún maestro artesano aquí en Cloud Gardens que pueda reparar armas?",
  str_homestory_chat_27321003 = "Sí.",
  str_homestory_chat_27321004 = "¿Con qué Chubb debo hablar?",
  str_homestory_chat_27321005 = "Er... No creo que ninguno de ellos pueda ayudarte, ¿pero tal vez uno de mis amigos pueda intentarlo?",
  str_homestory_chat_27321006 = "Nop.",
  str_homestory_chat_27321007 = "Suspiro... Qué lástima.",
  str_homestory_chat_27321008 = "¿Tu arma está rota?",
  str_homestory_chat_27321009 = "Por supuesto que no. Como mayordomo orgulloso, es mi deber asegurarme de que todo mi equipo funcione correctamente, y las armas no son una excepción.",
  str_homestory_chat_27321010 = "No se sabe cuándo mi maestro podría encontrarse en una situación peligrosa.",
  str_homestory_chat_27321011 = "Eso es muy profesional de tu parte...",
  str_homestory_chat_27322001 = "¿Cómo puedo ayudar?",
  str_homestory_chat_27322002 = "Buenos días, PlayerName. ¿Podría por favor proporcionarme la hora exacta en este momento?",
  str_homestory_chat_27322003 = "Por supuesto...? ¿Le pasa algo a tu reloj?",
  str_homestory_chat_27322004 = "Incluso el instrumento más preciso puede fallar a veces. De hecho, justo esta mañana...",
  str_homestory_chat_27322005 = "Me di cuenta de que mi reloj parecía ir una fracción de segundo más lento que ayer.",
  str_homestory_chat_27322006 = "¿Notas cosas así?",
  str_homestory_chat_27322007 = "Como mayordomo orgulloso, es mi deber llevar la cuenta del tiempo en todo momento.",
  str_homestory_chat_27322008 = "Después de todo, incluso la más pequeña desviación de la hora exacta de mi parte podría arruinar todo el horario de mi maestro para el día.",
  str_homestory_chat_27322009 = "No puedo evitar sentir celos de tu amo...",
  str_homestory_chat_27322010 = "Si tan solo tuviera a alguien como tú que me ayudara a mantenerme a tiempo...",
  str_homestory_chat_27323001 = "¿Tienes algo en mente, Minos?",
  str_homestory_chat_27323002 = "La hay, de hecho. Dime, ¿cómo crees que un mayordomo sirve mejor a su amo?",
  str_homestory_chat_27323003 = "¿Siguiendo órdenes?",
  str_homestory_chat_27323004 = "Obediencia absoluta...",
  str_homestory_chat_27323005 = "Si puedo hablar con franqueza... Estoy completamente en desacuerdo.",
  str_homestory_chat_27323006 = "¿Apoyándolos?",
  str_homestory_chat_27323007 = "¡Estás en lo correcto!",
  str_homestory_chat_27323008 = "El deber de un mayordomo no es simplemente obedecer las órdenes de su amo. La mayoría de las veces, debe ayudar a su maestro a darse cuenta de sus propios errores.",
  str_homestory_chat_27323009 = "En este sentido, un mayordomo y su amo pueden verse como iguales.",
  str_homestory_chat_27323010 = "Eso es cierto, sí.",
  str_homestory_chat_27324001 = "¿Cómo te sientes acerca de este lugar?",
  str_homestory_chat_27324002 = "Es un lugar encantador. Amplio, pero increíblemente limpio.",
  str_homestory_chat_27324003 = "Los Chubbs parecen mantener bastante bien el área.",
  str_homestory_chat_27324004 = "No son solo ellos, ¿sabes? Todos hacen su parte para cuidar de Cloud Gardens también.",
  str_homestory_chat_27324005 = "Mi querido PlayerName, Estás absolutamente en lo correcto.",
  str_homestory_chat_27324006 = "A decir verdad, tengo bastante envidia de lo habitable que es este lugar.",
  str_homestory_chat_27324007 = "El ambiente limpio, el aire fresco e incluso la cantidad de sol que recibe este lugar... Todo es simplemente excepcional.",
  str_homestory_chat_27324008 = "Pero lo más importante, está casi completamente libre de insectos dañinos y otros roedores molestos. Como resultado, mi trabajo aquí es mucho menos oneroso.",
  str_homestory_chat_27324009 = "¡Me alegro de que te guste aquí, Minos!",
  str_homestory_chat_26999999 = "Yo, yo, yo, te veo vagando, hermano.",
  str_homestory_chat_26901001 = "Hola Sadie.",
  str_homestory_chat_26901002 = "¡Yo yo yo! Solo estoy pasando el rato, ¿sabes?",
  str_homestory_chat_26901003 = "¿Por qué estás copiando mi forma de hablar?",
  str_homestory_chat_26901004 = "Lo siento, se me escapó...",
  str_homestory_chat_26901005 = "Yo, yo, yo, parece que te has dado cuenta de mi flujo.",
  str_homestory_chat_26921001 = "¿Qué estás leyendo?",
  str_homestory_chat_26921002 = "El ómnibus cómico anual de Swashbuckler. ¡Acaba de salir en Umbraton!",
  str_homestory_chat_26921003 = "Vine a Cloud Gardens solo para poder leerlo tres veces más.",
  str_homestory_chat_26921004 = "¿Tres veces más?",
  str_homestory_chat_26921005 = "¡Sí! ¡Podría leerlo cien veces y aún así no me cansaría!",
  str_homestory_chat_26921006 = "A juzgar por lo emocionado que estás, diría que ya lo has leído trescientas veces, ¿no es así?",
  str_homestory_chat_26921007 = "¡Nah, más como 666 veces!",
  str_homestory_chat_26921008 = "¡¿Eh?!",
  str_homestory_chat_26922001 = "¿Estás sonriendo?",
  str_homestory_chat_26922002 = "Acabo de pensar en algo que me hizo muy feliz, ¡como cuando piensas en Cloud Gardens!",
  str_homestory_chat_26922003 = "¿Algo feliz?",
  str_homestory_chat_26922004 = "Cada vez que pienso en bravucones, ¡no puedo evitar sonreír!",
  str_homestory_chat_26922005 = "¡Especialmente cuando pienso en cómo puedo frustrar los planes de los malos cada vez!",
  str_homestory_chat_26922006 = "¿Jardines de nubes?",
  str_homestory_chat_26922007 = "¡Así es! Te he estado observando durante un tiempo y me he dado cuenta de que cada vez que estás en Cloud Gardens, siempre tienes una sonrisa en la cara.",
  str_homestory_chat_26922008 = "Inconsciente e involuntariamente.",
  str_homestory_chat_26922009 = "Entonces... ¿Por qué estás sonriendo?",
  str_homestory_chat_26922010 = "¡Un espadachín sonríe cuando los malos lloran!",
  str_homestory_chat_26922011 = "¡Cada vez que pienso en esto, no puedo evitar soltar algunos versos de estilo libre!",
  str_homestory_chat_26922012 = "¡El espadachín, el villano ve! ¡Un puño sale volando y el villano empieza a llorar!",
  str_homestory_chat_26922013 = "¡Sí! ¡Ajá, ajá!",
  str_homestory_chat_26923001 = "Te gusta mucho el béisbol, ¿eh?",
  str_homestory_chat_26923002 = "No especialmente. ¿Por qué lo preguntas?",
  str_homestory_chat_26923003 = "Bueno, nunca te veo sin tu gorra de béisbol o tu bate...",
  str_homestory_chat_26923004 = "Me gusta ¿No te parece genial?",
  str_homestory_chat_26923005 = "¿Enfriar?",
  str_homestory_chat_26923006 = "Ya sabes, como si estuviera a punto de hacer algo extremadamente impresionante...?",
  str_homestory_chat_26923007 = "El béisbol nunca fue mi estilo, ¿sabes? Pero cuando se trata de rap, ¡tengo el flujo más genial!",
  str_homestory_chat_26923008 = "Super Sadie 666, lleva un bate, Super Sadie 666, balancea un bate.",
  str_homestory_chat_26923009 = "Así que básicamente lo usas como un arma.",
  str_homestory_chat_26923010 = "Súper Sadie 666, lleva gorra, Súper Sadie 666, ¡realmente abofetea!",
  str_homestory_chat_26923011 = "Bien, lo entiendo. Ya puedes dejar de hacer eso...",
  str_homestory_chat_27599999 = "*Bostezo* Hoy vuelves a dar un paseo tranquilo.",
  str_homestory_chat_27521001 = "Eres tú otra vez.",
  str_homestory_chat_27521002 = "¿Estabas bostezando hace un momento? ¿Estás cansado?",
  str_homestory_chat_27521003 = "No, siempre soy así.",
  str_homestory_chat_27521004 = "Verdadero. No hay ningún signo de fatiga en tu cara...",
  str_homestory_chat_27521005 = "Todo el mundo me dice eso.",
  str_homestory_chat_27521006 = "Supongo que este es uno de tus rasgos especiales.",
  str_homestory_chat_27522001 = "¿Siempre usas ese atuendo?",
  str_homestory_chat_27522002 = "De hecho lo hago. ¿Hay algo malo con eso?",
  str_homestory_chat_27522003 = "No te queda muy bien.",
  str_homestory_chat_27522004 = "Eso es porque la ropa ajustada me hace sentir incómodo. A veces incluso tengo dificultad para respirar.",
  str_homestory_chat_27522005 = "He intentado usarlos antes, pero no podía soportarlo.",
  str_homestory_chat_27522006 = "Un día, mi padre me dijo que podía usar ropa de una talla más.",
  str_homestory_chat_27522007 = "Después de eso, mi ropa ya no me dio problemas.",
  str_homestory_chat_27522008 = "Comprendo.",
  str_homestory_chat_27522009 = "Siempre llevas eso...",
  str_homestory_chat_27522010 = "Es porque tengo muchos conjuntos del mismo conjunto.",
  str_homestory_chat_27522011 = "Sin embargo, ese no es realmente mi punto. ¿No has probado a llevar otra ropa?",
  str_homestory_chat_27522012 = "No, me gusta la ropa como esta. Son muy cómodos.",
  str_homestory_chat_27522013 = "Supongo que sí...",
  str_homestory_chat_27523001 = "¿Las lámparas?",
  str_homestory_chat_27523002 = "Sí, quiero cambiar las farolas de aquí.",
  str_homestory_chat_27523003 = "¿Cambiarlos de qué manera?",
  str_homestory_chat_27523004 = "Quiero reemplazarlos con luces de neón de colores. Apuesto a que se vería bien.",
  str_homestory_chat_27523005 = "A los Chubbs sin duda les gustaría.",
  str_homestory_chat_27523006 = "Eso se siente como una gran empresa.",
  str_homestory_chat_27523007 = "¿Significa esto que estás de acuerdo con eso?",
  str_homestory_chat_27523008 = "¿Quieres que averigüe cuánto trabajo implicaría?",
  str_homestory_chat_27523009 = "Um, eso no será necesario...",
  str_homestory_chat_27524001 = "¿Puedes hablar un poco más alto?",
  str_homestory_chat_27524002 = "¿Estoy hablando demasiado bajo? ¿No puedes comunicarte conmigo?",
  str_homestory_chat_27524003 = "A veces no puedo oírte bien.",
  str_homestory_chat_27524004 = "Entonces deberíamos pararnos un poco más cerca cuando hablamos.",
  str_homestory_chat_27524005 = "Esto es tan fuerte como suena mi voz.",
  str_homestory_chat_27524006 = "Pero a veces no es tan conveniente estar demasiado cerca el uno del otro.",
  str_homestory_chat_27524007 = "¿Porqué crees?",
  str_homestory_chat_27524008 = "¿No es una distancia más corta entre nosotros mejor para la comunicación?",
  str_homestory_chat_27524009 = "Er... Dejemos este tema en suspenso por el momento.",
  str_homestory_chat_27525001 = "¿Dulce?",
  str_homestory_chat_27525002 = "Sí, PlayerName, ¿Te gusta el caramelo?",
  str_homestory_chat_27525003 = "Sí.",
  str_homestory_chat_27525004 = "Una vez comí estas gomitas en Umbraton que no eran demasiado dulces y no se me pegaban a los dientes...",
  str_homestory_chat_27525005 = "Tienes que llevarme allí para probarlos algún día. Estaria agradecido.",
  str_homestory_chat_27525006 = "Claro, pero no me pareces tan emocionado.",
  str_homestory_chat_27525007 = "No, estoy deseando que llegue.",
  str_homestory_chat_27525008 = "No.",
  str_homestory_chat_27525009 = "Qué vergüenza. Quería recomendarte todo tipo de dulces.",
  str_homestory_chat_27525010 = "Sobre todo el pop-rock...",
  str_homestory_chat_27699999 = "¡Hola! Estoy de buen humor hoy!",
  str_homestory_chat_27601001 = "¡Hola!",
  str_homestory_chat_27601002 = "Escuché que estabas buscando algo que hacer.",
  str_homestory_chat_27601003 = "Así es. Aunque esto no es Lumopolis, después de que vine aquí...",
  str_homestory_chat_27601004 = "No he podido deshacerme de la sensación de que tengo la obligación de contribuir a este lugar. Así que solo quiero hacer algo.",
  str_homestory_chat_27601005 = "No hay prisa. Una ciudad no se puede construir en un día, después de todo.",
  str_homestory_chat_27601006 = "Eso es lo que dijo Lady Raphael también... Está bien entonces.",
  str_homestory_chat_27621001 = "¿Flores creciendo?",
  str_homestory_chat_27621002 = "Sí. ¡Hay un montón de flores interesantes aquí, especialmente las altas!",
  str_homestory_chat_27621003 = "Esos... son árboles únicos...",
  str_homestory_chat_27621004 = "¡Ay, qué asombroso! Algunas de ellas parecen flores, especialmente la del dosel. ¿Los cultivaste todos tú mismo?",
  str_homestory_chat_27621005 = "Sí.",
  str_homestory_chat_27621006 = "Los Chubbs hicieron la mayor parte del trabajo.",
  str_homestory_chat_27621007 = "¿Puedo cultivar un poco también? ¡Soy bueno cuidando las plantas!",
  str_homestory_chat_27621008 = "Hmm... Necesito pensarlo.",
  str_homestory_chat_27622001 = "Mencionaste pájaros...",
  str_homestory_chat_27622002 = "Cloud Gardens es tan grande. Apuesto a que muchos pájaros vienen aquí.",
  str_homestory_chat_27622003 = "Quiero construirles un nido para que tengan un lugar donde descansar cuando vengan.",
  str_homestory_chat_27622004 = "¡Qué buena idea! Eres muy observador y te encantan los pájaros.",
  str_homestory_chat_27622005 = "En realidad... esto fue idea de Lady Raphael.",
  str_homestory_chat_27622006 = "Dijo que esto me haría más paciente y menos imprudente.",
  str_homestory_chat_27622007 = "Después de venir aquí, no he tenido nada que hacer, y creo que me ha hecho volver mucho a mi antiguo yo.",
  str_homestory_chat_27622008 = "Por eso vine a preguntarte dónde puedo encontrar pájaros. ¡Iré a buscarlos!",
  str_homestory_chat_27622009 = "Ahí está esa impaciencia tuya otra vez...",
  str_homestory_chat_27622010 = "¿Qué dijiste? ¿Dónde están?",
  str_homestory_chat_27622011 = "Ah, lo que quiero decir es que no puedes ser impaciente. Necesitas buscarlos lentamente.",
  str_homestory_chat_27622012 = "Esto también te entrena para ser más paciente, ¿verdad?",
  str_homestory_chat_27622013 = "Hmm, tienes razón.",
  str_homestory_chat_27623001 = "¿Ejercicios médicos?",
  str_homestory_chat_27623002 = "Sí. Cloud Gardens es bastante pacífico, pero aún necesitamos hacer este tipo de ejercicios.",
  str_homestory_chat_27623003 = "Necesitamos estar preparados para los accidentes incluso si los enemigos no nos atacan.",
  str_homestory_chat_27623004 = "Por ejemplo, alguien podría ahogarse o caerse del techo.",
  str_homestory_chat_27623005 = "Supongo que tienes razón.",
  str_homestory_chat_27623006 = "¿Cómo deberíamos empezar? ¿Necesito encontrar algunos de los otros para coordinar con usted?",
  str_homestory_chat_27623007 = "¡Eso no será necesario! ¡Hay muchos Chubbs aquí!",
  str_homestory_chat_27623008 = "¡Esperar! ¿Pero no son aurorianos...?",
  str_homestory_chat_27623009 = "¿Serán realmente efectivos los ejercicios médicos de esta manera?",
  str_homestory_chat_27623010 = "¡Está bien mientras mis habilidades no se oxiden!",
  str_homestory_chat_27623011 = "A-Bien, entonces.",
  str_homestory_chat_27799999 = "¡Hola! ¡Te ves muy bien hoy!",
  str_homestory_chat_27721001 = "Siempre estás tan alegre.",
  str_homestory_chat_27721002 = "¿Cómo lo haces? ¿Cuál es tu secreto?",
  str_homestory_chat_27721003 = "Es solo que los ídolos siempre son así, incluso si sus corazones están llenos de tristeza...",
  str_homestory_chat_27721004 = "¡Se mantienen positivos en todo momento y hacen su mejor acto para todos!",
  str_homestory_chat_27721005 = "Después de todo, ¿de qué otra manera podemos llenar todo el continente con el poder sanador del amor?",
  str_homestory_chat_27721006 = "Cuando lo pones así, eres realmente increíble...",
  str_homestory_chat_27722001 = "¿Me estabas buscando?",
  str_homestory_chat_27722002 = "PlayerName, necesito hacerte una pregunta muy seria, y debes responderla honestamente.",
  str_homestory_chat_27722003 = "¿P-Por qué? ¿Qué ocurre?",
  str_homestory_chat_27722004 = "¿Crees que recientemente... mi peso...",
  str_homestory_chat_27722005 = "(Parece preocupada por su peso. ¿Cómo debo responderle...?)",
  str_homestory_chat_27722006 = "Te ves más... redonda.",
  str_homestory_chat_27722007 = "¡Lo sabía! Apuesto a que es porque comí en exceso recientemente.",
  str_homestory_chat_27722008 = "Y la vida es demasiado relajada aquí... ¡No puedo seguir así!",
  str_homestory_chat_27722009 = "¡Parece que no voy a comer nada esta noche! ¡Y tendré que correr 50 vueltas!",
  str_homestory_chat_27722010 = "Te ves bien.",
  str_homestory_chat_27722011 = "¿En serio? ¡Dime la verdad, o nunca volveré a confiar en ti!",
  str_homestory_chat_27722012 = "Bueno... ¿Tal vez has ganado un poco de peso?",
  str_homestory_chat_27722013 = "¡Sabía que comía en exceso hace unos días! ¡Necesito empezar a ser más estricto conmigo mismo!",
  str_homestory_chat_27722014 = "Quiero decir, no hay necesidad de reaccionar exageradamente. Es solo un poco de peso extra...",
  str_homestory_chat_27722015 = "Incluso un poco es demasiado. Este es el precio de ser un ídolo.",
  str_homestory_chat_27722016 = "Eres tan estricto contigo mismo.",
  str_homestory_chat_27723001 = "¿Vas a hacer ejercicio?",
  str_homestory_chat_27723002 = "Actuación ensayando, en realidad! ¿Hay una sala de entrenamiento especial por aquí?",
  str_homestory_chat_27723003 = "Erm.",
  str_homestory_chat_27723004 = "Suspiro, este es realmente el lugar perfecto para unas vacaciones.",
  str_homestory_chat_27723005 = "Pero no puedo dejar de entrenar... Una ídolo siempre debe estar en su mejor momento.",
  str_homestory_chat_27723006 = "¿Tal vez podamos hacer algo de entrenamiento sin equipo profesional?",
  str_homestory_chat_27723007 = "¡Bien! Déjame ver lo que tenemos aquí...",
  str_homestory_chat_27723008 = "Carreras de fondo, natación, montañismo, baile... ¡Hay tantas cosas que hacer!",
  str_homestory_chat_27723009 = "Tienes esto.",
  str_homestory_chat_27724001 = "¿Un cuarto?",
  str_homestory_chat_27724002 = "Bien, quiero una habitación especial solo para Marshmallow.",
  str_homestory_chat_27724003 = "¿Te refieres a tu perro?",
  str_homestory_chat_27724004 = "Sí. Verás, nunca duerme bien afuera, ya veces aquí también llueve.",
  str_homestory_chat_27724005 = "Es verdad.",
  str_homestory_chat_27724006 = "¡Eso es todo! ¡Le haré una pequeña guarida debajo de mi cama! Solo necesito una manta.",
  str_homestory_chat_27724007 = "¡Buena idea!",
  str_homestory_chat_27724008 = "¡Le voy a pedir a los Chubbs que lo hagan!",
  str_homestory_chat_27724009 = "Parece que ya lo tienes todo planeado.",
  str_homestory_chat_27725001 = "Te ves muy bien, también.",
  str_homestory_chat_27725002 = "¡Por cierto! Y es principalmente porque aquí no hay melón amargo.",
  str_homestory_chat_27725003 = "¿Melón amargo? ¿No te gusta el melón amargo?",
  str_homestory_chat_27725004 = "¡¿Me estás diciendo que sí?!",
  str_homestory_chat_27725005 = "no me importa",
  str_homestory_chat_27725006 = "¡No te importa! ¡Increíble! Pero ese sabor amargo...",
  str_homestory_chat_27725007 = "¡Vaya! Ya veo... Estás tratando de perder peso, ¿verdad?",
  str_homestory_chat_27725008 = "Erm... N-No...",
  str_homestory_chat_27725009 = "Suspiro, pareces entender la importancia del control de peso también. Es difícil, ¿no?",
  str_homestory_chat_27725010 = "Honestamente, no soy...",
  str_homestory_chat_27725011 = "Es asqueroso.",
  str_homestory_chat_27725012 = "¡Derecha! Entonces, ¡no dejes que el melón amargo se acerque aquí! ¡No lo olvides!",
  str_homestory_chat_27725013 = "Sin problema.",
  str_homestory_chat_27899999 = "¿Mmm? ¿Que pasa?",
  str_homestory_chat_27821001 = "¿Qué estás haciendo?",
  str_homestory_chat_27821002 = "Me preguntaba si debería hacer una mecedora o una hamaca...",
  str_homestory_chat_27821003 = "¿Por qué razón?",
  str_homestory_chat_27821004 = "Para descansar, naturalmente. ¿Para qué más los usaría, hacer ejercicio?",
  str_homestory_chat_27821005 = "Imagínate tumbado al sol, la brisa haciéndote cosquillas en la mejilla... ¡Ah!",
  str_homestory_chat_27821006 = "Suena increíblemente relajado...",
  str_homestory_chat_27822001 = "Te ves muy relajado.",
  str_homestory_chat_27822002 = "Sí, este es un lugar raro donde uno puede venir a relajarse por completo.",
  str_homestory_chat_27822003 = "¿No te gusta este tipo de sentimiento también, PlayerName?",
  str_homestory_chat_27822004 = "Si.",
  str_homestory_chat_27822005 = "¡Así es! ¡Sabía que lo conseguirías!",
  str_homestory_chat_27822006 = "Sabía que también te gustaría la sensación de relajación sin preocupaciones.",
  str_homestory_chat_27822007 = "Especialmente me encanta no hacer nada, solo mirar hacia arriba y observar el viento empujando suavemente las nubes.",
  str_homestory_chat_27822008 = "O escuchando el sonido de las hojas y dejando mi mente completamente en blanco.",
  str_homestory_chat_27822009 = "Es genial para aliviar la fatiga mental.",
  str_homestory_chat_27822010 = "Está bien, lo intentaré algún día.",
  str_homestory_chat_27822011 = "No está mal, pero...",
  str_homestory_chat_27822012 = "No es bueno relajarse demasiado... Deberíamos dedicar nuestro tiempo a hacer cosas.",
  str_homestory_chat_27822013 = "¿Te gusta construir una nueva estructura? Pero podemos hacer que los Chubbs lo hagan.",
  str_homestory_chat_27822014 = "Puedes y debes pasar más tiempo relajándote.",
  str_homestory_chat_27822015 = "Eso... no es exactamente lo que quise decir.",
  str_homestory_chat_27823001 = "¿Qué quieres?",
  str_homestory_chat_27823002 = "Escuché que había algunos animales de aspecto extraño por estas partes.",
  str_homestory_chat_27823003 = "no he visto ninguno",
  str_homestory_chat_27823004 = "¡Qué vergüenza! Pensé que podría encontrar algo interesante aquí.",
  str_homestory_chat_27823005 = "Pero también puedo considerar esto como un año sabático.",
  str_homestory_chat_27823006 = "Ah... Sí, los hay.",
  str_homestory_chat_27823007 = "¡Tenía un buen presentimiento sobre este lugar! ¡Ahora puedo disfrutar de mis vacaciones y buscar bestias maravillosas al mismo tiempo!",
  str_homestory_chat_27823008 = "¡Dos pájaros de un tiro!",
  str_homestory_chat_27823009 = "Vagar parece haber sido tu objetivo principal...",
  str_homestory_chat_27824001 = "¿Pescar?",
  str_homestory_chat_27824002 = "Sí, hay muchos peces en el río cercano, mucha gente va a pescar allí.",
  str_homestory_chat_27824003 = "Así es.",
  str_homestory_chat_27824004 = "¿Te gusta pescar?",
  str_homestory_chat_27824005 = "Seguro.",
  str_homestory_chat_27824006 = "Está bien, supongo.",
  str_homestory_chat_27824007 = "Hmm... De todos modos, prefiero observar los peces en lugar de atraparlos yo mismo.",
  str_homestory_chat_27824008 = "Me siento tan relajado viéndolos caminar por el agua.",
  str_homestory_chat_27824009 = "Podrías ir a la Fuente de la Esperanza.",
  str_homestory_chat_27824010 = "Bueno, eso es diferente. Después de todo, estar atrapado en el abrazo de la Fuente de los Deseos te da una sensación completamente diferente.",
  str_homestory_chat_27824011 = "Hace sentido...",
  str_homestory_chat_27825001 = "¿Necesitas algo de beber?",
  str_homestory_chat_27825002 = "Derecha. Es genial aquí, pero le falta algo...",
  str_homestory_chat_27825003 = "¡Y ese algo es una botella de alcohol!",
  str_homestory_chat_27825004 = "Beber durante el día...",
  str_homestory_chat_27825005 = "Sólo un traguito y nada más. Con una brisa tan suave, si hubiera otra mecedora...",
  str_homestory_chat_27825006 = "¡Maravilloso!",
  str_homestory_chat_27825007 = "Entonces, ¿ya no vas a buscar bestias maravillosas?",
  str_homestory_chat_27825008 = "¡Vine aquí para relajarme! Pero si no hay alcohol...",
  str_homestory_chat_27825009 = "¿Tal vez el arroyo de allí tiene lo que estoy buscando? ¡Derecha!",
  str_homestory_chat_27825010 = "Bueno, es tu desición.",
  str_homestory_chat_28099999 = "¿De qué estás cotilleando estos días?",
  str_homestory_chat_28001001 = "¿Eh? no estoy chismeando de nada...",
  str_homestory_chat_28001002 = "¿Por qué te gustan tanto los chismes?",
  str_homestory_chat_28001003 = "¡Porque es tan intrigante!",
  str_homestory_chat_28001004 = "Por ejemplo, escuché que una persona importante en uno de los grandes gremios en realidad sueña con ser novelista, o algo así...",
  str_homestory_chat_28001005 = "¿No crees que eso es simplemente fascinante?",
  str_homestory_chat_28001006 = "Eso es... cada uno por su cuenta, supongo.",
  str_homestory_chat_28001007 = "¡Es por eso que tengo que recopilar mucha información para satisfacer las necesidades de diferentes lectores!",
  str_homestory_chat_28001008 = "Bueno, te deseo suerte.",
  str_homestory_chat_28021001 = "Ese dispositivo...",
  str_homestory_chat_28021002 = "Parece que lo llevas contigo a todas partes. ¿Realmente necesitas tomar fotos en cualquier momento y en cualquier lugar?",
  str_homestory_chat_28021003 = "¡Por supuesto! ¡Y eso es porque los chismes siempre se basan en la verdad!",
  str_homestory_chat_28021004 = "¿Eh? ¿Estás seguro de eso?",
  str_homestory_chat_28021005 = "¿Cuál es tu opinión sobre esto, entonces?",
  str_homestory_chat_28021006 = "Los rumores deben basarse en la verdad.",
  str_homestory_chat_28021007 = "¡Así es!",
  str_homestory_chat_28021008 = "Pero inventando cosas de vez en cuando...",
  str_homestory_chat_28021009 = "¿Supongo que realmente no importa? No sería un asunto de gran importancia de cualquier manera.",
  str_homestory_chat_28021010 = "¡No!",
  str_homestory_chat_28021011 = "¡No digas eso! Incluso los chismes deben ser ciertos, de lo contrario, los lectores perderán el interés tarde o temprano.",
  str_homestory_chat_28021012 = "¡El chisme debe tener un cierto grado de autenticidad para atraer lectores!",
  str_homestory_chat_28021013 = "Supongo que ni siquiera los chismes deberían escribirse cruelmente.",
  str_homestory_chat_28022001 = "Tu bolsa...",
  str_homestory_chat_28022002 = "porque es tan grande? Y siempre lo llevas contigo.",
  str_homestory_chat_28022003 = "Es grande porque está lleno de material periodístico: notas, fotos, periódicos, incluso folletos...",
  str_homestory_chat_28022004 = "¿Necesitas llevar todo eso contigo? ¿No puedes dejarlo en tu oficina?",
  str_homestory_chat_28022005 = "¡De ninguna manera! ¡Las noticias siempre están conectadas!",
  str_homestory_chat_28022006 = "A veces, el primer olor de una gran historia se esconde en las noticias más insignificantes.",
  str_homestory_chat_28022007 = "Una vez que te encuentras con personas o cosas que posiblemente podrían contener una historia, ¡nunca sabes cuándo podrías necesitarlas!",
  str_homestory_chat_28022008 = "¿Pero no crees que esos chismes se volverían obsoletos con el tiempo?",
  str_homestory_chat_28022009 = "Es por eso que necesito llevar esta bolsa conmigo. ¡Lo tenía hecho a medida!",
  str_homestory_chat_28022010 = "No solo es enorme, también tiene muchos compartimentos, ¡así que puedo encontrar la información que necesito cuando la necesito!",
  str_homestory_chat_28022011 = "¡Recuerdo la ubicación específica de todos y cada uno de los documentos!",
  str_homestory_chat_28022012 = "Si tu memoria es tan buena, ¿por qué no memorizas toda la información?",
  str_homestory_chat_28023001 = "¿Tienes algún chisme?",
  str_homestory_chat_28023002 = "Ah... No, nada. La vida aquí es tan aburrida.",
  str_homestory_chat_28023003 = "Todo es Chubbs, Chubbs, Chubbs.",
  str_homestory_chat_28023004 = "No hay cafeterías ni quioscos donde pueda espiar para obtener información.",
  str_homestory_chat_28023005 = "Sin embargo, es una buena oportunidad para tomar un descanso.",
  str_homestory_chat_28023006 = "¿Qué bueno es eso? ¡Me perdería todas las últimas noticias!",
  str_homestory_chat_28023007 = "Pero la vida aquí es así de pacífica. ¿Por qué no encuentras otra cosa que hacer?",
  str_homestory_chat_28023008 = "Algo más... ¡Lo tengo!",
  str_homestory_chat_28023009 = "¡Puedo entrenar a los Chubbs para que se enteren de los últimos chismes!",
  str_homestory_chat_28023010 = "Así... jejeje...",
  str_homestory_chat_28023011 = "¡Por favor no!",
  str_homestory_chat_28199999 = "¿Qué has estado haciendo últimamente, mi joven amigo?",
  str_homestory_chat_28121001 = "¿Cuales son tus aficiones?",
  str_homestory_chat_28121002 = "Me encanta el tallado en madera.",
  str_homestory_chat_28121003 = "Tallado en madera?",
  str_homestory_chat_28121004 = "Sí, toma un trozo de madera corriente, un buen cuchillo de trinchar...",
  str_homestory_chat_28121005 = "Y una obra de arte se formará en tus manos.",
  str_homestory_chat_28121006 = "A veces me hace más feliz que ganar una batalla.",
  str_homestory_chat_28121007 = "Realmente te gusta, ¿no?",
  str_homestory_chat_28122001 = "¿Árbol único?",
  str_homestory_chat_28122002 = "Se me ocurrió una idea cuando vi los maravillosos árboles aquí.",
  str_homestory_chat_28122003 = "Quieres tallar algo con ellos, ¿no?",
  str_homestory_chat_28122004 = "Eso es correcto. ¿Puedo?",
  str_homestory_chat_28122005 = "No.",
  str_homestory_chat_28122006 = "Un rotundo \"No\", ¿eh? Estos árboles deben ser importantes para ti.",
  str_homestory_chat_28122007 = "Principalmente porque... son tan difíciles de cultivar.",
  str_homestory_chat_28122008 = "Pensemos...",
  str_homestory_chat_28122009 = "¿Necesita muchos materiales para tallar en madera?",
  str_homestory_chat_28122010 = "Sí, nunca he tallado uno antes, por lo que puede haber muchos materiales desperdiciados.",
  str_homestory_chat_28122011 = "Probablemente tengan características muy diferentes a la madera que normalmente uso para tallar.",
  str_homestory_chat_28122012 = "Entonces... me temo que no.",
  str_homestory_chat_28122013 = "Bien... Supongo que dejaré de buscar buena madera aquí.",
  str_homestory_chat_28122014 = "O tal vez debería comprar algunos en lugares extranjeros...",
  str_homestory_chat_28123001 = "¿Te gustan los gatos?",
  str_homestory_chat_28123002 = "Sí, por eso tengo tres.",
  str_homestory_chat_28123003 = "¡¿Tres?!",
  str_homestory_chat_28123004 = "Pero solo he visto uno.",
  str_homestory_chat_28123005 = "Porque tienen funciones diferentes.",
  str_homestory_chat_28123006 = "¿Diferentes deberes? ¿En serio?",
  str_homestory_chat_28123007 = "Yixin pelea conmigo, Yimeng pasa tiempo conmigo aquí, y en cuanto a Yinuo...",
  str_homestory_chat_28123008 = "Yinuo es muy escurridizo y ni siquiera sé dónde está la mayor parte del tiempo.",
  str_homestory_chat_28123009 = "¿Eso cuenta como tener un gato?",
  str_homestory_chat_28124001 = "¿Estás buscando comprar algo?",
  str_homestory_chat_28124002 = "Quiero conseguir algunas... piezas interesantes para mi habitación. Me hará sentir como vivir en Twin Pavilions Bay.",
  str_homestory_chat_28124003 = "¿Piezas interesantes... como antigüedades? Las antigüedades de Longzhou son difíciles de conseguir.",
  str_homestory_chat_28124004 = "No tiene que ser antigüedades de Longzhou. De hecho, espero antigüedades de Astra.",
  str_homestory_chat_28124005 = "Como espadas de Lumopolis, Vintage Wine de Umbraton, Bone Carvings de Northland...",
  str_homestory_chat_28124006 = "Parece que eres un hombre con una amplia gama de intereses.",
  str_homestory_chat_28124007 = "Gracias. Pensé que ya que estoy aquí, debería tratar de apreciar la cultura del lugar.",
  str_homestory_chat_28124008 = "Es una buena oportunidad para conocer a Astra.",
  str_homestory_chat_28124009 = "Estaré atento a ti.",
  str_homestory_chat_28125001 = "Diferentes tallas?",
  str_homestory_chat_28125002 = "Sí. ¿Sabes algo de ellos?",
  str_homestory_chat_28125003 = "Yo sé un poco.",
  str_homestory_chat_28125004 = "¿Vaya? Entonces dime, ¿qué tipos de tallas hay en este continente?",
  str_homestory_chat_28125005 = "En su mayoría de piedra y madera, y Northland tiene tallas de hueso.",
  str_homestory_chat_28125006 = "¡Escuché que Illumina y Rediesel Wrench tienen tallas de hierro raras!",
  str_homestory_chat_28125007 = "Ya veo, así que hay tantos... Pero parece que no hay tallas de raíz.",
  str_homestory_chat_28125008 = "¿Tallas de raíz?",
  str_homestory_chat_28125009 = "Es algo que es exclusivo de Longzhou. Te lo explicaré cuando tenga la oportunidad.",
  str_homestory_chat_28125010 = "Ahora estoy realmente intrigado.",
  str_homestory_chat_28125011 = "no lo entiendo del todo...",
  str_homestory_chat_28125012 = "Es una pena, tendremos que parar aquí.",
  str_homestory_chat_28125013 = "Siento que necesito decir algo...",
  str_homestory_chat_28299999 = "¿Qué es?",
  str_homestory_chat_28221001 = "¿Quieres saber dónde puedes nadar?",
  str_homestory_chat_28221002 = "Sí, he pasado demasiado tiempo en tierra y mi habilidad para nadar se está oxidando.",
  str_homestory_chat_28221003 = "¿En el rio?",
  str_homestory_chat_28221004 = "Eso es un poco demasiado superficial, creo. Busco algo más profundo, preferiblemente con ondas.",
  str_homestory_chat_28221005 = "Olas de diferentes magnitudes, como el océano.",
  str_homestory_chat_28221006 = "Entonces, ¿por qué no simplemente ir a la playa y nadar en el océano?",
  str_homestory_chat_28222001 = "¿Qué te gusta comer?",
  str_homestory_chat_28222002 = "Puede que no te guste lo que a mí me gusta. Por ejemplo, fideos de caracol de río.",
  str_homestory_chat_28222003 = "Esta bien...",
  str_homestory_chat_28222004 = "¿También te gusta? ¡Eso es genial!",
  str_homestory_chat_28222005 = "Bueno, no lo encuentro repulsivo, pero trato de no comerlo cuando hay otras personas alrededor.",
  str_homestory_chat_28222006 = "Correcto, lo entiendo.",
  str_homestory_chat_28222007 = "Ya eres lo suficientemente valiente para poder comer esto. ¡Un auténtico héroe Astra!",
  str_homestory_chat_28222008 = "Bueno, eso es demasiado...",
  str_homestory_chat_28222009 = "Tienes un punto.",
  str_homestory_chat_28222010 = "Tiene un olor muy picante.",
  str_homestory_chat_28222011 = "Normalmente lo como solo.",
  str_homestory_chat_28222012 = "¡Eso es muy considerado de tu parte!",
  str_homestory_chat_28223001 = "¿Estás buscando medicina?",
  str_homestory_chat_28223002 = "Sí, para el mareo. ¿Usted tiene alguna?",
  str_homestory_chat_28223003 = "No.",
  str_homestory_chat_28223004 = "Yo podría...",
  str_homestory_chat_28223005 = "Espera, ¿por qué lo necesitas?",
  str_homestory_chat_28223006 = "¿No eres un patrón experimentado?",
  str_homestory_chat_28223007 = "Es para otras personas, por supuesto. Más personas se marean de lo que piensas.",
  str_homestory_chat_28223008 = "Incluso algunos marineros veteranos lo consiguen a veces.",
  str_homestory_chat_28223009 = "Ya veo, iré a buscar algunos.",
  str_homestory_chat_28224001 = "Escuché que estás buscando un bote.",
  str_homestory_chat_28224002 = "Sí, pensé en esto cuando vi el río.",
  str_homestory_chat_28224003 = "Cloud Gardens está cerrado al mundo exterior y no se puede entrar ni salir a través de las montañas. Pero este río parece un paso tranquilo.",
  str_homestory_chat_28224004 = "Así que me pregunto si puedo realizar algunas operaciones sencillas utilizando el río.",
  str_homestory_chat_28224005 = "No.",
  str_homestory_chat_28224006 = "¿Por qué?",
  str_homestory_chat_28224007 = "Si bien es agradable y tranquilo, los Chubb dicen que las corrientes son bastante desfavorables en muchas secciones del río.",
  str_homestory_chat_28224008 = "Y hay arrecifes en aguas poco profundas que vuelcan los barcos con facilidad.",
  str_homestory_chat_28224009 = "Quizás.",
  str_homestory_chat_28224010 = "¿En serio? ¿Está seguro?",
  str_homestory_chat_28224011 = "Los Chubbs dicen que las aguas pueden volverse bastante complicadas a veces.",
  str_homestory_chat_28224012 = "Pero no sé los detalles.",
  str_homestory_chat_28224013 = "¿Complicado dices? Parece que se requiere una encuesta adecuada.",
  str_homestory_chat_28224014 = "Tal vez... Me apresuré un poco.",
  str_homestory_chat_28225001 = "tu espada...",
  str_homestory_chat_28225002 = "¿Qué pasa con eso?",
  str_homestory_chat_28225003 = "Alguien ha presentado una denuncia contra usted.",
  str_homestory_chat_28225004 = "¿Eh? ¿Quién? ¿Por qué harían eso?",
  str_homestory_chat_28225005 = "Los Chubbs. Ven que siempre estás jugando con él.",
  str_homestory_chat_28225006 = "Y piensan que podrías hacerles daño.",
  str_homestory_chat_28225007 = "Bueno, tienen razón.",
  str_homestory_chat_28225008 = "Por eso estoy aquí en Cloud Gardens. Para cazar Chubbs.",
  str_homestory_chat_28225009 = "¡¿Hablas en serio?!",
  str_homestory_chat_28225010 = "¿En serio creías eso?",
  str_homestory_chat_28225011 = "¡Por supuesto que no!",
  str_homestory_chat_28225012 = "Así que no te preocupes por eso. Sólo diles que no pretendo hacer daño.",
  str_homestory_chat_28225013 = "No deberían tener miedo, porque juguetear con mi cuchillo es solo un hábito mío.",
  str_homestory_chat_28225014 = "R-correcto.",
  str_homestory_chat_28399999 = "PlayerName, ¿quieres probar algunas hierbas?",
  str_homestory_chat_28301001 = "¡Parece que encontraste muchos de ellos!",
  str_homestory_chat_28301002 = "Sí, el clima aquí es excelente para cultivar hierbas.",
  str_homestory_chat_28301003 = "Muchas plantas en la naturaleza tienen efectos medicinales.",
  str_homestory_chat_28301004 = "Por no hablar de esos maravillosos árboles...",
  str_homestory_chat_28301005 = "¿Estás... tras el Árbol Único ahora?",
  str_homestory_chat_28301006 = "Aún no. Después de todo, los Chubbs los protegen mucho.",
  str_homestory_chat_28301007 = "Así que he estado pensando en trasplantar algunas de las hierbas de Longzhou aquí.",
  str_homestory_chat_28301008 = "Es una buena idea.",
  str_homestory_chat_28321001 = "¿Meriendas?",
  str_homestory_chat_28321002 = "He estado comiendo gachas por un tiempo, así que estoy buscando bocadillos para variar.",
  str_homestory_chat_28321003 = "Le pregunté al Chubb Merchant, ¡pero no tienen nada!",
  str_homestory_chat_28321004 = "¿No hay buenos bocadillos en Astra?",
  str_homestory_chat_28321005 = "¡No, ahí hay!",
  str_homestory_chat_28321006 = "Seguir hablando.",
  str_homestory_chat_28321007 = "Gomitas de Northland.",
  str_homestory_chat_28321008 = "Son suaves, no demasiado dulces y no se pegan a los dientes. El regusto ligeramente dulce es para morirse.",
  str_homestory_chat_28321009 = "Bombones de Umbraton.",
  str_homestory_chat_28321010 = "El chocolate puro es realmente amargo, por lo que muchas tiendas le agregan leche, azúcar e incluso una variedad de nueces.",
  str_homestory_chat_28321011 = "Como avellanas, piñones, bellotas...",
  str_homestory_chat_28321012 = "Parada.",
  str_homestory_chat_28321013 = "Estás babeando...",
  str_homestory_chat_28321014 = "¡Algún día los probaré todos! Pero por ahora...",
  str_homestory_chat_28321015 = "Supongo que me las arreglaré con mi imaginación.",
  str_homestory_chat_28321016 = "De alguna manera, realmente eres algo.",
  str_homestory_chat_28322001 = "¿Una acería?",
  str_homestory_chat_28322002 = "Sí, mira esto.",
  str_homestory_chat_28322003 = "Después de venir a Astra, me doy cuenta de que la forma en que sopesas las cosas es diferente.",
  str_homestory_chat_28322004 = "Usas la cosa en el suelo que tiene un plato a cada lado.",
  str_homestory_chat_28322005 = "Te refieres a una escala.",
  str_homestory_chat_28322006 = "Sí, pero no se ven muy portátiles y necesitas una superficie plana para usarlos.",
  str_homestory_chat_28322007 = "Mi Steelyard es mucho más fácil de usar. ¿Por qué Astra está atrasado en esto?",
  str_homestory_chat_28322008 = "En realidad, usan acerías en Umbraton.",
  str_homestory_chat_28322009 = "Espera, ¿qué?",
  str_homestory_chat_28322010 = "Al menos el Lin Guild, creo. Además, las escalas son muy precisas.",
  str_homestory_chat_28322011 = "Las acerías... pueden verse afectadas por la persona que las opera.",
  str_homestory_chat_28322012 = "Ya veo. Supongo que es como dijo Buzi, \"¡adopta medidas que se adapten a las condiciones locales!\"",
  str_homestory_chat_28322013 = "Quiere decir que cada uno tiene sus méritos.",
  str_homestory_chat_28323001 = "¿Estás buscando un gato?",
  str_homestory_chat_28323002 = "Bueno, más exactamente, mi hermano está buscando un compañero.",
  str_homestory_chat_28323003 = "¿Su hermano?",
  str_homestory_chat_28323004 = "¡Pequeña cola! De todos modos, ¿tienes un gato o no?",
  str_homestory_chat_28323005 = "Aquí no, pero los que vienen para quedarse pueden traer uno o dos.",
  str_homestory_chat_28323006 = "¿Por qué no les preguntas?",
  str_homestory_chat_28323007 = "Pero son de Astra, y no los conozco bien.",
  str_homestory_chat_28323008 = "¡Todos ustedes viven aquí, estará bien!",
  str_homestory_chat_28323009 = "¿D-de veras?",
  str_homestory_chat_28323010 = "Eres tan extrovertida que no será un problema.",
  str_homestory_chat_28323011 = "¡Supongo que tendré que hacerlo! Voy a preguntarles en un día o dos.",
  str_homestory_chat_28499999 = "Parece que hoy tienes mucho tiempo libre, pequeña Caelestite.",
  str_homestory_chat_28421001 = "Parece que tú también.",
  str_homestory_chat_28421002 = "Solo voy a dar un paseo.",
  str_homestory_chat_28421003 = "¿Un paseo?",
  str_homestory_chat_28421004 = "Ya que no tengo tareas importantes que atender, y no hay mucho trabajo que hacer en Cloud Gardens...",
  str_homestory_chat_28421005 = "Sin mencionar que casi nada por aquí puede despertar mi interés, así que... Sí.",
  str_homestory_chat_28421006 = "Está bien...",
  str_homestory_chat_28422001 = "¿Quieres hablar de comida?",
  str_homestory_chat_28422002 = "Bien. No sé qué te gusta comer, pequeña Caelestite.",
  str_homestory_chat_28422003 = "Postres",
  str_homestory_chat_28422004 = "En realidad te gustan las cosas dulces... Qué trillado.",
  str_homestory_chat_28422005 = "Pero a todos les gustan las cosas dulces, como el chocolate.",
  str_homestory_chat_28422006 = "Sin embargo, el chocolate es en realidad amargo. La razón por la que crees que es dulce es en realidad por el azúcar añadido.",
  str_homestory_chat_28422007 = "Entonces... ¿te gustan las cosas amargas?",
  str_homestory_chat_28422008 = "Realmente no...",
  str_homestory_chat_28422009 = "Carne",
  str_homestory_chat_28422010 = "¡El buen gusto! ¿Qué pasa con el hígado? ¿Especialmente bocadillos hechos de hígado...?",
  str_homestory_chat_28422011 = "Erm... No lo creo.",
  str_homestory_chat_28422012 = "Ay, qué desgracia.",
  str_homestory_chat_28423001 = "¿Estás buscando madera?",
  str_homestory_chat_28423002 = "Sí, quiero construir un pequeño nido en mi habitación. ¿Está bien?",
  str_homestory_chat_28423003 = "Seguro.",
  str_homestory_chat_28423004 = "Esa no es una buena idea.",
  str_homestory_chat_28423005 = "Pero... ¿para qué quieres construir un nido?",
  str_homestory_chat_28423006 = "Para hacerle un hogar. No ha estado durmiendo bien últimamente...",
  str_homestory_chat_28423007 = "¿Quién?",
  str_homestory_chat_28423008 = "Sacred Python, por supuesto, no se puede esperar que duerma en la cama de otra persona todas las noches...",
  str_homestory_chat_28423009 = "¡O-Claro que no! Que pensamiento tan aterrador...",
  str_homestory_chat_28423010 = "Entonces, ¿está bien entonces?",
  str_homestory_chat_28423011 = "Bueno... Puedes hacer uno debajo de tu cama.",
  str_homestory_chat_28424001 = "¿Libros?",
  str_homestory_chat_28424002 = "Bien. Quiero preguntarte, pequeña Caelestite, ¿qué te gusta leer?",
  str_homestory_chat_28424003 = "novelas",
  str_homestory_chat_28424004 = "Que respuesta más clara...",
  str_homestory_chat_28424005 = "Pero hay tantas buenas novelas, especialmente todas esas novelas de misterio de Umbraton...",
  str_homestory_chat_28424006 = "Parece que este género es realmente muy popular...",
  str_homestory_chat_28424007 = "Biografías.",
  str_homestory_chat_28424008 = "¿Oh? Interesante... ¿Te interesa la historia?",
  str_homestory_chat_28424009 = "Quiero saber más sobre la historia de Astra.",
  str_homestory_chat_28424010 = "Oye, ¿qué libros te gustan, Jeriah?",
  str_homestory_chat_28424011 = "Filosofía.",
  str_homestory_chat_28424012 = "¡Ay!",
  str_homestory_chat_28424013 = "Pareces sorprendido. La filosofía es realmente muy interesante. Te recomendaré algunos libros cuando tenga tiempo.",
  str_homestory_chat_28424014 = "A-Bien.",
  str_homestory_chat_28425001 = "¿Un Chubb?",
  str_homestory_chat_28425002 = "Sí. He notado que uno de los Chubbs es realmente muy inteligente.",
  str_homestory_chat_28425003 = "¿Qué Chubb?",
  str_homestory_chat_28425004 = "El de la barba en Hyacinth Square.",
  str_homestory_chat_28425005 = "¿Élder Chubb?",
  str_homestory_chat_28425006 = "Sí. Se llama el Anciano, por lo que debe ser sabio.",
  str_homestory_chat_28425007 = "¿Solo por esto...?",
  str_homestory_chat_28425008 = "De hecho, al \"Anciano\" también se le conoce como \"Barbudo\"...",
  str_homestory_chat_28425009 = "barbudo?",
  str_homestory_chat_28425010 = "Creo que solo se puso una barba falsa en la cara para parecer inteligente.",
  str_homestory_chat_28425011 = "Mmm... Ya veo.",
  str_homestory_chat_28425012 = "Bueno eso es embarazoso...",
  str_homestory_chat_28425013 = "Creo que debería irme.",
  str_homestory_chat_28599999 = "Hola, PlayerName. ¿Que esta pasando ahora?",
  str_homestory_chat_28501001 = "Poco. ¿Estás bien?",
  str_homestory_chat_28501002 = "Quiero encontrar un trabajo de medio tiempo en Cloud Gardens.",
  str_homestory_chat_28501003 = "¿Un trabajo de medio tiempo?",
  str_homestory_chat_28501004 = "Ya le he preguntado al Elder Chubb y al Chubb Merchant, pero parece que no tienen nada adecuado para mí.",
  str_homestory_chat_28501005 = "Sí, no hay mucho trabajo disponible aquí, y todos nos ocupamos de nuestros propios asuntos.",
  str_homestory_chat_28501006 = "¿No tienes ningún trabajo de entrega disponible? Enviar correo es importante, ¡lo sabes!",
  str_homestory_chat_28501007 = "Este lugar no es demasiado grande. No hay trabajo de entrega, además, la gente viene aquí para tomarse un descanso de todo eso.",
  str_homestory_chat_28501008 = "*suspiro* Oh bueno...",
  str_homestory_chat_28521001 = "¿Algo te molesta?",
  str_homestory_chat_28521002 = "Sí, y es el tipo de cosas que simplemente no se pueden tolerar por un momento.",
  str_homestory_chat_28521003 = "Erm... ¿Eclipsitos?",
  str_homestory_chat_28521004 = "Todo el mundo odia los eclipses...",
  str_homestory_chat_28521005 = "¿Chicos malos?",
  str_homestory_chat_28521006 = "¿Qué significa eso?",
  str_homestory_chat_28521007 = "Como... gente que hirió a tus amigos.",
  str_homestory_chat_28521008 = "Comprendo.",
  str_homestory_chat_28521009 = "Entonces, ¿qué odias, Kya?",
  str_homestory_chat_28521010 = "¡Gente que llega tarde!",
  str_homestory_chat_28521011 = "¿Cómo puede alguien soportar no ser puntual? Y a veces ya hemos fijado la hora con antelación.",
  str_homestory_chat_28521012 = "A las personas a las que no les importa llegar a tiempo... ¡deberían aprender una lección!",
  str_homestory_chat_28521013 = "Cierto...",
  str_homestory_chat_28522001 = "¿Estás buscando comprar algo?",
  str_homestory_chat_28522002 = "Sí, me gustaría comprar un reloj.",
  str_homestory_chat_28522003 = "Pero no vendemos relojes en Cloud Gardens. ¿Estás seguro de que estás en el lugar correcto?",
  str_homestory_chat_28522004 = "No, escuché que tienes un servicio especial aquí.",
  str_homestory_chat_28522005 = "¿Servicio especial?",
  str_homestory_chat_28522006 = "Sí, el legendario \"Descuento de Cloud Gardens\" del que he oído hablar.",
  str_homestory_chat_28522007 = "Se supone que es un gran descuento. ¡Algunos dicen que es hasta una cuarta parte del precio habitual!",
  str_homestory_chat_28522008 = "¡Eso es ridículo! ¿Quién te dijo eso?",
  str_homestory_chat_28522009 = "¿Eh? ¿Así que eso no servirá...?",
  str_homestory_chat_28522010 = "Que pena... Me encontré con un reloj en Umbraton que me gustó mucho...",
  str_homestory_chat_28522011 = "Pero es demasiado caro. Tardaré diez años en pagarlo... Con un descuento, solo tardaré dos años y medio...",
  str_homestory_chat_28522012 = "Guau... Tienes que pedir un aumento.",
  str_homestory_chat_28522013 = "¡Todo se debe a que Umbraton es demasiado caro! ¡Maldigo a esos mercaderes sin alma!",
  str_homestory_chat_28522014 = "¡Correcto!",
  str_homestory_chat_28523001 = "¿Alimento?",
  str_homestory_chat_28523002 = "Sí, ni siquiera sé lo que te gusta comer normalmente, PlayerName.",
  str_homestory_chat_28523003 = "Hmm... Solo como lo que se ofrece.",
  str_homestory_chat_28523004 = "¿De verdad no te importa?",
  str_homestory_chat_28523005 = "Bebí la solución nutritiva que Colossus preparó para mí durante años...",
  str_homestory_chat_28523006 = "Así que... realmente no sabes cómo disfrutar la comida... pero supongo que yo soy igual.",
  str_homestory_chat_28523007 = "¿Oh? ¿En realidad?",
  str_homestory_chat_28523008 = "A veces solo como una galleta o un poco de cecina para que mis pedidos no se retrasen.",
  str_homestory_chat_28523009 = "Solo después de terminar el trabajo como lo que quiero, como fideos fritos picantes.",
  str_homestory_chat_28523010 = "Parece que siempre estás trabajando duro también, PlayerName... Pero tal vez esa es la única forma en que hemos logrado lograr lo que tenemos.",
  str_homestory_chat_28523011 = "Erm... Creo que malinterpretaste completamente la situación allí.",
  str_homestory_chat_28699999 = "Te ves tan relajado, PlayerName.",
  str_homestory_chat_28621001 = "Tú también.",
  str_homestory_chat_28621002 = "De hecho, este sentimiento es tan relajante que me da sueño, bostezo—",
  str_homestory_chat_28621003 = "Bostezo-",
  str_homestory_chat_28621004 = "Parece que eres el mismo.",
  str_homestory_chat_28621005 = "¿Es esta somnolencia infecciosa?",
  str_homestory_chat_28621006 = "Qué interesante... ¿Vas a tomar una siesta?",
  str_homestory_chat_28621007 = "No, tengo otro lugar al que debo ir primero.",
  str_homestory_chat_28621008 = "¡Espero que te mantengas motivado entonces!",
  str_homestory_chat_28622001 = "Tu mano...",
  str_homestory_chat_28622002 = "¿Te refieres a mi Mano Divina?",
  str_homestory_chat_28622003 = "Sí.",
  str_homestory_chat_28622004 = "Oh, es una larga historia... Solo necesitas saber que puede usar Luminatics potentes.",
  str_homestory_chat_28622005 = "Entiendo...",
  str_homestory_chat_28622006 = "No.",
  str_homestory_chat_28622007 = "Es tu mano izquierda.",
  str_homestory_chat_28622008 = "¿Mi mano izquierda? Claro, también me preguntan sobre eso con bastante frecuencia.",
  str_homestory_chat_28622009 = "Así es... Tu mano izquierda es poderosa. ¿Es ese el poder de la Mano Divina?",
  str_homestory_chat_28622010 = "Oh, para nada. Es porque siempre uso mi mano izquierda.",
  str_homestory_chat_28622011 = "Se volvió muy fuerte sin que yo me diera cuenta...",
  str_homestory_chat_28622012 = "Supongo que esto cuenta como un tipo de entrenamiento indirecto.",
  str_homestory_chat_28623001 = "¿Eclipsites?",
  str_homestory_chat_28623002 = "Parece que los Eclipsites nunca han venido aquí.",
  str_homestory_chat_28623003 = "Es correcto.",
  str_homestory_chat_28623004 = "Sería un gran problema si realmente vienen aquí.",
  str_homestory_chat_28623005 = "Eh... Entonces como puedo encontrarlo...",
  str_homestory_chat_28623006 = "¿Él?",
  str_homestory_chat_28623007 = "¡Ay, nada! Incluso si no hay eclipses, debería estar bien preguntar dónde hay rastros de eclipses, ¿verdad?",
  str_homestory_chat_28623008 = "Sabes algo al respecto?",
  str_homestory_chat_28623009 = "De cualquier manera, no hay ninguno aquí, así que deberías renunciar a tu idea.",
  str_homestory_chat_28623010 = "Supongo que tendré que preguntarle a esos Chubbs entonces.",
  str_homestory_chat_28623011 = "¡Ellos tampoco saben!",
  str_homestory_chat_28624001 = "¿Quieres hacer negocios?",
  str_homestory_chat_28624002 = "En realidad, solo quiero comprar algunas cosas como libros.",
  str_homestory_chat_28624003 = "Realmente no puedes conseguirlos aquí en Cloud Gardens. ¿Por qué no vas a Umbraton?",
  str_homestory_chat_28624004 = "Porque está demasiado lejos. Solo quiero ver si hay una librería cerca para comprar libros al azar para pasar el tiempo.",
  str_homestory_chat_28624005 = "¿No están Lumopolis y Umbraton bastante cerca...?",
  str_homestory_chat_28624006 = "Pero ya estoy aquí. ¿Tiene Chubb Merchant algo que vender?",
  str_homestory_chat_28624007 = "Que yo sepa, no.",
  str_homestory_chat_28624008 = "¿Oh? Parece que solo puedo... bostezar...",
  str_homestory_chat_28624009 = "Ve a tomar una siesta. Esa también es una manera de pasar el tiempo.",
  str_homestory_chat_28625001 = "¿Meriendas?",
  str_homestory_chat_28625002 = "Sí. ¿Qué bocadillos te gusta comer?",
  str_homestory_chat_28625003 = "Pasteles pequeños.",
  str_homestory_chat_28625004 = "Entonces te gustan los dulces... ¿Te sientes mal de alguna manera después de comerlos?",
  str_homestory_chat_28625005 = "No, Tina. ¿No te gustan las cosas dulces?",
  str_homestory_chat_28625006 = "Galletas.",
  str_homestory_chat_28625007 = "Especialmente los ligeramente salados porque saben muy bien con un poco de agua caliente.",
  str_homestory_chat_28625008 = "Has hecho una buena elección. Los postres no tienen que ser dulces...",
  str_homestory_chat_28625009 = "¡Comer bocadillos con una variedad de sabores es el camino a seguir!",
  str_homestory_chat_28625010 = "Parece que no te gustan las cosas dulces...",
  str_homestory_chat_28625011 = "Los odio porque me pongo inexplicablemente ansioso y tengo dificultad para dormir después de comerlos.",
  str_homestory_chat_28625012 = "Es muy doloroso dar vueltas y vueltas en la cama. ¿Sabes cómo es?",
  str_homestory_chat_28625013 = "Me ha pasado antes. Me sentí tan cansada al día siguiente.",
  str_homestory_chat_28625014 = "Sí, por eso a veces también necesito dormir durante el día.",
  str_homestory_chat_28625015 = "Pero siempre estás durmiendo incluso cuando no has comido nada dulce...",
  str_homestory_chat_28999999 = "PlayerName, ¿Que necesitas que haga?",
  str_homestory_chat_28921001 = "¿Oh? Charlemos casualmente.",
  str_homestory_chat_28921002 = "Parece que eres bastante libre tú mismo. ¿Quieres desarrollar algunas aficiones?",
  str_homestory_chat_28921003 = "¿Cómo qué?",
  str_homestory_chat_28921004 = "Es muy agradable plantar flores.",
  str_homestory_chat_28921005 = "Tienes la oportunidad de ver las semillas sembradas brotar y crecer antes de finalmente florecer en magníficas flores...",
  str_homestory_chat_28921006 = "Te hará suspirar ante la belleza de la naturaleza.",
  str_homestory_chat_28921007 = "Ya estoy plantando arboles...",
  str_homestory_chat_28921008 = "Eso también es bueno. Sigue así y algún día te inspirarás.",
  str_homestory_chat_28922001 = "tu arma...",
  str_homestory_chat_28922002 = "¿Qué pasa con eso?",
  str_homestory_chat_28922003 = "A veces no parece un arma, especialmente esa broca.",
  str_homestory_chat_28922004 = "Entiendo. No se parece a las armas estándar utilizadas por los Lumo Knights, ¿verdad?",
  str_homestory_chat_28922005 = "¡Exactamente! Y muchos caballeros usan espadas, lanzas y demás...",
  str_homestory_chat_28922006 = "¿Hay alguna razón para esto?",
  str_homestory_chat_28922007 = "La razón no es importante, al igual que el arma que usa un caballero no es importante.",
  str_homestory_chat_28922008 = "¿No importante?",
  str_homestory_chat_28922009 = "Porque la caballerosidad de un caballero es lo que hace que un caballero sea quien es.",
  str_homestory_chat_28922010 = "¡Lo sé! Como dicen, las virtudes de un caballero son la humildad, la tolerancia, etc.",
  str_homestory_chat_28922011 = "Sí, eso es lo que hace que un caballero sea un caballero, no las armas.",
  str_homestory_chat_28922012 = "Entiendo.",
  str_homestory_chat_28923001 = "¿Qué quieres comprar?",
  str_homestory_chat_28923002 = "Quiero comprar un poco de aceite.",
  str_homestory_chat_28923003 = "¿Qué aceite?",
  str_homestory_chat_28923004 = "Debería tener un poco de aceite de cocina por aquí.",
  str_homestory_chat_28923005 = "Lo necesito para lubricar piezas. Debería poder conseguirlos en Umbraton.",
  str_homestory_chat_28923006 = "Bueno...",
  str_homestory_chat_28923007 = "Hay alguna dificultad, ¿verdad? Quiero decir, este es un lugar lleno de paisajes naturales.",
  str_homestory_chat_28923008 = "Hmm... Es cierto que realmente no necesitamos mucho de eso aquí.",
  str_homestory_chat_28923009 = "Principalmente quiero usarlo para hacer un poco de mantenimiento. Mi arma parece haberse atascado recientemente.",
  str_homestory_chat_28923010 = "Escucho este crujido que hace que me duelan los dientes cuando lo balanceo.",
  str_homestory_chat_28923011 = "En ese caso... Hagamos tiempo para ir a Umbraton.",
  str_homestory_chat_28924001 = "¿Qué tienes en mente?",
  str_homestory_chat_28924002 = "Estoy pensando en algo realmente importante, pero parece que no puedo encontrar una respuesta.",
  str_homestory_chat_28924003 = "¿Por qué no me cuentas al respecto?",
  str_homestory_chat_28924004 = "¿Qué crees que es más importante, la justicia o la igualdad?",
  str_homestory_chat_28924005 = "Justicia.",
  str_homestory_chat_28924006 = "Entonces, ¿estás de acuerdo en que los desfavorecidos deberían tener más derechos?",
  str_homestory_chat_28924007 = "¿Como otorgarles inmunidad incluso si cometen algunos delitos leves?",
  str_homestory_chat_28924008 = "Déjame pensar.",
  str_homestory_chat_28924009 = "Igualdad.",
  str_homestory_chat_28924010 = "Digamos que dos corredores están compitiendo en un sprint.",
  str_homestory_chat_28924011 = "Uno practica mucho correr, mientras que el otro es un soldado con una pierna rota.",
  str_homestory_chat_28924012 = "Según usted, los criterios para ganar no deberían tener en cuenta la condición física de estos dos.",
  str_homestory_chat_28924013 = "Sí.",
  str_homestory_chat_28924014 = "¿Pero es eso realmente bueno?",
  str_homestory_chat_28924015 = "¡Ahhhh! Estas preguntas son tan molestas, y no puedo encontrar la respuesta correcta.",
  str_homestory_chat_28924016 = "Sí... es por eso que estoy caminando de un lado a otro aquí.",
  str_homestory_chat_28925001 = "¿El Desierto de Rediesel?",
  str_homestory_chat_28925002 = "He oído que has viajado a muchos lugares. ¿Has visitado este lugar?",
  str_homestory_chat_28925003 = "No tengo mucha impresión de este lugar.",
  str_homestory_chat_28925004 = "Oh... Qué desafortunado.",
  str_homestory_chat_28925005 = "Parece que has estado allí antes, Leyn?",
  str_homestory_chat_28925006 = "He tenido la suerte de visitarlo varias veces. El paisaje allí es realmente diferente al de Lumopolis.",
  str_homestory_chat_28925007 = "Los residentes allí también ven las cosas de manera diferente a los residentes de Lumopolis. No importa cuán difícil sea la vida, no faltan quienes están a la altura de las circunstancias.",
  str_homestory_chat_28925008 = "Parece que tienes toda una historia que contar sobre tus experiencias en el desierto de Rediesel...",
  str_homestory_chat_28925009 = "Te lo contaré si tengo la oportunidad.",
  str_homestory_chat_28925010 = "Seguro.",
  str_homestory_chat_28925011 = "¿Qué opinas sobre la cultura y las costumbres locales?",
  str_homestory_chat_28925012 = "Son apasionados y desenfrenados... como el desierto.",
  str_homestory_chat_28925013 = "En efecto. Aunque realmente no pude adaptarme a ellos, creo que su existencia es necesaria para esta tierra.",
  str_homestory_chat_28925014 = "Es lo mismo para muchas cosas en este mundo.",
  str_homestory_chat_29099999 = "PlayerName, hoy es un buen día para dar un paseo.",
  str_homestory_chat_29001001 = "Hola, Matthieu.",
  str_homestory_chat_29001002 = "Parece que hoy es otro día relajante para ti. Los plebeyos aquí seguro que están relajados.",
  str_homestory_chat_29001003 = "Aquí no hay plebeyos. Todos son iguales.",
  str_homestory_chat_29001004 = "¿Qué hay de esos tipos cuadrados?",
  str_homestory_chat_29001005 = "¿Te refieres a los Chubbs?",
  str_homestory_chat_29001006 = "Sí, los veo trabajando en todas partes a todas horas del día.",
  str_homestory_chat_29001007 = "Algunos de ellos son guías en Hyacinth Tower, mientras que otros riegan plantas o hacen cuentas todo el día.",
  str_homestory_chat_29001008 = "Eso es lo que les apasiona...",
  str_homestory_chat_29021001 = "¿Quieres construir algo?",
  str_homestory_chat_29021002 = "Sí, tengo más dinero del que puedo gastar de todos modos.",
  str_homestory_chat_29021003 = "Eso no es lo que quise decir... ¿No vives en Lumopolis?",
  str_homestory_chat_29021004 = "¿No deberías construir algo allí?",
  str_homestory_chat_29021005 = "Es porque hay algo que no puedo tolerar aquí.",
  str_homestory_chat_29021006 = "¿Qué es eso?",
  str_homestory_chat_29021007 = "El barro causado por la lluvia! Voy a construir un techo sobre el valle.",
  str_homestory_chat_29021008 = "Uno que puede bloquear todo el cielo.",
  str_homestory_chat_29021009 = "¡Eso es enorme!",
  str_homestory_chat_29021010 = "¿Qué pasa entonces con nuestras necesidades de iluminación?",
  str_homestory_chat_29021011 = "No tienes que preocuparte por eso. Escuché que puedes instalar un dispositivo que abre el techo cuando hace sol y lo cierra cuando llueve.",
  str_homestory_chat_29021012 = "Escuché sobre esto de los miembros de Illumina aquí. Aparentemente, eso es lo que hacen en sus Ciudades Subterráneas.",
  str_homestory_chat_29021013 = "Siento que has aprendido algunas cosas extrañas...",
  str_homestory_chat_29021014 = "¡Así que estás de acuerdo entonces! Te dejaré estimar el costo entonces.",
  str_homestory_chat_29021015 = "¡Esperar! ¡Aún no lo he aceptado!",
  str_homestory_chat_29022001 = "¿Vajilla?",
  str_homestory_chat_29022002 = "La vajilla aquí es demasiado tosca. Míralos: hacen que incluso las comidas más deliciosas sean desagradables.",
  str_homestory_chat_29022003 = "¡Eso es un poco exagerado!",
  str_homestory_chat_29022004 = "Yo estoy diciendo la verdad. ¡Compruébalo tú mismo si no me crees! Todo está hecho de madera o arcilla.",
  str_homestory_chat_29022005 = "Ni siquiera hay un cuchillo de mesa de plata para cortar pan.",
  str_homestory_chat_29022006 = "Debes haber estado hambriento estos últimos días...",
  str_homestory_chat_29022007 = "Entonces, ¿puedes traernos un juego de vajilla de plata?",
  str_homestory_chat_29022008 = "Considere comprar un juego de té de porcelana blanca para el té de la tarde si puede.",
  str_homestory_chat_29022009 = "Eso cuesta mucho, ¿verdad? Suena muy caro. ¿Sabes lo que cuesta aproximadamente?",
  str_homestory_chat_29022010 = "¿El precio? No tengo ni idea.",
  str_homestory_chat_29022011 = "No sabes el precio pero quieres que lo compre... ¿Estás pensando en hacerme pagar primero?",
  str_homestory_chat_29022012 = "Eso es un hecho. Puedes pedirle el dinero a mi mayordomo después de comprarlo.",
  str_homestory_chat_29022013 = "¡Esperar! ¡No he dicho que sí!",
  str_homestory_chat_29023001 = "¿Quieres contratar a un sirviente?",
  str_homestory_chat_29023002 = "Sí, voy a ofrecer una gran paga.",
  str_homestory_chat_29023003 = "Lo que quiero saber es por qué de repente quieres contratar a un sirviente.",
  str_homestory_chat_29023004 = "Aquí no tenemos sirvientes.",
  str_homestory_chat_29023005 = "¿Por qué de repente quieres hacer esto?",
  str_homestory_chat_29023006 = "Es para que pueda dejar que mi sirviente se ocupe de todas las cosas misceláneas que surjan.",
  str_homestory_chat_29023007 = "Un noble como yo debe dedicar mi tiempo a asuntos más importantes.",
  str_homestory_chat_29023008 = "Como considerar el desarrollo de Cloud Gardens o explorar una veta de gemas cercana.",
  str_homestory_chat_29023009 = "Creo que deberías experimentar cómo es la vida ordinaria cuando estás aquí...",
  str_homestory_chat_29023010 = "Tal vez... esos tipos cuadrados serían buenos candidatos.",
  str_homestory_chat_29023011 = "Los Chubbs?",
  str_homestory_chat_29023012 = "¡Buena suposición!",
  str_homestory_chat_29023013 = "¡De ninguna manera!",
  str_homestory_chat_29199999 = "¿Estás patrullando Cloud Gardens o simplemente estás dando un paseo?",
  str_homestory_chat_29101001 = "¿Qué estás haciendo?",
  str_homestory_chat_29101002 = "Nada en absoluto, así que simplemente distraído.",
  str_homestory_chat_29101003 = "Esa es realmente una respuesta honesta...",
  str_homestory_chat_29101004 = "No tengo nada que hacer, así que he estado pasando el rato y pensando.",
  str_homestory_chat_29101005 = "Sí, puedes aprovechar esta oportunidad para relajarte un poco.",
  str_homestory_chat_29121001 = "¿Niños?",
  str_homestory_chat_29121002 = "Sí, como no hay niños aquí, es un poco... demasiado tranquilo.",
  str_homestory_chat_29121003 = "Existen.",
  str_homestory_chat_29121004 = "¿Dónde?",
  str_homestory_chat_29121005 = "Esos tipos, por ejemplo, son de Lumopolis, Rediesel Wrench...",
  str_homestory_chat_29121006 = "Deberían venir a quedarse en Cloud Gardens por unos días.",
  str_homestory_chat_29121007 = "¿Te refieres a ellos? Suspiro...",
  str_homestory_chat_29121008 = "¿Por qué estás suspirando?",
  str_homestory_chat_29121009 = "Ya no son niños. Son capaces de ser independientes.",
  str_homestory_chat_29121010 = "Eso es cierto.",
  str_homestory_chat_29121011 = "Realmente no hay ninguno.",
  str_homestory_chat_29121012 = "Suspiro. Tendré que ir a ver a Chubb, entonces.",
  str_homestory_chat_29121013 = "¿Por qué? ¿Que planeas hacer?",
  str_homestory_chat_29121014 = "Relájate, solo voy a observarlos desde lejos y solo ayudaré cuando haya un problema.",
  str_homestory_chat_29121015 = "Como tropezar y caer.",
  str_homestory_chat_29121016 = "¿Por qué eres tan amable?",
  str_homestory_chat_29121017 = "¿A qué estás llegando?",
  str_homestory_chat_29121018 = "¡Nada! ¡Gracias!",
  str_homestory_chat_29122001 = "¿Rompecabezas de palabras?",
  str_homestory_chat_29122002 = "¿Te gustan los crucigramas?",
  str_homestory_chat_29122003 = "Sí.",
  str_homestory_chat_29122004 = "Realmente no.",
  str_homestory_chat_29122005 = "¿Por qué preguntas?",
  str_homestory_chat_29122006 = "Estoy aburrido y no tengo crucigramas que resolver.",
  str_homestory_chat_29122007 = "Pensé que al Chubb con lentes le gustarían, pero todo lo que podía pensar era en contar frijoles.",
  str_homestory_chat_29122008 = "Y el Chubb barbudo se pasa el día dando vueltas como tú...",
  str_homestory_chat_29122009 = "Ejem, estoy revisando todos los Jardines de las Nubes, no holgazaneando.",
  str_homestory_chat_29122010 = "En cuanto a ti, Hati, ¿no encuentras otra forma de relajarte que no sea resolver crucigramas?",
  str_homestory_chat_29122011 = "Eso es porque los crucigramas son liberadores, especialmente cuando resuelves uno muy difícil...",
  str_homestory_chat_29122012 = "¡Simplemente no puedes describir cómo se siente!",
  str_homestory_chat_29122013 = "Creo que deberías concentrarte en relajar tu mente...",
  str_homestory_chat_29123001 = "¿Que estas obteniendo?",
  str_homestory_chat_29123002 = "Aguja e hilos.",
  str_homestory_chat_29123003 = "Debes estar cosiendo algo. ¿Tiene algún agujero o rasgadura en su ropa?",
  str_homestory_chat_29123004 = "Puede que tengas una fuerte capacidad psíquica, pero no eres observador.",
  str_homestory_chat_29123005 = "¿Qué?",
  str_homestory_chat_29123006 = "Tengo que reparar una muñeca dañada.",
  str_homestory_chat_29123007 = "¿Reparaste esas cosas?",
  str_homestory_chat_29123008 = "¿Ocurre algo? Puedo hacerlos también, solo necesito trapos, agujas e hilos.",
  str_homestory_chat_29123009 = "No pareces del tipo...",
  str_homestory_chat_29123010 = "Entonces, para ti, soy alguien que no debería estar en eso, PlayerName?",
  str_homestory_chat_29123011 = "Eso es porque parecías demasiado genial y directo para ese tipo de cosas.",
  str_homestory_chat_29123012 = "Eso es un estereotipo de tu parte.",
  str_homestory_chat_29123013 = "Ser genial y directo no tiene relevancia para la fabricación de muñecas.",
  str_homestory_chat_29123014 = "Cierto.",
  str_homestory_chat_29124001 = "Especias?",
  str_homestory_chat_29124002 = "Quiero algunas especias para sazonar.",
  str_homestory_chat_29124003 = "Me parece que estás cocinando algo delicioso.",
  str_homestory_chat_29124004 = "¡Así es, estoy haciendo un guiso!",
  str_homestory_chat_29124005 = "¡Guiso!",
  str_homestory_chat_29124006 = "Entonces, ¿qué carne trajiste específicamente?",
  str_homestory_chat_29124007 = "¿Carne? No tengo carne.",
  str_homestory_chat_29124008 = "¿Qué?",
  str_homestory_chat_29124009 = "Es demasiado grande para cargar y se pudrirá. ¿Alguien vende carne por aquí?",
  str_homestory_chat_29124010 = "UH no.",
  str_homestory_chat_29124011 = "Entonces tenemos un gran problema, especialmente cuando no veo una presa por ninguna parte.",
  str_homestory_chat_29124012 = "Entonces, ¿la pesca podría ser la única alternativa? ¿Sustituir la carne por pescado?",
  str_homestory_chat_29124013 = "¿No sería eso un plato de pescado en su lugar?",
  str_homestory_chat_29124014 = "El guiso de pescado también está bien. Puede ser delicioso, y no se necesita mucho condimento.",
  str_homestory_chat_29124015 = "Tengo la sensación de que superaste el problema de la carne.",
  str_homestory_chat_29399999 = "¿Ocupado?",
  str_homestory_chat_29321001 = "¿Entrenamiento de arpón?",
  str_homestory_chat_29321002 = "Me gustaría saber si hay un instructor de lanza en Cloud Gardens.",
  str_homestory_chat_29321003 = "Este es un lugar de paz...",
  str_homestory_chat_29321004 = "Es solo para practicar y estar en forma, o la lanza se desafilará.",
  str_homestory_chat_29321005 = "¿Por qué te esfuerzas tanto cuando solo estás aquí por unos días?",
  str_homestory_chat_29321006 = "¡No puedo ser complaciente! ¡Debo mantener la disciplina como un noble de Lumopolis!",
  str_homestory_chat_29321007 = "Está bien, puedes empezar a practicar por ti mismo, supongo...",
  str_homestory_chat_29322001 = "Alguien presentó una queja sobre ti.",
  str_homestory_chat_29322002 = "¿En realidad? ¿Quién es?",
  str_homestory_chat_29322003 = "Tus compañeros de cuarto.",
  str_homestory_chat_29322004 = "¿Encontraron inquietante mi práctica diaria con la lanza?",
  str_homestory_chat_29322005 = "Sí.",
  str_homestory_chat_29322006 = "Hay más, también.",
  str_homestory_chat_29322007 = "¿Encontraron irritante que me levantara demasiado temprano?",
  str_homestory_chat_29322008 = "Eso también...",
  str_homestory_chat_29322009 = "Entonces, ¿estás diciendo que hay más?",
  str_homestory_chat_29322010 = "Sí, sobre todo quejándose de que siempre doblas las mantas en cubos perfectos.",
  str_homestory_chat_29322011 = "¿Debería ser así? ¡Es repugnante dejarlos tirados en las camas!",
  str_homestory_chat_29322012 = "El punto es que no puedes exigir a otros que hagan lo mismo.",
  str_homestory_chat_29322013 = "Pero...",
  str_homestory_chat_29322014 = "De todos modos, no seas tan estricto con los demás.",
  str_homestory_chat_29323001 = "¿Qué te gustaría preguntarle a Chubbs?",
  str_homestory_chat_29323002 = "Quiero saber si podrían ser mis escuderos.",
  str_homestory_chat_29323003 = "No hay precedentes para eso en Cloud Gardens, pero ¿puedes hacerlo en Lumopolis?",
  str_homestory_chat_29323004 = "Soy caballero, por lo tanto tengo derecho a alistar escuderos. ¿Cuento con su aprobación, Maestro de los Jardines de Nubes?",
  str_homestory_chat_29323005 = "Sí.",
  str_homestory_chat_29323006 = "Dejame pensar sobre eso.",
  str_homestory_chat_29323007 = "Espera un minuto, ¿qué te hizo querer que fueran tus escuderos?",
  str_homestory_chat_29323008 = "¡Porque creo que son aptos para el deber!",
  str_homestory_chat_29323009 = "Mandíbula cuadrada, pecho abultado...",
  str_homestory_chat_29323010 = "¡Ciertamente son material de escudero que seguirá las virtudes caballerescas!",
  str_homestory_chat_29323011 = "Creo que lo entendiste todo mal...",
  str_homestory_chat_29323012 = "¡De ninguna manera! ¡Tienen el aspecto para ello y sé que pueden hacerlo!",
  str_homestory_chat_29323013 = "Bueno, entonces tienes que perdonar mi rechazo porque no funcionará.",
  str_homestory_chat_29324001 = "¿Ópera?",
  str_homestory_chat_29324002 = "¿Qué impresión tienes de la ópera?",
  str_homestory_chat_29324003 = "Uno bastante bueno.",
  str_homestory_chat_29324004 = "¡Entonces no es un problema!",
  str_homestory_chat_29324005 = "No puedo decir que me importaba lo suficiente...",
  str_homestory_chat_29324006 = "Suspiro. Veo que va a ser un problema.",
  str_homestory_chat_29324007 = "¿Qué estás haciendo?",
  str_homestory_chat_29324008 = "Me gustaría construir un escenario en Cloud Gardens para poder invitar a las compañías a actuar.",
  str_homestory_chat_29324009 = "Si hay espacio, sería bueno convertirlo en un teatro de ópera en toda regla, además de una compañía residente o dos.",
  str_homestory_chat_29324010 = "Entonces podemos ver la ópera más nueva en cualquier momento.",
  str_homestory_chat_29324011 = "Uh, no creo que eso sea posible...",
  str_homestory_chat_29999999 = "Hola, como has estado recientemente??",
  str_homestory_chat_29901001 = "¿Muy bien y tu?",
  str_homestory_chat_29901002 = "Me he adaptado a la vida en Cloud Gardens, pero siento que el ritmo aquí es un poco lento.",
  str_homestory_chat_29901003 = "¿Lento?",
  str_homestory_chat_29901004 = "¿No sería genial si hubiera algunos desafíos aquí de vez en cuando, como una competencia de talar árboles?",
  str_homestory_chat_29901005 = "Vamos a sentarnos y relajarnos.",
  str_homestory_chat_29921001 = "¿Bebida?",
  str_homestory_chat_29921002 = "¿Qué le gustaría?",
  str_homestory_chat_29921003 = "Café",
  str_homestory_chat_29921004 = "Una opción muy popular. ¿Sería correcto decir que los demás tienen una influencia sobre ti?",
  str_homestory_chat_29921005 = "Sí, y a menudo encuentro bastante divertido preparar café para uno mismo y cosas así...",
  str_homestory_chat_29921006 = "Si vas a un café, también puedes chatear con tus amigos mientras tomas un café.",
  str_homestory_chat_29921007 = "Eso tiene sentido.",
  str_homestory_chat_29921008 = "Té",
  str_homestory_chat_29921009 = "¿Qué te gusta del té? Escuché que algunos tés son muy amargos.",
  str_homestory_chat_29921010 = "Si le agregas un poco de algo, puede saber muy bien. Además, si solo le agregas hojas de té...",
  str_homestory_chat_29921011 = "El primer sabor puede ser amargo, pero después sentirás un dulzor inexplicable en la garganta.",
  str_homestory_chat_29921012 = "Escuché que también puede refrescar la mente.",
  str_homestory_chat_29921013 = "Así es. Sugiero darle una oportunidad la próxima vez.",
  str_homestory_chat_29921014 = "Jugo",
  str_homestory_chat_29921015 = "Entonces, prefieres los sabores naturales... Bueno, eso tiene sentido: eres un Caelestite.",
  str_homestory_chat_29921016 = "Un poco de jugo mixto también puede ser bastante bueno... Creo que simplemente me gusta la sensación refrescante.",
  str_homestory_chat_29921017 = "Y también puede ayudar a complementar varios nutrientes, lo que lo hace beneficioso para su cuerpo. Lo consideraré la próxima vez.",
  str_homestory_chat_29921018 = "¡Bien! ¡Genial!",
  str_homestory_chat_29921019 = "Agua con gas",
  str_homestory_chat_29921020 = "¿Realmente disfrutas eructar después de cada sorbo? ¡Increíble!",
  str_homestory_chat_29921021 = "¿No crees que estás exagerando...?",
  str_homestory_chat_29922001 = "¿Quieres cultivar algo aquí?",
  str_homestory_chat_29922002 = "Quiero empezar a trabajar en un terreno aquí en Cloud Gardens y cultivar algunos frijoles.",
  str_homestory_chat_29922003 = "Seguro",
  str_homestory_chat_29922004 = "Todavía debería haber mucho espacio abierto aquí... pero primero, tenemos que preguntarle a los Chubbs.",
  str_homestory_chat_29922005 = "No",
  str_homestory_chat_29922006 = "Espera, ¿por qué frijoles?",
  str_homestory_chat_29922007 = "Según la investigación de Illumina, estos frijoles son los cultivos más adecuados para el cultivo a gran escala y cuentan con una nutrición relativamente alta.",
  str_homestory_chat_29922008 = "¿Qué pasa con el sabor?",
  str_homestory_chat_29922009 = "¡Hay innumerables sabores y miles de formas de preparar frijoles!",
  str_homestory_chat_29922010 = "Recuerdo que había muchos tipos en Umbraton... Creo que había uno llamado tofu.",
  str_homestory_chat_29922011 = "¡Conozco el tofu! Escuché que es del Lejano Oriente: ¡un alimento milagroso que transforma los frijoles en magia!",
  str_homestory_chat_29922012 = "Se deshace en la boca, y sin ningún condimento, aún posee un sabor natural a frijol...",
  str_homestory_chat_29922013 = "¡Y es versátil! Ya sea dulce, salado, agrio o picante, ¡el tofu se puede combinar con cualquier condimento!",
  str_homestory_chat_29922014 = "Eso es realmente impresionante...",
  str_homestory_chat_29923001 = "¿Quieres ir a Umbraton?",
  str_homestory_chat_29923002 = "Después de estar en Cloud Gardens durante tanto tiempo, me he dado cuenta de que no hay mucha comunicación entre aquí y Umbraton.",
  str_homestory_chat_29923003 = "Sí, Cloud Gardens es un lugar relativamente apartado.",
  str_homestory_chat_29923004 = "Pero esta es una característica bastante única: este aislamiento permite una tranquilidad sin interrupciones.",
  str_homestory_chat_29923005 = "Y no es demasiado problema llegar a Umbraton desde aquí...",
  str_homestory_chat_29923006 = "Me gustaría poder comprar un poco de leche de Umbraton con regularidad.",
  str_homestory_chat_29923007 = "¿Leche?",
  str_homestory_chat_29923008 = "Illumina proporciona raciones de leche, pero no hay nada como esto en Cloud Gardens, y tampoco parece haber una tienda donde pueda comprar algo.",
  str_homestory_chat_29923009 = "Bien. Si quieres beber leche, solo puedes obtenerla del exterior.",
  str_homestory_chat_29923010 = "Si realmente quieres un poco, recuérdamelo la próxima vez que vaya a Umbraton y recogeré algunas cajas para ti.",
  str_homestory_chat_29923011 = "Pero Umbraton no está exactamente cerca, así que me temo que no podré probar la leche fresca que ofrecen...",
  str_homestory_chat_29923012 = "En ese caso... ¿qué tal el yogur?",
  str_homestory_chat_29923013 = "¡Claro, el yogur es bueno!",
  str_homestory_chat_29923014 = "Alegra oírlo.",
  str_homestory_chat_29924001 = "¿Una pajarera?",
  str_homestory_chat_29924002 = "Derecha, para colgar en la ventana o en el techo.",
  str_homestory_chat_29924003 = "Quiero decir... ¿por qué quieres una pajarera?",
  str_homestory_chat_29924004 = "Para Aoha. No puedo dejarlo posarse en la punta de mis dedos todo el tiempo.",
  str_homestory_chat_29924005 = "Especialmente cuando estoy durmiendo... Siento que no tiene adónde ir.",
  str_homestory_chat_29924006 = "Suena menos que ideal.",
  str_homestory_chat_29924007 = "Entonces, me gustaría darle una casita. No hace falta que sea grande.",
  str_homestory_chat_29924008 = "He visto algunas pajareras pequeñas en Umbraton. Parecían bastante simples, pero la madera...",
  str_homestory_chat_29924009 = "Ya le pedí a los Chubbs que compraran algunos.",
  str_homestory_chat_29924010 = "Por supuesto que sí, Yingel. Eres tan eficiente.",
  str_homestory_chat_29924011 = "Estás de acuerdo conmigo, ¿sí?",
  str_homestory_chat_29924012 = "No veo ninguna razón por la que no... Mientras no ocupes el espacio de nadie más.",
  str_homestory_chat_29924013 = "Ahora tenemos que encontrar un carpintero...",
  str_homestory_chat_29924014 = "Eso parece que todavía tenemos un camino por recorrer antes de que esté terminado.",
  str_homestory_chat_29299999 = "Es un placer verte.",
  str_homestory_chat_29201001 = "¿Cómo va todo?",
  str_homestory_chat_29201002 = "Paz, prosperidad: Cloud Gardens es verdaderamente un paraíso. Es un honor poder tomar un descanso aquí.",
  str_homestory_chat_29201003 = "Disfrútalo y relájate al contenido de tu corazón.",
  str_homestory_chat_29201004 = "Es por eso que a menudo pienso para mí mismo que también debería redoblar mis esfuerzos para proteger este paraíso.",
  str_homestory_chat_29201005 = "Y en particular, no debemos permitir que algún lodo en descomposición contamine este lugar, provocando así la invasión de entidades malvadas.",
  str_homestory_chat_29201006 = "Gracias por su arduo trabajo.",
  str_homestory_chat_29221001 = "¿Qué fruta te gusta?",
  str_homestory_chat_29221002 = "¿Por qué me preguntas eso de repente?",
  str_homestory_chat_29221003 = "Simplemente apareció en mi cabeza.",
  str_homestory_chat_29221004 = "Me gustan las frutas del sur, principalmente porque son jugosas, nutritivas y tienen una gran variedad de sabores.",
  str_homestory_chat_29221005 = "¿Y tú?",
  str_homestory_chat_29221006 = "manzanas",
  str_homestory_chat_29221007 = "Es un tipo de fruta muy común. ¿Qué te gusta de ellos?",
  str_homestory_chat_29221008 = "Tal vez sea porque son muy comunes. Además, las manzanas son bastante dulces y tienen una textura crujiente.",
  str_homestory_chat_29221009 = "Así es. Debido a que son tan comunes, hay muchas maneras de prepararlos.",
  str_homestory_chat_29221010 = "Escuché que también se pueden sazonar. Con esto en mente, de hecho pueden considerarse una fruta que realmente beneficia al público.",
  str_homestory_chat_29221011 = "Cierto.",
  str_homestory_chat_29221012 = "Uvas",
  str_homestory_chat_29221013 = "Las uvas son muy comunes y se han convertido en una fuente popular de muchas bebidas.",
  str_homestory_chat_29221014 = "¿Cómo qué?",
  str_homestory_chat_29221015 = "La gente bebía vino durante las comidas en Lumopolis, y algunos refrescos en Illumina también agregaban jugo de uva.",
  str_homestory_chat_29221016 = "También escuché que algunas personas comen uvas secas como bocadillos en el desierto de Rediesel.",
  str_homestory_chat_29221017 = "Ya no estamos hablando de bebidas, ¿verdad?",
  str_homestory_chat_29221018 = "Cierto, pero esas pasas en realidad se pueden usar como ingrediente en pan dulce.",
  str_homestory_chat_29221019 = "Eso es realmente asombroso.",
  str_homestory_chat_29222001 = "¿Que comida te gusta?",
  str_homestory_chat_29222002 = "Me gusta la comida caliente, especialmente la carne cocinada de forma sencilla y sin técnicas complicadas.",
  str_homestory_chat_29222003 = "¿Qué quieres decir?",
  str_homestory_chat_29222004 = "En pocas palabras, me gusta la carne hervida, combinada con mis condimentos favoritos.",
  str_homestory_chat_29222005 = "Suena muy conveniente.",
  str_homestory_chat_29222006 = "Sí, para los soldados, este tipo de comida es conveniente y deliciosa, y puede reponer rápidamente la fuerza física.",
  str_homestory_chat_29222007 = "Por lo tanto, es importante prestar siempre atención a los suministros de carne para garantizar que siempre haya comida caliente disponible en el campo de batalla.",
  str_homestory_chat_29222008 = "También puede ser un asunto complicado...",
  str_homestory_chat_29222009 = "¿Complicado?",
  str_homestory_chat_29222010 = "Hay muchas cosas a considerar, la primera es qué combustible usar para cocinar los alimentos.",
  str_homestory_chat_29222011 = "Luego, las consideraciones van desde conservar la carne hasta satisfacer las preferencias gustativas de cada soldado.",
  str_homestory_chat_29222012 = "Estas son todas las cosas que los líderes deben considerar, y un solo error cometido en cualquiera de estos aspectos puede conducir a una baja moral.",
  str_homestory_chat_29222013 = "Guau... No tenía idea de lo minucioso que eras.",
  str_homestory_chat_29223001 = "Dibujar un mapa?",
  str_homestory_chat_29223002 = "Sí. ¿Eres versado en el arte de la cartografía?",
  str_homestory_chat_29223003 = "Yo sé un poco.",
  str_homestory_chat_29223004 = "Excelente. Entonces realmente me vendría bien tu ayuda.",
  str_homestory_chat_29223005 = "Realmente no.",
  str_homestory_chat_29223006 = "¿Para qué quieres un mapa?",
  str_homestory_chat_29223007 = "Llevo muchos días aquí, pero todavía siento cierta inquietud en mi corazón.",
  str_homestory_chat_29223008 = "Porque te sientes asi?",
  str_homestory_chat_29223009 = "Después de mucha contemplación, solo puedo asumir que se debe a mi falta de familiaridad con Cloud Gardens.",
  str_homestory_chat_29223010 = "Permítanme decirlo así: no estoy muy familiarizado con este lugar, y siempre me siento algo inseguro cuando estoy en lugares desconocidos.",
  str_homestory_chat_29223011 = "No tienes que preocuparte de que vengan forasteros aquí. Puedes relajarte.",
  str_homestory_chat_29223012 = "Sea como fuere... Sigo sintiendo que tendré que dominar el terreno topografiándolo y cartografiándolo para sentirme cómodo.",
  str_homestory_chat_29223013 = "Correcto... Sigue así entonces.",
  str_homestory_chat_29224001 = "¿Buscando comprar algunas armas?",
  str_homestory_chat_29224002 = "Oh, parece que me entendiste mal. Quería preguntarle si consideraría construir un museo.",
  str_homestory_chat_29224003 = "¿Un museo?",
  str_homestory_chat_29224004 = "Uno que celebra las armas del mundo, como la alabarda larga de Lumopolis y el sable de mando de Illumina...",
  str_homestory_chat_29224005 = "¿Realmente necesitas construir un museo para eso? Parece que ni siquiera hay tantos tipos de armas disponibles. ¿No podemos simplemente designar una sala de recolección?",
  str_homestory_chat_29224006 = "Eso no es todo! ¡Incluso en algún lugar como Illumina, con su tradición de armas producidas en masa, tiene una gran cantidad de modelos y variedades!",
  str_homestory_chat_29224007 = "Hay docenas de lanzas, pistolas, cuchillos y dagas militares, así como todas las armas cuerpo a cuerpo, armas de largo alcance, armas frías y armas calientes...",
  str_homestory_chat_29224008 = "Además, las armas utilizadas por los nobles de Lumopolis también vienen en diferentes estilos y llevan insignias únicas.",
  str_homestory_chat_29224009 = "Podría continuar con los detalles para siempre. De todos modos, es por eso que una sola sala de recolección no será suficiente.",
  str_homestory_chat_29224010 = "Entonces, realmente hay tantos tipos... ¡Espera! ¿Tienes todas estas armas?",
  str_homestory_chat_29224011 = "Solo una pequeña porción, pero eso no me impedirá comenzar una colección a partir de este momento.",
  str_homestory_chat_29224012 = "Entonces, no tienes tantos en este momento... Eso me hace sentir un poco mejor.",
  str_homestory_chat_29224013 = "Teniendo en cuenta lo seguro que es este lugar, debería poder mantener mi colección segura aquí. Por eso quiero construir un museo dedicado a las armas.",
  str_homestory_chat_29224014 = "Déjame pensar en ello.",
  str_homestory_chat_30099999 = "¿Alguna novedad hoy?",
  str_homestory_chat_30021001 = "Oye, ¿tienes algún pasatiempo?",
  str_homestory_chat_30021002 = "Aficiones... ¿Por qué lo preguntas? PlayerName?",
  str_homestory_chat_30021003 = "Sólo quiero saber, es todo.",
  str_homestory_chat_30021004 = "Tal vez la observación es mi única afición real... ¿Y tú?",
  str_homestory_chat_30021005 = "Realmente no tengo ningún pasatiempo.",
  str_homestory_chat_30021006 = "En realidad, no estoy muy seguro.",
  str_homestory_chat_30021007 = "Tal vez sea... ¿caminar?",
  str_homestory_chat_30021008 = "Espera, ¿no fui yo quien te preguntó?",
  str_homestory_chat_30021009 = "Y esa es mi respuesta.",
  str_homestory_chat_30021010 = "Entonces... ¿tu hobby es recopilar información...?",
  str_homestory_chat_30022001 = "Parece que te gusta tomar notas.",
  str_homestory_chat_30022002 = "Así es. Como dice el refrán, \"un historial pobre es mejor que una mente brillante\".",
  str_homestory_chat_30022003 = "Siempre te veo escribiendo y dibujando. Parece agotador.",
  str_homestory_chat_30022004 = "Estoy acostumbrado, y tengo mi arma secreta.",
  str_homestory_chat_30022005 = "¿Arma secreta?",
  str_homestory_chat_30022006 = "Se llama taquigrafía.",
  str_homestory_chat_30022007 = "Suena poderoso... como una especie de técnica secreta que no se puede transmitir.",
  str_homestory_chat_30022008 = "Necesitas memorizar un montón de abreviaturas, mnemónicos, símbolos, etc., ¿verdad?",
  str_homestory_chat_30022009 = "Eh, no realmente. De hecho, el método taquigráfico se desarrolla principalmente en función de los hábitos de escritura de cada individuo.",
  str_homestory_chat_30022010 = "¿Ah?",
  str_homestory_chat_30022011 = "En muchos casos, las abreviaturas correspondientes solo deben ser entendidas por usted mismo, porque al final escribirá una correcta.",
  str_homestory_chat_30022012 = "Comprendo.",
  str_homestory_chat_30023001 = "Escuché que quieres comprar algo.",
  str_homestory_chat_30023002 = "Quiero comprar un telescopio para observación.",
  str_homestory_chat_30023003 = "¿Te gusta observar animales o plantas?",
  str_homestory_chat_30023004 = "Ah... Eso es parte de eso.",
  str_homestory_chat_30023005 = "¿Una parte de eso?",
  str_homestory_chat_30023006 = "La inteligencia recopilada sobre animales y plantas solo puede considerarse auxiliar hasta cierto punto...",
  str_homestory_chat_30023007 = "Principalmente observo la actividad diaria en Cloud Gardens, como la vida de los Chubbs...",
  str_homestory_chat_30023008 = "Ellos de nuevo...",
  str_homestory_chat_30023009 = "¿Otra vez?",
  str_homestory_chat_30023010 = "Parece que mucha gente está interesada en ellos en estos días.",
  str_homestory_chat_30023011 = "Porque, a diferencia de nosotros, son nativos de este lugar.",
  str_homestory_chat_30023012 = "Cuanto más aprendo, más puedo saber sobre Cloud Gardens, lo que, naturalmente, será de utilidad para usted.",
  str_homestory_chat_30023013 = "Creo... que es mejor pasar el tiempo relajándose tanto como puedas.",
  str_homestory_chat_30024001 = "¿Criar peces?",
  str_homestory_chat_30024002 = "Este lugar parece que sería muy adecuado para la piscicultura. ¿Tienes un estanque de peces?",
  str_homestory_chat_30024003 = "Tenemos uno aquí.",
  str_homestory_chat_30024004 = "No en este momento...",
  str_homestory_chat_30024005 = "Entonces, ¿quieres criar algunos peces?",
  str_homestory_chat_30024006 = "Sí. Cuando vi el estanque en la plaza, de repente pensé que criar peces en Cloud Gardens podría ser bueno.",
  str_homestory_chat_30024007 = "Sin embargo, el pez que me gusta es bastante extraño y deseo criarlo por separado.",
  str_homestory_chat_30024008 = "¿Estás hablando de Burbuja? Parece un poco peligroso.",
  str_homestory_chat_30024009 = "No te preocupes por eso, es solo una criatura ordinaria. Mi principal preocupación es que no es adecuado para criarlo en grupo, por lo que deseo criarlo por separado.",
  str_homestory_chat_30024010 = "Entendido... Lo investigaré.",
  str_homestory_chat_30299999 = "¿Estás inspeccionando tu territorio de nuevo?",
  str_homestory_chat_30221001 = "Solo voy a dar un paseo.",
  str_homestory_chat_30221002 = "¿Alguna vez has pensado en los problemas de seguridad aquí?",
  str_homestory_chat_30221003 = "Sí.",
  str_homestory_chat_30221004 = "¡Eso es lo que debe hacer un propietario! ¿Cuál es tu conclusión?",
  str_homestory_chat_30221005 = "Revisé, y dado el terreno de los Jardines, está bien como está.",
  str_homestory_chat_30221006 = "¿Mantenerlo igual...? Siento que es bastante laxo. Debe reforzar las medidas de seguridad.",
  str_homestory_chat_30221007 = "Lo tendré en cuenta.",
  str_homestory_chat_30221008 = "Nop.",
  str_homestory_chat_30221009 = "¡Esto es demasiado complaciente!",
  str_homestory_chat_30221010 = "Bueno, este es un lugar muy difícil de encontrar, y todos vinieron aquí para relajarse.",
  str_homestory_chat_30221011 = "No es necesario preocuparse por cuestiones de seguridad.",
  str_homestory_chat_30221012 = "¿Estás seguro?",
  str_homestory_chat_30221013 = "¡Sí, no es un problema!",
  str_homestory_chat_30221014 = "¿Y tú, lo has pensado?",
  str_homestory_chat_30221015 = "Hice varias rondas en los últimos días y es seguro según los estándares normales.",
  str_homestory_chat_30221016 = "Me alivia oírte decir eso.",
  str_homestory_chat_30221017 = "Pero aún así, no bajes la guardia ya que uno nunca puede ser demasiado cuidadoso...",
  str_homestory_chat_30221018 = "A-Muy bien.",
  str_homestory_chat_30221019 = "No hay necesidad de eso.",
  str_homestory_chat_30221020 = "¿Cómo puedes ser tan complaciente? ¿Alguna vez lo has pensado seriamente?",
  str_homestory_chat_30221021 = "Bueno, lo examinaré en detalle.",
  str_homestory_chat_30222001 = "Estoy pensando en Eraveil.",
  str_homestory_chat_30222002 = "¡Parece que finalmente estás contemplando cómo gobernar esta tierra!",
  str_homestory_chat_30222003 = "Sí.",
  str_homestory_chat_30222004 = "Aunque no he avanzado mucho.",
  str_homestory_chat_30222005 = "Todavía no.",
  str_homestory_chat_30222006 = "¿Tienes alguna idea o sugerencia?",
  str_homestory_chat_30222007 = "Lo mejor es asignar a los lugareños para supervisar.",
  str_homestory_chat_30222008 = "Por lugareños, te refieres a...",
  str_homestory_chat_30222009 = "Los Chubbs, por supuesto.",
  str_homestory_chat_30222010 = "Eso tiene sentido.",
  str_homestory_chat_30223001 = "En realidad...",
  str_homestory_chat_30223002 = "Hoy es un buen día, así que decidí dar un paseo.",
  str_homestory_chat_30223003 = "Veo que te gusta salir a caminar cuando hace buen tiempo. Sí despeja la mente.",
  str_homestory_chat_30223004 = "Un paseo tranquilo en un entorno tranquilo en un día soleado es propicio para pensar.",
  str_homestory_chat_30223005 = "O ni siquiera tienes que pensar y simplemente relajarte, tómatelo con calma.",
  str_homestory_chat_30223006 = "Después de todo, el punto es disfrutar del ambiente relajante aquí.",
  str_homestory_chat_30223007 = "El ambiente es realmente relajante, pero no estoy acostumbrado a esto.",
  str_homestory_chat_30223008 = "¿Porqué crees?",
  str_homestory_chat_30223009 = "En Lumopolis, a pesar de que está brillante y soleado, siento que mis hombros están pesados.",
  str_homestory_chat_30223010 = "Y se llama responsabilidad, que también me hace rumiar sin parar.",
  str_homestory_chat_30223011 = "Eso tiene que ser una carga pesada. Deberías tomártelo con calma ahora que estás aquí.",
  str_homestory_chat_30223012 = "No, es una armadura que puede protegerme y pulirme para enfrentar los desafíos.",
  str_homestory_chat_30223013 = "Uh, tal vez no deberías ser tan tenso...",
  str_homestory_chat_30224001 = "Estoy pensando en el libro que leí hace unos días.",
  str_homestory_chat_30224002 = "¿Qué es?",
  str_homestory_chat_30224003 = "Novela de misterio",
  str_homestory_chat_30224004 = "Es muy popular en Umbraton últimamente y los aspectos románticos fueron particularmente interesantes...",
  str_homestory_chat_30224005 = "¿Una novela, dijiste? Las ficciones son buenas sólo para relajarse. Contenían un conocimiento muy limitado para que usted lo adquiera.",
  str_homestory_chat_30224006 = "Si realmente quieres leer, deberías optar por los libros de historia.",
  str_homestory_chat_30224007 = "Libro de historia",
  str_homestory_chat_30224008 = "Gran elección.",
  str_homestory_chat_30224009 = "¿También te gusta leer libros de historia?",
  str_homestory_chat_30224010 = "Es correcto.",
  str_homestory_chat_30224011 = "Se basa en hechos para que puedas revisar el pasado e incluso predecir el futuro.",
  str_homestory_chat_30224012 = "Si bien el pronóstico es algo hipérbole, al menos puede obtener mucho conocimiento.",
  str_homestory_chat_30224013 = "Es mucho más gratificante intelectualmente que los cuentos inventados.",
  str_homestory_chat_30224014 = "Claro, leeré más.",
  str_homestory_chat_30225001 = "Sí.",
  str_homestory_chat_30225002 = "\"Nunca dejes de sembrar, sea de día o de noche\".",
  str_homestory_chat_30225003 = "¿Qué es eso?",
  str_homestory_chat_30225004 = "Es un proverbio de Lumopolis, lo que significa que uno debe trabajar duro todo el tiempo. Lo hiciste, y espero que puedas mantener la actitud.",
  str_homestory_chat_30225005 = "Lo haré.",
  str_homestory_chat_30225006 = "En ese caso, puedo considerar otorgarle un título. Sería una fortuna para Lumopolis tener más nobles como tú.",
  str_homestory_chat_30225007 = "¿En serio?",
  str_homestory_chat_30225008 = "Es una broma, obviamente.",
  str_homestory_chat_30225009 = "Oh, no importa, entonces.",
  str_homestory_chat_30199999 = "¿También estás solo?",
  str_homestory_chat_30121001 = "Si",
  str_homestory_chat_30121002 = "Veo que a ti también te gusta estar solo...",
  str_homestory_chat_30121003 = "En realidad, solo estoy dando un paseo porque es un buen día y no tengo nada mejor que hacer.",
  str_homestory_chat_30121004 = "¿Así que pasas tu tiempo libre dando un paseo? Parece que te gusta mucho.",
  str_homestory_chat_30121005 = "¿O tienes otro pasatiempo en solitario?",
  str_homestory_chat_30121006 = "Bueno, un paseo es solo una de las opciones. También me gusta salir con amigos a veces.",
  str_homestory_chat_30121007 = "Y-ya veo ...",
  str_homestory_chat_30122001 = "No",
  str_homestory_chat_30122002 = "Entonces, ¿dónde están tus amigos?",
  str_homestory_chat_30122003 = "Q-Lo que quise decir es que estaba buscando pasar el rato con alguien y me encontré contigo.",
  str_homestory_chat_30122004 = "Supongo que te gusta pasar el rato y charlar.",
  str_homestory_chat_30122005 = "Sí, en realidad.",
  str_homestory_chat_30122006 = "A veces tengo ganas de charlar... ¿Tú también lo entiendes?",
  str_homestory_chat_30122007 = "Me siento de esa manera.",
  str_homestory_chat_30122008 = "Ah, pensé que te gustaba estar solo.",
  str_homestory_chat_30122009 = "Eso es cierto, pero como tú, quiero hablar con otros de vez en cuando.",
  str_homestory_chat_30122010 = "A veces, supongo.",
  str_homestory_chat_30122011 = "¿Oh? Pensé que te encantaba chatear.",
  str_homestory_chat_30122012 = "No precisamente. A veces prefiero estar solo, otras veces quiero charlar.",
  str_homestory_chat_30122013 = "Todo depende de mi estado de ánimo en ese momento. ¿Qué pasa contigo?",
  str_homestory_chat_30122014 = "Preferiría la soledad la mayor parte del tiempo, pero me gustaría hablar de vez en cuando, como tú.",
  str_homestory_chat_30122015 = "Particularmente a ella... Siempre creí que tenía mucho que decirle si alguna vez la conocía.",
  str_homestory_chat_30122016 = "Espero que lo hagas.",
  str_homestory_chat_30123001 = "¿Qué estás haciendo?",
  str_homestory_chat_30123002 = "Pensando en cómo voy a hacer té negro de caballero aquí.",
  str_homestory_chat_30123003 = "¿Té negro de caballero?",
  str_homestory_chat_30123004 = "Es una bebida en Lumopolis, muy popular.",
  str_homestory_chat_30123005 = "Escuché sobre eso, aunque el ingrediente es difícil de manejar.",
  str_homestory_chat_30123006 = "Así es. Necesitarás té importado...",
  str_homestory_chat_30123007 = "Además de teteras de primera calidad, finas técnicas y ajustes de sabor.",
  str_homestory_chat_30123008 = "Hacer una buena taza de té negro de Knight puede llevar toda una tarde.",
  str_homestory_chat_30123009 = "¡Eso es un largo tiempo!",
  str_homestory_chat_30123010 = "Sí, es el té de la tarde, después de todo.",
  str_homestory_chat_30123011 = "Si lo haces por la mañana, podrías estar bebiéndolo al mediodía, ¿verdad?",
  str_homestory_chat_30123012 = "¿Pero eso sería el té del mediodía, entonces? ¿O el té de la mañana, incluso antes?",
  str_homestory_chat_30123013 = "Ese pensamiento nunca pasó por mi mente...",
  str_homestory_chat_30124001 = "¿Qué juegos te gusta jugar?",
  str_homestory_chat_30124002 = "El tipo solitario...",
  str_homestory_chat_30124003 = "¿Juegos en solitario? ¿Ajedrez contigo mismo? ¿O simplemente dando un paseo?",
  str_homestory_chat_30124004 = "A veces yo mismo jugaba al póquer. ¿Qué haces cuando estás solo?",
  str_homestory_chat_30124005 = "Pescar.",
  str_homestory_chat_30124006 = "Esa es una buena actividad. Escuché que es muy relajante.",
  str_homestory_chat_30124007 = "¿Escuchó? ¿Nunca has pescado antes?",
  str_homestory_chat_30124008 = "No tuve muchas oportunidades de intentarlo, ni muchas oportunidades de salir.",
  str_homestory_chat_30124009 = "Deberías disfrutar eso aquí, entonces.",
  str_homestory_chat_30124010 = "¿Jugando a las cartas?",
  str_homestory_chat_30124011 = "Hablando de jugar a las cartas, dime cómo jugar al póquer solo.",
  str_homestory_chat_30124012 = "Las reglas son... bastante complicadas. Te mostraré cuando tengamos la oportunidad.",
  str_homestory_chat_30124013 = "Está bien.",
  str_homestory_chat_30125001 = "¿Cómo te sientes?",
  str_homestory_chat_30125002 = "Me siento muy bien aquí, especialmente cuando puedo salir durante el día.",
  str_homestory_chat_30125003 = "¿Salir durante el día?",
  str_homestory_chat_30125004 = "Sí, por mi estado...",
  str_homestory_chat_30125005 = "Te tengo.",
  str_homestory_chat_30125006 = "Pero sigue siendo diferente de los gustos de Umbraton, ¿verdad?",
  str_homestory_chat_30125007 = "Sí... No hay muchas calles y no hay tiendas.",
  str_homestory_chat_30125008 = "¿Es aburrido para ti?",
  str_homestory_chat_30125009 = "No, en absoluto.",
  str_homestory_chat_30125010 = "Es un poco soso, pero el paisaje natural es muy agradable.",
  str_homestory_chat_30125011 = "Escuchar el canto de los pájaros, contemplar los relucientes arroyos bajo el sol...",
  str_homestory_chat_30125012 = "Eso sonó un poco forzado... Haré que los Chubb pidan más merchandising la próxima vez.",
  str_homestory_chat_30125013 = "La Fuente de la Esperanza, la Torre Jacinto y el Museo también son muy divertidos de visitar...",
  str_homestory_chat_30125014 = "Ok, lo tengo...",
  str_homestory_chat_30399999 = "¿Quieres una adivinación?",
  str_homestory_chat_30321001 = "Me gustaría saber...",
  str_homestory_chat_30321002 = "¡Muy bien, trabajo, por fin! ¿Sobre qué quieres una lectura?",
  str_homestory_chat_30321003 = "Carrera",
  str_homestory_chat_30321004 = "Dinero",
  str_homestory_chat_30321005 = "Romance",
  str_homestory_chat_30321006 = "¿Decidido? ¡Vamos a empezar!",
  str_homestory_chat_30321007 = "Espera, eso no es lo que quiero...",
  str_homestory_chat_30321008 = "¿Entonces que es eso? Estoy listo para ir.",
  str_homestory_chat_30321009 = "Solo quiero saber si la adivinación realmente funcionaría.",
  str_homestory_chat_30321010 = "¿A qué estás llegando? ¡He estado practicando desde que era muy pequeño!",
  str_homestory_chat_30321011 = "S-Así que deberías poder predecir el futuro, ¿verdad? Podrías hacer adivinación para todo.",
  str_homestory_chat_30321012 = "No precisamente. Primero, el escenario y el momento deben ser los correctos, luego necesitas inspiración...",
  str_homestory_chat_30321013 = "¡Y la suerte es el factor más importante, ya que no pude obtener un resultado varias veces!",
  str_homestory_chat_30321014 = "En otras palabras, ¡la adivinación podría fallar!",
  str_homestory_chat_30321015 = "Comprendo.",
  str_homestory_chat_30323001 = "No necesito uno ahora, entonces...",
  str_homestory_chat_30323002 = "Pero estaba inspirado y lo arruinaste.",
  str_homestory_chat_30323003 = "Oh, lo siento.",
  str_homestory_chat_30323004 = "Tengo que averiguar el diseño del nuevo conjunto familiar.",
  str_homestory_chat_30323005 = "¿Traje familiar?",
  str_homestory_chat_30323006 = "Es para susurro. Tenemos que estar en trajes a juego.",
  str_homestory_chat_30323007 = "¿También necesita ropa?",
  str_homestory_chat_30323008 = "Sí. Whisper puede enfermarse cuando hace frío.",
  str_homestory_chat_30323009 = "Usar algo puede mantenerlo abrigado, ¡sin mencionar la moda a juego!",
  str_homestory_chat_30323010 = "¡Impresionante! Pero para el atuendo de Whisper...",
  str_homestory_chat_30323011 = "¡Eso depende de mí diseñar y coser!",
  str_homestory_chat_30322001 = "¿Escuché que te gustan las historias?",
  str_homestory_chat_30322002 = "¡Sí, especialmente durante la adivinación!",
  str_homestory_chat_30322003 = "¿Necesitas eso para tu adivinación?",
  str_homestory_chat_30322004 = "Necesito obtener toda la atención del cliente para que pueda escuchar cada palabra que digo.",
  str_homestory_chat_30322005 = "¡Incluso si la adivinación falla, el cliente no sentirá que es una pérdida total de dinero!",
  str_homestory_chat_30322006 = "¿No es eso casi como una... estafa?",
  str_homestory_chat_30322007 = "¡Absolutamente no! ¡Las historias emocionantes valen la pena!",
  str_homestory_chat_30322008 = "Por eso hablo con Louise mucho, incluso la llevo a muchos lugares para eso!",
  str_homestory_chat_30322009 = "Louise?",
  str_homestory_chat_30322010 = "Sí, ella también es de Northland y una gran narradora.",
  str_homestory_chat_30322011 = "Creo que ustedes dos pueden estar calificados para escribir novelas en Umbraton ahora...",
  str_homestory_chat_30324001 = "¿Estás tratando de encontrar rocas?",
  str_homestory_chat_30324002 = "Sí. ¿Sabes dónde están las rocas bonitas?",
  str_homestory_chat_30324003 = "Por el rio.",
  str_homestory_chat_30324004 = "En el bosque.",
  str_homestory_chat_30324005 = "¡Gracias!",
  str_homestory_chat_30324006 = "¿Son las rocas para tu adivinación?",
  str_homestory_chat_30324007 = "No, no, solo para complementos de moda.",
  str_homestory_chat_30324008 = "Los Chubb se veían tan monótonos caminando de blanco todos los días.",
  str_homestory_chat_30324009 = "Entiendo que es simple, pero ¿no se verían mejor con collares hechos de rocas de colores?",
  str_homestory_chat_30324010 = "¡Pero aún no les has preguntado!",
  str_homestory_chat_30324011 = "¡Está bien, les encantará!",
  str_homestory_chat_30324012 = "E-¿Estás seguro de eso...?",
  str_homestory_chat_30499999 = "Nos encontremos de nuevo. Ciertamente eres un gran trabajador.",
  str_homestory_chat_30421001 = "Sí, solo haciendo las rondas.",
  str_homestory_chat_30421002 = "Escuché que viajaste mucho. ¿Dónde crees que es adecuado vivir en reclusión?",
  str_homestory_chat_30421003 = "¿Vivir en reclusión? ¿Te refieres a lugares donde puedes vivir solo?",
  str_homestory_chat_30421004 = "No del todo exacto. Preferiblemente, discreto pero aún con vecinos alrededor.",
  str_homestory_chat_30421005 = "Mmm, déjame pensar...",
  str_homestory_chat_30421006 = "Umbratón.",
  str_homestory_chat_30421007 = "Recuerdo la frase: esconderse a simple vista.",
  str_homestory_chat_30421008 = "Entonces, cuando esté lleno de todo tipo de personas, nadie se dará cuenta.",
  str_homestory_chat_30421009 = "Es una opción a tener en cuenta.",
  str_homestory_chat_30421010 = "Región septentrional.",
  str_homestory_chat_30421011 = "¿En la base de la Columna Vertebral del Mundo...?",
  str_homestory_chat_30421012 = "Fría, tranquila, remota. Un buen destino.",
  str_homestory_chat_30421013 = "Hay menos gente allí, por lo que la tierra está escasamente poblada y algo cerrada.",
  str_homestory_chat_30421014 = "Supongo que ese es el precio de la seguridad y la privacidad...",
  str_homestory_chat_30421015 = "Llave Reddiésel.",
  str_homestory_chat_30421016 = "¿Qué? ¿No es una banda de nómadas salvajes y errantes?",
  str_homestory_chat_30421017 = "Sí, pero supuestamente también tienen mucha gente de diferentes facciones.",
  str_homestory_chat_30421018 = "Y una vez que te unes y te acostumbras a las costumbres, son grandes personas.",
  str_homestory_chat_30421019 = "Eso no suena tan mal.",
  str_homestory_chat_30421020 = "Un pueblo pequeño.",
  str_homestory_chat_30421021 = "Puede encontrarlo en casi cualquier lugar, por lo que probablemente sea la última opción.",
  str_homestory_chat_30421022 = "Cierto.",
  str_homestory_chat_30422001 = "Pareces sonreír a menudo.",
  str_homestory_chat_30422002 = "Eso es porque me encanta estar aquí.",
  str_homestory_chat_30422003 = "Gracias.",
  str_homestory_chat_30422004 = "El paisaje no es excepcional, pero es muy reconfortante y sereno para mí.",
  str_homestory_chat_30422005 = "Es una sensación difícil de encontrar en otros lugares.",
  str_homestory_chat_30422006 = "¿Quizás porque está más apartado aquí?",
  str_homestory_chat_30422007 = "No, es el estado de ánimo general, especialmente la actitud.",
  str_homestory_chat_30422008 = "La sonrisa en la cara de todos, y esos Chubbs relajados...",
  str_homestory_chat_30422009 = "Esos vagos perezosos... ¿Se estaban volviendo locos otra vez?",
  str_homestory_chat_30422010 = "Estás perdiendo el punto, niño.",
  str_homestory_chat_30423001 = "Te levantas muy temprano.",
  str_homestory_chat_30423002 = "Porque tengo que hacer la cama.",
  str_homestory_chat_30423003 = "¿Hacer la cama? ¿Personalmente?",
  str_homestory_chat_30423004 = "Sí, ¿qué pasa?",
  str_homestory_chat_30423005 = "Simplemente no pensé que harías este tipo de tareas domésticas.",
  str_homestory_chat_30423006 = "¿Te sentiste así por lo que yo era?",
  str_homestory_chat_30423007 = "Oh...",
  str_homestory_chat_30423008 = "No es nada, lo hice más que nada porque me gustaba hacer camas para los niños.",
  str_homestory_chat_30423009 = "A veces, cuando me levantaba por la mañana, empezaba a hacerlo por costumbre, aunque todavía estaban en la cama.",
  str_homestory_chat_30423010 = "Así que no tenían más remedio que levantarse temprano y a veces se quejaban.",
  str_homestory_chat_30423011 = "Puedo imaginar.",
  str_homestory_chat_30423012 = "Pero eso es parte de inculcar disciplina. No puedo dormir, ¡y eso va para ti también!",
  str_homestory_chat_30423013 = "¿Qué? ¡Ah, sí, por supuesto!",
  str_homestory_chat_30424001 = "¿Música?",
  str_homestory_chat_30424002 = "Así es. ¿Qué tipo de música te gusta?",
  str_homestory_chat_30424003 = "El tipo más suave.",
  str_homestory_chat_30424004 = "Me gusta la música que escuché en Lumopolis la última vez.",
  str_homestory_chat_30424005 = "Ambiente suave y elegante.",
  str_homestory_chat_30424006 = "Easy listening es sin duda una música muy agradable.",
  str_homestory_chat_30424007 = "El tipo más intenso.",
  str_homestory_chat_30424008 = "Te refieres al tipo que sonaba como ruido...",
  str_homestory_chat_30424009 = "Es más que eso. También tiene ritmos.",
  str_homestory_chat_30424010 = "¿Es así...?",
  str_homestory_chat_30424011 = "¿Pero no sientes que es demasiado tranquilo no tener música aquí?",
  str_homestory_chat_30424012 = "Los sonidos de la naturaleza servirán. También puedes llamar a eso música.",
  str_homestory_chat_30424013 = "Pero si lo que quieres es otro tipo de música, aún tienes que ir a los lugares adecuados.",
  str_homestory_chat_30424014 = "Tienes razón. Debería disfrutar esta música mientras esté en Cloud Gardens.",
  str_homestory_chat_30425001 = "¿Qué no me gusta?",
  str_homestory_chat_30425002 = "No puedo pensar en nada inesperado... ¿Por qué tienes ganas de preguntar eso?",
  str_homestory_chat_30425003 = "El dormitorio se sentía algo húmedo esta mañana por la lluvia de hace unos días...",
  str_homestory_chat_30425004 = "Así que me recordó mis días en Umbraton.",
  str_homestory_chat_30425005 = "Umbraton... ¿Has cogido la temporada de lluvias?",
  str_homestory_chat_30425006 = "Suspiro, estuvo lloviznando todo el día, y la cama no era cómoda sin importar lo que hicieras...",
  str_homestory_chat_30425007 = "Escuché que es así en Umbraton, especialmente para esos meses...",
  str_homestory_chat_30425008 = "Pero no tenemos mucho de eso en Cloud Gardens.",
  str_homestory_chat_30425009 = "Por eso se siente bien aquí.",
  str_homestory_chat_30599999 = "¿Qué estás haciendo?",
  str_homestory_chat_30521001 = "Escuché que estás buscando perfumes.",
  str_homestory_chat_30521002 = "Sí. El aire es muy limpio aquí, pero le vendría bien un poco de perfume para acentuarlo.",
  str_homestory_chat_30521003 = "¿Por qué perfumes?",
  str_homestory_chat_30521004 = "Es sobre todo para los Chubbs. Creo que son guías perfectas.",
  str_homestory_chat_30521005 = "Pero es difícil distinguir muchos de ellos, a menos que tengas perfumes.",
  str_homestory_chat_30521006 = "Entonces, ¿es solo para distinguirlos? ¿No es absurdo usar perfumes para eso?",
  str_homestory_chat_30521007 = "Cierto... ¿Con rotuladores permanentes, entonces? Como \"#1\", \"#2\" y así sucesivamente.",
  str_homestory_chat_30521008 = "Eh... No importa.",
  str_homestory_chat_30522001 = "¿Tienda de té?",
  str_homestory_chat_30522002 = "Aquí no tenemos nada de eso.",
  str_homestory_chat_30522003 = "Oh, no, quiero abrir una tienda de té aquí y estoy investigando.",
  str_homestory_chat_30522004 = "¿Investigar sobre qué?",
  str_homestory_chat_30522005 = "Lo que le gusta a todo el mundo. Por ejemplo, ¿qué te gusta beber?",
  str_homestory_chat_30522006 = "Leche.",
  str_homestory_chat_30522007 = "Hmm, una elección saludable.",
  str_homestory_chat_30522008 = "gaseosas",
  str_homestory_chat_30522009 = "¿Oh? Eso es especial.",
  str_homestory_chat_30522010 = "Café.",
  str_homestory_chat_30522011 = "No está mal.",
  str_homestory_chat_30522012 = "té negro",
  str_homestory_chat_30522013 = "¡Tienes buen gusto!",
  str_homestory_chat_30522014 = "Por cierto, estás encuestando a otras personas además de mí, ¿verdad?",
  str_homestory_chat_30522015 = "¿Cuantos tienes?",
  str_homestory_chat_30522016 = "Todavía estoy preguntando una a la vez, y luego tengo que clasificar las respuestas tempranas, intermedias y tardías, mientras actualizo de vez en cuando.",
  str_homestory_chat_30522017 = "Eso es un montón de problemas para pasar ...",
  str_homestory_chat_30522018 = "Esa es la única manera de obtener datos precisos para concretar la bebida de autor.",
  str_homestory_chat_30522019 = "De alguna manera, no tengo la sensación de que nunca se va a abrir...",
  str_homestory_chat_30523001 = "¿Fiesta de baile?",
  str_homestory_chat_30523002 = "Sí. Últimamente me he sentido letárgico.",
  str_homestory_chat_30523003 = "Lo pensé y me di cuenta de que hacía mucho tiempo que no iba a una fiesta de baile.",
  str_homestory_chat_30523004 = "No creo que haya lugar para eso aquí.",
  str_homestory_chat_30523005 = "¡Entonces lanza uno! Todo lo que necesita es una configuración simple.",
  str_homestory_chat_30523006 = "Como un cuadrado, sillas, pancartas y demás.",
  str_homestory_chat_30523007 = "Pero la banda podría ser un problema. Creo que deberíamos contratar a alguien.",
  str_homestory_chat_30523008 = "¿Como los Chubbs, tal vez...?",
  str_homestory_chat_30523009 = "Espera, no saben tocar instrumentos.",
  str_homestory_chat_30523010 = "Deberían empezar a entrenar, entonces.",
  str_homestory_chat_30523011 = "Necesitamos un campo de entrenamiento especial, del tipo intenso de diez días.",
  str_homestory_chat_30523012 = "¡¿Diez días?!",
  str_homestory_chat_30523013 = "¿Demasiado? Que sean tres, entonces.",
  str_homestory_chat_30523014 = "Es mejor que vayas a Lumopolis para una fiesta...",
  str_homestory_chat_30524001 = "¿Una guía?",
  str_homestory_chat_30524002 = "Sí, siento que este es un lugar muy grande desde que llegué aquí.",
  str_homestory_chat_30524003 = "Necesitamos tener una guía para que los recién llegados no se pierdan.",
  str_homestory_chat_30524004 = "Mmm...",
  str_homestory_chat_30524005 = "¿Entonces estas de acuerdo?",
  str_homestory_chat_30524006 = "Bueno, tienes un punto.",
  str_homestory_chat_30524007 = "Este es un lugar muy grande y una guía sería muy valiosa.",
  str_homestory_chat_30524008 = "Dejame pensarlo.",
  str_homestory_chat_30524009 = "Hablando de eso, ¿ya tienes un candidato?",
  str_homestory_chat_30524010 = "Los Chubbs!",
  str_homestory_chat_30524011 = "¿Qué? ¿A ellos?",
  str_homestory_chat_30524012 = "Pasaron todo el día aquí y conocen el lugar de arriba abajo. Son perfectos.",
  str_homestory_chat_30524013 = "Uh, te diré qué, déjame detenerme en eso...",
  str_homestory_chat_30699999 = "¿Algún proyecto interesante?",
  str_homestory_chat_30621001 = "¿Construyendo un parque de diversiones?",
  str_homestory_chat_30621002 = "Buena idea, pero es demasiado remoto aquí, ¿cómo vamos a atraer visitantes? ¿O tal vez enfocándonos en los locales?",
  str_homestory_chat_30621003 = "Los Chubbs?",
  str_homestory_chat_30621004 = "¡Es correcto! Es una población pequeña, pero al tener en cuenta el futuro...",
  str_homestory_chat_30621005 = "¿Cómo es su tasa de natalidad? ¿Pueden proliferar rápidamente? ¿Cómo se reproducen?",
  str_homestory_chat_30621006 = "Es similar a, uh, los Aurorianos...?",
  str_homestory_chat_30621007 = "Eso no sonó como si estuvieras seguro en absoluto.",
  str_homestory_chat_30621008 = "Probablemente no puedan reproducirse.",
  str_homestory_chat_30621009 = "¿En serio?",
  str_homestory_chat_30621010 = "Sí. Nunca los vi nacer, como si todos aparecieran de la nada.",
  str_homestory_chat_30621011 = "Carrera interesante... Pero supongo que no puedo ganar dinero con ellos.",
  str_homestory_chat_30621012 = "Espera, ¿y si probamos un enfoque diferente...? ¡Lo tengo!",
  str_homestory_chat_30621013 = "Vamos a oírlo.",
  str_homestory_chat_30621014 = "Menos significa que es raro, raro significa que es precioso, precioso significa que atrae audiencia, ¡audiencia significa entradas!",
  str_homestory_chat_30621015 = "¿Estás pensando...",
  str_homestory_chat_30621016 = "¡Conviértelos en estrellas y ponlos en espectáculos por todo Astra!",
  str_homestory_chat_30621017 = "¡Lo llamaremos \"La Gira Mundial de una Raza Misteriosa!\" ¿Qué te parece?",
  str_homestory_chat_30621018 = "Creo que deberías salir ahora.",
  str_homestory_chat_30621019 = "¿Por qué?",
  str_homestory_chat_30621020 = "Los estás convirtiendo en un espectáculo de fenómenos...",
  str_homestory_chat_30621021 = "Eso puede ser factible.",
  str_homestory_chat_30621022 = "\"Superstar Chubbs\" es una propuesta intrigante, pero primero tenemos que conocer sus opiniones.",
  str_homestory_chat_30621023 = "¡No hay problema! ¡Avísame qué dicen!",
  str_homestory_chat_30622001 = "Hablemos de Jardines de nubes.",
  str_homestory_chat_30622002 = "Claro, de todos modos quería discutirlo.",
  str_homestory_chat_30622003 = "¿Qué es?",
  str_homestory_chat_30622004 = "Desarrollo inmobiliario. Tiene mucha naturaleza y poca comodidad.",
  str_homestory_chat_30622005 = "No hay zona de comida, distrito comercial, entretenimiento... No puedes atraer turistas.",
  str_homestory_chat_30622006 = "Nunca quise atraer turistas... Estoy bien siempre que mis amigos se sientan cómodos aquí.",
  str_homestory_chat_30622007 = "¡No! Eso podría ser sostenible por ahora, pero ¿alguna vez te has preguntado qué va a pasar en el futuro?",
  str_homestory_chat_30622008 = "¿Cuánto tiempo puedes resistir una vez que te quedas sin ingresos?",
  str_homestory_chat_30622009 = "En lugar de esperar el futuro, ¡deberías preocuparte por el ahora! ¿Qué te parece si me dejas dirigir los Jardines de Nubes, qué dices?",
  str_homestory_chat_30622010 = "¿A qué estás llegando?",
  str_homestory_chat_30622011 = "Véndemelo. ¡Lo convertiré en el distrito comercial más importante del mundo!",
  str_homestory_chat_30622012 = "Preferiría mantener el statu quo.",
  str_homestory_chat_30623001 = "Hablemos de tu cabello, en cambio.",
  str_homestory_chat_30623002 = "¿Mi cabello? No hay nada de qué hablar. Es bastante normal.",
  str_homestory_chat_30623003 = "Apuesto a que ese peinado es un gran lío.",
  str_homestory_chat_30623004 = "Acabo de ir a una peluquería. Solo cuesta unos miles de Nightium por visita.",
  str_homestory_chat_30623005 = "¡Unos miles! ¿Qué hacen que sea tan caro?",
  str_homestory_chat_30623006 = "Cortar, recortar, peinar y así sucesivamente. Hablando de eso, acabo de tener una idea para un proyecto.",
  str_homestory_chat_30623007 = "¿Qué es?",
  str_homestory_chat_30623008 = "¡Abre una peluquería aquí! Me imagino que hay suficientes personas que necesitan un peluquero aquí, ¿cierto?",
  str_homestory_chat_30623009 = "Probablemente será pequeño con un personal reducido, pero mientras tenga todo lo necesario y podamos importar productos de Umbratón.",
  str_homestory_chat_30623010 = "Un dueño de salón que conozco resulta tener las conexiones adecuadas...",
  str_homestory_chat_30623011 = "Supongo que solo quieres que te arreglen el cabello aquí.",
  str_homestory_chat_30623012 = "Por supuesto que lo hago gratis si lo obtuve. ¡Tú obtienes un 20% de descuento, sin embargo!",
  str_homestory_chat_30623013 = "¿Solo 20% de descuento...?",
  str_homestory_chat_30623014 = "¡¿Entonces estás de acuerdo?! ¡Mañana pondré en marcha la rueda!",
  str_homestory_chat_30623015 = "¡Espera un minuto, aún estaba pensando en la opción!",
  str_homestory_chat_30624001 = "Escuché que últimamente tienes tus ojos en los Chubbs, ¿verdad?",
  str_homestory_chat_30624002 = "Correcto. ¿Te interesa entregármelos?",
  str_homestory_chat_30624003 = "¡No son mercancía!",
  str_homestory_chat_30624004 = "¡De ninguna manera!",
  str_homestory_chat_30624005 = "Entiendo. Firmaron un contrato contigo, ¿cierto? Nombra tu precio.",
  str_homestory_chat_30624006 = "Compensaciones, tarifas de transferencia, bonificaciones por firmar... Evetodo es negociable.",
  str_homestory_chat_30624007 = "¿Qué tiene que ver eso con nada? ¿Por qué de repente quieres que trabajen para ti?",
  str_homestory_chat_30624008 = "Estoy lanzando un gran proyecto y necesito algunos trabajadores competentes.",
  str_homestory_chat_30624009 = "¿Trabajadores competentes? ¿Crees que Chubbs encaja en esa descripción?",
  str_homestory_chat_30624010 = "¡No es problema! Por ejemplo, ¡tú no te das cuenta de lo buenos trabajadores que son el Becario Chubb y el Comerciante Chubb!",
  str_homestory_chat_30624011 = "Pueden leer y hacer matemáticas, saben mucho, no comen mucho y probablemente no duermen en absoluto.",
  str_homestory_chat_30624012 = "¡Qué trabajador perfecto! No te preocupes, ¡pagaré por las horas extra!",
  str_homestory_chat_30624013 = "¡Doble salario para días laborables, triple para días festivos!",
  str_homestory_chat_30624014 = "¡Espera, puede que no estén dispuestos a hacer eso!",
  str_homestory_chat_30625001 = "Deja de pensar en proyectos y toma un sorbo de algo.",
  str_homestory_chat_30625002 = "Pero no hay nada para beber en los Jardines de Nubes. Todo lo que veo es agua fría.",
  str_homestory_chat_30625003 = "Es un lío traer café o té de Umbratón.",
  str_homestory_chat_30625004 = "¿No hay ninguna bebida especial local aquí?",
  str_homestory_chat_30625005 = "Supuestamente, las hojas de ciertos árboles únicos emiten un aroma distintivo, pero no sé cómo sabe en agua caliente.",
  str_homestory_chat_30625006 = "Árboles únicos, ¿eh? Esa es una opción a considerar.",
  str_homestory_chat_30625007 = "¿No me digas que pensaste en otra idea de negocio?",
  str_homestory_chat_30625008 = "Tendré que probarlo primero antes de poder explorar el potencial comercial.",
  str_homestory_chat_30625009 = "Ya que lo sugeriste, lo investigaré cuando tenga tiempo libre.",
  str_homestory_chat_30799999 = "¿Qué estás haciendo?",
  str_homestory_chat_30721001 = "Solo dando la ronda.",
  str_homestory_chat_30721002 = "¿No puedes hacer algo más significativo?",
  str_homestory_chat_30721003 = "Este es un pasatiempo mío. Probablemente estés aburrido hasta la médula, aunque.",
  str_homestory_chat_30721004 = "Estás en lo correcto... ¿Alguna actividad que recomendar en Jardines de Nubes?",
  str_homestory_chat_30721005 = "¿Pescar?",
  str_homestory_chat_30721006 = "Demasiado silencio, y es vergonzoso cuando no atrapas nada.",
  str_homestory_chat_30721007 = "¿Jardinería?",
  str_homestory_chat_30721008 = "Solo veo árboles grandes y extraños alrededor... Demasiado incómodo para mi gusto.",
  str_homestory_chat_30721009 = "Visita el museo.",
  str_homestory_chat_30721010 = "No hay mucho que ver allí.",
  str_homestory_chat_30721011 = "¡No te interesa nada! ¿Por qué no tomas una siesta en tu habitación?",
  str_homestory_chat_30721012 = "No te alteres. Solo intentaba que te relajaras y lo tomaras con calma.",
  str_homestory_chat_30721013 = "EveCada vez que te veo, estás haciendo la ronda o trabajando. Estoy preocupado por ti...",
  str_homestory_chat_30721014 = "La vida no se limita a expandir Jardines de nubes.",
  str_homestory_chat_30721015 = "Todo está bien. Hacer la ronda para mí es tomármelo con calma. Llámalo un paseo tranquilo.",
  str_homestory_chat_30721016 = "Muy bien, lo tengo. Por favor continua.",
  str_homestory_chat_30722001 = "Solo estoy dando un paseo. ¿Y tú?",
  str_homestory_chat_30722002 = "Solo te estoy buscando. ¿Te importaría ir a Umbraton conmigo si estás libre?",
  str_homestory_chat_30722003 = "¿Umbraton? ¿Ahora?",
  str_homestory_chat_30722004 = "Alguien me dio dos pases VIP para un restaurante elegante, así que puedo llevar a un acompañante.",
  str_homestory_chat_30722005 = "No hay almuerzo gratis...",
  str_homestory_chat_30722006 = "Tienes un favor que pedir, ¿verdad?",
  str_homestory_chat_30722007 = "¿No intentaste invitar a alguien más?",
  str_homestory_chat_30722008 = "¿O debería decir, no tienes a nadie más a quien puedas invitar?",
  str_homestory_chat_30722009 = "¿Así es como te sientes acerca de nuestra amistad? ¿No podemos simplemente sentarnos y compartir una comida?",
  str_homestory_chat_30722010 = "Déjame pensar en ello.",
  str_homestory_chat_30723001 = "Estoy pensando en ir a ver los árboles únicos ahora mismo.",
  str_homestory_chat_30723002 = "Árboles únicos, usted dijo... Escuché que algunos de ellos desprenden un aroma fascinante.",
  str_homestory_chat_30723003 = "Estoy pensando si se puede convertir en perfume.",
  str_homestory_chat_30723004 = "Tardaron mucho tiempo en crecer, así que no los molestes.",
  str_homestory_chat_30723005 = "No solo yo, a los Chubbs tampoco les gustaría.",
  str_homestory_chat_30723006 = "Eso es malo. ¿Qué voy a hacer con mi cita?",
  str_homestory_chat_30723007 = "¿Tu fecha?",
  str_homestory_chat_30723008 = "Prometí traerle un perfume especial y único.",
  str_homestory_chat_30723009 = "¿Qué se supone que es eso?",
  str_homestory_chat_30723010 = "Una mezcla de pólenes de árboles únicos y rocío vespertino, hecha especialmente para ella. El único en el mundo.",
  str_homestory_chat_30723011 = "¿Eso olerá bien?",
  str_homestory_chat_30723012 = "No necesariamente, pero está bien siempre y cuando ella crea que es especial.",
  str_homestory_chat_30723013 = "Supongo que eso es lo que alguien llamó \"misterios de las citas\"... De todos modos, los árboles únicos están fuera de discusión.",
  str_homestory_chat_30723014 = "Bien, veo que tendré que sacar otros \"misterios.\"",
  str_homestory_chat_30724001 = "¿Estás buscando a Chubbs?",
  str_homestory_chat_30724002 = "Sí, quiero discutir temas sobre ellos.",
  str_homestory_chat_30724003 = "¿Qué ocurre?",
  str_homestory_chat_30724004 = "Como guardianes de los Jardines de Nubes, carecen de encanto.",
  str_homestory_chat_30724005 = "Pero, ¿no es suficiente servir a las personas y garantizar el funcionamiento de los jardines de nubes?",
  str_homestory_chat_30724006 = "¡Equivocado!",
  str_homestory_chat_30724007 = "Si los cuidadores no son encantadores, ¿quién querría vivir aquí?",
  str_homestory_chat_30724008 = "Mira qué cuadrados y aburridos son.",
  str_homestory_chat_30724009 = "Los jardines de nubes no son parques de atracciones. No necesitamos clientela.",
  str_homestory_chat_30724010 = "EveTodos vienen aquí para relajarse. Los Chubbs simplemente tienen que mantener el mantenimiento diario.",
  str_homestory_chat_30724011 = "¿Así es como funciona...? Ya veo.",
  str_homestory_chat_30725001 = "¿Escuché que me estás buscando?",
  str_homestory_chat_30725002 = "Lo que realmente quiero es comprar una trama aquí.",
  str_homestory_chat_30725003 = "¿No me digas que alguien quiere construir un complejo turístico y te está contratando para administrarlo?",
  str_homestory_chat_30725004 = "No, incorrecto, amigo. Busco jubilarme aquí.",
  str_homestory_chat_30725005 = "¿No es aún demasiado temprano para eso?",
  str_homestory_chat_30725006 = "Solo un pensamiento. El ambiente aquí es agradable, después de todo. Aislado, tranquilo...",
  str_homestory_chat_30725007 = "Espero llegar al día en que pueda jubilarme aquí.",
  str_homestory_chat_30899999 = "¡Estoy Aquí!",
  str_homestory_chat_30801001 = "¡Hola, Bopper!",
  str_homestory_chat_30801002 = "¡Me viste!",
  str_homestory_chat_30801003 = "Eso es porque me saludaste con la mano.",
  str_homestory_chat_30801004 = "Los chicos de Rediesel Wrench siempre me ignoraban. Por lo general, no puedo obtener una respuesta de ellos.",
  str_homestory_chat_30801005 = "¡De ninguna manera! ¿Has intentado expresarte más, como lanzando sugerencias?",
  str_homestory_chat_30801006 = "¡Esa es la razón por la que me convertí en estratega! Pero solo el Lagarto Gigante parecía prestar atención a mis planes...",
  str_homestory_chat_30801007 = "Si tan solo Sinsa siguiera mi consejo de vez en cuando...",
  str_homestory_chat_30801008 = "Estoy seguro de que llegará el día. ¡No te rindas, Bopper!",
  str_homestory_chat_30821001 = "¿Qué pasa contigo últimamente?",
  str_homestory_chat_30821002 = "Creo que voy a comer en un rato. Estoy un poco hambriento.",
  str_homestory_chat_30821003 = "Jardines de nubes está un poco lejos del Desierto de Rediesel y probablemente no tenga lo que me gusta, aunque.",
  str_homestory_chat_30821004 = "¿Alimento del desierto de Rediesel? ¿Te refieres a carne seca de lagarto y cactus?",
  str_homestory_chat_30821005 = "Eso no es todo. ¿Qué hay disponible para comer en Jardines de Nubes?",
  str_homestory_chat_30821006 = "Pan.",
  str_homestory_chat_30821007 = "Eso es común. ¿Lo comes seco sin mermeladas?",
  str_homestory_chat_30821008 = "Solo el pan es suficiente.",
  str_homestory_chat_30821009 = "Está bien.",
  str_homestory_chat_30821010 = "Café.",
  str_homestory_chat_30821011 = "Es un buen levanta ánimos, pero un poco amargo y necesita mucho azúcar...",
  str_homestory_chat_30821012 = "Risotto.",
  str_homestory_chat_30821013 = "Es muy abundante, pero mejor con guarniciones.",
  str_homestory_chat_30821014 = "Tartas de frutas.",
  str_homestory_chat_30821015 = "No sabía que te gustaban tanto los dulces.",
  str_homestory_chat_30821016 = "No pareces estar muy interesado en esa comida.",
  str_homestory_chat_30821017 = "Nah, extraño el Desierto de Rediesel siempre que hablo de comida.",
  str_homestory_chat_30821018 = "La tormenta de arena puede ser terrible, pero la comida es agradable...",
  str_homestory_chat_30821019 = "Como los helados y pasteles de lagarto, o gusanos de rediesel fritos.",
  str_homestory_chat_30821020 = "May¿abrir una cafetería Rediesel en Jardines de Nubes? ¿Funcionará eso?",
  str_homestory_chat_30821021 = "Sin duda, cerrará sus puertas.",
  str_homestory_chat_30822001 = "Oye, ¿cómo te estás adaptando hasta ahora?",
  str_homestory_chat_30822002 = "¡Hola PlayerName! Es agradable aquí, tranquilo, cómodo, es solo...",
  str_homestory_chat_30822003 = "Aquí viene la parte mala...",
  str_homestory_chat_30822004 = "A veces no paro de estornudar, como... ¡Achú!",
  str_homestory_chat_30822005 = "No sé por qué, pero estoy bien cuando salgo de aquí.",
  str_homestory_chat_30822006 = "¿Algo en el ambiente, quizás? ¿Polen, tal vez?",
  str_homestory_chat_30822007 = "¡Achú! Probablemente, ya que las flores son raras en el Desierto de Rediesel.",
  str_homestory_chat_30822008 = "Todo lo que ves es arena, arena y más arena, con lo cual no tengo problema.",
  str_homestory_chat_30822009 = "Ya sea que me entre en la nariz o en los ojos, puedo sacarlo en dos movimientos.",
  str_homestory_chat_30822010 = "Pero los polenes de los que hablaste... ¡Achú! ¡Son muy molestos!",
  str_homestory_chat_30822011 = "Intenta mantenerte alejado de ellos o ven en otro momento.",
  str_homestory_chat_30822012 = "O soportarlo por unos días hasta que te acostumbres.",
  str_homestory_chat_30822013 = "La naturaleza en los jardines de nubes ciertamente difiere del desierto de Rediesel.",
  str_homestory_chat_30822014 = "Es muy relajante e incluso cautivador. ¡Achú!",
  str_homestory_chat_30823001 = "¿Qué estás mirando?",
  str_homestory_chat_30823002 = "Estoy tratando de encontrar el Águila Gigante. ¿Dónde lo estacionaste?",
  str_homestory_chat_30823003 = "Afuera.",
  str_homestory_chat_30823004 = "¿No te preocupa que eso pueda ser peligroso?",
  str_homestory_chat_30823005 = "Él puede protegerse a sí mismo. Even si no, simplemente puede volar lejos.",
  str_homestory_chat_30823006 = "¿Por qué lo estás buscando?",
  str_homestory_chat_30823007 = "Solo tengo curiosidad de dónde está y si puede protegerse a sí mismo.",
  str_homestory_chat_30823008 = "Está bien, no te preocupes.",
  str_homestory_chat_30823009 = "Sin embargo, si estás aquí, ¿dónde está el Lagarto Gigante?",
  str_homestory_chat_30823010 = "Monté en un coche. El Lagarto Gigante prefirió no salir del desierto.",
  str_homestory_chat_30823011 = "Probablemente esté pasando el tiempo con esos chicos poco confiables...",
  str_homestory_chat_30823012 = "Esa no es la forma de hablar sobre tus amigos...",
  str_homestory_chat_30999999 = "¿Qué estás haciendo?",
  str_homestory_chat_30921001 = "Solo dando un paseo. ¿Y tú?",
  str_homestory_chat_30921002 = "¿Tienes algo en mente?",
  str_homestory_chat_30921003 = "Claro que sí, y llegaste justo a tiempo para escuchar todo al respecto. Necesito tu opinión sobre algo.",
  str_homestory_chat_30921004 = "Qué es...?",
  str_homestory_chat_30921005 = "Echa un vistazo a estos generales. ¿Quién de ellos crees que sería un buen Gran Mariscal?",
  str_homestory_chat_30921006 = "Hmm... Déjame pensar.",
  str_homestory_chat_30921007 = "Sharona.",
  str_homestory_chat_30921008 = "Mmm. No es una mala candidata. Para este trabajo, tiene el liderazgo perfecto, la perspicacia estratégica y la lealtad.",
  str_homestory_chat_30921009 = "Lamentablemente, sin embargo, ella es de Lumopolis y, aunque prácticamente ha cortado todos los lazos con su vida pasada...",
  str_homestory_chat_30921010 = "En los ojos de \"esas personas\", ella está lejos de ser perfecta.",
  str_homestory_chat_30921011 = "Entiendo...",
  str_homestory_chat_30921012 = "Barton.",
  str_homestory_chat_30921013 = "En el mejor de los casos, es un general. El hombre solo se siente en casa cuando está en el campo de batalla.",
  str_homestory_chat_30921014 = "En tiempos de paz, terminará siendo una molestia para el público o se convertirá en un holgazán sin oficio.",
  str_homestory_chat_30921015 = "Vaya, eres duro.",
  str_homestory_chat_30921016 = "Solo diciendo la verdad.",
  str_homestory_chat_30921017 = "Hiiro.",
  str_homestory_chat_30921018 = "Su valentía está más allá de toda crítica, y dirige a sus tropas con la máxima disciplina y autoridad. Desafortunadamente...",
  str_homestory_chat_30921019 = "Hiiro a veces va mucho más allá de \"valiente\" que a menudo se pierde en el calor de la batalla.",
  str_homestory_chat_30921020 = "Por supuesto, no hace falta decir que un soldado debe ser valiente, pero la valentía nunca debe tener un costo en la victoria.",
  str_homestory_chat_30921021 = "Los dos no siempre van de la mano... No estoy seguro si puedes notar la sutil diferencia ahí.",
  str_homestory_chat_30921022 = "Creo que lo entiendo... hasta cierto punto.",
  str_homestory_chat_30921023 = "Entonces, parece que... nadie es realmente adecuado para el papel.",
  str_homestory_chat_30921024 = "Bueno, en realidad, míralo desde otro ángulo: si estos candidatos tuvieran adjuntos adecuados, oficiales de estado mayor o lo que sea, para ayudarles...",
  str_homestory_chat_30921025 = "Ellos podrían ser totalmente buenos Grandes Mariscales.",
  str_homestory_chat_30922001 = "Solo me voy a ver si alguno de mis amigos está por aquí.",
  str_homestory_chat_30922002 = "Hablando de amigos, ¿qué opinas de Reinhardt? ¿Dirías que es una buena amiga o una buena jefa?",
  str_homestory_chat_30922003 = "Ella es una buena amiga.",
  str_homestory_chat_30922004 = "Es una buena jefa.",
  str_homestory_chat_30922005 = "¿Por qué me preguntas esto de repente?",
  str_homestory_chat_30922006 = "Quizás ya sepas que los dos fuimos compañeros de clase.",
  str_homestory_chat_30922007 = "Solía ser mi oficial al mando... Su deseo era mi comando en aquel entonces.",
  str_homestory_chat_30922008 = "Sin embargo, por cómo van las cosas, podría llegar a ser su superior en el futuro.",
  str_homestory_chat_30922009 = "Ya veo... Estás pensando en cómo llevarte bien con ella, ¿verdad?",
  str_homestory_chat_30922010 = "Es correcto.",
  str_homestory_chat_30922011 = "No hay necesidad de preocuparse demasiado por eso. Simplemente sigue la corriente.",
  str_homestory_chat_30922012 = "Sabía que dirías eso, pero aún así cuenta como un buen consejo en mi libro.",
  str_homestory_chat_30922013 = "Gracias, PlayerName.",
  str_homestory_chat_30923001 = "Solo quiero ir a tomar un descanso.",
  str_homestory_chat_30923002 = "¿Qué haces normalmente para relajarte?",
  str_homestory_chat_30923003 = "Dar un paseo.",
  str_homestory_chat_30923004 = "Suena bastante básico.",
  str_homestory_chat_30923005 = "Ir a pescar.",
  str_homestory_chat_30923006 = "Eso es tan cliché.",
  str_homestory_chat_30923007 = "Escuché que los Caelestites desarrollaron un método único de relajación llamado \"meditación.\"",
  str_homestory_chat_30923008 = "Personalmente, rara vez medito... ¿Por qué te interesó la meditación de repente?",
  str_homestory_chat_30923009 = "¿Tú quieres intentarlo?",
  str_homestory_chat_30923010 = "La meditación es una forma de relajación y también una forma de entrenamiento.",
  str_homestory_chat_30923011 = "Al relajarte, puedes encontrar tu verdadero camino y reforzar la trayectoria de tu progreso.",
  str_homestory_chat_30923012 = "Este método de entrenamiento es crucial para mí, me ayuda a recargar mis \"baterías\", por así decirlo.",
  str_homestory_chat_30923013 = "Lo intentaré más tarde...",
  str_homestory_chat_30924001 = "Solo caminando.",
  str_homestory_chat_30924002 = "Parece que esto de caminar realmente te queda bien.",
  str_homestory_chat_30924003 = "¿Por qué dices eso?",
  str_homestory_chat_30924004 = "¡Porque te ves genial! ¿El secreto está en todos esos paseos, verdad?",
  str_homestory_chat_30924005 = "No.",
  str_homestory_chat_30924006 = "¿Cuál es tu secreto, entonces?",
  str_homestory_chat_30924007 = "Nada secreto. Solo tener un sueño profundo y mantener una vida saludable y equilibrada.",
  str_homestory_chat_30924008 = "Bueno tú, por el contrario, siempre pareces malhumorado... ¿Es porque a menudo te quedas despierto hasta tarde? No te mates a ti mismo por el trabajo.",
  str_homestory_chat_30924009 = "Podrías decir que es el precio de la responsabilidad.",
  str_homestory_chat_30925001 = "Simplemente patrullando Cloud Gardens.",
  str_homestory_chat_30925002 = "Vaya, qué difícil. No hay descanso para los malvados, ¿eh?",
  str_homestory_chat_30925003 = "Nah... Un buen paseo es exactamente lo que necesitaba.",
  str_homestory_chat_30925004 = "¿En serio? Así que así es como manejas el Jardín de las Nubes, ¿eh?",
  str_homestory_chat_30925005 = "Más o menos. Los Chubbs se encargan de la mayor parte del trabajo, mientras que yo solo echo un vistazo de vez en cuando.",
  str_homestory_chat_30925006 = "Vaya, ojalá dirigir Illumina fuera tan sencillo como dirigir Cloud Gardens.",
  str_homestory_chat_30925007 = "Aunque son muy diferentes.",
  str_homestory_chat_30925008 = "Después de todo, la Federación Illumina es responsable de repeler a los Eclipsites invasores...",
  str_homestory_chat_30925009 = "Y obviamente es mucho más grande que Cloud Gardens...",
  str_homestory_chat_30925010 = "Es correcto.",
  str_homestory_chat_30925011 = "Deberías aprender a soltar un poco esa presión. Ahora que estás en Cloud Gardens, simplemente relájate y diviértete aquí.",
  str_homestory_chat_31099999 = "Noche Blanca en lo alto. ¿Cómo va tu día hasta ahora?",
  str_homestory_chat_31001001 = "Ah, nada especial.",
  str_homestory_chat_31001002 = "Esto es algo bueno. Significa que la paz se ha preservado aquí.",
  str_homestory_chat_31001003 = "Está claro que realmente te encantan días como este.",
  str_homestory_chat_31001004 = "Todos en Crepúsculo viven una vida llena de estrés.",
  str_homestory_chat_31001005 = "Físicamente y espiritualmente...",
  str_homestory_chat_31001006 = "Los Eclipsites están tan cerca del perímetro del pueblo que los habitantes casi pueden sentirlos respirando en sus cuellos.",
  str_homestory_chat_31001007 = "Al llegar aquí, uno no puede evitar maravillarse de lo sereno que es.",
  str_homestory_chat_31001008 = "Si esta paz pudiera extenderse por todo el continente, sería algo maravilloso.",
  str_homestory_chat_31021001 = "Bastante bien. ¿Y tú?",
  str_homestory_chat_31021002 = "Me preguntaba... ¿Cómo consideras personalmente las diversas regiones del mundo?",
  str_homestory_chat_31021003 = "¿Por ejemplo...?",
  str_homestory_chat_31021004 = "Mmm... Lumopolis.",
  str_homestory_chat_31021005 = "Es el centro de la civilización.",
  str_homestory_chat_31021006 = "Gobernante del continente.",
  str_homestory_chat_31021007 = "¿Qué opinas de Lumopolis?",
  str_homestory_chat_31021008 = "Es el... centro de la civilización, ¿no?",
  str_homestory_chat_31021009 = "Algo en tu tono me dice que no estás tan seguro de eso.",
  str_homestory_chat_31021010 = "Eso se debe a que he vivido en Crepúsculo durante mucho tiempo y rara vez me aventuro a Lumopolis.",
  str_homestory_chat_31021011 = "¿Qué opinas de la Federación Illumina entonces, PlayerName?",
  str_homestory_chat_31021012 = "Es la primera línea de la lucha contra los Eclipsites.",
  str_homestory_chat_31021013 = "Es una organización unida.",
  str_homestory_chat_31021014 = "¿Por qué me preguntas sobre esto?",
  str_homestory_chat_31021015 = "Cuando pienso en lo que está pasando en Crepúsculo, no puedo evitar preocuparme por el futuro de Crepúsculo.",
  str_homestory_chat_31021016 = "Esos habitantes del pueblo... ¿Qué será de ellos?",
  str_homestory_chat_31021017 = "¿Piensas en estas cosas a menudo?",
  str_homestory_chat_31021018 = "Con una vida en Crepúsculo, no tengo más opción que pensar en estas cosas...",
  str_homestory_chat_31021019 = "Espero que el todopoderoso Dios de la Luz responda a mis oraciones y otorgue refugio a los habitantes del pueblo.",
  str_homestory_chat_31022001 = "A punto de dar un paseo por un rato.",
  str_homestory_chat_31022002 = "Parece que finalmente estás listo para disfrutar de tu tiempo libre.",
  str_homestory_chat_31022003 = "Supongo que sí. ¿Qué estás haciendo ahora mismo?",
  str_homestory_chat_31022004 = "Aún no lo he decidido. Después de llegar a Cloud Gardens, me sentí un poco fuera de lugar.",
  str_homestory_chat_31022005 = "¿Por qué dices eso?",
  str_homestory_chat_31022006 = "Cloud Gardens es tan diferente de Twilight, un lugar donde debes empuñar tu espada casi todos los días para sobrevivir...",
  str_homestory_chat_31022007 = "¿Luchando contra Eclipsites?",
  str_homestory_chat_31022008 = "Precisamente.",
  str_homestory_chat_31022009 = "Siempre me he preguntado cómo sería la vida si no tuviera que portar armas todos los días.",
  str_homestory_chat_31022010 = "Y ahora puedes experimentar esa vida en primera persona.",
  str_homestory_chat_31022011 = "Ah... Sería increíble si todos en Crepúsculo pudieran vivir así.",
  str_homestory_chat_31023001 = "Cosas habituales. ¿Qué estás haciendo por aquí?",
  str_homestory_chat_31023002 = "Estoy absorbiendo rastros de luz.",
  str_homestory_chat_31023003 = "¿Absorbiendo rastros de luz? ¡Oh! ¿Estás tomando el sol? Es bueno para ti, ¿sabes?",
  str_homestory_chat_31023004 = "No, en realidad estoy rezando.",
  str_homestory_chat_31023005 = "¿Orando?",
  str_homestory_chat_31023006 = "Porque la Luz es mi fe...",
  str_homestory_chat_31023007 = "A diferencia de Crepúsculo, Cloud Gardens rara vez ve un cielo nublado.",
  str_homestory_chat_31023008 = "Estando aquí en este maravilloso lugar, no puedo evitar sentir un deseo de invocación creciendo en mi corazón.",
  str_homestory_chat_31023009 = "Vale. Adelante y reza... Te dejo a ti.",
  str_homestory_chat_31199999 = "¿Qué estás haciendo, Navegador?",
  str_homestory_chat_31121001 = "Hola Antony, estoy pensando en salir...",
  str_homestory_chat_31121002 = "Para explorar algunas ruinas.",
  str_homestory_chat_31121003 = "¿Ruinas? ¿Te refieres al tipo inexplorado?",
  str_homestory_chat_31121004 = "¿Puedo ir?",
  str_homestory_chat_31121005 = "¡Claro, por qué no!",
  str_homestory_chat_31121006 = "Pero no te hagas muchas ilusiones.",
  str_homestory_chat_31121007 = "Estas ruinas a las que vamos han sido exploradas muchas veces antes.",
  str_homestory_chat_31121008 = "Si entiendo.",
  str_homestory_chat_31121009 = "Pero a veces, incluso una simple piedra puede contener secretos vitales.",
  str_homestory_chat_31121010 = "Bueno, con tu gran cerebro guiándonos, podríamos tener una oportunidad de encontrar algo especial.",
  str_homestory_chat_31121011 = "Para descansar un poco.",
  str_homestory_chat_31121012 = "¿Descansar? Entonces conozco el lugar perfecto para ti.",
  str_homestory_chat_31121013 = "Escuché que hay algunas ruinas cerca.",
  str_homestory_chat_31121014 = "Ruinas adornadas con numerosas pinturas rupestres misteriosas.",
  str_homestory_chat_31121015 = "¿Cómo tiene eso algo que ver con que yo descanse?",
  str_homestory_chat_31121016 = "Absolutamente.",
  str_homestory_chat_31121017 = "Acostado en las ruinas, mirando hacia arriba a las pinturas...",
  str_homestory_chat_31121018 = "Parece que has viajado en el tiempo a esa época.",
  str_homestory_chat_31121019 = "Para mí, eso cuenta como una forma de relajación.",
  str_homestory_chat_31121020 = "¿Pinturas murales, dices? Bueno, ahora sí que tienes mi atención.",
  str_homestory_chat_31121021 = "Entonces me prepararé para el viaje.",
  str_homestory_chat_31121022 = "Claro. Te veo en un rato.",
  str_homestory_chat_31122001 = "No tengo nada a mano. ¿Y tú?",
  str_homestory_chat_31122002 = "Estoy haciendo ajustes al Bastón Multiusos.",
  str_homestory_chat_31122003 = "¿Algúnas innovaciones nuevas para implementar?",
  str_homestory_chat_31122004 = "Apenas, solo intento reforzar el dispositivo de iluminación.",
  str_homestory_chat_31122005 = "La difusión de luz sigue siendo algo débil.",
  str_homestory_chat_31122006 = "Estoy aplicando el conocimiento que aprendí del Coloso para mejorar los efectos de iluminación.",
  str_homestory_chat_31122007 = "¿Te gustaría escuchar el principio específico detrás de ello?",
  str_homestory_chat_31122008 = "Específicamente, se trata de aumentar la producción real mediante las siguientes ecuaciones...",
  str_homestory_chat_31122009 = "Oh, acabo de recordar que sí tengo algo que hacer...",
  str_homestory_chat_31122010 = "Tengo que irme ahora. Nos vemos.",
  str_homestory_chat_31123001 = "Solo pasando el rato.",
  str_homestory_chat_31123002 = "Podría ir a ver a otros Aurorianos más tarde.",
  str_homestory_chat_31123003 = "Hablando de otros Aurorianos, ¿qué opinas de No. 33, Navegador?",
  str_homestory_chat_31123004 = "Un muy buen compañero.",
  str_homestory_chat_31123005 = "Sin duda.",
  str_homestory_chat_31123006 = "Sin embargo, ¿no te parece maravilloso que ella haya nacido en tiempos antiguos?",
  str_homestory_chat_31123007 = "Eh, no estarás buscando estudiarla, ¿verdad?",
  str_homestory_chat_31123008 = "Oh, no. Solo quiero estudiar su casco, eso es todo...",
  str_homestory_chat_31123009 = "¿Una chica enigmática?",
  str_homestory_chat_31123010 = "¡Tú también sientes lo mismo! Ya veo.",
  str_homestory_chat_31123011 = "Es difícil que un Aurorian nacido en tiempos antiguos no levante algunas cejas.",
  str_homestory_chat_31123012 = "Eh, no estarás buscando estudiarla, ¿verdad?",
  str_homestory_chat_31123013 = "Oh, no. Solo quiero estudiar su casco, eso es todo...",
  str_homestory_chat_31123014 = "Entonces, ¿por qué no vas a hablar con ella tú mismo?",
  str_homestory_chat_31123015 = "Ella debería poder responder a la mayoría de tus preguntas.",
  str_homestory_chat_31124001 = "Voy a leer un libro.",
  str_homestory_chat_31124002 = "Qué coincidencia, Navegante.",
  str_homestory_chat_31124003 = "Tú también vienes aquí a leer libros.",
  str_homestory_chat_31124004 = "¿Qué libro estás leyendo, Antony?",
  str_homestory_chat_31124005 = "Errores y desviaciones en trayectorias estelares.",
  str_homestory_chat_31124006 = "Um... Qué profundo...",
  str_homestory_chat_31124007 = "En realidad, no es difícil. Lo entenderás cuando lo leas, Navegante.",
  str_homestory_chat_31124008 = "Lo intentaré...",
  str_homestory_chat_31125001 = "Voy a ordenar mi habitación.",
  str_homestory_chat_31125002 = "¿Oh? Hablando de ordenar cosas, ¿tienes alguna preferencia?",
  str_homestory_chat_31125003 = "Limpieza.",
  str_homestory_chat_31125004 = "¿Y tú?",
  str_homestory_chat_31125005 = "Por ejemplo, en mi mochila, pondría el énfasis en la eficiencia.",
  str_homestory_chat_31125006 = "Ordenar los elementos según la necesidad.",
  str_homestory_chat_31125007 = "Los más importantes van arriba. Los que apenas se necesitan van abajo.",
  str_homestory_chat_31125008 = "Eficiencia.",
  str_homestory_chat_31125009 = "Yo también.",
  str_homestory_chat_31125010 = "Cuando organizo mi mochila, también pongo énfasis en la eficiencia.",
  str_homestory_chat_31125011 = "Déjame ayudarte a ordenar la habitación.",
  str_homestory_chat_31125012 = "Bien. Gracias por la ayuda.",
  str_homestory_chat_31299999 = "¿Algún plan para hoy?",
  str_homestory_chat_31221001 = "Aún no lo he decidido...",
  str_homestory_chat_31221002 = "¿Y tú?",
  str_homestory_chat_31221003 = "Practicar Luminatics, por supuesto.",
  str_homestory_chat_31221004 = "Dices eso cada vez. Me suena a que estás trabajando demasiado.",
  str_homestory_chat_31221005 = "Sabes, puedes relajarte de vez en cuando.",
  str_homestory_chat_31221006 = "No es bueno estar tenso como una cuerda de arco todo el tiempo.",
  str_homestory_chat_31221007 = "Está bien...?",
  str_homestory_chat_31222001 = "Voy a patrullar todo el día...",
  str_homestory_chat_31222002 = "No la tienes fácil, Navegador.",
  str_homestory_chat_31222003 = "Tan ocupado todos los días.",
  str_homestory_chat_31222004 = "Por favor, avísame si necesitas mi ayuda en algo.",
  str_homestory_chat_31222005 = "Bueno, no hay nada en lo que necesite ayuda...",
  str_homestory_chat_31222006 = "Déjame pensarlo...",
  str_homestory_chat_31222007 = "Oh, tengo una idea.",
  str_homestory_chat_31222008 = "¿Has oído hablar de la terapia de masaje frío?",
  str_homestory_chat_31222009 = "Colocando cubos de hielo en las partes adecuadas para relajar el cuerpo...",
  str_homestory_chat_31222010 = "¡Eso suena como un trabajo que puedo hacer fácilmente!",
  str_homestory_chat_31222011 = "Se siente un poco aterrador para mí cuando lo haces.",
  str_homestory_chat_31222012 = "¿Qué? ¿No quieres decir agradable?!",
  str_homestory_chat_31222013 = "Sin embargo, cuando termino de patrullar...",
  str_homestory_chat_31222014 = "Tal vez sí necesite un masaje.",
  str_homestory_chat_31222015 = "¡Maravilloso, te mostraré mis habilidades!",
  str_homestory_chat_31223001 = "Saliendo a dar un paseo.",
  str_homestory_chat_31223002 = "¿Puedo ir contigo?",
  str_homestory_chat_31223003 = "Seguro.",
  str_homestory_chat_31223004 = "¿A dónde vas, Navegante?",
  str_homestory_chat_31223005 = "¡La playa!",
  str_homestory_chat_31223006 = "¡Distrito comercial!",
  str_homestory_chat_31223007 = "Nunca he estado en ninguno de los dos...",
  str_homestory_chat_31223008 = "También es tu sueño ver el mundo, ¿verdad?",
  str_homestory_chat_31223009 = "Son lugares muy interesantes.",
  str_homestory_chat_31223010 = "Entonces, dame un minuto para prepararme.",
  str_homestory_chat_31224001 = "Yendo a ver a un amigo.",
  str_homestory_chat_31224002 = "¿Estás visitando No. 33, Navegante?",
  str_homestory_chat_31224003 = "Como sabes eso?",
  str_homestory_chat_31224004 = "Solo una corazonada.",
  str_homestory_chat_31224005 = "Estaba con No. 33 hace unos minutos.",
  str_homestory_chat_31224006 = "Tengo la sensación de que a No. 33 le importas mucho.",
  str_homestory_chat_31224007 = "Probablemente sea por Alina.",
  str_homestory_chat_31224008 = "No. 33 probablemente la vio en mí.",
  str_homestory_chat_31224009 = "Aunque yo también me siento así.",
  str_homestory_chat_31224010 = "Aunque sé que No. 33 nunca podría reemplazar a Alina...",
  str_homestory_chat_31224011 = "Si es posible, aún me gustaría ser su hermana.",
  str_homestory_chat_31225001 = "Finalicemos el plan para el próximo viaje.",
  str_homestory_chat_31225002 = "Hablando de eso, las fotos del último viaje... \"Fotos\" es la palabra correcta, ¿verdad?",
  str_homestory_chat_31225003 = "Sí, correcto.",
  str_homestory_chat_31225004 = "Solo estaba mirando las fotos.",
  str_homestory_chat_31225005 = "La tecnología moderna es realmente asombrosa.",
  str_homestory_chat_31225006 = "¿Cómo logra una máquina tan pequeña \"almacenar\" personas y paisajes?",
  str_homestory_chat_31225007 = "Es bastante complicado de explicar...",
  str_homestory_chat_31225008 = "Si estás interesado, Zarya, puedes hablar con Antony sobre eso.",
  str_homestory_chat_31225009 = "Él estará encantado de responder a tus preguntas.",
  str_homestory_chat_31399999 = "No. 33 en espera. Por favor, ingrese el comando.",
  str_homestory_chat_31321001 = "Descansa.",
  str_homestory_chat_31321002 = "Error de comando.",
  str_homestory_chat_31321003 = "La espera es descansar.",
  str_homestory_chat_31321004 = "Según el cálculo, no es necesario que cambie al modo de dormir en este momento.",
  str_homestory_chat_31321005 = "¿No te cansas para nada?",
  str_homestory_chat_31321006 = "Gracias por tu preocupación, pero no me siento fatigado en este momento.",
  str_homestory_chat_31321007 = "Sin más instrucciones, permaneceré en espera.",
  str_homestory_chat_31322001 = "Realiza una patrulla.",
  str_homestory_chat_31322002 = "Comando reconocido. Ejecutando la lista de misiones ahora.",
  str_homestory_chat_31322003 = "¡¿Espera, eso realmente funcionó?!",
  str_homestory_chat_31322004 = "Solo estaba bromeando...",
  str_homestory_chat_31322005 = "¿No confías en mi habilidad para cumplir misiones?",
  str_homestory_chat_31322006 = "Según registros acumulativos, he realizado un total de 5,005 patrullas y tengo mucha experiencia.",
  str_homestory_chat_31322007 = "No es que no confíe en ti, No. 33.",
  str_homestory_chat_31322008 = "Pero es mi deber. Tengo que hacerlo yo mismo.",
  str_homestory_chat_31322009 = "Entiendo. Respeto tu decisión.",
  str_homestory_chat_31323001 = "No ingresar nada.",
  str_homestory_chat_31323002 = "Por favor, ingrese el comando.",
  str_homestory_chat_31323003 = "Repetir, por favor ingrese el comando.",
  str_homestory_chat_31323004 = "¿Te confunde la frase \"Ingresar comando\"?",
  str_homestory_chat_31323005 = "Buscando una expresión más apropiada...",
  str_homestory_chat_31323006 = "\"Por favor, avísame si hay algo que necesites que haga.\"",
  str_homestory_chat_31323007 = "Bueno, no tengo nada urgente ahora mismo...",
  str_homestory_chat_31323008 = "Muy bien. Por favor, infórmame cuando tengas una necesidad.",
  str_homestory_chat_31323009 = "No. 33 te servirá durante todo el tiempo.",
  str_homestory_chat_31324001 = "Ve a pasar el rato con un amigo.",
  str_homestory_chat_31324002 = "Me gusta...",
  str_homestory_chat_31324003 = "Zarya.",
  str_homestory_chat_31324004 = "¿Extrañar a Zarya? Ella es, de hecho, una compañera muy importante para mí.",
  str_homestory_chat_31324005 = "Programaré nuevos programas de entrenamiento en Luminática para que ella mejore su poder.",
  str_homestory_chat_31324006 = "No, eso no es. Solo pasa el rato y charla con ella.",
  str_homestory_chat_31324007 = "Antony.",
  str_homestory_chat_31324008 = "Creo que tú y el Sr. Antony tendrán mucho de qué hablar.",
  str_homestory_chat_31324009 = "Si te refieres al dominio del conocimiento, estoy de acuerdo.",
  str_homestory_chat_31324010 = "Aunque basado en nuestros cincuenta encuentros anteriores...",
  str_homestory_chat_31324011 = "Creo que quizás está más intrigado por mis composiciones estructurales y tecnológicas.",
  str_homestory_chat_31324012 = "Sin embargo, es posible que él pueda deducir la información que he olvidado...",
  str_homestory_chat_31324013 = "¡Eso suena perfecto!",
  str_homestory_chat_31324014 = "Entonces deberías irte, No. 33.",
  str_homestory_chat_31324015 = "También debería seguir adelante con otra cosa.",
  str_homestory_chat_28899999 = "May ¿Puedo preguntar qué estás haciendo ahora mismo?",
  str_homestory_chat_28801001 = "De hecho, estaba a punto de preguntarte cómo te has estado adaptando a la vida por aquí.",
  str_homestory_chat_28801002 = "Este lugar es muy diferente a las otras ciudades de Astra, y ni hablar de las ciudades en Longzhou.",
  str_homestory_chat_28801003 = "Hay algo único en este lugar.",
  str_homestory_chat_28801004 = "¿Único?",
  str_homestory_chat_28801005 = "Algo muy tranquilo, que hace que uno olvide todas las luchas del mundo exterior.",
  str_homestory_chat_28801006 = "Entonces parece que te has acostumbrado aquí... Me alegra saberlo.",
  str_homestory_chat_28821001 = "¿Flores creciendo?",
  str_homestory_chat_28821002 = "Sí. May ¿Pregunto si también hay flores exóticas aquí?",
  str_homestory_chat_28821003 = "Si",
  str_homestory_chat_28821004 = "¿Me llevarás a verlos?",
  str_homestory_chat_28821005 = "Claro, pero... los Chubbs están cuidándolos ahora.",
  str_homestory_chat_28821006 = "Ya veo... Las flores raras naturalmente requieren mucho más cuidado y protección.",
  str_homestory_chat_28821007 = "¡Pero aún hay muchas otras plantas y flores para ver aquí en Eraveil! ¡Siéntete libre de echar un vistazo!",
  str_homestory_chat_28821008 = "Gracias por informarme, PlayerName.",
  str_homestory_chat_28821009 = "No",
  str_homestory_chat_28821010 = "Qué lástima. Parece que tendré que buscar una nueva misión ahora...",
  str_homestory_chat_28821011 = "Llenemos Eraveil con un mar de flores de Longzhou, ¡como las begonias! ¿Qué te parece?",
  str_homestory_chat_28821012 = "Lo pensare.",
  str_homestory_chat_28822001 = "¿Trasteando con un dispositivo?",
  str_homestory_chat_28822002 = "Un dispositivo compuesto por todo tipo de mecanismos más pequeños, para ser exactos. Escuché que hay muchas cosas así aquí en Astra.",
  str_homestory_chat_28822003 = "¿Cómo qué?",
  str_homestory_chat_28822004 = "Una vez vi un reloj elaborado expertamente, que no solo mostraba la hora sino que también producía un pequeño pájaro.",
  str_homestory_chat_28822005 = "¿Un pajarito?",
  str_homestory_chat_28822006 = "Así es. Cada hora, un pequeño pájaro salía con un \"ding\" y cantaba para señalar la hora.",
  str_homestory_chat_28822007 = "¿Un \"ding\"? Pensé que sonaba más como un \"cu-cú\"...",
  str_homestory_chat_28822008 = "¡Sí! ¡Ese fue el sonido que hizo!",
  str_homestory_chat_28822009 = "Oh, ese es un reloj de cuco. Son bastante interesantes, sí.",
  str_homestory_chat_28822010 = "Entonces, ¿cuándo puedo instalar uno en mi habitación?",
  str_homestory_chat_28822011 = "Eh... Esos pueden ser bastante caros, pero lo pensaré...",
  str_homestory_chat_28823001 = "¿Preparando una bebida?",
  str_homestory_chat_28823002 = "Sí. Desde que llegué aquí, he extrañado muchas cosas de mi tierra natal, incluyendo las bebidas.",
  str_homestory_chat_28823003 = "¿Tienes alguna recomendación de bebida tú mismo, PlayerName?",
  str_homestory_chat_28823004 = "té negro",
  str_homestory_chat_28823005 = "También tenemos este tipo de té en Astra y he escuchado que a muchas personas les encanta.",
  str_homestory_chat_28823006 = "Pero... la gente aquí está más preocupada por los bocadillos que acompañan a su té...",
  str_homestory_chat_28823007 = "Ya veo. También tendré que considerar eso.",
  str_homestory_chat_28823008 = "Refresco.",
  str_homestory_chat_28823009 = "¿Qué es eso...?",
  str_homestory_chat_28823010 = "Es una bebida ligeramente dulce con una sensación en boca realmente interesante.",
  str_homestory_chat_28823011 = "¿Y qué tipo de sensación en la boca sería esa?",
  str_homestory_chat_28823012 = "Se siente como un montón de burbujitas bailando en tu lengua. ¡Incluso te hace eructar si lo bebes demasiado rápido!",
  str_homestory_chat_28823013 = "Eso suena un poco más allá de mis gustos...",
  str_homestory_chat_28824001 = "¿Preparando desayuno?",
  str_homestory_chat_28824002 = "Sí. El desayuno es muy importante para la salud de uno. \"Las comidas del día comienzan con el amanecer\", como dice el refrán.",
  str_homestory_chat_28824003 = "Qué dicho más raro...",
  str_homestory_chat_28824004 = "También encuentro algunas costumbres de desayuno de Astra un poco raras.",
  str_homestory_chat_28824005 = "Por ejemplo, escuché que en Rediesel Wrench comen brochetas a la parrilla para el desayuno, mientras que algunas personas en Umbraton solo beben agua por la mañana.",
  str_homestory_chat_28824006 = "Eh... La verdad es que esos son solo un par de casos especiales.",
  str_homestory_chat_28824007 = "¿Las brochetas a la parrilla?",
  str_homestory_chat_28824008 = "Eso es solo una preferencia personal de cierta persona en la Rediesel Wrench...",
  str_homestory_chat_28824009 = "¿Y el agua?",
  str_homestory_chat_28824010 = "E-Ejem, estoy bastante seguro de que están tratando de perder peso o reducir sus gastos diarios.",
  str_homestory_chat_28824011 = "De cualquier manera, esas no son muy buenas representaciones de los hábitos normales de desayuno en Astra.",
  str_homestory_chat_28824012 = "Entonces, ¿cómo es un desayuno normal?",
  str_homestory_chat_28824013 = "Pan, leche, huevos, ese tipo de cosas.",
  str_homestory_chat_28824014 = "Ya veo. Esos suenan mucho más razonables, aunque aún difieren bastante de nuestros propios alimentos para el desayuno.",
  str_homestory_chat_28799999 = "¿Qué pasa?",
  str_homestory_chat_28701001 = "Te ves bastante libre en este momento.",
  str_homestory_chat_28701002 = "¿Qué? En realidad tengo algo muy importante que discutir contigo.",
  str_homestory_chat_28701003 = "¿Yo?",
  str_homestory_chat_28701004 = "¡Sí, tú! ¡Necesito decirte tu fortuna ahora mismo!",
  str_homestory_chat_28701005 = "Suena como si te lo acabaras de inventar...",
  str_homestory_chat_28701006 = "¡Por supuesto que no! Se me ocurrió esto mucho antes, quiero decir, he estado preocupado por ti desde hace bastante tiempo.",
  str_homestory_chat_28701007 = "Por lo que puedo ver, tu fortuna indica que eres propenso a las distracciones de manera crítica...",
  str_homestory_chat_28701008 = "¿En serio?",
  str_homestory_chat_28701009 = "¡Sí! Y para muchos, la causa de este trastorno grave es un exceso de tiempo libre...",
  str_homestory_chat_28701010 = "¡Ahora simplemente me estás llamando perezoso, verdad?!",
  str_homestory_chat_28701011 = "Así es.",
  str_homestory_chat_28721001 = "¿Cómo te sientes acerca de este lugar?",
  str_homestory_chat_28721002 = "Debo decir, el feng shui aquí es realmente notable...",
  str_homestory_chat_28721003 = "Mi adivinación me dice que este lugar es perfectamente adecuado para vivir en paz y seguridad.",
  str_homestory_chat_28721004 = "Es especialmente adecuado para criar todo tipo de animales, como por ejemplo pájaros...",
  str_homestory_chat_28721005 = "¿Quieres mantener pájaros aquí?",
  str_homestory_chat_28721006 = "¡Así es! May ¿Pregunto si hay otros pájaros espíritus aquí?",
  str_homestory_chat_28721007 = "Sí.",
  str_homestory_chat_28721008 = "No.",
  str_homestory_chat_28721009 = "Ah... Qué pena.",
  str_homestory_chat_28721010 = "Aun así, tengo que preguntar... ¿Por qué quieres tener más pájaros?",
  str_homestory_chat_28721011 = "Esperaba darles a Squawk y Jabber nuevos compañeros. Después de todo, ellos también han estado aquí por mucho tiempo.",
  str_homestory_chat_28721012 = "Compañeros, ¿eh...? Parece que realmente no necesitan a nadie más que a ti.",
  str_homestory_chat_28721013 = "Para adaptarse adecuadamente a las costumbres de Astra, naturalmente también necesitan compañeros de Astra.",
  str_homestory_chat_28721014 = "Y con nuevos amigos, tal vez no se queden a mi lado cada hora del día.",
  str_homestory_chat_28721015 = "Parece que simplemente necesitas un descanso de ellos.",
  str_homestory_chat_28722001 = "¿Comprando dulces?",
  str_homestory_chat_28722002 = "¡Claro! Después de comer y dormir bien, me sentí renovado y listo para un pequeño capricho.",
  str_homestory_chat_28722003 = "Mis pensamientos divagaron hacia las figuritas de azúcar hechas por los adivinos de mi tierra natal, así que pensé en preguntarles a los Chubbs sobre ellas...",
  str_homestory_chat_28722004 = "¡Solo para descubrir que apenas hay dulces aquí! ¿A la gente de Astra no les gustan tanto?",
  str_homestory_chat_28722005 = "¡Para nada! ¡Lumopolis y Umbraton son famosos por algunos de sus postres!",
  str_homestory_chat_28722006 = "De hecho, tienen todo tipo de pasteles con diseños hermosos...",
  str_homestory_chat_28722007 = "¿Hay bollos dulces con figuritas de azúcar?",
  str_homestory_chat_28722008 = "Es pastel.",
  str_homestory_chat_28722009 = "Ambos son postres, así que para mí es lo mismo.",
  str_homestory_chat_28722010 = "...No importa. En cualquier caso, hay muchos pasteles con bonitos patrones de flores en ellos.",
  str_homestory_chat_28722011 = "En cuanto a las figuritas de azúcar... creo que nunca he visto ninguna.",
  str_homestory_chat_28722012 = "Entonces parece que tendré que mostrar mis talentos únicos muy pronto. ¿Cuándo puedes llevarme a ver estas tortas?",
  str_homestory_chat_28722013 = "Uh... Probablemente no en unos días.",
  str_homestory_chat_28723001 = "¿Estás planeando algo?",
  str_homestory_chat_28723002 = "De hecho, lo soy. ¿Te llamó la atención mi bandera? ¿Qué te parece?",
  str_homestory_chat_28723003 = "Esta bien...",
  str_homestory_chat_28723004 = "¡Ojos agudos!",
  str_homestory_chat_28723005 = "Sin duda, es una bandera increíble.",
  str_homestory_chat_28723006 = "Simplemente parece una bandera ordinaria.",
  str_homestory_chat_28723007 = "Suspiro... simplemente no puedes ver la grandeza frente a tus ojos.",
  str_homestory_chat_28723008 = "Esta bandera contiene un poder inmenso: la sabiduría de los cielos arriba y el conocimiento de la tierra abajo...",
  str_homestory_chat_28723009 = "¿Acabas de...",
  str_homestory_chat_28723010 = "En cualquier caso, es una bandera muy poderosa y extraordinaria.",
  str_homestory_chat_28723011 = "Por esta razón, eres más que bienvenido a colocarlo en esa torre y usarlo como tu bandera de mando.",
  str_homestory_chat_28723012 = "Tal vez deberías aferrarte a ello...",
  str_homestory_chat_31499999 = "¿Qué estás haciendo, Navegante?",
  str_homestory_chat_31421001 = "Solo pensando en tomar un descanso...",
  str_homestory_chat_31421002 = "¿Un descanso? Tu rostro sí parece que le falta algo de color.",
  str_homestory_chat_31421003 = "¿Te sientes enfermo en absoluto?",
  str_homestory_chat_31421004 = "Sí, un poco...",
  str_homestory_chat_31421005 = "Aquí, ¿por qué no me dejas hacerte un rápido examen?",
  str_homestory_chat_31421006 = "No, en absoluto...",
  str_homestory_chat_31421007 = "Está bien, lo prometo. Como médico, generalmente puedo saber cuándo alguien no se siente bien.",
  str_homestory_chat_31421008 = "Hmm... A primera vista, nada parece fuera de lo común.",
  str_homestory_chat_31421009 = "Es posible que últimamente te hayas estado esforzando demasiado. Recuerda darle a tu cuerpo suficiente tiempo para descansar.",
  str_homestory_chat_31421010 = "¿Necesitas que te acompañe a tu habitación?",
  str_homestory_chat_31421011 = "No gracias, puedo llegar allí yo mismo.",
  str_homestory_chat_31421012 = "Seguro.",
  str_homestory_chat_31421013 = "Si alguna vez te sientes mal... No dudes en decírmelo.",
  str_homestory_chat_31422001 = "Estaba a punto de dar un paseo.",
  str_homestory_chat_31422002 = "Un paseo... Eso es bueno.",
  str_homestory_chat_31422003 = "Por cierto, ¿normalmente vas a caminar solo?",
  str_homestory_chat_31422004 = "¿Quieres venir?",
  str_homestory_chat_31422005 = "¿Te parece bien? Hace tiempo que quería dar un paseo contigo.",
  str_homestory_chat_31422006 = "¡Seguro!",
  str_homestory_chat_31422007 = "Sí, prefiero ir solo.",
  str_homestory_chat_31422008 = "Estoy de acuerdo, un poco de soledad realmente puede ayudar a una persona a organizar sus pensamientos.",
  str_homestory_chat_31422009 = "Lamentablemente... tengo mucho trabajo que hacer ahora mismo.",
  str_homestory_chat_31422010 = "De lo contrario, me hubiera gustado dar un paseo contigo.",
  str_homestory_chat_31422011 = "Ya veo, ¡entonces no permitas que te distraiga de tu trabajo!",
  str_homestory_chat_31422012 = "Hasta la próxima.",
  str_homestory_chat_31423001 = "Intentando terminar mi trabajo.",
  str_homestory_chat_31423002 = "Debe ser difícil para ti a veces. Solo recuerda no esforzarte demasiado.",
  str_homestory_chat_31423003 = "Excederse a veces puede tener el efecto contrario.",
  str_homestory_chat_31423004 = "Puedes confiar en mí en eso.",
  str_homestory_chat_31423005 = "Estoy seguro de que lo sabes, pero atiendo a muchos pacientes todos los días.",
  str_homestory_chat_31423006 = "Al principio, no presté atención a las demandas de mi cuerpo. Solo quería tratar a tantas personas como fuera posible...",
  str_homestory_chat_31423007 = "Afortunadamente, pude salvarlos a todos al final.",
  str_homestory_chat_31423008 = "Pero terminé colapsando de agotamiento bastante rápido...",
  str_homestory_chat_31423009 = "No me di cuenta de que podía ponerse tan mal.",
  str_homestory_chat_31423010 = "Puede ser, por eso necesitas conocer tus propios límites.",
  str_homestory_chat_31424001 = "¡Estoy planeando una cena!",
  str_homestory_chat_31424002 = "¿Una... cena de fiesta?",
  str_homestory_chat_31424003 = "¿Hay algún problema?",
  str_homestory_chat_31424004 = "No, solo... Me hizo recordar algunas cosas.",
  str_homestory_chat_31424005 = "En el pasado, solíamos tener muchas cenas familiares entre nosotros.",
  str_homestory_chat_31424006 = "Mirando hacia atrás, parece que teníamos uno casi todos los días.",
  str_homestory_chat_31424007 = "¡Tu familia debió ser realmente grande!",
  str_homestory_chat_31424008 = "Supongo que es cierto, al menos desde el punto de vista de los números...",
  str_homestory_chat_31424009 = "Pero ahora solo somos mi hermana y yo...",
  str_homestory_chat_31424010 = "¿Quieres unirte a nosotros?",
  str_homestory_chat_31424011 = "¿Eh? ¿Yo? No, yo... creo que voy a pasar...",
  str_homestory_chat_31424012 = "Más o menos me he acostumbrado a comer solo.",
  str_homestory_chat_31424013 = "Rebecca...",
  str_homestory_chat_31424014 = "Lo siento, creo que dije demasiado...",
  str_homestory_chat_31424015 = "Por favor, discúlpame...",
  str_homestory_chat_31425001 = "Solo buscando relajarme un poco.",
  str_homestory_chat_31425002 = "\"¿Relax?\" Ya veo...",
  str_homestory_chat_31425003 = "Tampoco creo haber tenido la oportunidad de relajarme en mucho tiempo.",
  str_homestory_chat_31425004 = "¿Podría preguntar qué sueles hacer para aliviar el estrés?",
  str_homestory_chat_31425005 = "¡De compras de ropa!",
  str_homestory_chat_31425006 = "Comprar ropa, eh...",
  str_homestory_chat_31425007 = "¿Tal vez también sea hora de actualizar mi guardarropa?",
  str_homestory_chat_31425008 = "¡Comiendo comida sabrosa!",
  str_homestory_chat_31425009 = "Comiendo, eh...",
  str_homestory_chat_31425010 = "También he pensado en intentar eso, pero no estoy en la mejor forma para hacerlo.",
  str_homestory_chat_31425011 = "Salir a comer... a veces puede afectarme muy mal.",
  str_homestory_chat_31425012 = "Eso suena realmente inconveniente...",
  str_homestory_chat_31425013 = "Después de charlar contigo, de repente me dan ganas de salir a hacer algunas compras.",
  str_homestory_chat_31425014 = "Pero tengo que volver a la clínica pronto...",
  str_homestory_chat_31425015 = "Está bien, ¡siempre hay una próxima vez!",
  str_homestory_chat_31425016 = "Está bien entonces. Me iré ahora.",
  str_homestory_chat_31425017 = "Espero que te sientas mejor hoy también.",
  str_homestory_chat_31599999 = "¿Qué haces, Navegador?",
  str_homestory_chat_31521001 = "Estaba a punto de hacer un poco de entrenamiento.",
  str_homestory_chat_31521002 = "Entrenamiento, ¿eh? ¿Necesitas un compañero?",
  str_homestory_chat_31521003 = "¡Incluso te haré un trato! ¡Veinte por ciento de descuento para un compañero de entrenamiento de primera clase!",
  str_homestory_chat_31521004 = "Estaré bien por mi cuenta.",
  str_homestory_chat_31521005 = "No, gracias...",
  str_homestory_chat_31521006 = "¿Qué? ¿Incluso después de ofrecerte un descuento tan generoso?",
  str_homestory_chat_31521007 = "Está bien, de todos modos tengo suficiente trabajo con el que lidiar.",
  str_homestory_chat_31521008 = "No seguiré presionándote al respecto.",
  str_homestory_chat_31521009 = "¡Llámame si alguna vez necesitas un compañero de entrenamiento! ¡Nos vemos!",
  str_homestory_chat_31522001 = "Estaba a punto de hacer algo de lectura.",
  str_homestory_chat_31522002 = "¿Lectura? Eso suena como algo que tú harías.",
  str_homestory_chat_31522003 = "Aunque realmente no me interesan mucho los libros.",
  str_homestory_chat_31522004 = "¿Quieres decir que no lees a menudo?",
  str_homestory_chat_31522005 = "¡N-No es como si nunca leyera o algo así!",
  str_homestory_chat_31522006 = "Simplemente prefiero pensar en cosas cuando tengo tiempo libre.",
  str_homestory_chat_31522007 = "Pero ahora que lo mencionas...",
  str_homestory_chat_31522008 = "Compré unos cómics de un vendedor ambulante el otro día, ¡y realmente son algo especial!",
  str_homestory_chat_31522009 = "Se trata de dos hermanas que dependen una de la otra para sobrevivir, pero un día se separan...",
  str_homestory_chat_31522010 = "Y al final, ellos... ¡Vaya, eso estuvo cerca!",
  str_homestory_chat_31522011 = "¡Si hubiera contado más, habría arruinado toda la historia!",
  str_homestory_chat_31522012 = "De todos modos, deberías echarles un vistazo cuando tengas tiempo.",
  str_homestory_chat_31522013 = "Olvidé el nombre de las historietas, pero no deberían ser demasiado difíciles de encontrar.",
  str_homestory_chat_31523001 = "Realmente no.",
  str_homestory_chat_31523002 = "¿Aburrido?",
  str_homestory_chat_31523003 = "¿Quieres venir a cobrar deudas conmigo?",
  str_homestory_chat_31523004 = "¡Es muy divertido, sabes!",
  str_homestory_chat_31523005 = "Creo que paso.",
  str_homestory_chat_31523006 = "No te preocupes, es totalmente seguro.",
  str_homestory_chat_31523007 = "Y conmigo cerca, tampoco tendrás que hacer mucho.",
  str_homestory_chat_31523008 = "Que necesitas que haga?",
  str_homestory_chat_31523009 = "No te preocupes, no tendrás que hacer mucho conmigo cerca.",
  str_homestory_chat_31523010 = "Todo lo que tienes que hacer es sacar pecho y lucir más amenazante.",
  str_homestory_chat_31523011 = "Solo necesitas actuar de manera intimidante.",
  str_homestory_chat_31523012 = "Deja el resto a un profesional como yo, ¿de acuerdo?",
  str_homestory_chat_31523013 = "Eso suena algo divertido.",
  str_homestory_chat_31523014 = "¿Verdad? ¡Así que ahora solo tienes que pagar y podemos irnos!",
  str_homestory_chat_31523015 = "Espera, ¿tengo que pagar por esto?",
