  str_homestory_chat_31523017 = "Creo que todavía necesito pensarlo.",
  str_homestory_chat_31523018 = "¿Eh? ?",
  str_homestory_chat_31524001 = "Preparándome para tomar un descanso.",
  str_homestory_chat_31524002 = "¿Tomar un descanso?",
  str_homestory_chat_31524003 = "Entonces, ¿qué demonios haces en tus días libres?!",
