  str_homestory_chat_31524005 = "¡Eso es una pérdida de tiempo!",
  str_homestory_chat_31524006 = "Juega juegos.",
  str_homestory_chat_31524007 = "Ya veo. Supongo que eso es bastante normal.",
  str_homestory_chat_31524008 = "Me gusta mantenerme ocupado y activo en mis días libres.",
  str_homestory_chat_31524009 = "¡No puedo permitirme perder ni un segundo!",
  str_homestory_chat_31524010 = "Entonces, ¿qué sueles hacer?",
  str_homestory_chat_31524011 = "¡Pasar tiempo con mi preciosa familia, por supuesto!",
  str_homestory_chat_31524012 = "Para mí, incluso si solo estoy mirando a Rebecca mientras duerme...",
  str_homestory_chat_31524013 = "¡Es un uso significativo de mi tiempo!",
  str_homestory_chat_31524014 = "¡Y también cuenta como protegerla!",
  str_homestory_chat_31524015 = "Seguro que eres un gran trabajador, Isa.",
  str_homestory_chat_31699999 = "Oye, ¿en qué estás ocupado?",
  str_homestory_chat_31621001 = "Voy a limpiar mi habitación.",
  str_homestory_chat_31621002 = "Limpieza de habitación, eh...",
  str_homestory_chat_31621003 = "¿Por qué ensuciar tus manos con eso cuando puedes usar una marioneta de relojería?",
  str_homestory_chat_31621004 = "Entonces, ¿quieres poner a trabajar uno de mis inventos?",
  str_homestory_chat_31621005 = "Está bien, puedo hacerlo yo mismo.",
  str_homestory_chat_31621006 = "¿Seguro? Supongo que eres del tipo que disfruta ordenando cosas y esas cosas.",
  str_homestory_chat_31621007 = "Te dejo disfrutar entonces.",
  str_homestory_chat_31621008 = "Lo mismo sigue vigente: Llámame cuando me necesites.",
  str_homestory_chat_31621009 = "Está bien...",
  str_homestory_chat_31621010 = "Volveré ahora y lo prepararé.",
  str_homestory_chat_31621011 = "No olvides llevar contigo cualquier cosa frágil, ya que no quiero ser responsable.",
  str_homestory_chat_31621012 = "Te veo en un rato.",
  str_homestory_chat_31622001 = "Quiero dar un paseo.",
  str_homestory_chat_31622002 = "¿Un paseo? Hace calor afuera y te quemarás con el sol.",
