  str_homestory_chat_31623008 = "No lo creas.",
  str_homestory_chat_31623009 = "Pero es posible que te lastimes por ello...",
  str_homestory_chat_31623010 = "¿Qué tipo de artilugio es?",
  str_homestory_chat_31623011 = "Almacena muchas cuentas y se autodestruye en caso de emergencia—",
