  str_homestory_chat_31623016 = "Lo siento, tengo que hacer esto solo.",
  str_homestory_chat_31624001 = "Vamos a pasar el rato en la sala de recreación en un minuto.",
  str_homestory_chat_31624002 = "¿La sala de recreación? ¡Hay demasiadas cosas para hacer allí!",
  str_homestory_chat_31624003 = "¿Prefieres algo intenso o algo relajante?",
  str_homestory_chat_31624004 = "Intenso.",
