  str_homestory_chat_31625002 = "¿Qué tal si probamos la comida callejera?",
  str_homestory_chat_31625003 = "Nadie conoce la comida callejera más que yo.",
  str_homestory_chat_31625004 = "Además de construir gadgets, lo que hago es ir de compras y comer comida callejera.",
  str_homestory_chat_31625005 = "¿Te gusta eso?",
  str_homestory_chat_31625006 = "Tengo un gusto sorprendentemente diverso.",
