  str_homestory_chat_31923001 = "Estoy revisando el libro mayor.",
  str_homestory_chat_31923002 = "¿Hay un problema con eso? Puedo ayudar si es necesario.",
  str_homestory_chat_31923003 = "¿Te importaría echar un vistazo entonces?",
  str_homestory_chat_31923004 = "Claro, el placer es todo mío.",
  str_homestory_chat_31923005 = "Permíteme quitarte la carga de tu mano...",
  str_homestory_chat_31923006 = "Ya veo. El libro mayor está bastante mal llevado y organizado.",
  str_homestory_chat_31923007 = "no quiero molestarte...",
  str_homestory_chat_31923008 = "Está bien, lo entiendo. Pero para ser honesto, el libro mayor es vital para cualquier institución.",
  str_homestory_chat_31923009 = "Tengo suficiente experiencia en la gestión de cuentas, ¿puedo hacer algunas sugerencias?",
  str_homestory_chat_31923010 = "¿En serio? ¡Cualquier sugerencia de Lady Sheol sería de gran ayuda para mí!",
  str_homestory_chat_31923011 = "¡Gracias!",
  str_homestory_chat_31923012 = "Jejeje, de nada.",
  str_homestory_chat_31923013 = "Son solo pequeños consejos y pistas.",
  str_homestory_chat_31923014 = "Debe ser lo más detallado posible con cada entrada, pero también conciso.",
  str_homestory_chat_31923015 = "No hace falta decir que las fechas y los propósitos deben enumerarse en columnas separadas. Además, registrar las cantidades en dos formatos puede reducir la posibilidad de errores.",
  str_homestory_chat_31923016 = "De esta manera, es mucho más fácil revisar.",
  str_homestory_chat_31923017 = "Comprendo.",
  str_homestory_chat_31923018 = "Además...",
  str_homestory_chat_31923019 = "¡Espera! ¡Necesito escribir esto!",
  str_homestory_chat_31924001 = "Tengo sed y quiero algo para beber.",
  str_homestory_chat_31924002 = "¿Qué tal un café?",
  str_homestory_chat_31924003 = "¿Café?",
  str_homestory_chat_31924004 = "Sí, acabo de comprar unos buenos granos de café.",
  str_homestory_chat_31924005 = "Sería genial obtener una segunda opinión.",
  str_homestory_chat_31924006 = "Pero no sé mucho sobre el café...",
  str_homestory_chat_31924007 = "Está bien. Solo dime qué piensas después de beberlo.",
  str_homestory_chat_31924008 = "No me importa intentarlo si eso es todo lo que se necesita.",
  str_homestory_chat_31924009 = "¿Te gusta el café, Señora Sheol?",
  str_homestory_chat_31924010 = "No especialmente, pero tampoco lo odio.",
  str_homestory_chat_31924011 = "Entonces, ¿por qué compraste los frijoles en lugar de café molido?",
  str_homestory_chat_31924012 = "Sin razón en particular. Los granos de café son una de las muchas empresas comerciales del Gremio Cloudrover, de todos modos.",
  str_homestory_chat_31924013 = "Acabo de tener el impulso de probarlo por mí mismo.",
  str_homestory_chat_31925001 = "Es mi turno de estudiar a continuación.",
  str_homestory_chat_31925002 = "¿Hora de estudio?",
  str_homestory_chat_31925003 = "En otras palabras, lee libros.",
  str_homestory_chat_31925004 = "Entiendo. May ¿Puedo preguntar qué tipo de libros planeas leer?",
  str_homestory_chat_31925005 = "Historia y geografía.",
  str_homestory_chat_31925006 = "También sé un poco sobre estos temas. May ¿Te hago algunas recomendaciones?",
  str_homestory_chat_31925007 = "¿Eres conocedora en tales campos, Señora Sheol?",
  str_homestory_chat_31925008 = "Como comerciante, cuanto más sé, mejor. Así, puedo conversar con clientes de diferentes oficios.",
  str_homestory_chat_31925009 = "Uno tiene que trabajar duro para ser un gran comerciante, veo.",
  str_homestory_chat_31925010 = "Economía.",
  str_homestory_chat_31925011 = "¿Oh? ¿Estás interesado en economía?",
  str_homestory_chat_31925012 = "No tanto interesado, sino curioso.",
  str_homestory_chat_31925013 = "Por no mencionar que siempre es mejor leer más libros.",
  str_homestory_chat_31925014 = "Exactamente.",
  str_homestory_chat_31925015 = "Tengo muchos buenos libros de mi colección personal que puedo recomendar.",
  str_homestory_chat_31925016 = "Por favor, pasa alguna vez.",
  str_homestory_chat_32099999 = "¡Quiero amueblar de nuevo mi oficina! ¿Qué estilo crees que funciona mejor?",
  str_homestory_chat_32021001 = "¡Estilo Northland!",
  str_homestory_chat_32021002 = "¿Oh? Bueno, gran parte de Northland parece sacado de un cuento de hadas, especialmente sus decoraciones y arquitectura.",
  str_homestory_chat_32021003 = "No me di cuenta de que eras tan romántico.",
  str_homestory_chat_32021004 = "Eres un científico.",
  str_homestory_chat_32021005 = "Ideas románticas como esta probablemente te molestan, ¿verdad?",
  str_homestory_chat_32021006 = "Eres de la Federación Illumina.",
  str_homestory_chat_32021007 = "¿No significa eso que te opones a ideas imprácticas y románticas como esta?",
  str_homestory_chat_32021008 = "¡Qué monumental malentendido!",
  str_homestory_chat_32021009 = "Es cierto que soy un científico de la Federación Illumina...",
  str_homestory_chat_32021010 = "Entonces, es natural que todos crean que no quiero tener nada que ver con el romanticismo.",
  str_homestory_chat_32021011 = "Pero creo que esta es una visión muy estrecha de la noción.",
  str_homestory_chat_32021012 = "Para hacer lo desconocido comprensible, para convertir los páramos en ciudades...",
  str_homestory_chat_32021013 = "¿No es eso también romántico a su manera?",
  str_homestory_chat_32021014 = "Supongo que eso tiene sentido.",
  str_homestory_chat_32021015 = "No sabía que también eras un debatiente elocuente.",
  str_homestory_chat_32021016 = "También soy alguien muy bueno tomando sugerencias.",
  str_homestory_chat_32021017 = "¡Por eso he decidido redecorar mi oficina al estilo de Northland!",
  str_homestory_chat_32022001 = "¡Estilo Lumopolis!",
  str_homestory_chat_32022002 = "El estilo de Lumopolis tiene una sensación muy clásica y piadosa.",
  str_homestory_chat_32022003 = "Con todos los cables y maquinaria que atraviesan mi oficina, no estoy seguro si tal estilo de decoración sería una buena combinación...",
  str_homestory_chat_32022004 = "Pero tu personalidad está llena de contradicciones.",
  str_homestory_chat_32022005 = "¡El fuerte contraste es lo que lo hace un ajuste perfecto!",
  str_homestory_chat_32022006 = "Las cosas desparejadas también tienen un cierto encanto.",
  str_homestory_chat_32022007 = "¿Quién dice que las cosas tienen que coincidir para ser hermosas?",
  str_homestory_chat_32022008 = "¡Jajajaja! ¡Haces un buen punto!",
  str_homestory_chat_32022009 = "Tu conocimiento y percepción son cualidades extremadamente admirables.",
  str_homestory_chat_32022010 = "¿Podrían derivarse de tus innumerables viajes por el mundo?",
  str_homestory_chat_32022011 = "Estoy seguro de que también es porque nos conocemos desde hace tanto tiempo...",
  str_homestory_chat_32022012 = "¡Lo tomaré como un cumplido!",
  str_homestory_chat_32023001 = "¡Estilo Umbraton!",
  str_homestory_chat_32023002 = "¡Qué sugerencia tan complicada para ofrecer!",
  str_homestory_chat_32023003 = "Entonces dime, ¿cómo definirías exactamente el estilo de Umbraton?",
  str_homestory_chat_32023004 = "Desde mi experiencia, Umbraton tiende a enfatizar en la diversidad.",
  str_homestory_chat_32023005 = "Esa es la belleza de ello. ¿No lo ves...?",
  str_homestory_chat_32023006 = "Puede parecer solo una sugerencia aleatoria, pero cuando realmente lo piensas...",
  str_homestory_chat_32023007 = "¡Es la idea perfecta que abarca todas las sugerencias!",
  str_homestory_chat_32023008 = "De hecho, ¡no tendrás que preocuparte por redecorar tu oficina nunca más! ¡Ni en los próximos cincuenta años!",
  str_homestory_chat_32023009 = "Guau... ¡A veces mis ideas son tan buenas que incluso me sorprendo a mí mismo!",
  str_homestory_chat_32023010 = "Solo estás inventando excusas porque no se te ocurrió una idea mejor, ¿verdad?",
  str_homestory_chat_32023011 = "Jeje... ¿Me delaté?",
  str_homestory_chat_32023012 = "No importa. Supongo que en parte tengo la culpa de que hayas terminado así, así que no seguiré insistiendo en el tema.",
  str_homestory_chat_32023013 = "¡Así que lo sabías todo el tiempo!",
  str_homestory_chat_32023014 = "Soy un genio en todo el sentido de la palabra. Nunca olvides eso.",
  str_homestory_chat_32024001 = "¡Estilo Longzhou!",
  str_homestory_chat_32024002 = "Vaya, no puedo creer que hayas sugerido eso...",
  str_homestory_chat_32024003 = "Siempre me ha fascinado el estilo de decoración de esa tierra lejana...",
  str_homestory_chat_32024004 = "¿Pero tienes alguna idea de cuánto costaría?",
  str_homestory_chat_32024005 = "Incluso algo tan simple como una silla de madera...",
  str_homestory_chat_32024006 = "¡Costaría lo mismo que redecorar toda mi oficina de nuevo!",
  str_homestory_chat_32024007 = "Ese tipo de lujo siempre estará fuera del alcance para personas normales como nosotros, mi amigo Caelestite.",
  str_homestory_chat_32024008 = "\"¿Gente normal\"?",
  str_homestory_chat_32024009 = "Nunca esperé escucharte referirte a ti mismo como una persona \"normal\" en mi vida...",
  str_homestory_chat_32024010 = "O para ponerte a mi nivel, en todo caso...",
  str_homestory_chat_32024011 = "¡Gracias, Longzhou!",
  str_homestory_chat_32024012 = "¿Es realmente tan caro?",
  str_homestory_chat_32024013 = "No sabía que los muebles de Longzhou fueran tan caros...",
  str_homestory_chat_32024014 = "¡Perdóname, Longzhou!",
  str_homestory_chat_32024015 = "... Ugh, gracias por recordarme que nunca lograré mis sueños de una oficina al estilo Longzhou.",
  str_homestory_chat_32024016 = "¡Ahora compénsame por mi angustia mental!",
  str_homestory_chat_32024017 = "P-Pero ¡No tengo dinero!",
  str_homestory_chat_32025001 = "¡Estilo Caelestita!",
  str_homestory_chat_32025002 = "¿Así que tu propio estilo? Qué respuesta verdaderamente inesperada.",
  str_homestory_chat_32025003 = "Me refería al estilo de mi gente, no al mío propio...",
  str_homestory_chat_32025004 = "¿Entonces estás dispuesto a redecorar personalmente mi oficina?",
  str_homestory_chat_32025005 = "¡¿Cómo sacaste esa idea de mi sugerencia?!",
  str_homestory_chat_32025006 = "Bueno, en este mundo—",
  str_homestory_chat_32025007 = "El único familiarizado con el estilo de los Caelestitas no es otro que tú mismo.",
  str_homestory_chat_32025008 = "¡N-No tenías que decirlo de esa manera!",
  str_homestory_chat_32025009 = "Además, hay muchos historiadores y arqueólogos en Lumopolis y la Federación Illumina que pueden ayudarte...",
  str_homestory_chat_32025010 = "Estoy seguro de que saben todo sobre el estilo de los Celestitas.",
  str_homestory_chat_32025011 = "Sí, pero ¿por qué querría su ayuda en lugar de la tuya...",
  str_homestory_chat_32025012 = "¿Puedes darme, digamos incluso una, razón?",
  str_homestory_chat_32025013 = "... No puedo.",
  str_homestory_chat_32025014 = "Pero puedo pensar en tres buenas razones por las que quieres mi ayuda.",
  str_homestory_chat_32025015 = "Uno, soy barato. Dos, no cobraré tanto. Y tres, te ahorraré dinero...",
  str_homestory_chat_32025016 = "¡Jajajaja! No deberías menospreciarte tanto, ¿sabes?",
  str_homestory_chat_32025017 = "Pregunto porque sabía que harías un gran trabajo decorando mi oficina.",
  str_homestory_chat_32025018 = "Y también porque disfruto tanto hablar contigo.",
  str_homestory_chat_32025019 = "¡Eso es todo!",
  str_homestory_chat_32199999 = "¿Qué deseas pedir?",
  str_homestory_chat_32121001 = "Paz mundial.",
  str_homestory_chat_32121002 = "Vaya, para que alguien haga un deseo tan desinteresado como este—",
  str_homestory_chat_32121003 = "O no te lo estás tomando en serio en absoluto...",
  str_homestory_chat_32121004 = "O realmente quieres algo tan grandioso.",
  str_homestory_chat_32121005 = "Entonces, ¿cuál se aplica a ti, PlayerName?",
  str_homestory_chat_32121006 = "No lo tomes en serio.",
  str_homestory_chat_32121007 = "Jaja, eso se ajusta a tu estilo.",
  str_homestory_chat_32121008 = "Nunca has sido de los que dejan el futuro solo a las esperanzas y deseos. Cuando realmente quieres algo, lo persigues y lo haces realidad...",
  str_homestory_chat_32121009 = "Quiero algo tan grandioso.",
  str_homestory_chat_32121010 = "En otras palabras, la paz mundial es tu verdadero objetivo en esta vida.",
  str_homestory_chat_32121011 = "Vas a grandes longitudes para asegurarte de que cada paso que das te acerca más a ese sueño...",
  str_homestory_chat_32121012 = "En todos mis miles de años, personas como tú siempre me dan los mayores dolores de cabeza.",
  str_homestory_chat_32121013 = "¿Eh? ¿Por qué?",
  str_homestory_chat_32121014 = "Porque personas como tú también son las que terminan cambiando el mundo.",
  str_homestory_chat_32122001 = "Paz y seguridad para aquellos que me son queridos.",
  str_homestory_chat_32122002 = "Escucho ese tipo de deseo en mi templo todo el tiempo.",
  str_homestory_chat_32122003 = "Me hace preguntar, ¿son felices o simplemente desafortunadas las personas que hacen este tipo de deseo?",
  str_homestory_chat_32122004 = "¡Feliz, por supuesto!",
  str_homestory_chat_32122005 = "Significa que mantienen a sus amigos y seres queridos en sus corazones, y también quieren que sean felices...",
  str_homestory_chat_32122006 = "¿Cómo podrían ser posiblemente desafortunados?",
  str_homestory_chat_32122007 = "Porque la felicidad es fugaz.",
  str_homestory_chat_32122008 = "¡...!",
  str_homestory_chat_32122009 = "La única razón por la que las personas hacen este tipo de deseo es porque son conscientes de eso, ¿no crees?",
  str_homestory_chat_32122010 = "... Tienes un punto.",
  str_homestory_chat_32122011 = "En un mundo invadido por Eclipsites, siempre corremos el riesgo de encontrarnos con desgracias inesperadas.",
  str_homestory_chat_32122012 = "Por eso quiero hacer todo lo posible para asegurarme de que mis amigos estén seguros.",
  str_homestory_chat_32122013 = "Incluso si es algo tan insignificante como pedir un deseo por ellos.",
  str_homestory_chat_32122014 = "Je. El universo es impermanente, y sin embargo, las personas a menudo encuentran fuerza y significado debido a ello.",
  str_homestory_chat_32122015 = "Esa es precisamente la razón por la que tengo tanto respeto y admiración por los mortales.",
  str_homestory_chat_32123001 = "Visitar cada rincón del mundo.",
  str_homestory_chat_32123002 = "¿Oh? Eso no es un deseo que escucho todos los días, PlayerName.",
  str_homestory_chat_32123003 = "Ya eres más que capaz de hacer eso, ¿entonces por qué convertirlo en un deseo?",
  str_homestory_chat_32123004 = "¿Podría ser que algo se interpone en el camino?",
  str_homestory_chat_32123005 = "No tengo dinero.",
  str_homestory_chat_32123006 = "\"Hay quienes viven para el ocio, pero las circunstancias de la vida niegan su alegría.\"",
  str_homestory_chat_32123007 = "¡Pero eso es fácil de resolver! ¡Solo toma algunas de mis joyas y empeña por algo de dinero!",
  str_homestory_chat_32123008 = "Hay demasiados monstruos.",
  str_homestory_chat_32123009 = "\"Un oso bloquea el camino mientras los tigres y leopardos aúllan a nuestros lados.\"",
  str_homestory_chat_32123010 = "Pero seguramente incluso los Eclipsites más duros no son rival para ti conmigo a tu lado, ¿verdad?",
  str_homestory_chat_32123011 = "Por cierto, PlayerName, ¿entiendes el significado de mis poemas?",
  str_homestory_chat_32123012 = "Sí, escuché muchos de ellos mientras viajaba por Longzhou.",
  str_homestory_chat_32123013 = "Cuanto más los veía y escuchaba, más empezaban a tener sentido.",
  str_homestory_chat_32123014 = "¡Realmente sabes cómo aprender de tus viajes, PlayerName!",
  str_homestory_chat_32123015 = "¡Gracias!",
  str_homestory_chat_32123016 = "De todos modos, ahora eres un querido amigo mío. No puedo dejarte hacer todo el trabajo pesado, ya sabes.",
  str_homestory_chat_32123017 = "¡Es por eso que seguiré viajando por el mundo y mejorándome tanto como sea posible!",
  str_homestory_chat_32123018 = "¡Bien, bien! Te estaré esperando.",
  str_homestory_chat_32124001 = "Refugiarse en el Colossus para siempre.",
  str_homestory_chat_32124002 = "¡Lo entiendo completamente! No hay nada más cómodo que acurrucarte en tu propio pequeño nido.",
  str_homestory_chat_32124003 = "¿Verdad? ¡A veces una estancia en casa es exactamente lo que necesitamos!",
  str_homestory_chat_32124004 = "Especialmente cuando hace frío y está nevando afuera, como en el invierno...",
  str_homestory_chat_32124005 = "No hay nada como acurrucarse en casa con una bebida caliente y un buen libro...",
  str_homestory_chat_32124006 = "¿Realmente haces todo eso?",
  str_homestory_chat_32124007 = "Normalmente solo duermo todo el tiempo.",
  str_homestory_chat_32124008 = "Deberías intentarlo la próxima vez.",
  str_homestory_chat_32124009 = "¡Bueno, suena interesante!",
  str_homestory_chat_32124010 = "Hmm... Primero, ¡tendré que conseguirme una manta grande y bonita!",
  str_homestory_chat_32124011 = "Tal vez lo haga a tu manera la próxima vez.",
  str_homestory_chat_32124012 = "¡Okey! ¡Incluso podemos hacerlo juntos!",
  str_homestory_chat_32124013 = "¡De esa manera, puedes despertarme a una hora razonable!",
  str_homestory_chat_32124014 = "Nunca supe que los deseos de tu corazón eran tan simples, PlayerName.",
  str_homestory_chat_32124015 = "Al principio pensé que querrías traer de vuelta a tu pueblo, o algo así...",
  str_homestory_chat_32124016 = "Es demasiado tarde para cambiar cosas así...",
  str_homestory_chat_32124017 = "Además, un deseo debería usarse para mejorar nuestras vidas y las vidas de nuestros amigos, ¿verdad?",
  str_homestory_chat_32124018 = "Precisamente. Aceptar que el pasado ha terminado es ser valiente.",
  str_homestory_chat_32125001 = "¡Para que seas feliz para siempre!",
  str_homestory_chat_32125002 = "¿Eh? ¿Realmente desperdiciarías un deseo único en la vida en mí de esa manera?",
  str_homestory_chat_32125003 = "¿Por qué?",
  str_homestory_chat_32125004 = "¡Porque los deseos deberían hacerse por el bien de nuestros amigos y familia!",
  str_homestory_chat_32125005 = "Además, es mejor luchar por las cosas que quieres en lugar de desearlas.",
  str_homestory_chat_32125006 = "... Jajaja, ¡siempre quise decir eso! Sonó bastante genial, ¿verdad?",
  str_homestory_chat_32125007 = "... Lo hizo.",
  str_homestory_chat_32125008 = "No hace falta reírse tampoco. Nunca me burlaría de ti por eso.",
  str_homestory_chat_32125009 = "¿Tal vez debería pedir un deseo también?",
  str_homestory_chat_32125010 = "¿Oh? ¿Una diosa haciendo un deseo, eh? Supongo que siempre hay una primera vez para todo!",
  str_homestory_chat_32125011 = "Por la luz del sol y la luna y la fuerza de los ríos y océanos.",
  str_homestory_chat_32125012 = "May mi amigo PlayerName disfruta de la fuerza del cuerpo, el descanso reparador y la alegría en los días venideros.",
  str_homestory_chat_32125013 = "¿Acabo de escuchar mi nombre...?",
  str_homestory_chat_32125014 = "En otras palabras, te deseo buena salud, buena comida, buen sueño...",
  str_homestory_chat_32125015 = "¡Y un muy feliz año nuevo!",
  str_homestory_chat_32125016 = "Guau...",
  str_homestory_chat_32125017 = "Ahora podemos tener otro año feliz juntos.",
  str_homestory_chat_32125018 = "Confía en mí, el deseo de un dragón nunca debe tomarse a la ligera.",
  str_homestory_chat_32125019 = "¡E-Entendido! También...",
  str_homestory_chat_32125020 = "Gracias, Chen'ni.",
  str_homestory_chat_32299999 = "¿Qué estás haciendo, PlayerName?",
  str_homestory_chat_32221001a = "Mmm...",
  str_homestory_chat_32221001 = "Voy a pasar el día en la cama.",
  str_homestory_chat_32221002 = "¿Todo el día? Me recuerdas a uno de mis condiscípulos mayores.",
  str_homestory_chat_32221003 = "¿Tu discípulo mayor?",
  str_homestory_chat_32221004 = "Sí. Solía cuidarme muy bien, pero...",
  str_homestory_chat_32221005 = "Nunca se tomó las cosas muy en serio. De hecho, algunas personas incluso dirían que es perezoso.",
  str_homestory_chat_32221006 = "Hablemos de tomar siestas todo el tiempo.",
  str_homestory_chat_32221007 = "Pero sus habilidades eran de primera categoría, y nuestro maestro lo consideraba un genio.",
  str_homestory_chat_32221008 = "Cuando lo pienso, probablemente él estaba en un nivel completamente diferente al nuestro.",
  str_homestory_chat_32221009 = "Voy a leer un poco.",
  str_homestory_chat_32221010 = "¿Leyendo, eh? Tengo curiosidad por saber qué tipo de libros lees.",
  str_homestory_chat_32221011 = "En mis días de templo, simplemente leía todo tipo de libros.",
  str_homestory_chat_32221012 = "Aparte de los estudios metafísicos, también leemos sobre artes marciales y todo tipo de otras cosas.",
  str_homestory_chat_32221013 = "Aunque en aquel entonces estaba un poco más interesado en el entrenamiento de artes marciales que en los libros...",
  str_homestory_chat_32221014 = "Dime, ¿por qué no les damos a nuestros amigos demoníacos una rápida lección de literatura?",
  str_homestory_chat_32221015 = "Después de todo, solo saber cómo pelear nunca es suficiente.",
  str_homestory_chat_32221016 = "Está bien, iré a hablar con Ah Ding y los demás. ¡Nos vemos luego!",
  str_homestory_chat_32221017 = "Claro, te veo en un rato.",
  str_homestory_chat_32222001 = "Podría ir a terminar algo de trabajo.",
  str_homestory_chat_32222002 = "¿Trabajo, eh? Sí, yo también.",
  str_homestory_chat_32222003 = "Acabo de aceptar un nuevo trabajo hoy.",
  str_homestory_chat_32222004 = "Aparentemente, algo ha estado causando un alboroto en una casa antigua, pero no saben si es un Eclipsite o un animal salvaje.",
  str_homestory_chat_32222005 = "Realmente no hace diferencia. Sacaré lo que sea que esté ahí y le daré una buena paliza de todos modos.",
  str_homestory_chat_32222006 = "Espero que nada salga mal...",
  str_homestory_chat_32222007 = "No te preocupes, Ah Ding y los demás estarán conmigo.",
  str_homestory_chat_32222008 = "Si algo sale mal, siempre puedo confiar en la técnica de cabezazo de hierro de Ah Ding.",
  str_homestory_chat_32222009 = "¡Buena suerte!",
  str_homestory_chat_32222010 = "Bueno, debería empezar a prepararme para salir.",
  str_homestory_chat_32223001 = "Podría ir a visitar a un amigo.",
  str_homestory_chat_32223002 = "¿Visitando a un amigo? Eso siempre es bueno.",
  str_homestory_chat_32223003 = "He estado viajando en Longzhou durante años y he hecho muchos amigos en el proceso.",
  str_homestory_chat_32223004 = "Hablando de eso, ¿alguna vez te haces amigo de personas que no tienen nada en común contigo?",
  str_homestory_chat_32223005 = "Si.",
  str_homestory_chat_32223006 = "Tenía la sensación de que dirías eso.",
  str_homestory_chat_32223007 = "Después de todo, este Coloso es hogar de muchas personas con ascendencia de demonios.",
  str_homestory_chat_32223008 = "El mundo es vasto, y las perspectivas de las personas deberían ser igual de amplias.",
  str_homestory_chat_32223009 = "Realmente no.",
  str_homestory_chat_32223010 = "¿En serio...? Supongo que eso también es comprensible.",
  str_homestory_chat_32223011 = "Después de todo, el mundo está lleno de problemas que nacieron de las personas que se malinterpretan entre sí.",
  str_homestory_chat_32223012 = "Pero creo que la gente se volverá más sabia algún día...",
  str_homestory_chat_32223013 = "Suficientemente sabio para aceptar las cosas que no entienden.",
  str_homestory_chat_32223014 = "Espero que sí.",
  str_homestory_chat_32224001 = "Estaba a punto de hacer algo de ejercicio.",
  str_homestory_chat_32224002 = "¿Ejercicio, eh? ¡De repente ya no me siento cansado!",
  str_homestory_chat_32224003 = "El entrenamiento es como hacer un castillo de arena: todo se desmorona si paras incluso un día.",
  str_homestory_chat_32224004 = "¿Entonces qué dices? ¿Te importa si me uno a ti hoy?",
  str_homestory_chat_32224005 = "Tienes una buena base, y el entrenamiento definitivamente sacará a relucir tu increíble potencial.",
  str_homestory_chat_32224006 = "N-No importa...",
  str_homestory_chat_32224007 = "¿En serio? Eso es muy malo.",
  str_homestory_chat_32224008 = "Tal vez simplemente vaya a entrenar con los diablillos en su lugar.",
  str_homestory_chat_32224009 = "Claro. ¡Deberías poder levantar a Ah Ding sin problema!",
  str_homestory_chat_32224010 = "Por otro lado, los diabólicos elefantes del Reino Dian...",
  str_homestory_chat_32224011 = "¡Ni siquiera intentaría levantar uno de esos!",
  str_homestory_chat_146901001 = "Pierre",
  str_homestory_chat_124901001 = "Kuro",
  str_homestory_chat_151901001 = "Sork",
  str_homestory_chat_173901001 = "Patsy",
  str_homestory_chat_104901001 = "Kuma",
  str_homestory_chat_115901001 = "Hachi",
  str_homestory_chat_247901001 = "momo",
  str_homestory_chat_32399999 = "Si pudieras ser un animal, ¿cuál serías?",
  str_homestory_chat_32321001 = "Zorro de nieve.",
  str_homestory_chat_32321002 = "¡Te entiendo! ¡Los zorros de nieve son geniales!",
  str_homestory_chat_32321003 = "¡Ágiles, móviles, cazadores sobresalientes con la capacidad de mezclarse con la nieve para ocultarse!",
  str_homestory_chat_32321004 = "¡Increíblemente alta supervivencia! Gran elección.",
  str_homestory_chat_32321005 = "En realidad, elegí eso solo porque...",
  str_homestory_chat_32321006 = "Los zorros de nieve son lindos.",
  str_homestory_chat_32321007 = "Son adorables y esponjosos.",
  str_homestory_chat_32321008 = "Si cada cazador fuera tan mortal como tú...",
  str_homestory_chat_32321009 = "¡Sería mejor si me convirtiera en un animal suave y los moviera con mi ternura!",
  str_homestory_chat_32321010 = "Te encantan los zorros de nieve, ¿verdad?",
  str_homestory_chat_32321011 = "Si fuera uno, tal vez viviría el resto de mi vida en paz bajo tu protección.",
  str_homestory_chat_32321012 = "¡Qué suposición lógica y razonable!",
  str_homestory_chat_32321013 = "¡Eso es exactamente cómo piensa un Auroriano!",
  str_homestory_chat_32321014 = "Pero a los animales en la nieve no les importa complacer a los Aurorianos.",
  str_homestory_chat_32321015 = "Ejem... Lo siento, no soy ni un animal ni un auroriano.",
  str_homestory_chat_32321016 = "Solo soy un pequeño Caelestite débil que pone la supervivencia por encima de todo lo demás.",
  str_homestory_chat_32322001 = "Oso grizzly.",
  str_homestory_chat_32322002 = "...",
  str_homestory_chat_32322003 = "PlayerName...",
  str_homestory_chat_32322004 = "¿Qué pasa? ¿Por qué la lástima en tus ojos?",
  str_homestory_chat_32322005 = "¿Qué? No, no hay piedad. Lo entiendo.",
  str_homestory_chat_32322006 = "Eres un blandengue sin mucha fuerza física, así que...",
  str_homestory_chat_32322007 = "Naturalmente, anhelas un cuerpo poderoso como el de un oso grizzly.",
  str_homestory_chat_32322008 = "¡Entiendo. Realmente lo hago!",
  str_homestory_chat_32322009 = "¿Qué estás diciendo?",
  str_homestory_chat_32322010 = "\"¿Un debilucho sin mucha fuerza física\"? ¡Eso es ir un poco lejos!",
  str_homestory_chat_32322011 = "Solo pensé—",
  str_homestory_chat_32322012 = "¿Solo pensaste qué?",
  str_homestory_chat_32322013 = "¡La forma en que un oso grizzly duerme durante todo el invierno es lo que disfrutaría!",
  str_homestory_chat_32322014 = "PlayerName...",
  str_homestory_chat_32322015 = "¿Por qué hay más lástima en tus ojos ahora?",
  str_homestory_chat_32323001 = "Gaviota.",
  str_homestory_chat_32323002 = "Oh, ¿te refieres a esos pájaros obsesionados con las papas fritas?",
  str_homestory_chat_32323003 = "Espera, no...",
  str_homestory_chat_32323004 = "Las papas fritas no son lo único que comen.",
  str_homestory_chat_32323005 = "Más bien, no son exigentes en absoluto cuando se trata de comida.",
  str_homestory_chat_32323006 = "Bayas, algas, pescado, insectos... Comen todo eso, y por supuesto, también papas fritas.",
  str_homestory_chat_32323007 = "Son de mente muy abierta y probarán cualquier cosa.",
  str_homestory_chat_32323008 = "¡Eso está muy cerca de cómo quiero vivir!",
  str_homestory_chat_32323009 = "Ahora que lo dices, lo mencionaste antes...",
  str_homestory_chat_32323010 = "Quieres visitar todos los rincones del mundo y verlo todo.",
  str_homestory_chat_32323011 = "¡Ese es el pájaro perfecto para ti!",
  str_homestory_chat_32323012 = "Eres un Caelestite y se sabe que están asociados con el cielo y el vuelo.",
  str_homestory_chat_32323013 = "El Coloso es mis alas.",
  str_homestory_chat_32323014 = "¡Eres bienvenido a viajar conmigo si quieres!",
  str_homestory_chat_32323015 = "Mientras no comamos papas fritas todo el tiempo.",
  str_homestory_chat_32323016 = "¡Deja de hablar sobre papas fritas!",
  str_homestory_chat_32324001 = "Conejo.",
  str_homestory_chat_32324002 = "¿En serio? Esa es una elección única.",
  str_homestory_chat_32324003 = "Los conejos no pueden luchar y están en el fondo de la cadena alimentaria en la naturaleza.",
  str_homestory_chat_32324004 = "¿Por qué querrías ser un animal tan débil?",
  str_homestory_chat_32324005 = "Los conejos no son débiles.",
  str_homestory_chat_32324006 = "Nadie cuida de los conejos.",
  str_homestory_chat_32324007 = "La apariencia tímida e inofensiva es en realidad su mejor arma.",
  str_homestory_chat_32324008 = "¿Por qué más Novio elegiría a un conejo como su compañero de inteligencia?",
  str_homestory_chat_32324009 = "En comparación con los ataques preventivos, prefiero los ataques reactivos.",
  str_homestory_chat_32324010 = "Los conejos tienen un oído agudo.",
  str_homestory_chat_32324011 = "Acechan en la oscuridad y escuchan todo a su alrededor.",
  str_homestory_chat_32324012 = "Todo lo que sienten ayuda a sus amigos.",
  str_homestory_chat_32324013 = "¿No crees que eso suena mucho como un Caelestite con habilidades psíquicas?",
  str_homestory_chat_32324014 = "Es cierto. Tu perspectiva como Caelestite es muy diferente a la de un Auroriano.",
  str_homestory_chat_32324015 = "Además, eso me dio una nueva perspectiva para mejorar mi caza.",
  str_homestory_chat_32324016 = "Oh no, no acabo de vender a los conejos por un puñado de monedas, ¿verdad?",
  str_homestory_chat_32324017 = "¡Lo verás a la hora de la cena!",
  str_homestory_chat_32325001 = "Ballena.",
  str_homestory_chat_32325002 = "¡Señor del mar! Una elección muy razonable.",
  str_homestory_chat_32325003 = "¿Es eso porque los Caelestites desean poder?",
  str_homestory_chat_32325004 = "No exactamente.",
  str_homestory_chat_32325005 = "Existe una especie de ballena llamada orca. Escuché que valoran mucho a la familia.",
  str_homestory_chat_32325006 = "Vivirían con su familia hasta la muerte.",
  str_homestory_chat_32325007 = "Supongo que eso es algo que aprecio y me atrae.",
  str_homestory_chat_32325008 = "PlayerName...",
  str_homestory_chat_32325009 = "Lo siento, no quise recordarte tu pasado.",
  str_homestory_chat_32325010 = "Está bien, no te preocupes.",
  str_homestory_chat_32325011 = "Tengo una familia en el Coloso.",
  str_homestory_chat_32325012 = "Así que mi deseo ya se hizo realidad.",
  str_homestory_chat_32325013 = "Soroz es mi familia.",
  str_homestory_chat_32325014 = "Haríamos cualquier cosa por el otro.",
  str_homestory_chat_32325015 = "Ah, ahora lo entiendo.",
  str_homestory_chat_32325016 = "Soy igual que tú.",
  str_homestory_chat_32325017 = "Perdí a mi familia hace mucho tiempo, pero encontré una nueva familia.",
  str_homestory_chat_32325018 = "En ese sentido, la familia va más allá de un simple vínculo de sangre.",
  str_homestory_chat_32325019 = "Sabía que lo conseguirías.",
  str_homestory_chat_32325020 = "Gracias, Tiare.",
  str_homestory_chat_32499999 = "¡Croac!",
  str_homestory_chat_32421001 = "¡Veo que al pequeño también le gusta estar aquí!",
  str_homestory_chat_32599999 = "Si tuvieras que elegir un pasatiempo de coleccionismo, ¿cuál escogerías?",
  str_homestory_chat_32521001 = "Figuritas.",
  str_homestory_chat_32521002 = "¿Como los que se usan en las mesas de arena para determinar tácticas de combate?",
  str_homestory_chat_32521003 = "No tenía idea de que fueras un entusiasta militar tan apasionado.",
  str_homestory_chat_32521004 = "Sí, eso es correcto.",
  str_homestory_chat_32521005 = "Todos me llaman el Navegante, lo que también me convierte en una especie de comandante.",
  str_homestory_chat_32521006 = "Además, no hay nada malo en practicar estrategias de combate de vez en cuando.",
  str_homestory_chat_32521007 = "PlayerName... No me di cuenta de que te preparabas tan a fondo para cada batalla.",
  str_homestory_chat_32521008 = "Te estoy viendo bajo una nueva luz una vez más.",
  str_homestory_chat_32521009 = "Creo que tienes una idea equivocada...",
  str_homestory_chat_32521010 = "Cuando digo figuritas, me refiero a las coloridas y caras—",
  str_homestory_chat_32521011 = "¿Entonces comprarías los modelos de soldados más avanzados, completos con sistemas de armas integrados?",
  str_homestory_chat_32521012 = "PlayerName... No tenía idea de que tomaras las simulaciones de combate tan en serio.",
  str_homestory_chat_32521013 = "Rara vez encuentro a otros que son como yo.",
  str_homestory_chat_32521014 = "Sigamos haciendo nuestro mejor esfuerzo, ¿de acuerdo?",
  str_homestory_chat_32521015 = "Eh... ¡Claro!",
  str_homestory_chat_32522001 = "Muebles.",
  str_homestory_chat_32522002 = "¿Muebles? Supongo que tienes una cantidad considerable de artículos de mobiliario raros en Cloud Gardens.",
  str_homestory_chat_32522003 = "Así que eso es lo que te gusta.",
  str_homestory_chat_32522004 = "¡Sí! Los muebles no solo hacen nuestras vidas más cómodas...",
  str_homestory_chat_32522005 = "También me ayuda a acercarme más a mis amigos.",
  str_homestory_chat_32522006 = "Sí, te he visto a ti y a tus amigos teniendo conversaciones apasionadas alrededor de tus muebles.",
  str_homestory_chat_32522007 = "Ya veo. Utilizas los muebles como una especie de \"trampa para amigos\".",
  str_homestory_chat_32522008 = "Después de colocar el mueble correcto, esperas la oportunidad perfecta—",
  str_homestory_chat_32522009 = "Para crear recuerdos inolvidables de nuestras aventuras.",
  str_homestory_chat_32522010 = "¿Y esos muebles sirven como recordatorios de esas aventuras, verdad? Eso tiene sentido.",
  str_homestory_chat_32522011 = "Ciertas aves de presa tienen un hábito similar.",
  str_homestory_chat_32522012 = "Después de desgarrar a sus presas y devorar la carne, decoran sus nidos con los huesos—",
  str_homestory_chat_32522013 = "¡E-E-E-Espera un segundo!",
  str_homestory_chat_32522014 = "¡Algo sobre eso no parece estar bien!",
  str_homestory_chat_32523001 = "Vice.",
  str_homestory_chat_32523002 = "Recogerías... ¿Teniente Vice? Lo siento, pero no entiendo.",
  str_homestory_chat_32523003 = "Después de todo, ella es una persona extremadamente única.",
  str_homestory_chat_32523004 = "¿Quieres decir que no entiendes? ¡En realidad, hay toneladas de diferentes Vicios!",
  str_homestory_chat_32523005 = "Como \"Me grita para que limpie el almacén\" Vice, y \"Me acosa para que asuma más trabajos\" Vice...",
  str_homestory_chat_32523006 = "\"Me Recuerda a Limpiar Mi Habitación\" Vice, y \"Me Obliga a Comer Comida Indescriptiblemente Horrible\" Vice...",
  str_homestory_chat_32523007 = "... Aunque todos esos suenan increíblemente negativos, creo que ahora entiendo.",
  str_homestory_chat_32523008 = "Solo quieres ver todos los lados del Teniente Vice, ¿no es así?",
  str_homestory_chat_32523009 = "¡Ejem, yo no dije eso!",
  str_homestory_chat_32524001 = "Colosos.",
  str_homestory_chat_32524002 = "Colossi... ¿Realmente puedes recolectar esos?",
  str_homestory_chat_32524003 = "Bueno, obviamente no los pondría en un estante ni nada. Supongo...",
  str_homestory_chat_32524004 = "Lo que realmente quiero es ver aún más Colosos por ahí.",
  str_homestory_chat_32524005 = "PlayerName... Por lo que puedo ver, realmente debes extrañar tu casa.",
  str_homestory_chat_32524006 = "Estás en lo correcto.",
  str_homestory_chat_32524007 = "Creo que puedo relacionarme.",
  str_homestory_chat_32524008 = "Cuando estaba luchando para restaurar el honor de mi familia...",
  str_homestory_chat_32524009 = "Cualquier cosa que me recordara a casa fortalecería mi espíritu de lucha cien veces más.",
  str_homestory_chat_32524010 = "No es del todo eso.",
  str_homestory_chat_32524011 = "Los Colosos tienen mucho que enseñarme sobre ellos mismos, así como sobre los Caelestites.",
  str_homestory_chat_32524012 = "Con ese conocimiento, puedo estar preparado para cualquier problema que Soroz pueda tener en el futuro!",
  str_homestory_chat_32524013 = "Así que en lugar de aferrarte al pasado, luchas para preservar lo que aprecias en el presente...",
  str_homestory_chat_32524014 = "Realmente estás determinado, Celestita Uno.",
  str_homestory_chat_32524015 = "Gracias por comprender, Rachel.",
  str_homestory_chat_32524016 = "En mis ojos, has sido parte de mi familia desde hace mucho tiempo.",
  str_homestory_chat_32525001 = "Aurorianos.",
  str_homestory_chat_32525002 = "¿Es eso lo que los Aurorians significan para ti? ¿Coleccionables?",
  str_homestory_chat_32525003 = "¡Bueno, sí! Después de todo, ¡soy un perfeccionista de corazón!",
  str_homestory_chat_32525004 = "¿Y qué significa eso exactamente?",
  str_homestory_chat_32525005 = "No te equivoques. Es solo una metáfora.",
  str_homestory_chat_32525006 = "Solo quiero luchar junto a tantos Aurorianos como sea posible.",
  str_homestory_chat_32525007 = "De esa manera, puedo seguir desarrollando mi colección... quiero decir, mi capacidad para adaptarme...",
  str_homestory_chat_32525008 = "¡Y entonces ningún problema será demasiado difícil para mí manejar! Tiene sentido, ¿verdad?",
  str_homestory_chat_32525009 = "Ya veo... Lamento haber dudado de ti hace un momento.",
  str_homestory_chat_32525010 = "Admiro tus encomiables intenciones.",
  str_homestory_chat_32525011 = "¿Por qué no tenemos una batalla de práctica la próxima vez?",
  str_homestory_chat_32525012 = "¿Ah?",
  str_homestory_chat_32699999 = "¡Vaya, si no es el Último Caelestita! ¿Qué estás haciendo?",
  str_homestory_chat_32621001 = "Oh...",
  str_homestory_chat_32621002 = "Estaba a punto de hacer algo de ejercicio.",
  str_homestory_chat_32621003 = "¡Ya veo! ¿Un poco de entrenamiento de fuerza, eh?",
  str_homestory_chat_32621004 = "¡Justo como pensé, no tomas descansos ni en días normales!",
  str_homestory_chat_32621005 = "¿También entrenas bastante a menudo, Zeta?",
  str_homestory_chat_32621006 = "Mi sabiduría y carisma son mis mejores atributos. ¡Incluso sin entrenamiento físico, sigo siendo muy fuerte!",
  str_homestory_chat_32621007 = "Por ejemplo, ¿alguna vez has visto a un león entrenarse a sí mismo antes?",
  str_homestory_chat_32621008 = "¡Por supuesto que no! ¡Eso es porque es completamente inaceptable que una criatura naturalmente poderosa entrene para volverse aún más poderosa!",
  str_homestory_chat_32621009 = "Estaba planeando tomar un descanso.",
  str_homestory_chat_32621010 = "Ya veo. ¿Descansando un poco antes de la próxima batalla brutal, eh?",
  str_homestory_chat_32621011 = "Justo como pensé, tomas tus descansos tan en serio como tu trabajo!",
  str_homestory_chat_32621012 = "¡Eres igual que yo! Aunque todos digan que como demasiados dulces...",
  str_homestory_chat_32621013 = "¡Siempre equilibro mi dieta comiendo también dulces enriquecidos con vitaminas!",
  str_homestory_chat_32621014 = "¿Hmm? ¡Uh-oh, casi es hora de que me reúna con esos chicos! Lo siento, ¡pero tengo que irme!",
  str_homestory_chat_32621015 = "Está bien, te veré más tarde.",
  str_homestory_chat_32622001 = "Tengo algunas cosas importantes que hacer pronto.",
  str_homestory_chat_32622002 = "¿Cosas importantes? Suena terriblemente sospechoso...",
  str_homestory_chat_32622003 = "¿Es algo tan importante que no puedes contárselo a tus amigos?",
  str_homestory_chat_32622004 = "Para alejarse de su desagradable pasado, se va sin decir adiós y enfrenta su sombrío destino solo...",
  str_homestory_chat_32622005 = "¡Pero no te preocupes, nunca estarás solo de nuevo! ¡Estaré a tu lado dondequiera que vayas!",
  str_homestory_chat_32622006 = "Gracias, Zeta, pero realmente es solo un poco de trabajo de mantenimiento para el Colossus.",
  str_homestory_chat_32622007 = "¿Eh? Oh, eso es aburrido.",
  str_homestory_chat_32622008 = "¿Quieres ayudarme a ordenar algunos archivos?",
  str_homestory_chat_32622009 = "¿Qué? ¿Quieres decir que eso es todo?",
  str_homestory_chat_32622010 = "Ejem... Lo siento, pero acabo de recordar que tengo algo más que hacer ahora mismo.",
  str_homestory_chat_32622011 = "¡Los guerreros también pueden estar súper ocupados, sabes! ¡Nos vemos!",
  str_homestory_chat_32623001 = "Realmente no.",
  str_homestory_chat_32623002 = "\"Realmente nada\", ¿eh? Supongo que eso significa que nada malo ha ocurrido.",
  str_homestory_chat_32623003 = "¡Pero los guerreros salvadores del mundo como nosotros no podemos permitirnos perder el enfoque!",
  str_homestory_chat_32623004 = "El mal acecha en cada esquina, ¡así que siempre debemos estar atentos a él!",
  str_homestory_chat_32623005 = "Simplemente no te metas en problemas.",
  str_homestory_chat_32623006 = "Simplemente estás esperando que ocurra el caos, ¿verdad?",
  str_homestory_chat_32623007 = "¡Relájate! El gran guerrero Zeta nunca haría nada para causar problemas!",
  str_homestory_chat_32623008 = "De alguna manera, tu juramento solo me hace preocupar aún más...",
  str_homestory_chat_32624001 = "Tengo ganas de un bocadillo ahora mismo.",
  str_homestory_chat_32624002 = "¿Un bocadillo? ¡Entonces te encontraste con la persona correcta!",
  str_homestory_chat_32624003 = "Tengo todo tipo de dulces. Aquí, ¡elige el que quieras!",
  str_homestory_chat_32624004 = "Pero quiero algo salado.",
  str_homestory_chat_32624005 = "¡También tengo caramelos salados! ¡Como este, una piruleta de pimiento fantasma!",
  str_homestory_chat_32624006 = "Está hecho con auténticos pimientos fantasma. ¡Dicen que no podrás respirar después de solo unos pocos lametones!",
  str_homestory_chat_32624007 = "Pero aún no lo he probado por mí mismo, así que no sé si es cierto o no.",
  str_homestory_chat_32624008 = "Entonces, ¿por qué me lo darías?",
  str_homestory_chat_32624009 = "¡No te preocupes si lo hago!",
  str_homestory_chat_32624010 = "Siéntete libre de tomar lo que quieras. Pero te advierto: hay algunas bombas mezcladas allí, así que ten cuidado cuando las estés comiendo.",
  str_homestory_chat_32624011 = "¿B-Bombas? ¿Cuáles son las bombas?",
  str_homestory_chat_32624012 = "¿Quieres decir que no puedes diferenciarlos? ¡Es totalmente obvio!",
  str_homestory_chat_32624013 = "Quizás para ti, pero yo no puedo distinguirlos en absoluto.",
  str_homestory_chat_32624014 = "Eh, no tienes remedio. Aquí, elegiré uno solo para ti entonces.",
  str_homestory_chat_32624015 = "Tengo algunas otras cosas que hacer, así que te veré más tarde.",
  str_homestory_chat_32799999 = "¿Hay algún juego al que te gustaría jugar últimamente?",
  str_homestory_chat_32721001 = "Juegos de rol",
  str_homestory_chat_32721002 = "¡Ah, buena elección!",
  str_homestory_chat_32721003 = "¿Qué te hizo elegir eso?",
  str_homestory_chat_32721004 = "¿Te interesa más la configuración del juego o la historia?",
  str_homestory_chat_32721005 = "El escenario",
  str_homestory_chat_32721006 = "Es genial sentir que estás viviendo en otro lugar.",
  str_homestory_chat_32721007 = "El tipo de experiencia... Lo entiendo.",
  str_homestory_chat_32721008 = "La historia",
  str_homestory_chat_32721009 = "Normalmente es el tipo de cosas de los buenos chicos matando al dragón.",
  str_homestory_chat_32721010 = "Pero no me importa en absoluto.",
  str_homestory_chat_32721011 = "El tipo que te hace sentir bien... Eso me gusta.",
  str_homestory_chat_32721012 = "¿No te gusta ese tipo de juego, Batia?",
  str_homestory_chat_32721013 = "Lo hago, es solo que... No tengo una preferencia particular.",
  str_homestory_chat_32721014 = "Lo disfruto más cuando hay una amplia variedad para elegir.",
  str_homestory_chat_32722001 = "Juegos de estrategia",
  str_homestory_chat_32722002 = "¡Eso no es sorprendente!",
  str_homestory_chat_32722003 = "Me gustaría mejorar mi habilidad de navegación como Caelestite.",
  str_homestory_chat_32722004 = "Así que estoy mejor compuesto cuando me enfrento a los Eclipsites.",
  str_homestory_chat_32722005 = "Me estás diciendo.",
  str_homestory_chat_32722006 = "¿Quieres mejorar cómo los contrarrestas jugando juegos estratégicos?",
  str_homestory_chat_32722007 = "Es impresionante que pensarías en eso incluso cuando estás jugando un juego.",
  str_homestory_chat_32722008 = "Bueno, en realidad he estado entrenando para eso.",
  str_homestory_chat_32722009 = "Sería agradable jugar todo tipo de simulaciones y escenarios en un juego.",
  str_homestory_chat_32723001 = "Juegos casuales",
  str_homestory_chat_32723002 = "Los juegos de emparejar fichas son bastante fáciles, ¿verdad?",
  str_homestory_chat_32723003 = "Eh, no necesariamente.",
  str_homestory_chat_32723004 = "Incluso ese tipo de juego puede ser duro y muy desafiante.",
  str_homestory_chat_32723005 = "¿Qué tan duro?",
  str_homestory_chat_32723006 = "No puedes hacer un movimiento en absoluto.",
  str_homestory_chat_32723007 = "¿Qué tan desafiante?",
  str_homestory_chat_32723008 = "Muchos requisitos extraños que exigen tiempo y esfuerzo.",
  str_homestory_chat_32723009 = "Tal vez debería reconsiderarlo.",
  str_homestory_chat_32724001 = "¡Tetrablox! ¡Tetrablox!",
  str_homestory_chat_32724002 = "¿También te gusta Tetrablox?!",
  str_homestory_chat_32724003 = "Podrías decir eso, pero definitivamente no soy tan bueno como tú.",
  str_homestory_chat_32724004 = "No soy lo suficientemente rápido para despejar tantos bloques.",
  str_homestory_chat_32724005 = "Es parte suerte y parte habilidad... Te puedo mostrar.",
  str_homestory_chat_32724006 = "¿Por qué no nos proponemos alcanzar el Nivel 30 por ahora?",
  str_homestory_chat_32725001 = "Realmente no",
  str_homestory_chat_32725002 = "Deberíamos salir.",
  str_homestory_chat_32725003 = "¿Afuera? ¿Te refieres a afuera-afuera o aquí-afuera?",
  str_homestory_chat_32725004 = "Afuera-afuera",
  str_homestory_chat_32725005 = "Uh, no suelo ir de viajes a menudo...",
  str_homestory_chat_32725006 = "Está bien. Tenemos el Coloso.",
  str_homestory_chat_32725007 = "Aquí-afuera",
  str_homestory_chat_32725008 = "Está bien. Es cómodo aquí y tenemos un paraguas.",
  str_homestory_chat_32725009 = "No te estoy molestando, ¿verdad?",
  str_homestory_chat_32725010 = "Si nos caemos...",
  str_homestory_chat_32725011 = "¡Podemos mirar el cielo tumbados de espaldas!",
  str_homestory_chat_32899999 = "Si pudieras tener en tus manos un objeto mágico, ¿qué querrías?",
  str_homestory_chat_32821001 = "Una impresora de dinero.",
  str_homestory_chat_32821002 = "¡Vaya! Eso es ciertamente... un tipo particular de \"magia\", supongo.",
  str_homestory_chat_32821003 = "Estoy bromeando... pero seriamente nos estamos quedando sin fondos para el mantenimiento del Coloso estos días.",
  str_homestory_chat_32821004 = "¡Ya estoy manejando ocho trabajos al día!",
  str_homestory_chat_32821005 = "Si ese es el caso, ¿por qué no trabajar para True Order?",
  str_homestory_chat_32821006 = "El pago que ofrezco no deshonrará la reputación de Varaki.",
  str_homestory_chat_32821007 = "¿Dónde debería enviar mi currículum?!",
  str_homestory_chat_32821008 = "No hay necesidad de tales formalidades mundanas. Cuando llegue la oportunidad guiada por la Verdad, trabajaremos juntos naturalmente.",
  str_homestory_chat_32821009 = "Forzarlo no traerá ningún bien.",
  str_homestory_chat_32821010 = "Eso suena un poco inestable...",
  str_homestory_chat_32821011 = "No estás haciendo simplemente promesas vacías, ¿verdad?",
  str_homestory_chat_32821012 = "Honestamente me sorprende que pienses eso.",
  str_homestory_chat_32821013 = "¿Realmente nos ves en True Order como un grupo sospechoso que engaña a sus seguidores?",
  str_homestory_chat_32821014 = "¡Absolutamente no! Es solo que me he encontrado con demasiados jefes sospechosos últimamente...",
  str_homestory_chat_32822001 = "Una capa de invisibilidad.",
  str_homestory_chat_32822002 = "Vaya...?",
  str_homestory_chat_32822003 = "¿Por qué... me miras así?",
  str_homestory_chat_32822004 = "Je...",
  str_homestory_chat_32822005 = "¡¿Qué tiene de gracioso eso?!",
  str_homestory_chat_32822006 = "No hay necesidad de avergonzarse, Navegante. Es natural tener estos pensamientos a tu edad.",
  str_homestory_chat_32822007 = "¿De qué pensamientos estás hablando? ¡Solo pienso que una capa de invisibilidad sería genial para misiones de sigilo!",
  str_homestory_chat_32822008 = "Sí, por supuesto. No querrías que fuera de otra manera.",
  str_homestory_chat_32822009 = "¿Para qué crees que lo quiero en el mundo?",
  str_homestory_chat_32823001 = "Una escoba que barre por sí misma.",
  str_homestory_chat_32823002 = "Oh vaya, con todos los objetos mágicos para elegir, ¿solo quieres una escoba? Tus deseos son bastante modestos.",
  str_homestory_chat_32823003 = "Si no quieres hacer la limpieza, ¿por qué no simplemente contratas a un sirviente?",
  str_homestory_chat_32823004 = "Alguien tan alto como tú podría no entenderlo...",
  str_homestory_chat_32823005 = "Pero dar órdenes a alguien más, incluso si les estoy pagando, me hace sentir incómodo.",
  str_homestory_chat_32823006 = "¡Pero si es una escoba mágica, puedo dar órdenes sin sentirme mal!",
  str_homestory_chat_32823007 = "Ya veo. Realmente eres un alma bondadosa.",
  str_homestory_chat_32823008 = "Pero, si reprimes demasiado tu \"yo\" por los demás, podrías alejarte de la Verdad.",
  str_homestory_chat_32823009 = "Cuidar de los demás es parte del \"yo\".",
  str_homestory_chat_32823010 = "Bien argumentado. Tu sabiduría y perspicacia son verdaderamente extraordinarias.",
  str_homestory_chat_32823011 = "De hecho, si pudieras expresar completamente tu naturaleza gentil...",
  str_homestory_chat_32823012 = "Seguramente te convertirías en un santo sacrificado, justo como Nails...",
  str_homestory_chat_32823013 = "N-n-no, eso no es necesario. ¡Estoy bien siendo solo ordinario!",
  str_homestory_chat_32823014 = "Entonces, ¿solo los ególatras pueden acercarse a la Verdad?",
  str_homestory_chat_32823015 = "Jeje... Tus palabras son bastante agudas; qué adorable.",
  str_homestory_chat_32823016 = "Pero sí, resulta que aquellos que comprenden la Verdad tienden a ser ególatras.",
  str_homestory_chat_32823017 = "Tus palabras afiladas son como las espinas de una rosa... Quizás es la Verdad manifestándose en ti... quién sabe.",
  str_homestory_chat_32823018 = "¿No es un poco difícil llevarse bien con este Señor de la Verdad...?",
  str_homestory_chat_32824001 = "Un reloj de arena que retrocede el tiempo.",
  str_homestory_chat_32824002 = "¿Retrocediendo en el tiempo? Una elección clásica.",
  str_homestory_chat_32824003 = "Disculpa por preguntar, ¿pero es porque quieres volver diecisiete años atrás para cambiar lo que sucedió en Eraveil?",
  str_homestory_chat_32824004 = "Por supuesto.",
  str_homestory_chat_32824005 = "Es natural que quieras eso.",
  str_homestory_chat_32824006 = "Si realmente tienes la oportunidad de hacerlo realidad, tal vez... estaré a tu lado.",
  str_homestory_chat_32824007 = "¿Qué? Pensé que todos estarían en contra de un cambio tan grande en la historia...",
  str_homestory_chat_32824008 = "Tengo miedo de cambiar las cosas tanto.",
  str_homestory_chat_32824009 = "Todo Astra se vería afectado...",
  str_homestory_chat_32824010 = "Como mucho, solo volvería al día antes de ayer y encontraría mi dinero perdido... jaja.",
  str_homestory_chat_32824011 = "...El tejido del tiempo es extremadamente misterioso.",
  str_homestory_chat_32824012 = "La forma en que se forma el \"pasado\" es mucho más compleja de lo que pensamos.",
  str_homestory_chat_32824013 = "A veces, podría ser el \"futuro\" el que da forma al \"pasado\".",
  str_homestory_chat_32824014 = "...",
  str_homestory_chat_32825001 = "Una poción que te permite aprender mientras duermes.",
  str_homestory_chat_32825002 = "...",
  str_homestory_chat_32825003 = "De tus ojos, veo una profunda desaprobación...",
  str_homestory_chat_32825004 = "Je... Aprecio lo inteligente que eres.",
  str_homestory_chat_32825005 = "Hay toneladas de novelas de fantasía centradas en la magia...",
  str_homestory_chat_32825006 = "Pero incluso ellos rara vez describen la poción que quieres. ¿Sabes por qué?",
  str_homestory_chat_32825007 = "¿Los autores no son lo suficientemente audaces?",
  str_homestory_chat_32825008 = "Porque el conocimiento es el único camino hacia la Verdad.",
  str_homestory_chat_32825009 = "Y el aprendizaje es una cosa que no permite atajos.",
  str_homestory_chat_32825010 = "¿Lo entiendes ahora?",
  str_homestory_chat_32825011 = "...¡Lo entiendo totalmente, Maestro Victoria!",
  str_homestory_chat_32999999 = "¿Alguna vez te has arrepentido de algo?",
  str_homestory_chat_32921001 = "Me quedé despierto tres días jugando.",
  str_homestory_chat_32921002 = "¿Juegos...? ¿Qué son esos?",
  str_homestory_chat_32921003 = "Son demonios.",
  str_homestory_chat_32921004 = "¿Diablos? ¿Te refieres a criaturas viles como los Eclipsites o los Necroservants?",
  str_homestory_chat_32921005 = "Te protegeré, PlayerName, porque exactamente por esto el Señor me ha otorgado el poder de la Sangre Sagrada.",
  str_homestory_chat_32921006 = "La Sangre Sagrada no puede hacer nada al respecto.",
  str_homestory_chat_32921007 = "Los diablos llamados juegos usan la alegría como cebo, desperdiciando mi juventud y agotando mi dinero...",
  str_homestory_chat_32921008 = "¡Incluso el guerrero más fuerte no puede escapar de sus garras!",
  str_homestory_chat_32921009 = "Pero... Pero suena como si simplemente te estuvieras entregando a la tentación sin poner resistencia.",
  str_homestory_chat_32921010 = "Debes protegerme.",
  str_homestory_chat_32921011 = "La próxima vez que Gronru me tiente con juegos, ¡tienes que bloquearla!",
  str_homestory_chat_32921012 = "¿Gronru?",
  str_homestory_chat_32921013 = "Ella es la reina demonio de los juegos en el infierno. Si no fuera por ella, no terminaría así...",
  str_homestory_chat_32921014 = "¿No es eso simplemente... culpar a alguien más por tu culpa?",
  str_homestory_chat_32921015 = "Quizás esto es por lo que realmente deberías arrepentirte, ¿no crees?",
  str_homestory_chat_32921016 = "¡Ugh...! Dejemos este tema. ¡Adiós!",
  str_homestory_chat_32922001 = "Apilando una torre de frutas en un restaurante.",
  str_homestory_chat_32922002 = "¿Una torre de frutas?",
  str_homestory_chat_32922003 = "Ejem, ¿sabes esos restaurantes donde puedes obtener una ensalada de frutas de autoservicio si pides un plato principal?",
  str_homestory_chat_32922004 = "Puedes tomar todo lo que quieras, pero solo una vez.",
  str_homestory_chat_32922005 = "Por lo tanto, apilar tanta ensalada como sea posible en un plato se convierte en una forma de arte.",
  str_homestory_chat_32922006 = "Entonces, ¿amontonaste una... torre de frutas en tu plato?",
  str_homestory_chat_32922007 = "No, no me mires así...",
  str_homestory_chat_32922008 = "¡Eso requiere habilidad real!",
  str_homestory_chat_32922009 = "...Si te sientes orgulloso, ¿por qué te arrepentiste?",
  str_homestory_chat_32922010 = "Me comí toda la torre de frutas y tuve diarrea durante tres días...",
  str_homestory_chat_32922011 = "Entonces has recibido el castigo del Señor; tus pecados han sido limpiados, PlayerName.",
  str_homestory_chat_32922012 = "Tus ojos se han vuelto cálidos de nuevo, lo que me hace sentir aún más extraño...",
  str_homestory_chat_32923001 = "Acelerando.",
  str_homestory_chat_32923002 = "Acelerando... No sabía que el Colossus tenía límites de velocidad.",
  str_homestory_chat_32923003 = "El cielo es ahora mío para vagar libremente...",
  str_homestory_chat_32923004 = "Pero en los días cuando muchos Colosos estaban en el cielo, había límites de velocidad habituales.",
  str_homestory_chat_32923005 = "Estaban para mantener a salvo a otros Colosos y pájaros, y la mayoría del tiempo los seguía.",
  str_homestory_chat_32923006 = "Entonces, ¿por qué aceleraste?",
  str_homestory_chat_32923007 = "Cumpleaños de Vice.",
  str_homestory_chat_32923008 = "Aceleré hacia Umbraton para agarrar uno de los cincuenta pasteles de frutas ultra-lujosos de edición limitada.",
  str_homestory_chat_32923009 = "El cumpleaños de Carleen.",
  str_homestory_chat_32923010 = "Aceleré hacia Lumopolis para el banquete de cumpleaños y tuve que recoger mi vestido de noche de la tintorería en el camino...",
  str_homestory_chat_32923011 = "Entiendo...",
  str_homestory_chat_32923012 = "Dado que fue por ella, no puedo culparte.",
  str_homestory_chat_32923013 = "¿Y ya te has arrepentido sinceramente, verdad?",
  str_homestory_chat_32923014 = "¡Por supuesto!",
  str_homestory_chat_32923015 = "Incluso sin que nadie lo imponga, aún te adhieres a las costumbres de tu clan y te arrepientes cuando las rompes.",
  str_homestory_chat_32923016 = "Tu carácter noble es admirable.",
  str_homestory_chat_32923017 = "El Señor de la Verdad te bendecirá, PlayerName.",
  str_homestory_chat_32923018 = "Gracias... Quiero decir, ¡gracias a Él!",
  str_homestory_chat_32924001 = "Falta perseverancia.",
  str_homestory_chat_32924002 = "¿Te resulta difícil apegarte a las cosas?",
  str_homestory_chat_32924003 = "Sí... especialmente cuando decido hacer ejercicio, ejem...",
  str_homestory_chat_32924004 = "Entrenar el cuerpo es un proceso doloroso. Yo lo he pasado, así que lo entiendo.",
  str_homestory_chat_32924005 = "En realidad, no necesitas esforzarte tanto porque tu fuerza no reside en tu cuerpo.",
  str_homestory_chat_32924006 = "El ejercicio no te va, pero debe haber algo a lo que puedas aferrarte, ¿verdad?",
  str_homestory_chat_32924007 = "Algo así... Supongo...",
  str_homestory_chat_32924008 = "¿Cómo qué?",
  str_homestory_chat_32924009 = "Comiendo... durmiendo...",
  str_homestory_chat_32924010 = "...",
  str_homestory_chat_32924011 = "¡Hay más! Como...",
  str_homestory_chat_32924012 = "...¡Como respirar!",
  str_homestory_chat_32924013 = "...",
  str_homestory_chat_33099999 = "¿Qué tipo de libros te gusta leer?",
  str_homestory_chat_33021001 = "novelas",
  str_homestory_chat_33021002 = "Interesante.",
  str_homestory_chat_33021003 = "¿Sabes qué? Lo que llamas novelas tiene una historia sorprendentemente corta.",
  str_homestory_chat_33021004 = "Solo estaban comenzando en mi época.",
  str_homestory_chat_33021005 = "¡Eso es noticia para mí!",
  str_homestory_chat_33021006 = "Pensé que las novelas... um, ¿siempre han estado allí?",
  str_homestory_chat_33021007 = "Es un sesgo cognitivo común pensar que los nuevos conceptos en cultura y sociedad siempre han existido.",
  str_homestory_chat_33021008 = "No solo las novelas, conceptos como la infancia, el amor, la razón, y así sucesivamente, también son productos de los tiempos modernos.",
  str_homestory_chat_33021009 = "Una vez que te acostumbras a ellos, es difícil imaginar la vida de otra manera...",
  str_homestory_chat_33021010 = "Por lo tanto, el malentendido de que \"siempre han existido\".",
  str_homestory_chat_33021011 = "Es algo difícil de creer.",
  str_homestory_chat_33021012 = "¿No tenían los aurorianos historias para leer en el pasado?",
  str_homestory_chat_33021013 = "En aquel entonces, teníamos epopeyas, dramas y fábulas, que tienen elementos de narración pero son bastante diferentes de las novelas.",
  str_homestory_chat_33021014 = "Últimamente, he estado leyendo algunas de las novelas más vendidas que se muestran en las librerías. Comparado con las epopeyas y tal...",
  str_homestory_chat_33021015 = "Sus tramas son más complejas, las emociones más matizadas, sin duda un producto de la opulencia social.",
  str_homestory_chat_33021016 = "Hace cien años, los aurorianos no tenían tiempo para reflexionar sobre cosas tan \"inútiles\".",
  str_homestory_chat_33021017 = "Ya veo... ¡Es realmente esclarecedor hablar contigo!",
  str_homestory_chat_33022001 = "Libro de historia.",
  str_homestory_chat_33022002 = "Es raro que alguien de tu edad esté interesado en la historia.",
  str_homestory_chat_33022003 = "Es bueno leer historia, pero ten cuidado de no pensar que todo lo escrito en un libro es absolutamente cierto.",
  str_homestory_chat_33022004 = "Lo entiendo, Sr. Wilhelm. ¿Quieres decir \"la historia la escriben los vencedores\", verdad?",
  str_homestory_chat_33022005 = "Esa declaración simplemente refleja la distorsión deliberada de la historia por aquellos en el poder. La realidad es mucho más compleja.",
  str_homestory_chat_33022006 = "Incluso cuando los historiadores escriben la historia con la noble intención de \"restaurar la verdad\"...",
  str_homestory_chat_33022007 = "Inevitablemente están influenciados por el espíritu y el ethos de su propia época.",
  str_homestory_chat_33022008 = "Lo que escriben ya es \"historia vista por el contemporáneo\", no \"historia\" en sí misma.",
  str_homestory_chat_33022009 = "¿Estás diciendo... que la historia no puede ser restaurada con precisión?",
  str_homestory_chat_33022010 = "Como era de esperar de un joven que lee historia, ya has notado la ironía de \"historia y verdad\".",
  str_homestory_chat_33023001 = "Poesía.",
  str_homestory_chat_33023002 = "Hmph, a veces pienso que eres demasiado viejo para tu edad, pero luego me sorprendes con algunos intereses juveniles.",
  str_homestory_chat_33023003 = "Hay un dicho, \"Morir joven mientras aún persiste la juventud es una bendición para el poeta\". ¿Qué opinas de eso?",
  str_homestory_chat_33023004 = "Estoy de acuerdo.",
  str_homestory_chat_33023005 = "Tus pensamientos son peligrosos.",
  str_homestory_chat_33023006 = "Escribir poesía exige fervor juvenil. Es mejor morir temprano que esperar a que esa pasión se desvanezca.",
  str_homestory_chat_33023007 = "¿Una vida sin pasión no vale la pena vivir—es eso lo que piensas?",
  str_homestory_chat_33023008 = "Definitivamente no, ¿pero qué hay de esos poetas?",
  str_homestory_chat_33023009 = "Siempre hay alguien que ve algo como el propósito de toda su vida, ¿verdad?",
  str_homestory_chat_33023010 = "Propósito de toda la vida... Para mí, quizás sea el camino para acercarme más al Señor.",
  str_homestory_chat_33023011 = "Tienes una aguda visión, PlayerName.",
  str_homestory_chat_33023012 = "No estoy de acuerdo.",
  str_homestory_chat_33023013 = "¿Estás en contra de la \"teoría del talento innato\"?",
  str_homestory_chat_33023014 = "¿Qué quieres decir?",
  str_homestory_chat_33023015 = "De todas las formas literarias, la poesía es la que más talento exige.",
  str_homestory_chat_33023016 = "Muchos grandes poetas alcanzan la fama en su adolescencia y veintena, agotan sus talentos y luego se reducen a lo mediocre.",
  str_homestory_chat_33023017 = "Pero no estás de acuerdo con este tipo de destino.",
  str_homestory_chat_33023018 = "Mientras uno viva, puede perseguir la poesía otorgada por lo divino con un alma enriquecida por experiencias mundanas.",
  str_homestory_chat_33023019 = "¿Es eso lo que piensas?",
  str_homestory_chat_33023020 = "Yo... tal vez. Odio la idea de atar las posibilidades de la vida a la \"juventud\".",
  str_homestory_chat_33023021 = "Pensándolo bien, eso es justo lo que quisiste decir.",
  str_homestory_chat_33023022 = "¡Pero nunca podría expresarlo tan bien como tú! ¡Eres increíble, Sr. Wilhelm!",
  str_homestory_chat_33024001 = "Libros de ciencia popular.",
  str_homestory_chat_33024002 = "La ciencia, eh... Sin duda ha hecho grandes contribuciones a la sociedad.",
  str_homestory_chat_33024003 = "Pero con el marco científico actual, los Aurorianos seguramente se están alejando de la Verdad.",
  str_homestory_chat_33024004 = "Eh, ¿cómo es eso?",
  str_homestory_chat_33024005 = "¿Victoria alguna vez te ha dicho, \"La Verdad tiene muchas dimensiones\"?",
  str_homestory_chat_33024006 = "¡Ella dice eso mucho!",
  str_homestory_chat_33024007 = "Aquí es donde reside el misterio.",
  str_homestory_chat_33024008 = "La ciencia se basa en la previsibilidad.",
  str_homestory_chat_33024009 = "Hacer algo diez mil veces y obtener el mismo resultado cada vez es lo que lo convierte en una \"conclusión científica\".",
  str_homestory_chat_33024010 = "Pero la Verdad reside en la chispa uno en un millón.",
  str_homestory_chat_33024011 = "Lo captas en una sola mirada, y esa mirada, sin importar cuántas veces la tomes, siempre es diferente.",
  str_homestory_chat_33024012 = "¿Lo entiendes?",
  str_homestory_chat_33024013 = "Lo entiendo.",
  str_homestory_chat_33024014 = "Tonterías. Si realmente puedes entenderlo de mis palabras al azar, ¿para qué necesitamos el Orden Verdadero?",
  str_homestory_chat_33024015 = "...",
  str_homestory_chat_33024016 = "No lo entiendo.",
  str_homestory_chat_33024017 = "Está bien. Te gusta la ciencia, así que sigue estudiándola.",
  str_homestory_chat_33024018 = "Cuando la ciencia alcanza su pico, podría convertirse en otra puerta de entrada a la Verdad.",
  str_homestory_chat_33025001 = "Textos teológicos.",
  str_homestory_chat_33025002 = "¿¿¿???",
  str_homestory_chat_33025003 = "...Ah, ya veo.",
  str_homestory_chat_33025004 = "¿Has estado leyendo... cómo se llama? ¿\"Novelas de fantasía\"? Las que se basan en mitos.",
  str_homestory_chat_33025005 = "Y por eso te intrigan los conceptos y escenarios en ellos, ¿verdad?",
  str_homestory_chat_33025006 = "¿Eh? No, Sr. Wilhelm.",
  str_homestory_chat_33025007 = "Al oírte mencionar mucho \"la Verdad\" y \"Señor\", quiero entender de qué estás hablando.",
  str_homestory_chat_33025008 = "¡¿?!",
  str_homestory_chat_33025009 = "¿Para... mí?",
  str_homestory_chat_33025010 = "Sí. Encuentro tus charlas intrigantes y quiero poder responderte a veces.",
  str_homestory_chat_33025011 = "...Ugh, ¿es demasiado frívolo leer textos teológicos con esa mentalidad?",
  str_homestory_chat_33025012 = "...No, no lo es.",
  str_homestory_chat_33025013 = "¿Qué pasa?",
  str_homestory_chat_33025014 = "¡Nada! Ve a leer ahora.",
  str_homestory_chat_33025015 = "Si hay algo que no entiendes... no dudes en preguntarme.",
  str_homestory_chat_33199999 = "¿Algún sueño interesante últimamente?",
  str_homestory_chat_33121001 = "¿Sueños interesantes?",
  str_homestory_chat_33121002 = "No puedo pensar en ninguno...",
  str_homestory_chat_33121003 = "Hmm... ¿Estás bajo mucha presión?",
  str_homestory_chat_33121004 = "¿No es agotador dormir sin dulces sueños?",
  str_homestory_chat_33121005 = "¿Eh? Yo no diría eso...",
  str_homestory_chat_33121006 = "Mucho estrés se ha ido después de una buena noche de sueño.",
  str_homestory_chat_33121007 = "¿Es eso así? Pero...",
  str_homestory_chat_33121008 = "Seguro.",
  str_homestory_chat_33121009 = "Ah. PlayerName, eres un hombre optimista!",
  str_homestory_chat_33121010 = "¿Eh? ¿Mis sueños te llevaron a esta conclusión?",
  str_homestory_chat_33121011 = "¡Sí! Aquellos que viven una vida feliz y tratan a los demás con optimismo...",
  str_homestory_chat_33121012 = "¡Tendrán muchas cosas hermosas con sus seres queridos en sus sueños!",
  str_homestory_chat_33121013 = "Jeje. Aunque hay una manera aún más simple.",
  str_homestory_chat_33121014 = "¡Ven a verme cuando quieras sentir un sueño dulce!",
  str_homestory_chat_33121015 = "¡Lo haré!",
  str_homestory_chat_33122001 = "Un mundo sin Eclipsites.",
  str_homestory_chat_33122002 = "Vaya. Por favor dame un minuto para procesar esto...",
  str_homestory_chat_33122003 = "¡Esa sería una burbuja sin ninguna mancha!",
  str_homestory_chat_33122004 = "¡La burbuja más hermosa y perfecta!",
  str_homestory_chat_33122005 = "¿Qué hiciste allí?",
  str_homestory_chat_33122006 = "Viajé por todas partes con todos.",
  str_homestory_chat_33122007 = "¡Guau. Ojalá estuviera allí contigo!",
  str_homestory_chat_33122008 = "Abrazamos el viento y vimos juntos el nacimiento de un nuevo mundo en la cima del Colossus...",
  str_homestory_chat_33122009 = "Trabajamos juntos para restaurar nuestra patria.",
  str_homestory_chat_33122010 = "¡Qué amable y desinteresado eres incluso en tus sueños!",
  str_homestory_chat_33122011 = "Es muy importante restaurar los colores de la burbuja, en efecto.",
  str_homestory_chat_33122012 = "¿Me llevarías contigo la próxima vez para experimentar juntos un sueño tan hermoso?",
  str_homestory_chat_33122013 = "Claro, simplemente no sé cuándo sería eso...",
  str_homestory_chat_33123001 = "Longzhou.",
  str_homestory_chat_33123002 = "Longzhou. Lo leí en un libro de cuentos de hadas...",
  str_homestory_chat_33123003 = "Los cuentos de hadas de allí son bastante profundos.",
  str_homestory_chat_33123004 = "Les gusta usar palabras grandes y frases extrañas. Difícil para mí entender...",
  str_homestory_chat_33123005 = "La cultura de Longzhou es de hecho profunda y extensa.",
  str_homestory_chat_33123006 = "Sus gadgets, calendario y Aurorians son verdaderamente intrigantes.",
  str_homestory_chat_33123007 = "¿De verdad? Nunca he visto a un Aurorian de Longzhou.",
  str_homestory_chat_33123008 = "Le pediré a mi antepasado que me dé un vistazo esta noche en mi sueño.",
  str_homestory_chat_33123009 = "¿Hablas en serio?",
  str_homestory_chat_33123010 = "¿Qué tal si te presento a algunos de sus Aurorians la próxima vez?",
  str_homestory_chat_33123011 = "¡Hurra! Eres tan amable conmigo, ¡justo como mi antepasado!",
  str_homestory_chat_33124001 = "Un espectáculo de circo.",
  str_homestory_chat_33124002 = "¿Hmm... Un espectáculo?",
  str_homestory_chat_33124003 = "Vi muchos cuando estaba en el circo...",
  str_homestory_chat_33124004 = "Aunque no recuerdo mucho...",
  str_homestory_chat_33124005 = "¡Sé con seguridad que eran intérpretes increíbles!",
  str_homestory_chat_33124006 = "¿Cuál es tu parte favorita del espectáculo?",
  str_homestory_chat_33124007 = "¿Supongo que el lanzamiento de cuchillos?",
  str_homestory_chat_33124008 = "¿El lanzamiento de cuchillos? No sabía que te gustaba la emoción.",
  str_homestory_chat_33124009 = "¡Es emocionante y siempre termina bien!",
  str_homestory_chat_33124010 = "Por eso también soy fan.",
  str_homestory_chat_33124011 = "¿Supongo que el espectáculo de magia?",
  str_homestory_chat_33124012 = "¿El espectáculo de magia? ¡Jeno es un fabuloso mago!",
  str_homestory_chat_33124013 = "¡Recuerdo lo misterioso que se sentía! ¡Podía decir mucho simplemente dibujando unas pocas cartas!",
  str_homestory_chat_33124014 = "Hmm... Echo de menos a todos del circo...",
  str_homestory_chat_33124015 = "¡Vamos a ver un espectáculo de circo juntos si tenemos la oportunidad!",
  str_homestory_chat_33124016 = "¡Acuerdo!",
  str_homestory_chat_33125001 = "Eraveil.",
  str_homestory_chat_33125002 = "Eraveil... Ese es tu lugar de origen, ¿no es así?",
  str_homestory_chat_33125003 = "Nací en un barco. El hogar es un concepto extraño para mí.",
  str_homestory_chat_33125004 = "¿Te gusta Eraveil?",
  str_homestory_chat_33125005 = "Sí, después de todo, mi gente había estado viviendo allí durante generaciones.",
  str_homestory_chat_33125006 = "Pero pasé diecisiete años bajo tierra.",
  str_homestory_chat_33125007 = "Todavía hay mucho que no sé sobre mis antepasados.",
  str_homestory_chat_33125008 = "Esa es una de las razones por las que estoy viajando.",
  str_homestory_chat_33125009 = "Vaya. ¿El Caelestita también está tratando de aprender sobre sus antepasados?",
  str_homestory_chat_33125010 = "Somos bastante similares, ¿no?",
  str_homestory_chat_33125011 = "¿Quizás mi antepasado conoce al tuyo?",
  str_homestory_chat_33125012 = "¡Quizás solían ser buenos amigos!",
  str_homestory_chat_33125013 = "Jaja. Eso es un pensamiento muy interesante.",
  str_homestory_chat_33125014 = "Jeje. ¡Nuestros antepasados deben estar muy felices de vernos continuar su amistad!",
  str_homestory_chat_33299999 = "¿Tienes algo que quieras proteger?",
  str_homestory_chat_33221001 = "Las cosas que quiero proteger...",
  str_homestory_chat_33221002 = "Hay tantos, tú sabes.",
  str_homestory_chat_33221003 = "¿Puedes ser más específico?",
  str_homestory_chat_33221004 = "Hmm... Es difícil de describir.",
  str_homestory_chat_33221005 = "¿Qué tipo de cosas estás preguntando?",
  str_homestory_chat_33221006 = "De conceptos grandiosos como ideales y creencias.",
  str_homestory_chat_33221007 = "Hasta los pequeños e intrincados detalles.",
  str_homestory_chat_33221008 = "Tal vez puedas darme algunos ejemplos.",
  str_homestory_chat_33221009 = "Qué tal...",
  str_homestory_chat_33221010 = "Los cuchillos que atesoro, mi cuervo, y mayores como Tweety.",
  str_homestory_chat_33221011 = "En ese caso... ¡Hay algo que debo proteger ahora mismo!",
  str_homestory_chat_33221012 = "Para proteger la cena de esta noche, ¡debo evitar que Vice desarrolle un nuevo plato!!!",
  str_homestory_chat_33222001 = "el coloso",
  str_homestory_chat_33222002 = "Comprendo.",
  str_homestory_chat_33222003 = "Tu compañero dejó atrás el campo de batalla para pasar eones contigo.",
  str_homestory_chat_33222004 = "Y tus espíritus se entrelazaron en una armonía milagrosa.",
  str_homestory_chat_33222005 = "Yo también me sorprendí cuando abrí la reliquia familiar... Entiendo ahora.",
  str_homestory_chat_33222006 = "Ahora que lo mencionas, parece que compartimos un destino similar.",
  str_homestory_chat_33222007 = "De hecho, incluso nuestros ancestros se conocieron hace mucho tiempo.",
  str_homestory_chat_33222008 = "Me ayudaste a cumplir mi misión, así que ahora, te ayudaré a proteger el Colossus.",
  str_homestory_chat_33222009 = "Gracias, con tu ayuda...",
  str_homestory_chat_33222010 = "¡Podemos hacerlo sin duda!",
  str_homestory_chat_33223001 = "La gloria de los ancestros.",
  str_homestory_chat_33223002 = "Entiendo cómo se siente.",
  str_homestory_chat_33223003 = "Después de todo, he llegado hasta aquí siguiendo la voluntad de mis antepasados.",
  str_homestory_chat_33223004 = "No ha sido un viaje fácil, lleno como estaba de dudas...",
  str_homestory_chat_33223005 = "Pero he cumplido mi destino. ¿Y tú, a dónde te ha llevado tu camino?",
  str_homestory_chat_33223006 = "Hay algunos logros...",
  str_homestory_chat_33223007 = "Entonces, felicidades para ti.",
  str_homestory_chat_33223008 = "Todavía estoy trabajando en ello...",
  str_homestory_chat_33223009 = "Entonces estaré velando por ti.",
  str_homestory_chat_33223010 = "Si necesitas ayuda, siéntete libre de decírmelo.",
  str_homestory_chat_33223011 = "No solo te agradezco por tu ayuda. Estoy genuinamente fascinado por la historia de los Caelestites.",
  str_homestory_chat_33223012 = "Gracias.",
  str_homestory_chat_33224001 = "¡Justicia!",
  str_homestory_chat_33224002 = "¿Oh?",
  str_homestory_chat_33224003 = "¿También quieres convertirte en un camarada de la justicia?",
  str_homestory_chat_33224004 = "¡Ya lo soy!",
  str_homestory_chat_33224005 = "He llegado a apreciar verdaderamente tu sentido de la justicia a través de nuestro tiempo juntos.",
  str_homestory_chat_33224006 = "Creo que debes ser el candidato más adecuado.",
  str_homestory_chat_33224007 = "¡Por supuesto que quiero!",
  str_homestory_chat_33224008 = "¿En serio? Tener tal determinación y creencia es bastante impresionante.",
  str_homestory_chat_33224009 = "Pero este no es un trabajo fácil.",
  str_homestory_chat_33224010 = "¿Te gustaría ser mi asistente?",
  str_homestory_chat_33224011 = "Nuestras acciones contra el mal en la noche seguramente serán más efectivas con tu presencia.",
  str_homestory_chat_33224012 = "Uh, si se trata de esto, por favor permíteme pensarlo un poco más!",
  str_homestory_chat_33225001 = "Amistad.",
  str_homestory_chat_33225002 = "La amistad es realmente hermosa.",
  str_homestory_chat_33225003 = "Siempre estaba en movimiento, cambiando de trabajos y nunca realmente me asentaba.",
  str_homestory_chat_33225004 = "Pero ahora, he encontrado a algunas personas increíbles a las que llamar amigos, como mi superior en la Unión de Mensajeros y ese amigo especial por la noche.",
  str_homestory_chat_33225005 = "Son los amigos que deseo proteger.",
  str_homestory_chat_33225006 = "¿Qué tipo de amistad quieres proteger?",
  str_homestory_chat_33225007 = "¡La amistad con todos en el Coloso!",
  str_homestory_chat_33225008 = "Correcto, todos en el Coloso son muy amables.",
  str_homestory_chat_33225009 = "Es solo que estoy acostumbrado a una vida de mantener distancia con las personas.",
  str_homestory_chat_33225010 = "Parece que todavía no estoy listo para hacerme amigo de todos.",
  str_homestory_chat_33225011 = "Entonces, si estamos hablando del presente...",
  str_homestory_chat_33225012 = "¡Mi amistad contigo!",
  str_homestory_chat_33225013 = "Lo siento, solo... No creo que te haya mencionado.",
  str_homestory_chat_33225014 = "Después de todo, que estés a mi lado se ha convertido en algo a lo que estoy acostumbrado.",
  str_homestory_chat_33225015 = "Permíteme rectificar.",
  str_homestory_chat_33225016 = "Proteger nuestra amistad es extremadamente importante.",
  str_homestory_chat_33225017 = "¡Es mi honor! ¡Apreciaré esta amistad!",
  str_homestory_chat_33399999 = "Si un día te despiertas y eres la única persona que queda en el mundo, ¿qué harías?",
  str_homestory_chat_33321001 = "Continúa durmiendo.",
  str_homestory_chat_33321002 = "Debo estar soñando.",
  str_homestory_chat_33321003 = "¿Por qué es así? Normalmente, las personas irían inmediatamente a explorar y hacer cosas que normalmente no pueden hacer, ¿verdad?",
  str_homestory_chat_33321004 = "¡Pero yo soy la estrella!",
  str_homestory_chat_33321005 = "Normalmente, suceden muchas cosas inusuales.",
  str_homestory_chat_33321006 = "Jajaja, tú, de todas las personas, eres incluso más arrogante que yo.",
  str_homestory_chat_33321007 = "¿Alguna vez lo has pensado? Si todos desaparecieran, tus habilidades psíquicas serían inútiles, ¿verdad?",
  str_homestory_chat_33321008 = "Bueno... Como no hay nada que hacer, realmente debería irme a dormir.",
  str_homestory_chat_33321009 = "¿Qué es lo que quieres hacer pero no puedes?",
  str_homestory_chat_33321010 = "Humph. Al principio, parece que hay mucho, pero al pensar más detenidamente, no parece haber mucho.",
  str_homestory_chat_33321011 = "Haré lo que quiera hacer, las reglas no pueden detenerme.",
  str_homestory_chat_33321012 = "¡No existe tal cosa como \"algo que no puedes hacer usualmente\"!",
  str_homestory_chat_33321013 = "Qué tipo tan peligroso...",
  str_homestory_chat_33322001 = "Primero, corre al parque de diversiones en Umbraton o Harbor City.",
  str_homestory_chat_33322002 = "Entonces, ¡disfrutemos de las actividades que normalmente requieren hacer fila!",
  str_homestory_chat_33322003 = "¿Debería llamarte... honesto o tenso?",
  str_homestory_chat_33322004 = "Tu sueño puede hacerse realidad simplemente colándote en el parque de atracciones a medianoche.",
  str_homestory_chat_33322005 = "... ¿Quién pensaría en hacer tal cosa!?",
  str_homestory_chat_33322006 = "Eres la radiante e irrestricta Lady Pepita.",
  str_homestory_chat_33322007 = "Vamos, te llevaré allí esta noche.",
  str_homestory_chat_33322008 = "(Oh, no. En realidad estoy un poco encantado...)",
  str_homestory_chat_33323001 = "Ve a la librería para leer libros gratis",
  str_homestory_chat_33323002 = "Puedo mirar todo el día, sentarme donde quiera, y no preocuparme por la mirada del empleado de la tienda... ¡Ah, el cielo!",
  str_homestory_chat_33323003 = "...",
  str_homestory_chat_33323004 = "Sé que mi deseo es humilde, pero no tienes que mirarme tan sin palabras...",
  str_homestory_chat_33323005 = "Malinterpretaste, no pensé que tu deseo fuera humilde en absoluto.",
  str_homestory_chat_33323006 = "Pero si quieres leer libros gratis, todo lo que necesitas hacer es ponerte un atuendo elegante... y puedes entrar a la librería y elegir lo que quieras.",
  str_homestory_chat_33323007 = "Una vez que hayas seleccionado, simplemente menciona el nombre de cualquier noble. La librería puede cobrar el pago al final del Tsuki.",
  str_homestory_chat_33323008 = "Esos nobles tratan sus facturas mensuales como copos de nieve, nunca se molestan en revisarlas una por una.",
  str_homestory_chat_33323009 = "T-Tú... Es-Esto es un crimen, ¿no es así?",
  str_homestory_chat_33323010 = "¡Ja! Esos nobles ignorantes, soy yo quien está difundiendo conocimiento entre la gente común... ¿Y llamas a esto un crimen?",
  str_homestory_chat_33323011 = "Diría que es mi bendición.",
  str_homestory_chat_33323012 = "...",
  str_homestory_chat_33324001 = "Bañándose en el río",
  str_homestory_chat_33324002 = "¡Ptui!",
  str_homestory_chat_33324003 = "*tos*... Para ser honesto contigo, he querido hacer esto durante mucho tiempo.",
  str_homestory_chat_33324004 = "Pero todavía estás preocupado... ¿verdad?",
  str_homestory_chat_33324005 = "No, voy todo el tiempo.",
  str_homestory_chat_33324006 = "¿¡Qué?! No estás preocupado—",
  str_homestory_chat_33324007 = "¿Viene alguien?",
  str_homestory_chat_33324008 = "Petey está aquí. Además, ¿qué tipo de persona miraría a los demás mientras se bañan?",
  str_homestory_chat_33324009 = "Además, todos son iguales, ¿qué hay para ser tímido?",
  str_homestory_chat_33324010 = "... ¡No, no, espera! ¡Ni siquiera pienses en engañarme para que me bañe en el río ahora mismo!",
  str_homestory_chat_33324011 = "¿Atacado por pirañas?",
  str_homestory_chat_33324012 = "Cuando voy a bañarme en el río, suelo estar cubierto de barro.",
  str_homestory_chat_33324013 = "Los tiburones serían envenenados y se desmayarían.",
  str_homestory_chat_33324014 = "Tan grandioso... no, eso no es a lo que me refería para mirar!",
  str_homestory_chat_33325001 = "Sentado en el trono de Lumopolis",
  str_homestory_chat_33325002 = "¡Todavía vas a cruzar las piernas!",
  str_homestory_chat_33325003 = "Suspiro, estoy sin ideas, he estado sentado un rato ahora.",
  str_homestory_chat_33325004 = "¿¡Qué?! Permíteme preguntar primero, ¿no estás autorizado, verdad...?",
  str_homestory_chat_33325005 = "¿Podría ser que el padre de Carleen también me invite amablemente?",
  str_homestory_chat_33325006 = "¿Es cómoda la silla para sentarse?",
  str_homestory_chat_33325007 = "Tsk, no es cómodo en absoluto, ¡es muy difícil!",
  str_homestory_chat_33325008 = "Por el bien de Carleen, dejé un cojín allí.",
  str_homestory_chat_33325009 = "Realmente espero que el Señor de la Ciudad me agradezca... ¡Jajaja!",
  str_homestory_chat_33325010 = "¿Cómo llegaste allí?",
  str_homestory_chat_33325011 = "Esa noche, estaba haciendo graffiti en una hermosa pared blanca, luego llegaron los guardias...",
  str_homestory_chat_33325012 = "Acabo de descubrir que es el Salón de Justicia de Lumopolis.",
  str_homestory_chat_33325013 = "...",
  str_homestory_chat_33325014 = "¡Y luego me topé con el lugar donde está el trono del Señor de la Ciudad!",
  str_homestory_chat_33325015 = "Por el bien de la seguridad, tengo que mantener una cierta distancia de ti...",
  str_homestory_chat_33429999 = "¿Te importaría compartir algunas cosas interesantes sobre este tiempo?",
  str_homestory_chat_33421001 = "Por supuesto, pero no tienes que ser tan educado.",
  str_homestory_chat_33421002 = "Ha pasado tanto tiempo. Solo sé muy poco sobre el mundo ahora.",
  str_homestory_chat_33421003 = "Y podría convertirme más en una carga que en una ayuda si no me adapto al mundo moderno.",
  str_homestory_chat_33421004 = "Por favor, cuéntame más sobre el mundo.",
  str_homestory_chat_33421005 = "Oh, no te preocupes por eso. Verás, he pasado los últimos diecisiete años bajo tierra.",
  str_homestory_chat_33421006 = "¡Todavía estoy muy en el proceso de explorar este mundo!",
  str_homestory_chat_33421007 = "Entonces, podemos compartir nuestras experiencias entre nosotros.",
  str_homestory_chat_33421008 = "¡Disfrutemos del mundo juntos!",
  str_homestory_chat_33421009 = "Es un gran mundo en efecto.",
  str_homestory_chat_33421010 = "Es un placer compartir mis pensamientos contigo.",
  str_homestory_chat_33421011 = "En el nombre de Aquiles, también compartiré contigo todo lo que sé.",
  str_homestory_chat_33421012 = "Si deseas saber sobre tus compañeros Caelestites, estoy feliz de compartir sus historias contigo.",
  str_homestory_chat_33421013 = "¡Estoy muy interesado! Cuéntame sobre ellos algún día.",
  str_homestory_chat_33422001 = "¿Estás interesado en el rally de autos Rediesel?",
  str_homestory_chat_33422002 = "Coche... Acabo de ser presentado al término.",
  str_homestory_chat_33422003 = "Solíamos tener carruajes para el transporte en mi época.",
  str_homestory_chat_33422004 = "Se dice que los coches no solo son más rápidos que los carruajes, sino también más estables.",
  str_homestory_chat_33422005 = "La tecnología ahora es asombrosa.",
  str_homestory_chat_33422006 = "¿Quieres intentar manejar?",
  str_homestory_chat_33422007 = "Aún no he dominado la habilidad.",
  str_homestory_chat_33422008 = "Intentarlo precipitadamente probablemente conduciría a numerosos riesgos y problemas innecesarios.",
  str_homestory_chat_33422009 = "¿Quieres que te lleve a dar un paseo?",
  str_homestory_chat_33422010 = "Suena como una actividad perfecta para el tiempo de ocio.",
  str_homestory_chat_33422011 = "Sin embargo, como guerrero, realmente quiero aprender a controlar mi propio coche.",
  str_homestory_chat_33422012 = "Quizás podrías practicar conducir en el futuro usando el simulador en el Colossus. Estaría encantado de enseñarte.",
  str_homestory_chat_33422013 = "¿Existe tal herramienta conveniente?",
  str_homestory_chat_33422014 = "Por favor, déjame intentarlo. Realmente quiero aprender algunas técnicas de la nueva era.",
  str_homestory_chat_33422015 = "¡No hay problema!",
  str_homestory_chat_33423001 = "Por ejemplo, ¿el acuario en Harbor City? Ese lugar es bastante bueno.",
  str_homestory_chat_33423002 = "Un término tan novedoso. ¿Qué tipo de lugar es ese?",
  str_homestory_chat_33423003 = "Un lugar muy soñador.",
  str_homestory_chat_33423004 = "Como si estuviera sumergido en un sueño de las profundidades del mar.",
  str_homestory_chat_33423005 = "Puedes ver muchos paisajes que no se pueden ver en tierra.",
